window.BOOK={"key":"risala","app":"mutoon","lsk":"mutoon_risala_v1","title":"الرسالة","unitWord":"فقرة","sub":"الفقه المالكي مع مقدمة في العقيدة · ابن أبي زيد القيرواني (ت ٣٨٦هـ) · ٤٦ بابًا","source":"https://shamela.ws/book/21589 (الفواكه الدواني على رسالة ابن أبي زيد القيرواني للنفراوي، دار الفكر ١٤١٥هـ/١٩٩٥م: نص الرسالة المشكول بأعلى الصفحات) · قوبل بـ: https://shamela.ws/book/1430 (الرسالة، نسخة التتائي، جمع وتحقيق إبراهيم السناري، معهد المخطوطات العربية ١٤٤٢هـ) + https://shamela.ws/book/11373 (متن الرسالة، دار الفكر) + https://shamela.ws/book/7441 (متن الرسالة بأعلى «الثمر الداني» للآبي، المكتبة الثقافية)؛ والشكل مقابَل بنشرة السناري وبمتن «كفاية الطالب الرباني» https://shamela.ws/book/21597 — انظر risala-sources.md","note":"الشكل من نص الرسالة المشكول بأعلى صفحات «الفواكه الدواني». قوبل اللفظ كلمةً كلمةً بسكربت على نشرة السناري المحققة (نسخة التتائي)، وعلى متن الرسالة (دار الفكر)، وعلى متن «الثمر الداني». وقوبل الشكل على نشرة السناري وعلى متن «كفاية الطالب الرباني» المشكول. كل تغيير مسجّل في تقرير المصادر.","chapters":[{"id":"ri1","title":"مُقَدِّمَةُ الرِّسَالَةِ","units":[{"id":"ri1_1","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١","segs":[["matn","وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَآلِهِ وَصَحْبِهِ وَسَلَّمَ."]]},{"id":"ri1_2","label":"مُقَدِّمَةُ الرِّسَالَةِ · ٢","segs":[["matn","قَالَ أَبُو مُحَمَّدٍ عَبْدُ اللَّهِ بْنُ أَبِي زَيْدٍ الْقَيْرَوَانِيُّ رَضِيَ اللَّهُ عَنْهُ وَأَرْضَاهُ: الْحَمْدُ لِلَّهِ الَّذِي ابْتَدَأَ الْإِنْسَانَ بِنِعْمَتِهِ، وَصَوَّرَهُ فِي الْأَرْحَامِ بِحِكْمَتِهِ،"]]},{"id":"ri1_3","label":"مُقَدِّمَةُ الرِّسَالَةِ · ٣","segs":[["matn","وَأَبْرَزَهُ إِلَى رِفْقِهِ، وَمَا يَسَّرَ لَهُ مِنْ رِزْقِهِ، وَعَلَّمَهُ مَا لَمْ يَكُنْ يَعْلَمُ، وَكَانَ فَضْلُ اللَّهِ عَلَيْهِ عَظِيمًا، وَنَبَّهَهُ بِآثَارِ صَنْعَتِهِ،"]]},{"id":"ri1_4","label":"مُقَدِّمَةُ الرِّسَالَةِ · ٤","segs":[["matn","وَأَعْذَرَ إِلَيْهِ عَلَى أَلْسِنَةِ الْمُرْسَلِينَ الْخِيَرَةِ مِنْ خَلْقِهِ، فَهَدَى مَنْ وَفَّقَهُ بِفَضْلِهِ، وَأَضَلَّ مَنْ خَذَلَهُ بِعَدْلِهِ، وَيَسَّرَ الْمُؤْمِنِينَ لِلْيُسْرَى، وَشَرَحَ صُدُورَهُمْ لِلذِّكْرَى، فَآمَنُوا بِاللَّهِ بِأَلْسِنَتِهِمْ نَاطِقِينَ،"]]},{"id":"ri1_5","label":"مُقَدِّمَةُ الرِّسَالَةِ · ٥","segs":[["matn","وَبِقُلُوبِهِمْ مُخْلِصِينَ، وَبِمَا أَتَتْهُمْ بِهِ رُسُلُهُ وَكُتُبُهُ عَامِلِينَ، وَتَعَلَّمُوا مَا عَلَّمَهُمْ، وَوَقَفُوا عِنْدَ مَا حَدَّ لَهُمْ، وَاسْتَغْنَوْا بِمَا أَحَلَّ لَهُمْ عَمَّا حَرَّمَ عَلَيْهِمْ."]]},{"id":"ri1_6","label":"مُقَدِّمَةُ الرِّسَالَةِ · ٦","segs":[["matn","أَمَّا بَعْدُ أَعَانَنَا اللَّهُ وَإِيَّاكَ عَلَى رِعَايَةِ وَدَائِعِهِ، وَحِفْظِ مَا أَوْدَعَنَا مِنْ شَرَائِعِهِ فَإِنَّكَ سَأَلْتَنِي أَنْ أَكْتُبَ لَكَ جُمْلَةً مُخْتَصَرَةً مِنْ وَاجِبِ أُمُورِ الدِّيَانَةِ،"]]},{"id":"ri1_7","label":"مُقَدِّمَةُ الرِّسَالَةِ · ٧","segs":[["matn","مِمَّا تَنْطِقُ بِهِ الْأَلْسِنَةُ، وَتَعْتَقِدُهُ الْقُلُوبُ وَتَعْمَلُهُ الْجَوَارِحُ وَمَا يَتَّصِلُ بِالْوَاجِبِ مِنْ ذَلِكَ مِنَ السُّنَنِ مِنْ مُؤَكَّدِهَا وَنَوَافِلِهَا وَرَغَائِبِهَا،"]]},{"id":"ri1_8","label":"مُقَدِّمَةُ الرِّسَالَةِ · ٨","segs":[["matn","وَشَيْءٍ مِنَ الْآدَابِ مِنْهَا، وَجُمَلٍ مِنْ أُصُولِ الْفِقْهِ وَفُنُونِهِ عَلَى مَذْهَبِ الْإِمَامِ مَالِكِ بْنِ أَنَسٍ رَحِمَهُ اللَّهُ تَعَالَى وَطَرِيقَتِهِ،"]]},{"id":"ri1_9","label":"مُقَدِّمَةُ الرِّسَالَةِ · ٩","segs":[["matn","مَعَ مَا سَهَّلَ سَبِيلَ مَا أَشْكَلَ مِنْ ذَلِكَ مِنْ تَفْسِيرِ الرَّاسِخِينَ وَبَيَانِ الْمُتَفَقِّهِينَ، لِمَا رَغِبْتَ فِيهِ مِنْ تَعْلِيمِ ذَلِكَ لِلْوِلْدَانِ كَمَا تُعَلِّمُهُمْ حُرُوفَ الْقُرْآنِ؛"]]},{"id":"ri1_10","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١٠","segs":[["matn","لِيَسْبِقَ إِلَى قُلُوبِهِمْ مِنْ فَهْمِ دِينِ اللَّهِ وَشَرَائِعِهِ مَا تُرْجَى لَهُمْ بَرَكَتُهُ، وَتُحْمَدُ لَهُمْ عَاقِبَتُهُ، فَأَجَبْتُكَ إِلَى ذَلِكَ لِمَا رَجَوْتُهُ لِنَفْسِي وَلَكَ مِنْ ثَوَابِ مَنْ عَلَّمَ دِينَ اللَّهِ أَوْ دَعَا إِلَيْهِ."]]},{"id":"ri1_11","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١١","segs":[["matn","وَاعْلَمْ أَنَّ خَيْرَ الْقُلُوبِ أَوْعَاهَا لِلْخَيْرِ، وَأَرْجَى الْقُلُوبِ لِلْخَيْرِ مَا لَمْ يَسْبِقِ الشَّرُّ إِلَيْهِ، وَأَوْلَى مَا عُنِيَ بِهِ النَّاصِحُونَ،"]]},{"id":"ri1_12","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١٢","segs":[["matn","وَرَغِبَ فِي أَجْرِهِ الرَّاغِبُونَ إِيصَالُ الْخَيْرِ إِلَى قُلُوبِ أَوْلَادِ الْمُؤْمِنِينَ لِيَرْسَخَ فِيهَا، وَتَنْبِيهُهُمْ عَلَى مَعَالِمِ الدِّيَانَةِ وَحُدُودِ الشَّرِيعَةِ لِيُرَاضُوا عَلَيْهَا، وَمَا عَلَيْهِمْ أَنْ تَعْتَقِدَهُ مِنَ الدِّينِ قُلُوبُهُمْ، وَتَعْمَلَ بِهِ جَوَارِحُهُمْ؛"]]},{"id":"ri1_13","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١٣","segs":[["matn","فَإِنَّهُ رُوِيَ أَنَّ تَعْلِيمَ الصِّغَارِ لِكِتَابِ اللَّهِ يُطْفِئُ غَضَبَ اللَّهِ. وَأَنَّ تَعْلِيمَ الشَّيْءِ فِي الصِّغَرِ كَالنَّقْشِ فِي الْحَجَرِ."]]},{"id":"ri1_14","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١٤","segs":[["matn","وَقَدْ مَثَّلْتُ لَكَ مِنْ ذَلِكَ مَا يَنْتَفِعُونَ إِنْ شَاءَ اللَّهُ بِحِفْظِهِ، وَيَشْرُفُونَ بِعِلْمِهِ، وَيَسْعَدُونَ بِاعْتِقَادِهِ وَالْعَمَلِ بِهِ."]]},{"id":"ri1_15","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١٥","segs":[["matn","وَقَدْ جَاءَ أَنْ يُؤْمَرُوا بِالصَّلَاةِ لِسَبْعِ سِنِينَ، وَيُضْرَبُوا عَلَيْهَا لِعَشْرٍ، وَيُفَرَّقَ بَيْنَهُمْ فِي الْمَضَاجِعِ. فَكَذَلِكَ يَنْبَغِي أَنْ يُعَلَّمُوا مَا فَرَضَ اللَّهُ عَلَى الْعِبَادِ مِنْ قَوْلٍ وَعَمَلٍ قَبْلَ بُلُوغِهِمْ؛"]]},{"id":"ri1_16","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١٦","segs":[["matn","لِيَأْتِيَ عَلَيْهِمُ الْبُلُوغُ وَقَدْ تَمَكَّنَ ذَلِكَ مِنْ قُلُوبِهِمْ، وَسَكَنَتْ إِلَيْهِ أَنْفُسُهُمْ، وَأَنِسَتْ بِمَا يَعْمَلُونَ بِهِ مِنْ ذَلِكَ جَوَارِحُهُمْ، وَقَدْ فَرَضَ اللَّهُ سُبْحَانَهُ عَلَى الْقُلُوبِ عَمَلًا مِنَ الِاعْتِقَادَاتِ، وَعَلَى الْجَوَارِحِ الظَّاهِرَةِ عَمَلًا مِنَ الطَّاعَاتِ."]]},{"id":"ri1_17","label":"مُقَدِّمَةُ الرِّسَالَةِ · ١٧","segs":[["matn","وَسَأُفَصِّلُ لَكَ مَا شَرَطْتُ لَكَ ذِكْرَهُ بَابًا بَابًا؛ لِيَقْرُبَ مِنْ فَهْمِ مُتَعَلِّمِيهِ إِنْ شَاءَ اللَّهُ تَعَالَى، وَإِيَّاهُ نَسْتَخِيرُ، وَبِهِ نَسْتَعِينُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ نَبِيِّهِ، وَآلِهِ وَصَحْبِهِ وَسَلَّمَ تَسْلِيمًا كَثِيرًا."]]}]},{"id":"ri2","title":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ","units":[{"id":"ri2_1","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١","segs":[["matn","مِنْ ذَلِكَ الْإِيمَانُ بِالْقَلْبِ وَالنُّطْقُ بِاللِّسَانِ أَنَّ اللَّهَ إِلَهٌ وَاحِدٌ لَا إِلَهَ غَيْرُهُ، وَلَا شَبِيهَ لَهُ، وَلَا نَظِيرَ لَهُ، وَلَا وَلَدَ لَهُ، وَلَا وَالِدَ لَهُ، وَلَا صَاحِبَةَ لَهُ،"]]},{"id":"ri2_2","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢","segs":[["matn","وَلَا شَرِيكَ لَهُ، لَيْسَ لِأَوَّلِيَّتِهِ ابْتِدَاءٌ، وَلَا لِآخِرِيَّتِهِ انْقِضَاءٌ، لَا يَبْلُغُ كُنْهَ صِفَتِهِ الْوَاصِفُونَ، وَلَا يُحِيطُ بِأَمْرِهِ الْمُتَفَكِّرُونَ، يَعْتَبِرُ الْمُتَفَكِّرُونَ بِآيَاتِهِ، وَلَا يَتَفَكَّرُونَ فِي مَائِيَّةِ ذَاتِهِ."]]},{"id":"ri2_3","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٣","segs":[["matn","﴿وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾، الْعَالِمُ الْخَبِيرُ، الْمُدَبِّرُ الْقَدِيرُ، السَّمِيعُ الْبَصِيرُ، الْعَلِيُّ الْكَبِيرُ."]]},{"id":"ri2_4","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٤","segs":[["matn","وَأَنَّهُ فَوْقَ عَرْشِهِ الْمَجِيدِ بِذَاتِهِ، وَهُوَ فِي كُلِّ مَكَانٍ بِعِلْمِهِ، خَلَقَ الْإِنْسَانَ وَيَعْلَمُ مَا تُوَسْوِسُ بِهِ نَفْسُهُ، وَهُوَ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ،"]]},{"id":"ri2_5","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٥","segs":[["matn","﴿وَمَا تَسْقُطُ مِنْ وَرَقَةٍ إِلَّا يَعْلَمُهَا وَلَا حَبَّةٍ فِي ظُلُمَاتِ الْأَرْضِ وَلَا رَطْبٍ وَلَا يَابِسٍ إِلَّا فِي كِتَابٍ مُبِينٍ﴾، عَلَى الْعَرْشِ اسْتَوَى، وَعَلَى الْمُلْكِ احْتَوَى."]]},{"id":"ri2_6","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٦","segs":[["matn","وَلَهُ الْأَسْمَاءُ الْحُسْنَى، وَالصِّفَاتُ الْعُلَى، لَمْ يَزَلْ بِجَمِيعِ صِفَاتِهِ وَأَسْمَائِهِ، تَعَالَى أَنْ تَكُونَ صِفَاتُهُ مَخْلُوقَةً، وَأَسْمَاؤُهُ مُحْدَثَةً."]]},{"id":"ri2_7","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٧","segs":[["matn","كَلَّمَ مُوسَى بِكَلَامِهِ الَّذِي هُوَ صِفَةُ ذَاتِهِ لَا خَلْقٌ مِنْ خَلْقِهِ، وَتَجَلَّى لِلْجَبَلِ فَصَارَ دَكًّا مِنْ جَلَالِهِ، وَأَنَّ الْقُرْآنَ كَلَامُ اللَّهِ، لَيْسَ بِمَخْلُوقٍ فَيَبِيدَ، وَلَا صِفَةً لِمَخْلُوقٍ فَيَنْفَدَ."]]},{"id":"ri2_8","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٨","segs":[["matn","وَالْإِيمَانُ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ، حُلْوِهِ وَمُرِّهِ، وَكُلُّ ذَلِكَ قَدْ قَدَّرَهُ اللَّهُ رَبُّنَا، وَمَقَادِيرُ الْأُمُورِ بِيَدِهِ، وَمَصْدَرُهَا عَنْ قَضَائِهِ، عَلِمَ كُلَّ شَيْءٍ قَبْلَ كَوْنِهِ،"]]},{"id":"ri2_9","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٩","segs":[["matn","فَجَرَى عَلَى قَدَرِهِ، لَا يَكُونُ مِنْ عِبَادِهِ قَوْلٌ وَلَا عَمَلٌ إِلَّا وَقَدْ قَضَاهُ، وَسَبَقَ عِلْمُهُ بِهِ ﴿أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ﴾."]]},{"id":"ri2_10","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٠","segs":[["matn","يُضِلُّ مَنْ يَشَاءُ فَيَخْذُلُهُ بِعَدْلِهِ، وَيَهْدِي مَنْ يَشَاءُ فَيُوَفِّقُهُ بِفَضْلِهِ، فَكُلٌّ مُيَسَّرٌ بِتَيْسِيرِهِ إِلَى مَا سَبَقَ مِنْ عِلْمِهِ وَقَدَرِهِ مِنْ شَقِيٍّ أَوْ سَعِيدٍ،"]]},{"id":"ri2_11","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١١","segs":[["matn","تَعَالَى أَنْ يَكُونَ فِي مُلْكِهِ مَا لَا يُرِيدُ، أَوْ يَكُونَ لِأَحَدٍ عَنْهُ غِنًى، أَوْ يَكُونَ خَالِقٌ لِشَيْءٍ إِلَّا هُوَ، رَبُّ الْعِبَادِ وَرَبُّ أَعْمَالِهِمْ، وَالْمُقَدِّرُ لِحَرَكَاتِهِمْ وَآجَالِهِمْ."]]},{"id":"ri2_12","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٢","segs":[["matn","الْبَاعِثُ الرُّسُلَ إِلَيْهِمْ لِإِقَامَةِ الْحُجَّةِ عَلَيْهِمْ، ثُمَّ خَتَمَ الرِّسَالَةَ وَالنِّذَارَةَ وَالنُّبُوَّةَ بِمُحَمَّدٍ نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَهُ آخِرَ الْمُرْسَلِينَ بَشِيرًا وَنَذِيرًا، وَدَاعِيًا إِلَى اللَّهِ بِإِذْنِهِ وَسِرَاجًا مُنِيرًا، وَأَنْزَلَ عَلَيْهِ كِتَابَهُ الْحَكِيمَ، وَشَرَحَ بِهِ دِينَهُ الْقَوِيمَ، وَهَدَى بِهِ الصِّرَاطَ الْمُسْتَقِيمَ."]]},{"id":"ri2_13","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٣","segs":[["matn","وَأَنَّ السَّاعَةَ آتِيَةٌ لَا رَيْبَ فِيهَا، وَأَنَّ اللَّهَ يَبْعَثُ مَنْ يَمُوتُ كَمَا بَدَأَهُمْ يَعُودُونَ، وَأَنَّ اللَّهَ سُبْحَانَهُ ضَاعَفَ لِعِبَادِهِ الْمُؤْمِنِينَ الْحَسَنَاتِ، وَصَفَحَ لَهُمْ بِالتَّوْبَةِ عَنْ كَبَائِرِ السَّيِّئَاتِ، وَغَفَرَ لَهُمُ الصَّغَائِرَ بِاجْتِنَابِ الْكَبَائِرِ،"]]},{"id":"ri2_14","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٤","segs":[["matn","وَجَعَلَ مَنْ لَمْ يَتُبْ مِنَ الْكَبَائِرِ صَائِرًا إِلَى مَشِيئَتِهِ ﴿إِنَّ اللَّهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ﴾، وَمَنْ عَاقَبَهُ بِنَارِهِ أَخْرَجَهُ مِنْهَا بِإِيمَانِهِ؛"]]},{"id":"ri2_15","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٥","segs":[["matn","فَأَدْخَلَهُ بِهِ جَنَّتَهُ، وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ، وَيَخْرُجُ مِنْهَا بِشَفَاعَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ شَفَعَ لَهُ مِنْ أَهْلِ الْكَبَائِرِ مِنْ أُمَّتِهِ."]]},{"id":"ri2_16","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٦","segs":[["matn","وَأَنَّ اللَّهَ سُبْحَانَهُ قَدْ خَلَقَ الْجَنَّةَ فَأَعَدَّهَا دَارَ خُلُودٍ لِأَوْلِيَائِهِ، وَأَكْرَمَهُمْ فِيهَا بِالنَّظَرِ إِلَى وَجْهِهِ الْكَرِيمِ، وَهِيَ الَّتِي أَهْبَطَ مِنْهَا آدَمَ نَبِيَّهُ وَخَلِيفَتَهُ إِلَى أَرْضِهِ بِمَا سَبَقَ فِي سَابِقِ عِلْمِهِ."]]},{"id":"ri2_17","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٧","segs":[["matn","وَأَنَّ اللَّهَ خَلَقَ النَّارَ فَأَعَدَّهَا دَارَ خُلُودٍ لِمَنْ كَفَرَ بِهِ، وَأَلْحَدَ فِي آيَاتِهِ وَكُتُبِهِ وَرُسُلِهِ، وَجَعَلَهُمْ مَحْجُوبِينَ عَنْ رُؤْيَتِهِ."]]},{"id":"ri2_18","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٨","segs":[["matn","وَأَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى يَجِيءُ يَوْمَ الْقِيَامَةِ وَالْمَلَكُ صَفًّا صَفًّا لِعَرْضِ الْأُمَمِ وَحِسَابِهَا وَعُقُوبَتِهَا وَثَوَابِهَا. وَتُوضَعُ الْمَوَازِينُ لِوَزْنِ أَعْمَالِ الْعِبَادِ؛ ﴿فَمَنْ ثَقُلَتْ مَوَازِينُهُ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ﴾."]]},{"id":"ri2_19","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ١٩","segs":[["matn","وَيُؤْتَوْنَ صَحَائِفَهُمْ بِأَعْمَالِهِمْ؛ فَمَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا، وَمَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ فَأُولَئِكَ يَصْلَوْنَ سَعِيرًا."]]},{"id":"ri2_20","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٠","segs":[["matn","وَأَنَّ الصِّرَاطَ حَقٌّ يَجُوزُهُ الْعِبَادُ بِقَدْرِ أَعْمَالِهِمْ: فَنَاجُونَ مُتَفَاوِتُونَ فِي سُرْعَةِ النَّجَاةِ عَلَيْهِ مِنْ نَارِ جَهَنَّمَ. وَقَوْمٌ أَوْبَقَتْهُمْ فِيهَا أَعْمَالُهُمْ."]]},{"id":"ri2_21","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢١","segs":[["matn","وَالْإِيمَانُ بِحَوْضِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَرِدُهُ أُمَّتُهُ، لَا يَظْمَأُ مَنْ شَرِبَ مِنْهُ، وَيُذَادُ عَنْهُ مَنْ بَدَّلَ وَغَيَّرَ."]]},{"id":"ri2_22","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٢","segs":[["matn","وَأَنَّ الْإِيمَانَ قَوْلٌ بِاللِّسَانِ وَإِخْلَاصٌ بِالْقَلْبِ وَعَمَلٌ بِالْجَوَارِحِ، يَزِيدُ بِزِيَادَةِ الْأَعْمَالِ، وَيَنْقُصُ بِنَقْصِهَا، فَيَكُونُ فِيهَا النَّقْصُ وَبِهَا الزِّيَادَةُ، وَلَا يَكْمُلُ قَوْلُ الْإِيمَانِ إِلَّا بِالْعَمَلِ،"]]},{"id":"ri2_23","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٣","segs":[["matn","وَلَا قَوْلٌ وَعَمَلٌ إِلَّا بِالنِّيَّةِ، وَلَا قَوْلٌ وَعَمَلٌ وَنِيَّةٌ إِلَّا بِمُوَافَقَةِ السُّنَّةِ، وَأَنَّهُ لَا يَكْفُرُ أَحَدٌ بِذَنْبٍ مِنْ أَهْلِ الْقِبْلَةِ."]]},{"id":"ri2_24","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٤","segs":[["matn","وَأَنَّ الشُّهَدَاءَ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ، وَأَرْوَاحُ أَهْلِ السَّعَادَةِ بَاقِيَةٌ نَاعِمَةٌ إِلَى يَوْمِ يُبْعَثُونَ، وَأَرْوَاحُ أَهْلِ الشَّقَاوَةِ مُعَذَّبَةٌ إِلَى يَوْمِ الدِّينِ."]]},{"id":"ri2_25","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٥","segs":[["matn","وَأَنَّ الْمُؤْمِنِينَ يُفْتَنُونَ فِي قُبُورِهِمْ وَيُسْأَلُونَ ﴿يُثَبِّتُ اللَّهُ الَّذِينَ آمَنُوا بِالْقَوْلِ الثَّابِتِ فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ﴾."]]},{"id":"ri2_26","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٦","segs":[["matn","وَأَنَّ عَلَى الْعِبَادِ حَفَظَةً يَكْتُبُونَ أَعْمَالَهُمْ، وَلَا يَسْقُطُ شَيْءٌ مِنْ ذَلِكَ عَنْ عِلْمِ رَبِّهِمْ، وَأَنَّ مَلَكَ الْمَوْتِ يَقْبِضُ الْأَرْوَاحَ بِإِذْنِ رَبِّهِ."]]},{"id":"ri2_27","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٧","segs":[["matn","وَأَنَّ خَيْرَ الْقُرُونِ الْقَرْنُ الَّذِينَ رَأَوْا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَآمَنُوا بِهِ، ثُمَّ الَّذِينَ يَلُونَهُمْ ثُمَّ الَّذِينَ يَلُونَهُمْ، وَأَفْضَلُ الصَّحَابَةِ الْخُلَفَاءُ الرَّاشِدُونَ الْمَهْدِيُّونَ: أَبُو بَكْرٍ ثُمَّ عُمَرُ ثُمَّ عُثْمَانُ ثُمَّ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُمْ أَجْمَعِينَ،"]]},{"id":"ri2_28","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٨","segs":[["matn","وَأَنْ لَا يُذْكَرَ أَحَدٌ مِنْ صَحَابَةِ الرَّسُولِ إِلَّا بِأَحْسَنِ ذِكْرٍ، وَالْإِمْسَاكُ عَمَّا شَجَرَ بَيْنَهُمْ، وَأَنَّهُمْ أَحَقُّ النَّاسِ أَنْ يُلْتَمَسَ لَهُمْ أَحْسَنُ الْمَخَارِجِ، وَيُظَنَّ بِهِمْ أَحْسَنُ الْمَذَاهِبِ."]]},{"id":"ri2_29","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٢٩","segs":[["matn","وَالطَّاعَةُ لِأَئِمَّةِ الْمُسْلِمِينَ مِنْ وُلَاةِ أُمُورِهِمْ وَعُلَمَائِهِمْ، وَاتِّبَاعُ السَّلَفِ الصَّالِحِ وَاقْتِفَاءُ آثَارِهِمْ، وَالِاسْتِغْفَارُ لَهُمْ."]]},{"id":"ri2_30","label":"بَابُ مَا تَنْطِقُ بِهِ الْأَلْسِنَةُ وَتَعْتَقِدُهُ الْأَفْئِدَةُ مِنْ وَاجِبِ أُمُورِ الدِّيَانَاتِ · ٣٠","segs":[["matn","وَتَرْكُ الْمِرَاءِ وَالْجِدَالِ فِي الدِّينِ وَتَرْكُ كُلِّ مَا أَحْدَثَهُ الْمُحْدِثُونَ، وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ نَبِيِّهِ وَعَلَى آلِهِ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ وَسَلِّمْ تَسْلِيمًا كَثِيرًا."]]}]},{"id":"ri3","title":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ","units":[{"id":"ri3_1","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ١","segs":[["matn","الْوُضُوءُ يَجِبُ لِمَا يَخْرُجُ مِنْ أَحَدِ الْمَخْرَجَيْنِ مِنْ بَوْلٍ أَوْ غَائِطٍ أَوْ رِيحٍ، أَوْ لِمَا يَخْرُجُ مِنَ الذَّكَرِ مِنْ مَذْيٍ مَعَ غَسْلِ الذَّكَرِ كُلِّهِ مِنْهُ، وَهُوَ مَاءٌ أَبْيَضُ رَقِيقٌ يَخْرُجُ عِنْدَ اللَّذَّةِ بِالْإِنْعَاظِ عِنْدَ الْمُلَاعَبَةِ أَوِ التَّذْكَارِ."]]},{"id":"ri3_2","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ٢","segs":[["matn","وَأَمَّا الْوَدْيُ فَهُوَ مَاءٌ أَبْيَضُ خَاثِرٌ يَخْرُجُ بِأَثَرِ الْبَوْلِ يَجِبُ مِنْهُ مَا يَجِبُ مِنَ الْبَوْلِ. وَأَمَّا الْمَنِيُّ فَهُوَ الْمَاءُ الدَّافِقُ الَّذِي يَخْرُجُ عِنْدَ اللَّذَّةِ الْكُبْرَى بِالْجِمَاعِ رَائِحَتُهُ كَرَائِحَةِ الطَّلْعِ."]]},{"id":"ri3_3","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ٣","segs":[["matn","وَمَاءُ الْمَرْأَةِ مَاءٌ رَقِيقٌ أَصْفَرُ يَجِبُ مِنْهُ الطُّهْرُ، فَيَجِبُ مِنْ هَذَا طُهْرُ جَمِيعِ الْجَسَدِ كَمَا يَجِبُ مِنْ طُهْرِ الْحَيْضَةِ."]]},{"id":"ri3_4","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ٤","segs":[["matn","وَأَمَّا دَمُ الِاسْتِحَاضَةِ فَيَجِبُ مِنْهُ الْوُضُوءُ، وَيُسْتَحَبُّ لَهَا وَلِسَلِسِ الْبَوْلِ أَنْ يَتَوَضَّأَ لِكُلِّ صَلَاةٍ. وَيَجِبُ الْوُضُوءُ مِنْ زَوَالِ الْعَقْلِ: بِنَوْمٍ مُسْتَثْقَلٍ أَوْ إِغْمَاءٍ أَوْ سُكْرٍ أَوْ تَخَبُّطِ جُنُونٍ."]]},{"id":"ri3_5","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ٥","segs":[["matn","وَيَجِبُ الْوُضُوءُ مِنَ الْمُلَامَسَةِ لِلَّذَّةِ، وَالْمُبَاشَرَةِ بِالْجَسَدِ لِلَّذَّةِ، وَالْقُبْلَةِ لِلَّذَّةِ، وَمِنْ مَسِّ الذَّكَرِ، وَاخْتُلِفَ فِي مَسِّ الْمَرْأَةِ فَرْجَهَا فِي إِيجَابِ الْوُضُوءِ بِذَلِكَ."]]},{"id":"ri3_6","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ٦","segs":[["matn","وَيَجِبُ الطُّهْرُ مِمَّا ذَكَرْنَا مِنْ خُرُوجِ الْمَاءِ الدَّافِقِ لِلَّذَّةِ فِي نَوْمٍ أَوْ يَقَظَةٍ مِنْ رَجُلٍ أَوِ امْرَأَةٍ، أَوِ انْقِطَاعِ دَمِ الْحَيْضَةِ أَوِ الِاسْتِحَاضَةِ أَوِ النِّفَاسِ، أَوْ بِمَغِيبِ الْحَشَفَةِ فِي الْفَرْجِ وَإِنْ لَمْ يُنْزِلْ."]]},{"id":"ri3_7","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ٧","segs":[["matn","وَمَغِيبُ الْحَشَفَةِ فِي الْفَرْجِ يُوجِبُ الْغُسْلَ، وَيُوجِبُ الْحَدَّ، وَيُوجِبُ الصَّدَاقَ، وَيُحَصِّنُ الزَّوْجَيْنِ، وَيُحِلُّ الْمُطَلَّقَةَ ثَلَاثًا لِلَّذِي طَلَّقَهَا، وَيُفْسِدُ الْحَجَّ، وَيُفْسِدُ الصَّوْمَ."]]},{"id":"ri3_8","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ٨","segs":[["matn","وَإِذَا رَأَتِ الْمَرْأَةُ الْقَصَّةَ الْبَيْضَاءَ تَطَهَّرَتْ، وَكَذَلِكَ إِذَا رَأَتِ الْجُفُوفَ تَطَهَّرَتْ مَكَانَهَا، رَأَتْهُ بَعْدَ يَوْمٍ أَوْ يَوْمَيْنِ أَوْ سَاعَةٍ، ثُمَّ إِنْ عَاوَدَهَا دَمٌ أَوْ رَأَتْ صُفْرَةً أَوْ كُدْرَةً تَرَكَتِ الصَّلَاةَ،"]]},{"id":"ri3_9","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ٩","segs":[["matn","ثُمَّ إِذَا انْقَطَعَ عَنْهَا اغْتَسَلَتْ، وَصَلَّتْ، وَلَكِنَّ ذَلِكَ كُلَّهُ كَدَمٍ وَاحِدٍ فِي الْعِدَّةِ وَالِاسْتِبْرَاءِ حَتَّى يَبْعُدَ مَا بَيْنَ الدَّمَيْنِ مِثْلُ ثَمَانِيَةِ أَيَّامٍ أَوْ عَشَرَةٍ؛ فَيَكُونُ حَيْضًا مُؤْتَنَفًا."]]},{"id":"ri3_10","label":"بَابُ مَا يَجِبُ مِنْهُ الْوُضُوءُ وَالْغُسْلُ · ١٠","segs":[["matn","وَمَنْ تَمَادَى بِهَا الدَّمُ بَلَغَتْ خَمْسَةَ عَشَرَ يَوْمًا، ثُمَّ هِيَ مُسْتَحَاضَةٌ: تَتَطَهَّرُ، وَتَصُومُ وَتُصَلِّي، وَيَأْتِيهَا زَوْجُهَا، وَإِذَا انْقَطَعَ دَمُ النُّفَسَاءِ وَإِنْ كَانَ قُرْبَ الْوِلَادَةِ اغْتَسَلَتْ وَصَلَّتْ، وَإِنْ تَمَادَى بِهَا الدَّمُ جَلَسَتْ سِتِّينَ لَيْلَةً، ثُمَّ اغْتَسَلَتْ، وَكَانَتْ مُسْتَحَاضَةً تُصَلِّي وَتَصُومُ وَتُوطَأُ."]]}]},{"id":"ri4","title":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ","units":[{"id":"ri4_1","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ١","segs":[["matn","وَالْمُصَلِّي يُنَاجِي رَبَّهُ؛ فَعَلَيْهِ أَنْ يَتَأَهَّبَ لِذَلِكَ بِالْوُضُوءِ أَوْ بِالطُّهْرِ إِنْ وَجَبَ عَلَيْهِ الطُّهْرُ، وَيَكُونُ ذَلِكَ بِمَاءٍ طَاهِرٍ غَيْرِ مَشُوبٍ بِنَجَاسَةٍ، وَلَا بِمَاءٍ قَدْ تَغَيَّرَ لَوْنُهُ لِشَيْءٍ خَالَطَهُ مِنْ شَيْءٍ نَجِسٍ أَوْ طَاهِرٍ،"]]},{"id":"ri4_2","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ٢","segs":[["matn","إِلَّا مَا غَيَّرَتْ لَوْنَهُ الْأَرْضُ الَّتِي هُوَ بِهَا مِنْ سَبِخَةٍ أَوْ حَمْأَةٍ أَوْ نَحْوِهِمَا، وَمَاءُ السَّمَاءِ وَمَاءُ الْعُيُونِ وَمَاءُ الْآبَارِ وَمَاءُ الْبَحْرِ طَيِّبٌ طَاهِرٌ مُطَهِّرٌ لِلنَّجَاسَاتِ."]]},{"id":"ri4_3","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ٣","segs":[["matn","وَمَاءٌ غُيِّرَ لَوْنُهُ بِشَيْءٍ طَاهِرٍ حَلَّ فِيهِ؛ فَذَلِكَ الْمَاءُ طَاهِرٌ غَيْرُ مُطَهِّرٍ فِي وُضُوءٍ أَوْ طُهْرٍ أَوْ زَوَالِ نَجَاسَةٍ."]]},{"id":"ri4_4","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ٤","segs":[["matn","وَمَا غَيَّرَتْهُ النَّجَاسَةُ فَلَيْسَ بِطَاهِرٍ وَلَا مُطَهِّرٍ، وَقَلِيلُ الْمَاءِ يُنَجِّسُهُ قَلِيلُ النَّجَاسَةِ وَإِنْ لَمْ تُغَيِّرْهُ."]]},{"id":"ri4_5","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ٥","segs":[["matn","وَقِلَّةُ الْمَاءِ مَعَ إِحْكَامِ الْغُسْلِ سُنَّةٌ، وَالسَّرَفُ مِنْهُ غُلُوٌّ وَبِدْعَةٌ، وَقَدْ تَوَضَّأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمُدٍّ، وَهُوَ وَزْنُ رِطْلٍ وَثُلُثٍ، وَتَطَهَّرَ بِصَاعٍ، وَهُوَ أَرْبَعَةُ أَمْدَادٍ بِمُدِّهِ."]]},{"id":"ri4_6","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ٦","segs":[["matn","عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ. وَطَهَارَةُ الْبُقْعَةِ لِلصَّلَاةِ وَاجِبَةٌ، وَكَذَلِكَ طَهَارَةُ الثَّوْبِ، فَقِيلَ: إِنَّ ذَلِكَ فِيهِمَا وَاجِبٌ وُجُوبَ الْفَرَائِضِ، وَقِيلَ: وُجُوبَ السُّنَنِ الْمُؤَكَّدَةِ."]]},{"id":"ri4_7","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ٧","segs":[["matn","وَيُنْهَى عَنِ الصَّلَاةِ فِي مَعَاطِنِ الْإِبِلِ وَمَحَجَّةِ الطَّرِيقِ وَظَهْرِ بَيْتِ اللَّهِ الْحَرَامِ وَالْحَمَّامِ حَيْثُ لَا يُوقَنُ مِنْهُ بِطَهَارَةٍ وَالْمَزْبَلَةِ وَالْمَجْزَرَةِ وَمَقْبَرَةِ الْمُشْرِكِينَ وَكَنَائِسِهِمْ."]]},{"id":"ri4_8","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ٨","segs":[["matn","وَأَقَلُّ مَا يُصَلِّي فِيهِ الرَّجُلُ مِنَ اللِّبَاسِ ثَوْبٌ سَاتِرٌ مِنْ دِرْعٍ أَوْ رِدَاءٍ، وَالدِّرْعُ: الْقَمِيصُ، وَيُكْرَهُ أَنْ يُصَلِّيَ بِثَوْبٍ لَيْسَ عَلَى أَكْتَافِهِ مِنْهُ شَيْءٌ، فَإِنْ فَعَلَ لَمْ يُعِدْ."]]},{"id":"ri4_9","label":"بَابُ طَهَارَةِ الْمَاءِ وَالثَّوْبِ وَالْبُقْعَةِ وَمَا يُجْزِئُ مِنَ اللِّبَاسِ فِي الصَّلَاةِ · ٩","segs":[["matn","وَأَقَلُّ مَا يُجْزِئُ الْمَرْأَةَ مِنَ اللِّبَاسِ فِي الصَّلَاةِ الدِّرْعُ الْحَصِيفُ السَّابِغُ الَّذِي يَسْتُرُ ظُهُورَ قَدَمَيْهَا وَخِمَارٌ تَتَقَنَّعُ بِهِ، وَتُبَاشِرُ بِكَفَّيْهَا الْأَرْضَ فِي السُّجُودِ مِثْلَ الرَّجُلِ."]]}]},{"id":"ri5","title":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ","units":[{"id":"ri5_1","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١","segs":[["matn","وَلَيْسَ الِاسْتِنْجَاءُ مِمَّا يَجِبُ أَنْ يُوصَلَ بِهِ الْوُضُوءُ لَا فِي سُنَنِ الْوُضُوءِ وَلَا فِي فَرَائِضِهِ، وَهُوَ مِنْ بَابِ إِيجَابِ زَوَالِ النَّجَاسَةِ بِهِ أَوْ بِالِاسْتِجْمَارِ: لِئَلَّا يُصَلِّيَ بِهَا فِي جَسَدِهِ، وَيُجْزِئُ فِعْلُهُ بِغَيْرِ نِيَّةٍ، وَكَذَلِكَ غَسْلُ الثَّوْبِ النَّجِسِ."]]},{"id":"ri5_2","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢","segs":[["matn","وَصِفَةُ الِاسْتِنْجَاءِ أَنْ يَبْدَأَ بَعْدَ غَسْلِ يَدِهِ فَيَغْسِلَ مَخْرَجَ الْبَوْلِ، ثُمَّ يَمْسَحَ مَا فِي الْمَخْرَجِ مِنَ الْأَذَى بِمَدَرٍ أَوْ غَيْرِهِ أَوْ بِيَدِهِ، ثُمَّ يَحُكَّهَا بِالْأَرْضِ،"]]},{"id":"ri5_3","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٣","segs":[["matn","وَيَغْسِلَهَا، ثُمَّ يَسْتَنْجِيَ بِالْمَاءِ، وَيُوَاصِلَ صَبَّهُ، وَيَسْتَرْخِيَ قَلِيلًا، وَيُجِيدَ عَرْكَ ذَلِكَ بِيَدِهِ حَتَّى يَتَنَظَّفَ، وَلَيْسَ عَلَيْهِ غَسْلُ مَا بَطَنَ مِنَ الْمَخْرَجَيْنِ، وَلَا يَسْتَنْجِي مِنْ رِيحٍ."]]},{"id":"ri5_4","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٤","segs":[["matn","وَمَنِ اسْتَجْمَرَ بِثَلَاثَةِ أَحْجَارٍ يَخْرُجُ آخِرُهُنَّ نَقِيًّا أَجْزَأَهُ، وَالْمَاءُ أَطْهَرُ وَأَطْيَبُ وَأَحَبُّ إِلَى الْعُلَمَاءِ."]]},{"id":"ri5_5","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٥","segs":[["matn","وَمَنْ لَمْ يَخْرُجْ مِنْهُ بَوْلٌ وَلَا غَائِطٌ، وَتَوَضَّأَ لِحَدَثٍ أَوْ نَوْمٍ أَوْ لِغَيْرِ ذَلِكَ مِمَّا يُوجِبُ الْوُضُوءَ فَلَا بُدَّ مِنْ غَسْلِ يَدَيْهِ قَبْلَ إِدْخَالِهِمَا فِي الْإِنَاءِ."]]},{"id":"ri5_6","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٦","segs":[["matn","وَمِنْ سُنَّةِ الْوُضُوءِ غَسْلُ الْيَدَيْنِ قَبْلَ إِدْخَالِهِمَا فِي الْإِنَاءِ، وَالْمَضْمَضَةُ وَالِاسْتِنْشَاقُ وَالِاسْتِنْثَارُ وَمَسْحُ الْأُذُنَيْنِ سَنَةٌ، وَبَاقِيهِ فَرِيضَةٌ."]]},{"id":"ri5_7","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٧","segs":[["matn","فَمَنْ قَامَ إِلَى وُضُوءٍ مِنْ نَوْمٍ أَوْ غَيْرِهِ فَقَدْ قَالَ بَعْضُ الْعُلَمَاءِ: يَبْدَأُ فَيُسَمِّي اللَّهَ، وَلَمْ يَرَهُ بَعْضُهُمْ مِنَ الْأَمْرِ الْمَعْرُوفِ، وَكَوْنُ الْإِنَاءِ عَلَى يَمِينِهِ أَمْكَنُ لَهُ فِي تَنَاوُلِهِ."]]},{"id":"ri5_8","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٨","segs":[["matn","وَيَبْدَأُ فَيَغْسِلُ يَدَيْهِ قَبْلَ أَنْ يُدْخِلَهُمَا فِي الْإِنَاءِ ثَلَاثًا، فَإِنْ كَانَ قَدْ بَالَ أَوْ تَغَوَّطَ غَسَلَ ذَلِكَ مِنْهُ، ثُمَّ تَوَضَّأَ، ثُمَّ يُدْخِلُ يَدَهُ فِي الْإِنَاءِ فَيَأْخُذُ الْمَاءَ، فَيُمَضْمِضُ فَاهُ ثَلَاثًا مِنْ غَرْفَةٍ وَاحِدَةٍ إِنْ شَاءَ أَوْ ثَلَاثِ غَرَفَاتٍ،"]]},{"id":"ri5_9","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٩","segs":[["matn","وَإِنِ اسْتَاكَ بِأُصْبُعِهِ فَحَسَنٌ، ثُمَّ يَسْتَنْشِقُ بِأَنْفِهِ الْمَاءَ، وَيَسْتَنْثِرُهُ ثَلَاثًا: يَجْعَلُ يَدَهُ عَلَى أَنْفِهِ كَامْتِخَاطِهِ، وَيُجْزِئُهُ أَقَلُّ مِنْ ثَلَاثٍ فِي الْمَضْمَضَةِ وَالِاسْتِنْشَاقِ، وَلَهُ جَمْعُ ذَلِكَ فِي غَرْفَةٍ وَاحِدَةٍ، وَالنِّهَايَةُ أَحْسَنُ."]]},{"id":"ri5_10","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٠","segs":[["matn","ثُمَّ يَأْخُذُ الْمَاءَ إِنْ شَاءَ بِيَدَيْهِ جَمِيعًا، وَإِنْ شَاءَ بِيَدِهِ الْيُمْنَى، فَيَجْعَلُهُ فِي يَدَيْهِ جَمِيعًا، ثُمَّ يَنْقُلُهُ إِلَى وَجْهِهِ،"]]},{"id":"ri5_11","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١١","segs":[["matn","فَيُفْرِغُهُ عَلَيْهِ غَاسِلًا لَهُ بِيَدَيْهِ مِنْ أَعْلَى جَبْهَتِهِ وَحَدُّهُ مَنَابِتِ شَعْرِ رَأْسِهِ إِلَى طَرَفِ ذَقَنِهِ وَدَوْرُ وَجْهِهِ كُلِّهِ مِنْ حَدِّ عَظْمَيْ لَحْيَيْهِ إِلَى صُدْغَيْهِ،"]]},{"id":"ri5_12","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٢","segs":[["matn","وَيُمِرُّ يَدَيْهِ عَلَى مَا غَارَ مِنْ ظَاهِرِ أَجْفَانِهِ وَأَسَارِيرِ جَبْهَتِهِ وَمَا تَحْتَ مَارِنِهِ مِنْ ظَاهِرِ أَنْفِهِ؛ يَغْسِلُ وَجْهَهُ هَكَذَا ثَلَاثًا، يَنْقُلُ الْمَاءَ إِلَيْهِ."]]},{"id":"ri5_13","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٣","segs":[["matn","وَيُحَرِّكُ لِحْيَتَهُ فِي غَسْلِ وَجْهِهِ بِكَفَّيْهِ لِيُدَاخِلَهَا الْمَاءُ لِدَفْعِ الشَّعْرِ لِمَا يُلَاقِيِهِ مِنَ الْمَاءِ، وَلَيْسَ عَلَيْهِ تَخْلِيلُهَا فِي الْوُضُوءِ فِي قَوْلِ مَالِكٍ، وَيُجْرِيَ عَلَيْهَا يَدَيْهِ إِلَى آخِرِهَا."]]},{"id":"ri5_14","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٤","segs":[["matn","ثُمَّ يَغْسِلُ يَدَهُ الْيُمْنَى ثَلَاثًا أَوِ اثْنَتَيْنِ، يُفِيضُ عَلَيْهَا الْمَاءَ، وَيَعْرُكُهَا بِيَدِهِ الْيُسْرَى، وَيُخَلِّلُ أَصَابِعَ يَدَيْهِ بَعْضَهَا بِبَعْضٍ، ثُمَّ يَغْسِلُ الْيُسْرَى كَذَلِكَ."]]},{"id":"ri5_15","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٥","segs":[["matn","وَيَبْلُغُ فِيهِمَا بِالْغَسْلِ إِلَى الْمِرْفَقَيْنِ، يُدْخِلُهُمَا فِي غَسْلِهِ، وَقَدْ قِيلَ: إِلَيْهِمَا حَدُّ الْغَسْلِ؛ فَلَيْسَ بِوَاجِبٍ إِدْخَالُهُمَا فِيهِ، وَإِدْخَالُهُمَا فِيهِ أَحْوَطُ لِزَوَالِ تَكَلُّفِ التَّحْدِيدِ."]]},{"id":"ri5_16","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٦","segs":[["matn","ثُمَّ يَأْخُذُ الْمَاءَ بِيَدِهِ الْيُمْنَى، فَيُفْرِغُهُ عَلَى بَاطِنِ يَدِهِ الْيُسْرَى، ثُمَّ يَمْسَحُ بِهِمَا رَأْسَهُ، يَبْدَأُ مِنْ مُقَدَّمِهِ مِنْ أَوَّلِ مَنَابِتِ شَعْرِ رَأْسِهِ، وَقَدْ قَرَنَ أَطْرَافَ أَصَابِعِ يَدَيْهِ بَعْضَهَا بِبَعْضٍ عَلَى رَأْسِهِ، وَجَعَلَ إِبْهَامَيْهِ عَلَى صُدْغَيْهِ،"]]},{"id":"ri5_17","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٧","segs":[["matn","ثُمَّ يَذْهَبُ بِيَدَيْهِ مَاسِحًا إِلَى طَرَفِ شَعْرِ رَأْسِهِ مِمَّا يَلِي قَفَاهُ، ثُمَّ يَرُدُّهُمَا إِلَى حَيْثُ بَدَأَ، وَيَأْخُذُ بِإِبْهَامَيْهِ خَلْفَ أُذُنَيْهِ إِلَى صُدْغَيْهِ،"]]},{"id":"ri5_18","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٨","segs":[["matn","وَكَيْفَمَا مَسَحَ أَجْزَأَهُ إِذَا أَوْعَبَ رَأْسَهُ، وَالْأَوَّلُ أَحْسَنُ، وَلَوْ أَدْخَلَ يَدَيْهِ فِي الْإِنَاءِ، ثُمَّ رَفَعَهُمَا مَبْلُولَتَيْنِ، وَمَسَحَ بِهِمَا رَأْسَهُ أَجْزَأَهُ."]]},{"id":"ri5_19","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ١٩","segs":[["matn","ثُمَّ يُفْرِغُ الْمَاءَ عَلَى سَبَّابَتَيْهِ وَإِبْهَامَيْهِ، وَإِنْ شَاءَ غَمَسَ ذَلِكَ فِي الْمَاءِ، ثُمَّ يَمْسَحُ أُذُنَيْهِ ظَاهِرَهُمَا وَبَاطِنَهُمَا."]]},{"id":"ri5_20","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٠","segs":[["matn","وَتَمْسَحُ الْمَرْأَةُ كَمَا ذَكَرْنَا، وَتَمْسَحُ عَلَى دَلَالَيْهَا، وَلَا تَمْسَحُ عَلَى الْوِقَايَةِ، وَتُدْخِلُ يَدَيْهَا مِنْ تَحْتِ عِقَاصِ شَعْرِهَا فِي رُجُوعِ يَدَيْهَا فِي الْمَسْحِ."]]},{"id":"ri5_21","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢١","segs":[["matn","ثُمَّ يَغْسِلُ رِجْلَيْهِ، يَصُبُّ الْمَاءَ بِيَدِهِ الْيُمْنَى عَلَى رِجْلِهِ الْيُمْنَى، وَيَعْرُكُهَا بِيَدِهِ الْيُسْرَى قَلِيلًا قَلِيلًا يُوعِبُهَا بِذَلِكَ ثَلَاثًا، وَإِنْ شَاءَ خَلَّلَ أَصَابِعَهُ فِي ذَلِكَ،"]]},{"id":"ri5_22","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٢","segs":[["matn","وَإِنْ تَرَكَ فَلَا حَرَجَ، وَالتَّخْلِيلُ أَطْيَبُ لِلنَّفْسِ، وَيَعْرُكُ عَقِبَيْهِ وَعُرْقُوبَيْهِ وَمَا لَا يَكَادُ يُدَاخِلُهُ الْمَاءُ بِسُرْعَةٍ مِنْ جَسَاوَةٍ أَوْ شُقُوقٍ، فَلْيُبَالِغْ بِالْعَرْكِ مَعَ صَبِّ الْمَاءِ بِيَدِهِ؛"]]},{"id":"ri5_23","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٣","segs":[["matn","فَإِنَّهُ جَاءَ الْأَثَرُ: «وَيْلٌ لِلْأَعْقَابِ مِنَ النَّارِ»، وَعَقِبُ الشَّيْءِ: طَرَفُهُ وَآخِرُهُ، ثُمَّ يَغْسِلُ الْيُسْرَى مِثْلَ ذَلِكَ."]]},{"id":"ri5_24","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٤","segs":[["matn","وَلَيْسَ تَحْدِيدُ غَسْلِ أَعْضَائِهِ ثَلَاثًا ثَلَاثًا بِأَمْرٍ لَا يُجْزِئُ دُونَهُ، وَلَكِنَّهُ أَكْثَرُ مَا يَفْعَلُ، وَمَنْ كَانَ يُوعِبُ بِأَقَلَّ مِنْ ذَلِكَ أَجْزَأَهُ إِذَا أَحْكَمَ ذَلِكَ، وَلَيْسَ كُلُّ النَّاسِ فِي إِحْكَامِ ذَلِكَ سَوَاءً."]]},{"id":"ri5_25","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٥","segs":[["matn","وَقَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"ri5_26","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٦","segs":[["matn","«مَنْ تَوَضَّأَ فَأَحْسَنَ الْوُضُوءَ، ثُمَّ رَفَعَ طَرْفَهُ إِلَى السَّمَاءِ، فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ فُتِحَتْ لَهُ أَبْوَابُ الْجَنَّةِ الثَّمَانِيَةُ يَدْخُلُ مِنْ أَيِّهَا شَاءَ»،"]]},{"id":"ri5_27","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٧","segs":[["matn","وَقَدِ اسْتَحَبَّ بَعْضُ الْعُلَمَاءِ أَنْ يَقُولَ بِأَثَرِ الْوُضُوءِ: «اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ، وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ»."]]},{"id":"ri5_28","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٨","segs":[["matn","وَيَجِبُ عَلَيْهِ أَنْ يَعْمَلَ عَمَلَ الْوُضُوءِ احْتِسَابًا لِلَّهِ تَعَالَى لِمَا أَمَرَهُ بِهِ يَرْجُو تَقَبُّلَهُ وَثَوَابَهُ وَتَطْهِيرَهُ مِنَ الذُّنُوبِ، بِهِ وَيُشْعِرُ نَفْسَهُ أَنَّ ذَلِكَ تَأَهُّبٌ وَتَنَظُّفٌ لِمُنَاجَاةِ رَبِّهِ وَالْوُقُوفِ بَيْنَ يَدَيْهِ لِأَدَاءِ فَرَائِضِهِ وَالْخُضُوعِ لَهُ بِالرُّكُوعِ وَالسُّجُودِ؛"]]},{"id":"ri5_29","label":"بَابُ صِفَةِ الْوُضُوءِ وَمَسْنُونِهِ وَمَفْرُوضِهِ وَذِكْرِ الِاسْتِنْجَاءِ وَالِاسْتِجْمَارِ · ٢٩","segs":[["matn","فَيَعْمَلُ عَلَى يَقِينٍ بِذَلِكَ وَتَحَفُّظٍ فِيهِ؛ فَإِنَّ تَمَامَ كُلِّ عَمَلٍ بِحُسْنِ النِّيَّةِ فِيهِ."]]}]},{"id":"ri6","title":"بَابٌ فِي الْغُسْلِ","units":[{"id":"ri6_1","label":"بَابٌ فِي الْغُسْلِ · ١","segs":[["matn","أَمَّا الطُّهْرُ فَهُوَ مِنَ الْجَنَابَةِ وَمِنَ الْحَيْضَةِ وَالنِّفَاسِ سَوَاءٌ فَإِنِ اقْتَصَرَ الْمُتَطَهِّرُ عَلَى الْغُسْلِ دُونَ الْوُضُوءِ أَجْزَأَهُ،"]]},{"id":"ri6_2","label":"بَابٌ فِي الْغُسْلِ · ٢","segs":[["matn","وَأَفْضَلُ لَهُ أَنْ يَتَوَضَّأَ بَعْدَ أَنْ يَبْدَأَ بِغَسْلِ مَا بِفَرْجِهِ أَوْ جَسَدِهِ مِنَ الْأَذَى، ثُمَّ يَتَوَضَّأُ وُضُوءَ الصَّلَاةِ، فَإِنْ شَاءَ غَسَلَ رِجْلَيْهِ، وَإِنْ شَاءَ أَخَّرَهُمَا إِلَى آخِرِ غُسْلِهِ."]]},{"id":"ri6_3","label":"بَابٌ فِي الْغُسْلِ · ٣","segs":[["matn","ثُمَّ يَغْمِسُ يَدَيْهِ فِي الْإِنَاءِ، وَيَرْفَعُهُمَا غَيْرَ قَابِضٍ بِهِمَا شَيْئًا، فَيُخَلِّلُ بِهِمَا أُصُولَ شَعْرِ رَأْسِهِ، ثُمَّ يَغْرِفُ بِهِمَا عَلَى رَأْسِهِ ثَلَاثَ غَرَفَاتٍ غَاسِلًا لَهُ بِهِنَّ، وَتَفْعَلُ ذَلِكَ الْمَرْأَةُ، وَتَضْغَثُ شَعْرَ رَأْسِهَا وَلَيْسَ عَلَيْهَا حَلُّ عِقَاصِهَا."]]},{"id":"ri6_4","label":"بَابٌ فِي الْغُسْلِ · ٤","segs":[["matn","ثُمَّ يُفِيضُ الْمَاءَ عَلَى شِقِّهِ الْأَيْمَنِ ثُمَّ عَلَى شِقِّهِ الْأَيْسَرِ، وَيَتَدَلَّكُ بِيَدَيْهِ بِأَثَرِ صَبِّ الْمَاءِ حَتَّى يَعُمَّ جَسَدَهُ، وَمَا شَكَّ أَنْ يَكُونَ الْمَاءُ أَخَذَهُ مِنْ جَسَدِهِ عَاوَدَهُ بِالْمَاءِ، وَدَلَكَهُ بِيَدِهِ حَتَّى يُوعِبَ جَمِيعَ جَسَدِهِ،"]]},{"id":"ri6_5","label":"بَابٌ فِي الْغُسْلِ · ٥","segs":[["matn","وَيُتَابِعُ عُمْقَ سُرَّتِهِ وَتَحْتَ حَلْقِهِ، وَيُخَلِّلُ شَعْرَ لِحْيَتِهِ وَتَحْتَ جَنَاحَيْهِ وَبَيْنَ أَلْيَتَيْهِ وَرُفْغَيْهِ وَتَحْتَ رُكْبَتَيْهِ وَأَسَافِلَ رِجْلَيْهِ، وَيُخَلِّلُ أَصَابِعَ يَدَيْهِ، وَيَغْسِلُ رِجْلَيْهِ آخِرَ ذَلِكَ، يَجْمَعُ ذَلِكَ فِيهِمَا لِتَمَامِ غُسْلِهِ وَلِتَمَامِ وُضُوئِهِ إِنْ كَانَ أَخَّرَ غَسْلَهُمَا."]]},{"id":"ri6_6","label":"بَابٌ فِي الْغُسْلِ · ٦","segs":[["matn","وَيَحْذَرُ أَنْ يَمَسَّ ذَكَرَهُ فِي تَدَلُّكِهِ بِبَاطِنِ كَفِّهِ، فَإِنْ فَعَلَ ذَلِكَ وَقَدْ أَوْعَبَ طُهْرَهُ أَعَادَ الْوُضُوءَ،"]]},{"id":"ri6_7","label":"بَابٌ فِي الْغُسْلِ · ٧","segs":[["matn","وَإِنْ مَسَّهُ فِي ابْتِدَاءِ غُسْلِهِ وَبَعْدَ أَنْ غَسَلَ مَوَاضِعَ الْوُضُوءِ مِنْهُ فَلْيُمِرَّ بَعْدَ ذَلِكَ بِيَدَيْهِ عَلَى مَوَاضِعِ الْوُضُوءِ بِالْمَاءِ عَلَى مَا يَنْبَغِي مِنْ ذَلِكَ، وَيَنْوِيهِ."]]}]},{"id":"ri7","title":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ","units":[{"id":"ri7_1","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ١","segs":[["matn","التَّيَمُّمُ يَجِبُ لِعَدَمِ الْمَاءِ فِي السَّفَرِ إِذَا يَئِسَ أَنْ يَجِدَهُ فِي الْوَقْتِ، وَقَدْ يَجِبُ مَعَ وُجُودِهِ إِذَا لَمْ يَقْدِرْ عَلَى مَسِّهِ فِي سَفَرٍ أَوْ حَضَرٍ لِمَرَضٍ مَانِعٍ،"]]},{"id":"ri7_2","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ٢","segs":[["matn","أَوْ مَرِيضٌ يَقْدِرُ عَلَى مَسِّهِ وَلَا يَجِدُ مَنْ يُنَاوِلُهُ إِيَّاهُ، وَكَذَلِكَ مُسَافِرٌ يَقْرُبُ مِنْهُ الْمَاءُ وَيَمْنَعُهُ مِنْهُ خَوْفُ لُصُوصٍ أَوْ سِبَاعٍ،"]]},{"id":"ri7_3","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ٣","segs":[["matn","وَإِذَا أَيْقَنَ الْمُسَافِرُ بِوُجُودِ الْمَاءِ فِي الْوَقْتِ أَخَّرَ إِلَى آخِرِهِ، وَإِنْ يَئِسَ مِنْهُ تَيَمَّمَ فِي أَوَّلِهِ، وَإِنْ لَمْ يَكُنْ عِنْدَهُ مِنْهُ عِلْمٌ تَيَمَّمَ فِي وَسَطِهِ، وَكَذَلِكَ إِنْ خَافَ أَنْ لَا يُدْرِكَ الْمَاءَ فِي الْوَقْتِ وَرَجَا أَنْ يُدْرِكَهُ فِيهِ."]]},{"id":"ri7_4","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ٤","segs":[["matn","وَمَنْ تَيَمَّمَ مِنْ هَؤُلَاءِ ثُمَّ أَصَابَ الْمَاءَ فِي الْوَقْتِ بَعْدَ أَنْ صَلَّى؛"]]},{"id":"ri7_5","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ٥","segs":[["matn","فَأَمَّا الْمَرِيضُ الَّذِي لَمْ يَجِدْ مَنْ يُنَاوِلُهُ إِيَّاهُ فَلْيُعِدْ، وَكَذَلِكَ الْخَائِفُ مِنْ سِبَاعٍ وَنَحْوِهَا، وَكَذَلِكَ الْمُسَافِرُ الَّذِي يَخَافُ أَنْ لَا يُدْرِكَ الْمَاءَ فِي الْوَقْتِ وَيَرْجُو أَنْ يُدْرِكَهُ فِيهِ، وَلَا يُعِيدُ غَيْرُ هَؤُلَاءِ."]]},{"id":"ri7_6","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ٦","segs":[["matn","وَلَا يُصَلِّي صَلَاتَيْنِ بِتَيَمُّمٍ وَاحِدٍ مِنْ هَؤُلَاءِ إِلَّا مَرِيضٌ لَا يَقْدِرُ عَلَى مَسِّ الْمَاءِ لِضَرَرٍ بِجِسْمِهِ مُقِيمٍ، وَقَدْ قِيلَ: يَتَيَمَّمُ لِكُلِّ صَلَاةٍ، وَقَدْ رُوِيَ عَنْ مَالِكٍ فِيمَنْ ذَكَرَ صَلَوَاتٍ أَنْ يُصَلِّيَهَا بِتَيَمُّمٍ وَاحِدٍ."]]},{"id":"ri7_7","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ٧","segs":[["matn","وَالتَّيَمُّمُ بِالصَّعِيدِ الطَّاهِرِ، وَهُوَ مَا ظَهَرَ عَلَى وَجْهِ الْأَرْضِ مِنْهَا: مِنْ تُرَابٍ أَوْ رَمْلٍ أَوْ حِجَارَةٍ أَوْ سَبَخَةٍ."]]},{"id":"ri7_8","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ٨","segs":[["matn","يَضْرِبُ بِيَدَيْهِ الْأَرْضَ فَإِنْ تَعَلَّقَ بِهِمَا شَيْءٌ نَفَضَهُمَا نَفْضًا خَفِيفًا، ثُمَّ يَمْسَحُ بِهِمَا وَجْهَهُ كُلَّهُ مَسْحًا، ثُمَّ يَضْرِبُ بِيَدَيْهِ الْأَرْضَ، فَيَمْسَحُ يُمْنَاهُ بِيُسْرَاهُ:"]]},{"id":"ri7_9","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ٩","segs":[["matn","يَجْعَلُ أَصَابِعَ يَدِهِ الْيُسْرَى عَلَى أَطْرَافِ أَصَابِعِ يَدِهِ الْيُمْنَى، ثُمَّ يُمِرُّ أَصَابِعَهُ عَلَى ظَاهِرِ يَدِهِ وَذِرَاعِهِ وَقَدْ حَنَى عَلَيْهِ أَصَابِعَهُ حَتَّى يَبْلُغَ الْمِرْفَقَيْنِ،"]]},{"id":"ri7_10","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ١٠","segs":[["matn","ثُمَّ يَجْعَلُ كَفَّهُ عَلَى بَاطِنِ ذِرَاعِهِ مِنْ طَيِّ مِرْفَقِهِ قَابِضًا عَلَيْهِ حَتَّى يَبْلُغَ الْكُوعَ مِنْ يَدِهِ الْيُمْنَى، ثُمَّ يُجْرِي بَاطِنَ بُهْمِهِ عَلَى ظَاهِرِ بُهْمِ يَدِهِ الْيُمْنَى،"]]},{"id":"ri7_11","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ١١","segs":[["matn","ثُمَّ يَمْسَحُ الْيُسْرَى بِالْيُمْنَى هَكَذَا، فَإِذَا بَلَغَ الْكُوعَ مَسَحَ كَفَّهُ الْيُمْنَى بِكَفِّهِ الْيُسْرَى إِلَى آخِرِ أَطْرَافِهِ، وَلَوْ مَسَحَ الْيُمْنَى بِالْيُسْرَى وَالْيُسْرَى بِالْيُمْنَى كَيْفَ شَاءَ وَتَيَسَّرَ عَلَيْهِ، وَأَوْعَبَ الْمَسْحَ لَأَجْزَأَهُ."]]},{"id":"ri7_12","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ١٢","segs":[["matn","وَإِذَا لَمْ يَجِدِ الْجُنُبُ أَوِ الْحَائِضُ الْمَاءَ لِلطُّهْرِ تَيَمَّمَا وَصَلَّيَا، فَإِذَا وَجَدَا الْمَاءَ تَطَهَّرَا وَلَمْ يُعِيدَا مَا صَلَّيَا،"]]},{"id":"ri7_13","label":"بَابٌ فِي مَنْ لَمْ يَجِدِ الْمَاءَ وَصِفَةِ التَّيَمُّمِ · ١٣","segs":[["matn","وَلَا يَطَأُ الرَّجُلُ امْرَأَتَهُ الَّتِي انْقَطَعَ عَنْهَا دَمُ حَيْضٍ أَوْ نِفَاسٍ بِالتَّطَهُّرِ بِالتَّيَمُّمِ حَتَّى يَجِدَ مِنَ الْمَاءِ مَا تَتَطَهَّرُ بِهِ الْمَرْأَةُ ثُمَّ مَا يَتَطَهَّرَانِ بِهِ جَمِيعًا، وَفِي بَابِ جَامِعِ الصَّلَاةِ شَيْءٌ مِنْ مَسَائِلِ التَّيَمُّمِ."]]}]},{"id":"ri8","title":"بَابٌ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ","units":[{"id":"ri8_1","label":"بَابٌ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ · ١","segs":[["matn","وَلَهُ أَنْ يَمْسَحَ عَلَى الْخُفَّيْنِ فِي الْحَضَرِ وَالسَّفَرِ مَا لَمْ يَنْزِعْهُمَا، وَذَلِكَ إِذَا أَدْخَلَ فِيهِمَا رِجْلَيْهِ بَعْدَ أَنْ غَسَلَهُمَا فِي وُضُوءٍ تَحِلُّ بِهِ الصَّلَاةُ، فَهَذَا الَّذِي إِذَا أَحْدَثَ وَتَوَضَّأَ مَسَحَ عَلَيْهِمَا، وَإِلَّا فَلَا."]]},{"id":"ri8_2","label":"بَابٌ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ · ٢","segs":[["matn","وَصِفَةُ الْمَسْحِ أَنْ يَجْعَلَ يَدَهُ الْيُمْنَى مِنْ فَوْقِ الْخُفِّ مِنْ طَرَفِ الْأَصَابِعِ، وَيَدَهُ الْيُسْرَى مِنْ تَحْتِ ذَلِكَ، ثُمَّ يَذْهَبُ بِيَدَيْهِ إِلَى حَدِّ الْكَعْبَيْنِ وَكَذَلِكَ يَفْعَلُ بِالْيُسْرَى،"]]},{"id":"ri8_3","label":"بَابٌ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ · ٣","segs":[["matn","وَيَجْعَلُ يَدَهُ الْيُسْرَى مِنْ فَوْقِهَا وَالْيُمْنَى مِنْ أَسْفَلِهَا، وَلَا يَمْسَحُ عَلَى طِينٍ فِي أَسْفَلِ خُفِّهِ أَوْ رَوْثِ دَابَّةٍ حَتَّى يُزِيلَهُ بِمَسْحٍ أَوْ غَسْلٍ، وَقِيلَ: يَبْدَأُ فِي مَسْحِ أَسْفَلِهِ مِنَ الْكَعْبَيْنِ إِلَى أَطْرَافِ الْأَصَابِعِ؛"]]},{"id":"ri8_4","label":"بَابٌ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ · ٤","segs":[["matn","لِئَلَّا يَصِلَ إِلَى عَقِبِ خُفِّهِ شَيْءٌ مِنْ رُطُوبَةِ مَا مَسَحَ مِنْ خُفَّيْهِ مِنَ الْقَشْبِ، وَإِنْ كَانَ فِي أَسْفَلِهِ طِينٌ فَلَا يَمْسَحُ عَلَيْهِ حَتَّى يُزِيلَهُ."]]}]},{"id":"ri9","title":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا","units":[{"id":"ri9_1","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ١","segs":[["matn","أَمَّا صَلَاةُ الصُّبْحِ فَهِيَ الصَّلَاةُ الْوُسْطَى عِنْدَ أَهْلِ الْمَدِينَةِ، وَهِيَ صَلَاةُ الْفَجْرِ فَأَوَّلُ وَقْتِهَا انْصِدَاعُ الْفَجْرِ الْمُعْتَرِضِ بِالضِّيَاءِ فِي أَقْصَى الْمَشْرِقِ ذَاهِبًا مِنَ الْقِبْلَةِ إِلَى دُبُرِ الْقِبْلَةِ حَتَّى يَرْتَفِعَ فَيَعُمَّ الْأُفُقَ،"]]},{"id":"ri9_2","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ٢","segs":[["matn","وَآخِرُ الْوَقْتِ الْإِسْفَارُ الْبَيِّنُ الَّذِي إِذَا سَلَّمَ مِنْهَا بَدَا حَاجِبُ الشَّمْسِ، وَمَا بَيْنَ هَذَيْنِ وَقْتٌ وَاسِعٌ، وَأَفْضَلُ ذَلِكَ أَوَّلُهُ."]]},{"id":"ri9_3","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ٣","segs":[["matn","وَوَقْتُ الظُّهْرِ إِذَا زَالَتِ الشَّمْسُ عَنْ كَبِدِ السَّمَاءِ وَأَخَذَ الظِّلُّ فِي الزِّيَادَةِ، وَيُسْتَحَبُّ أَنْ تُؤَخَّرَ فِي الصَّيْفِ إِلَى أَنْ يَزِيدَ ظِلُّ كُلِّ شَيْءٍ رُبُعُهُ بَعْدَ الظِّلِّ الَّذِي زَالَتْ عَلَيْهِ الشَّمْسُ، وَقِيلَ: إِنَّمَا يُسْتَحَبُّ ذَلِكَ فِي الْمَسَاجِدِ لِيُدْرِكَ النَّاسُ الصَّلَاةَ،"]]},{"id":"ri9_4","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ٤","segs":[["matn","وَأَمَّا الرَّجُلُ فِي خَاصَّةِ نَفْسِهِ فَأَوَّلُ الْوَقْتِ أَفْضَلُ لَهُ، وَقِيلَ: أَمَّا فِي شِدَّةِ الْحَرِّ فَالْأَفْضَلُ لَهُ أَنْ يُبْرِدَ بِهَا وَإِنْ كَانَ وَحْدَهُ لِقَوْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:"]]},{"id":"ri9_5","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ٥","segs":[["matn","«أَبْرِدُوا بِالصَّلَاةِ؛ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ»، وَآخِرُ الْوَقْتِ أَنْ يَصِيرَ ظِلُّ كُلِّ شَيْءٍ مِثْلَهُ بَعْدَ ظِلِّ نِصْفِ النَّهَارِ."]]},{"id":"ri9_6","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ٦","segs":[["matn","وَأَوَّلُ وَقْتِ الْعَصْرِ آخِرُ وَقْتِ الظُّهْرِ، وَآخِرُهُ أَنْ يَصِيرَ ظِلُّ كُلِّ شَيْءٍ مِثْلَيْهِ بَعْدَ ظِلِّ نِصْفِ النَّهَارِ، وَقِيلَ: إِذَا اسْتَقْبَلْتَ الشَّمْسَ بِوَجْهِكَ وَأَنْتَ قَائِمٌ غَيْرُ مُنَكِّسٍ رَأْسَكَ وَلَا مُطَأْطِئٍ لَهُ فَإِنْ نَظَرْتَ إِلَى الشَّمْسِ بِبَصَرِكَ فَقَدْ دَخَلَ الْوَقْتُ،"]]},{"id":"ri9_7","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ٧","segs":[["matn","وَإِنْ لَمْ تَرَهَا بِبَصَرِكَ فَلَمْ يَدْخُلِ الْوَقْتُ، وَإِنْ نَزَلَتْ عَنْ بَصَرِكَ فَقَدْ تَمَكَّنَ دُخُولُ الْوَقْتِ، وَالَّذِي وَصَفَ مَالِكٌ رَحِمَهُ اللَّهُ أَنَّ الْوَقْتَ فِيهَا مَا لَمْ تَصْفَرَّ الشَّمْسُ."]]},{"id":"ri9_8","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ٨","segs":[["matn","وَوَقْتُ الْمَغْرِبِ وَهِيَ صَلَاةُ الشَّاهِدِ يَعْنِي الْحَاضِرَ، يَعْنِي أَنَّ الْمُسَافِرَ لَا يَقْصُرُهَا وَيُصَلِّيهَا كَصَلَاةِ الْحَاضِرِ فَوَقْتُهَا غُرُوبُ الشَّمْسِ."]]},{"id":"ri9_9","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ٩","segs":[["matn","فَإِذَا تَوَارَتْ بِالْحِجَابِ وَجَبَتِ الصَّلَاةُ لَا تُؤَخَّرُ، وَلَيْسَ لَهَا إِلَّا وَقْتٌ وَاحِدٌ لَا تُؤَخَّرُ عَنْهُ."]]},{"id":"ri9_10","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ١٠","segs":[["matn","وَوَقْتُ صَلَاةِ الْعَتَمَةِ وَهِيَ صَلَاةُ الْعِشَاءِ، وَهَذَا الِاسْمُ أَوْلَى بِهَا غَيْبُوبَةُ الشَّفَقِ، وَالشَّفَقُ الْحُمْرَةُ الْبَاقِيَةُ فِي الْمَغْرِبِ مِنْ بَقَايَا شُعَاعِ الشَّمْسِ، فَإِذَا لَمْ يَبْقَ فِي الْمَغْرِبِ صُفْرَةٌ وَلَا حُمْرَةٌ فَقَدْ وَجَبَ الْوَقْتُ،"]]},{"id":"ri9_11","label":"بَابٌ فِي أَوْقَاتِ الصَّلَاةِ وَأَسْمَائِهَا · ١١","segs":[["matn","وَلَا يُنْظَرُ إِلَى الْبَيَاضِ فِي الْمَغْرِبِ، فَذَلِكَ لَهَا وَقْتٌ إِلَى ثُلُثِ اللَّيْلِ مِمَّنْ يُرِيدُ تَأْخِيرَهَا لِشُغْلٍ أَوْ عُذْرٍ، وَالْمُبَادَرَةُ بِهَا أَوْلَى، وَلَا بَأْسَ أَنْ يُؤَخِّرَهَا أَهْلُ الْمَسَاجِدِ قَلِيلًا لِاجْتِمَاعِ النَّاسِ، وَيُكْرَهُ النَّوْمُ قَبْلَهَا وَالْحَدِيثُ لِغَيْرِ شُغْلٍ بَعْدَهَا."]]}]},{"id":"ri10","title":"بَابٌ فِي الْأَذَانِ وَالْإِقَامَةِ","units":[{"id":"ri10_1","label":"بَابٌ فِي الْأَذَانِ وَالْإِقَامَةِ · ١","segs":[["matn","وَالْأَذَانُ وَاجِبٌ فِي الْمَسَاجِدِ وَالْجَمَاعَاتِ الرَّاتِبَةِ، فَأَمَّا الرَّجُلُ فِي خَاصَّةِ نَفْسِهِ فَإِنْ أَذَّنَ فَحَسَنٌ، وَلَا بُدَّ لَهُ مِنَ الْإِقَامَةِ، وَأَمَّا الْمَرْأَةُ فَإِنْ أَقَامَتْ فَحَسَنٌ، وَإِلَّا فَلَا حَرَجَ، وَلَا يُؤَذَّنُ لِصَلَاةٍ قَبْلَ وَقْتِهَا إِلَّا الصُّبْحَ؛"]]},{"id":"ri10_2","label":"بَابٌ فِي الْأَذَانِ وَالْإِقَامَةِ · ٢","segs":[["matn","فَلَا بَأْسَ أَنْ يُؤَذَّنَ لَهَا فِي السُّدُسِ الْأَخِيرِ مِنَ اللَّيْلِ."]]},{"id":"ri10_3","label":"بَابٌ فِي الْأَذَانِ وَالْإِقَامَةِ · ٣","segs":[["matn","وَالْأَذَانُ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، ثُمَّ تُرَجِّعُ،"]]},{"id":"ri10_4","label":"بَابٌ فِي الْأَذَانِ وَالْإِقَامَةِ · ٤","segs":[["matn","بِأَرْفَعَ مِنْ صَوْتِكَ أَوَّلَ مَرَّةٍ، فَتُكَرِّرُ التَّشَهُّدَ فَتَقُولُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ حَيَّ عَلَى الصَّلَاةِ،"]]},{"id":"ri10_5","label":"بَابٌ فِي الْأَذَانِ وَالْإِقَامَةِ · ٥","segs":[["matn","حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، حَيَّ عَلَى الْفَلَاحِ، فَإِنْ كُنْتَ فِي نِدَاءِ الصُّبْحِ زِدْتَ هَهُنَا: الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ،"]]},{"id":"ri10_6","label":"بَابٌ فِي الْأَذَانِ وَالْإِقَامَةِ · ٦","segs":[["matn","الصَّلَاةُ خَيْرٌ مِنَ النَّوْمِ، لَا تَقُلْ ذَلِكَ فِي غَيْرِ نِدَاءِ الصُّبْحِ، اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ مَرَّةً وَاحِدَةً."]]},{"id":"ri10_7","label":"بَابٌ فِي الْأَذَانِ وَالْإِقَامَةِ · ٧","segs":[["matn","وَالْإِقَامَةُ وِتْرٌ: اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، أَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، حَيَّ عَلَى الصَّلَاةِ، حَيَّ عَلَى الْفَلَاحِ، قَدْ قَامَتِ الصَّلَاةُ، اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ،"]]}]},{"id":"ri11","title":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ","units":[{"id":"ri11_1","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١","segs":[["matn","وَالْإِحْرَامُ فِي الصَّلَاةِ أَنْ تَقُولَ: اللَّهُ أَكْبَرُ، لَا يُجْزِئُ غَيْرُ هَذِهِ الْكَلِمَةِ، وَتَرْفَعُ يَدَيْكَ حَذْوَ مَنْكِبَيْكَ أَوْ دُونَ ذَلِكَ، ثُمَّ تَقْرَأُ،"]]},{"id":"ri11_2","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢","segs":[["matn","فَإِنْ كُنْتَ فِي الصُّبْحِ قَرَأْتَ جَهْرًا بِأُمِّ الْقُرْآنِ، لَا تَسْتَفْتِحُ بِبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، فِي أُمِّ الْقُرْآنِ وَلَا فِي السُّورَةِ الَّتِي بَعْدَهَا."]]},{"id":"ri11_3","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣","segs":[["matn","فَإِذَا قُلْتَ: ﴿وَلَا الضَّالِّينَ﴾ فَقُلْ: آمِينَ إِنْ كُنْتَ وَحْدَكَ أَوْ خَلْفَ إِمَامٍ، وَتُخْفِيهَا. وَلَا يَقُولُهَا الْإِمَامُ فِيمَا جَهَرَ فِيهِ، وَيَقُولُهَا فِيمَا أَسَرَّ فِيهِ، وَفِي قَوْلِهِ إِيَّاهَا فِي الْجَهْرِ اخْتِلَافٌ."]]},{"id":"ri11_4","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤","segs":[["matn","ثُمَّ تَقْرَأُ سُورَةً مِنْ طِوَالِ الْمُفَصَّلِ، وَإِنْ كَانَتْ أَطْوَلَ مِنْ ذَلِكَ فَحَسَنٌ بِقَدْرِ التَّغْلِيسِ، وَتَجْهَرُ بِقِرَاءَتِهَا."]]},{"id":"ri11_5","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٥","segs":[["matn","فَإِذَا تَمَّتِ السُّورَةُ كَبَّرَتْ فِي انْحِطَاطِكَ لِلرُّكُوعِ فَتُمَكِّنُ يَدَيْكَ مِنْ رُكْبَتَيْكَ، وَتُسَوِّي ظَهْرَكَ مُسْتَوِيًا، وَلَا تَرْفَعُ رَأْسَكَ، وَلَا تُطَأْطِئُهُ، وَتُجَافِي بِضَبْعَيْكَ عَنْ جَنْبَيْكَ،"]]},{"id":"ri11_6","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٦","segs":[["matn","وَتَعْتَقِدُ الْخُضُوعَ بِذَلِكَ: بِرُكُوعِكَ وَسُجُودِكَ، وَلَا تَدْعُو فِي رُكُوعِكَ، وَقُلْ إِنْ شِئْتَ: سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ، وَلَيْسَ فِي ذَلِكَ تَوْقِيتُ قَوْلٍ، وَلَا حَدَّ فِي اللُّبْثِ."]]},{"id":"ri11_7","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٧","segs":[["matn","ثُمَّ تَرْفَعُ رَأْسَكَ وَأَنْتَ قَائِلٌ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، ثُمَّ تَقُولُ: اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ إِنْ كُنْتَ وَحْدَكَ، وَلَا يَقُولُهَا الْإِمَامُ، وَلَا يَقُولُ الْمَأْمُومُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، وَيَقُولُ: اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ، وَتَسْتَوِي قَائِمًا مُطْمَئِنًّا مُتَرَسِّلًا."]]},{"id":"ri11_8","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٨","segs":[["matn","ثُمَّ تَهْوِي سَاجِدًا لَا تَجْلِسُ، ثُمَّ تَسْجُدُ، وَتُكَبِّرُ فِي انْحِطَاطِكَ لِلسُّجُودِ، فَتُمَكِّنُ جَبْهَتَكَ وَأَنْفَكَ مِنَ الْأَرْضِ، وَتُبَاشِرُ بِكَفَّيْكَ الْأَرْضَ بَاسِطًا يَدَيْكَ مُسْتَوِيَتَيْنِ إِلَى الْقِبْلَةِ: تَجْعَلُهُمَا حَذْوَ أُذُنَيْكَ أَوْ دُونَ ذَلِكَ،"]]},{"id":"ri11_9","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٩","segs":[["matn","وَكُلُّ ذَلِكَ وَاسِعٌ، غَيْرَ أَنَّكَ لَا تَفْتَرِشُ ذِرَاعَيْكَ فِي الْأَرْضِ، وَلَا تَضُمُّ عَضُدَيْكَ إِلَى جَنْبَيْكَ، وَلَكِنْ تُجَنِّحُ بِهِمَا تَجْنِيحًا وَسَطًا، وَتَكُونُ رِجْلَاكَ فِي سُجُودِكَ قَائِمَتَيْنِ، وَبُطُونُ إِبْهَامَيْهِمَا إِلَى الْأَرْضِ."]]},{"id":"ri11_10","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٠","segs":[["matn","وَتَقُولُ إِنْ شِئْتَ فِي سُجُودِكَ: سُبْحَانَكَ رَبِّي ظَلَمْتُ نَفْسِي، وَعَمِلْتُ سُوءًا، فَاغْفِرْ لِي، أَوْ غَيْرَ ذَلِكَ إِنْ شِئْتَ، وَتَدْعُو فِي السُّجُودِ إِنْ شِئْتَ، وَلَيْسَ لِطُولِ ذَلِكَ وَقْتٌ، وَأَقَلُّهُ أَنْ تُطَمْئِنَ مَفَاصِلُكَ مُتَمَكِّنًا."]]},{"id":"ri11_11","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١١","segs":[["matn","ثُمَّ تَرْفَعُ رَأْسَكَ بِالتَّكْبِيرِ، فَتَجْلِسُ، فَتَثْنِي رِجْلَكَ الْيُسْرَى فِي جُلُوسِكَ بَيْنَ السَّجْدَتَيْنِ، وَتَنْصِبُ الْيُمْنَى وَبُطُونُ أَصَابِعِهَا إِلَى الْأَرْضِ، وَتَرْفَعُ يَدَيْكَ عَنِ الْأَرْضِ عَلَى رُكْبَتَيْكَ."]]},{"id":"ri11_12","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٢","segs":[["matn","ثُمَّ تَسْجُدُ الثَّانِيَةَ كَمَا فَعَلْتَ أَوَّلًا ثُمَّ تَقُومُ مِنَ الْأَرْضِ كَمَا أَنْتَ مُعْتَمِدًا عَلَى يَدَيْكَ، لَا تَرْجِعُ جَالِسًا لِتَقُومَ مِنْ جُلُوسٍ، وَلَكِنْ كَمَا ذَكَرْتُ لَكَ، وَتُكَبِّرُ فِي حَالِ قِيَامِكَ."]]},{"id":"ri11_13","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٣","segs":[["matn","ثُمَّ تَقْرَأُ كَمَا قَرَأْتَ فِي الْأُولَى أَوْ دُونَ ذَلِكَ، وَتَفْعَلُ مِثْلَ ذَلِكَ سَوَاءً غَيْرَ أَنَّكَ تَقْنُتُ بَعْدَ الرُّكُوعِ، وَإِنْ شِئْتَ قَنَتَّ قَبْلَ الرُّكُوعِ بَعْدَ تَمَامِ الْقِرَاءَةِ."]]},{"id":"ri11_14","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٤","segs":[["matn","وَالْقُنُوتُ: اللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ، وَنُؤْمِنُ بِكَ، وَنَتَوَكَّلُ عَلَيْكَ وَنَخْنَعُ لَكَ، وَنَخْلَعُ وَنَتْرُكُ مَنْ يَكْفُرُكَ، اللَّهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ،"]]},{"id":"ri11_15","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٥","segs":[["matn","وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخَافُ عَذَابَكَ الْجِدَّ، إِنَّ عَذَابَكَ بِالْكَافِرِينَ مُلْحِقٌ، ثُمَّ تَفْعَلُ فِي السُّجُودِ وَالْجُلُوسِ كَمَا تَقَدَّمَ مِنَ الْوَصْفِ."]]},{"id":"ri11_16","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٦","segs":[["matn","فَإِذَا جَلَسْتَ بَعْدَ السَّجْدَتَيْنِ نَصَبْتَ رِجْلَكَ الْيُمْنَى وَبُطُونُ أَصَابِعِهَا إِلَى الْأَرْضِ، وَثَنَيْتَ الْيُسْرَى، وَأَفْضَيْتَ بِأَلْيَتِكَ إِلَى الْأَرْضِ، وَلَا تَقْعُدُ عَلَى رِجْلِكَ الْيُسْرَى، وَإِنْ شِئْتَ حَنَيْتَ الْيُمْنَى فِي انْتِصَابِهَا؛ فَجَعَلْتَ جَنْبَ بُهْمِهَا إِلَى الْأَرْضِ فَوَاسِعٌ."]]},{"id":"ri11_17","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٧","segs":[["matn","ثُمَّ تَتَشَهَّدُ، وَالتَّشَهُّدُ: التَّحِيَّاتُ لِلَّهِ، الزَّاكِيَاتُ لِلَّهِ، الطَّيِّبَاتُ الصَّلَوَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ،"]]},{"id":"ri11_18","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٨","segs":[["matn","أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، فَإِنْ سَلَّمْتَ بَعْدَ هَذَا أَجُزْأَكَ."]]},{"id":"ri11_19","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ١٩","segs":[["matn","وَمِمَّا تَزِيدُهُ إِنْ شِئْتَ: وَأَشْهَدُ أَنَّ الَّذِي جَاءَ بِهِ مُحَمَّدٌ حَقٌّ، وَأَنَّ الْجَنَّةَ حَقٌّ، وَأَنَّ النَّارَ حَقٌّ، وَأَنَّ السَّاعَةَ آتِيَةٌ لَا رَيْبَ فِيهَا، وَأَنَّ اللَّهَ يَبْعَثُ مَنْ فِي الْقُبُورِ."]]},{"id":"ri11_20","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٠","segs":[["matn","اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ وَارْحَمْ مُحَمَّدًا وَآلَ مُحَمَّدٍ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ وَرَحِمْتَ وَبَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، فِي الْعَالَمِينَ، إِنَّكَ حَمِيدٌ مَجِيدٌ."]]},{"id":"ri11_21","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢١","segs":[["matn","اللَّهُمَّ صَلِّ عَلَى مَلَائِكَتِكَ وَالْمُقَرَّبِينَ، وَعَلَى أَنْبِيَائِكَ وَالْمُرْسَلِينَ، وَعَلَى أَهْلِ طَاعَتِكَ أَجْمَعِينَ، اللَّهُمَّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِأَئِمَّتِنَا وَلِمَنْ سَبَقَنَا بِالْإِيمَانِ مَغْفِرَةً عَزْمًا."]]},{"id":"ri11_22","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٢","segs":[["matn","اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ سَأَلَكَ مِنْهُ مُحَمَّدٌ نَبِيُّكَ، وَأَعُوذُ بِكَ مِنْ كُلِّ شَرٍّ اسْتَعَاذَكَ مِنْهُ مُحَمَّدٌ نَبِيُّكَ، اللَّهُمَّ اغْفِرْ لَنَا مَا قَدَّمْنَا وَمَا أَخَّرْنَا، وَمَا أَسْرَرْنَا وَمَا أَعْلَنَّا وَمَا أَنْتَ أَعْلَمُ بِهِ مِنَّا."]]},{"id":"ri11_23","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٣","segs":[["matn","﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا، وَالْمَمَاتِ وَمِنْ فِتْنَةِ الْقَبْرِ،"]]},{"id":"ri11_24","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٤","segs":[["matn","وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَمِنْ عَذَابِ النَّارِ وَسُوءِ الْمَصِيرِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ."]]},{"id":"ri11_25","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٥","segs":[["matn","ثُمَّ تَقُولُ: السَّلَامُ عَلَيْكُمْ تَسْلِيمَةً وَاحِدَةً عَنْ يَمِينِكَ تَقْصِدُ بِهَا قُبَالَةَ وَجْهِكَ، وَتَتَيَامَنُ بِرَأْسِكَ قَلِيلًا، هَكَذَا يَفْعَلُ الْإِمَامُ وَالرَّجُلُ وَحْدَهُ، وَأَمَّا الْمَأْمُومُ فَيُسَلِّمُ وَاحِدَةً يَتَيَامَنُ بِهَا قَلِيلًا،"]]},{"id":"ri11_26","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٦","segs":[["matn","وَيَرُدُّ أُخْرَى عَلَى الْإِمَامِ قُبَالَتَهُ يُشِيرُ بِهَا إِلَيْهِ، وَيَرُدُّ عَلَى مَنْ كَانَ سَلَّمَ عَلَيْهِ عَلَى يَسَارِهِ، فَإِنْ لَمْ يَكُنْ سَلَّمَ عَلَيْهِ أَحَدٌ لَمْ يَرُدَّ عَلَى يَسَارِهِ شَيْئًا."]]},{"id":"ri11_27","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٧","segs":[["matn","وَيَجْعَلُ يَدَيْهِ فِي تَشَهُّدِهِ عَلَى فَخِذَيْهِ، وَيَقْبِضُ أَصَابِعَ يَدِهِ الْيُمْنَى، وَيَبْسُطُ السَّبَّابَةَ يُشِيرُ بِهَا، وَقَدْ نَصَبَ حَرْفَهَا إِلَى وَجْهِهِ، وَاخْتُلِفَ فِي تَحْرِيكِهَا: فَقِيلَ: يَعْتَقِدُ بِالْإِشَارَةِ بِهَا أَنَّ اللَّهَ إِلَهٌ وَاحِدٌ،"]]},{"id":"ri11_28","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٨","segs":[["matn","وَيَتَأَوَّلُ مَنْ يُحَرِّكُهَا أَنَّهَا مَقْمَعَةٌ لِلشَّيْطَانِ، وَأَحْسَبُ تَأْوِيلَ ذَلِكَ أَنْ يَذْكُرَ بِذَلِكَ مِنْ أَمْرِ الصَّلَاةِ مَا يَمْنَعُهُ إِنْ شَاءَ اللَّهُ عَنِ السَّهْوِ فِيهَا وَالشُّغْلِ عَنْهَا، وَيَبْسُطُ يَدَهُ الْيُسْرَى، عَلَى فَخِذِهِ الْأَيْسَرِ وَلَا يُحَرِّكُهَا وَلَا يُشِيرُ بِهَا."]]},{"id":"ri11_29","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٢٩","segs":[["matn","وَيُسْتَحَبُّ الذِّكْرُ بِأَثَرِ الصَّلَوَاتِ: يُسَبِّحُ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَيَحْمَدُ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَيُكَبِّرُ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَيَخْتِمُ الْمِائَةَ بِلَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ،"]]},{"id":"ri11_30","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٠","segs":[["matn","لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَيُسْتَحَبُّ بِإِثْرِ صَلَاةِ الصُّبْحِ التَّمَادِي فِي الذِّكْرِ وَالِاسْتِغْفَارِ وَالتَّسْبِيحِ وَالدُّعَاءِ إِلَى طُلُوعِ الشَّمْسِ أَوْ قُرْبِ طُلُوعِهَا، وَلَيْسَ بِوَاجِبٍ."]]},{"id":"ri11_31","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣١","segs":[["matn","وَيَرْكَعُ رَكْعَتَيِ الْفَجْرِ قَبْلَ صَلَاةِ الصُّبْحِ بَعْدَ الْفَجْرِ، يَقْرَأُ فِي كُلِّ رَكْعَةٍ بِأُمِّ الْقُرْآنِ يُسِرُّهَا."]]},{"id":"ri11_32","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٢","segs":[["matn","وَالْقِرَاءَةُ فِي الظُّهْرِ بِنَحْوِ الْقِرَاءَةِ فِي الصُّبْحِ مِنَ الطِّوَالِ أَوْ دُونَ ذَلِكَ قَلِيلًا، وَلَا يَجْهَرُ فِيهَا بِشَيْءٍ مِنَ الْقِرَاءَةِ،"]]},{"id":"ri11_33","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٣","segs":[["matn","وَيَقْرَأُ فِي الْأُولَى وَالثَّانِيَةِ فِي كُلِّ رَكْعَةٍ بِأُمِّ الْقُرْآنِ وَسُورَةٍ سِرًّا، وَفِي الْأَخِيرَتَيْنِ بِأُمِّ الْقُرْآنِ وَحْدَهَا سِرًّا، وَيَتَشَهَّدُ فِي الْجَلْسَةِ الْأُولَى إِلَى قَوْلِهِ:"]]},{"id":"ri11_34","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٤","segs":[["matn","وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، ثُمَّ يَقُومُ فَلَا يُكَبِّرُ حَتَّى يَسْتَوِيَ قَائِمًا، هَكَذَا يَفْعَلُ الْإِمَامُ وَالرَّجُلُ وَحْدَهُ، وَأَمَّا الْمَأْمُومُ فَبَعْدَ أَنْ يُكَبِّرَ الْإِمَامُ يَقُومُ الْمَأْمُومُ أَيْضًا،"]]},{"id":"ri11_35","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٥","segs":[["matn","فَإِذَا اسْتَوَى قَائِمًا كَبَّرَ، وَيَفْعَلُ فِي بَقِيَّةِ الصَّلَاةِ مِنْ صِفَةِ الرُّكُوعِ وَالسُّجُودِ وَالْجُلُوسِ نَحْوَ مَا تَقَدَّمَ ذِكْرُهُ فِي الصُّبْحِ."]]},{"id":"ri11_36","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٦","segs":[["matn","وَيَتَنَفَّلُ بَعْدَهَا، وَيُسْتَحَبُّ لَهُ أَنْ يَتَنَفَّلَ بِأَرْبَعِ رَكَعَاتٍ يُسَلِّمُ مِنْ كُلِّ رَكْعَتَيْنِ، وَيُسْتَحَبُّ لَهُ مِثْلُ ذَلِكَ قَبْلَ صَلَاةِ الْعَصْرِ."]]},{"id":"ri11_37","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٧","segs":[["matn","وَيَفْعَلُ فِي الْعَصْرِ كَمَا وَصَفْنَا فِي الظُّهْرِ سَوَاءً، إِلَّا أَنَّهُ يَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مَعَ أُمِّ الْقُرْآنِ بِالْقِصَارِ مِنَ السُّوَرِ مِثْلُ ﴿وَالضُّحَى﴾، ﴿وَإِنَّا أَنْزَلْنَاهُ﴾ وَنَحْوِهِمَا."]]},{"id":"ri11_38","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٨","segs":[["matn","وَأَمَّا الْمَغْرِبُ فَيَجْهَرُ بِالْقِرَاءَةِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْهَا، وَيَقْرَأُ فِي كُلِّ رَكْعَةٍ مِنْهُمَا بِأُمِّ الْقُرْآنِ وَسُورَةٍ مِنَ السُّوَرِ الْقِصَارِ وَفِي الثَّالِثَةِ بِأُمِّ الْقُرْآنِ فَقَطْ، وَيَتَشَهَّدُ وَيُسَلِّمُ."]]},{"id":"ri11_39","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٣٩","segs":[["matn","وَيُسْتَحَبُّ أَنْ يَتَنَفَّلَ بَعْدَهَا بِرَكْعَتَيْنِ، وَمَا زَادَ فَهُوَ خَيْرٌ، وَإِنْ تَنَفَّلَ بِسِتِّ رَكَعَاتٍ فَحَسَنٌ، وَالتَّنَفُّلُ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ مُرَغَّبٌ فِيهِ، وَأَمَّا غَيْرُ ذَلِكَ مِنْ شَأْنِهَا فَكَمَا تَقَدَّمَ ذِكْرُهُ فِي غَيْرِهَا."]]},{"id":"ri11_40","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٠","segs":[["matn","وَأَمَّا الْعِشَاءُ الْأَخِيرَةُ وَهِيَ الْعَتَمَةُ، وَاسْمُ الْعِشَاءِ أَخَصُّ بِهَا وَأَوْلَى فَيَجْهَرُ فِي الْأُوَّلَيَيْنِ بِأُمِّ الْقُرْآنِ وَسُورَةٍ فِي كُلِّ رَكْعَةٍ، وَقِرَاءَتُهَا أَطْوَلُ قَلِيلًا مِنْ قِرَاءَةِ الْعَصْرِ،"]]},{"id":"ri11_41","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤١","segs":[["matn","وَفِي الْأَخِيرَتَيْنِ بِأُمِّ الْقُرْآنِ فِي كُلِّ رَكْعَةٍ سِرًّا، ثُمَّ يَفْعَلُ فِي سَائِرِهَا كَمَا تَقَدَّمَ مِنَ الْوَصْفِ، وَيُكْرَهُ النَّوْمُ قَبْلَهَا، وَالْحَدِيثُ بَعْدَهَا لِغَيْرِ ضَرُورَةٍ."]]},{"id":"ri11_42","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٢","segs":[["matn","وَالْقِرَاءَةُ الَّتِي يُسِرُّ بِهَا فِي الصَّلَاةِ كُلُّهَا هِيَ بِتَحْرِيكِ اللِّسَانِ بِالتَّكَلُّمِ بِالْقُرْآنِ، وَأَمَّا الْجَهْرُ فَأَنْ يُسْمِعَ نَفْسَهُ وَمَنْ يَلِيهِ إِنْ كَانَ وَحْدَهُ."]]},{"id":"ri11_43","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٣","segs":[["matn","وَالْمَرْأَةُ دُونَ الرَّجُلِ فِي الْجَهْرِ، وَهِيَ فِي هَيْئَةِ صَلَاتِهَا مِثْلُهُ غَيْرَ أَنَّهَا تَنْضَمُّ، وَلَا تَفْرُجُ فَخِذَيْهَا وَلَا عَضُدَيْهَا، وَتَكُونُ مُنْضَمَّةً مُنْزَوِيَةً فِي جُلُوسِهَا وَسُجُودِهَا وَأَمْرِهَا كُلِّهِ."]]},{"id":"ri11_44","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٤","segs":[["matn","ثُمَّ يُصَلِّيَ الشَّفْعَ وَالْوِتْرَ جَهْرًا، وَكَذَلِكَ يُسْتَحَبُّ فِي نَوَافِلِ اللَّيْلِ الْإِجْهَارُ، وَفِي نَوَافِلِ النَّهَارِ الْإِسْرَارُ، وَإِنْ جَهَرَ فِي النَّهَارِ فِي تَنَفُّلِهِ فَذَلِكَ وَاسِعٌ، وَأَقَلُّ الشَّفْعِ رَكْعَتَانِ، وَيُسْتَحَبُّ أَنْ يَقْرَأَ فِي الْأُولَى بِأُمِّ الْقُرْآنِ ﴿وَسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى﴾،"]]},{"id":"ri11_45","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٥","segs":[["matn","وَفِي الثَّانِيَةِ بِأُمِّ الْقُرْآنِ ﴿وَقُلْ يَا أَيُّهَا الْكَافِرُونَ﴾، وَيَتَشَهَّدُ وَيُسَلِّمُ، ثُمَّ يُصَلِّي الْوِتْرَ رَكْعَةً، يَقْرَأُ فِيهَا بِأُمِّ الْقُرْآنِ ﴿وَقُلْ هُوَ اللَّهُ أَحَدٌ﴾ وَالْمُعَوِّذَتَيْنِ، وَإِنْ زَادَ مِنَ الْإِشْفَاعِ جَعَلَ آخِرَ ذَلِكَ الْوِتْرَ."]]},{"id":"ri11_46","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٦","segs":[["matn","وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ اثْنَتَيْ عَشْرَةَ رَكْعَةً، ثُمَّ يُوتِرُ بِوَاحِدَةٍ."]]},{"id":"ri11_47","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٧","segs":[["matn","وَقِيلَ: عَشْرَ رَكَعَاتٍ، ثُمَّ يُوتِرُ بِوَاحِدَةٍ، وَأَفْضَلُ اللَّيْلِ آخِرُهُ فِي الْقِيَامِ، فَمَنْ أَخَّرَ تَنَفُّلَهُ وَوِتْرَهُ إِلَى آخِرِهِ فَذَلِكَ أَفْضَلُ،"]]},{"id":"ri11_48","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٨","segs":[["matn","إِلَّا مَنِ الْغَالِبُ عَلَيْهِ أَنْ لَا يَنْتَبِهَ فَلْيُقَدِّمْ وَتْرَهُ مَعَ مَا يُرِيدُ مِنَ النَّوَافِلِ أَوَّلَ اللَّيْلِ، ثُمَّ إِنْ شَاءَ إِذَا اسْتَيْقَظَ فِي آخِرِهِ تَنَفَّلَ مَا شَاءَ مِنْهَا مَثْنَى مَثْنَى، وَلَا يُعِيدُ الْوِتْرَ."]]},{"id":"ri11_49","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٤٩","segs":[["matn","وَمَنْ غَلَبَتْهُ عَيْنَاهُ عَنْ حِزْبِهِ فَلَهُ أَنْ يُصَلِّيَهُ مَا بَيْنَهُ وَبَيْنَ طُلُوعِ الْفَجْرِ وَأَوَّلِ الْإِسْفَارِ، ثُمَّ يُوتِرُ، وَيُصَلِّي الصُّبْحَ، وَلَا يَقْضِي الْوِتْرَ مَنْ ذَكَرَهُ بَعْدَ أَنْ صَلَّى الصُّبْحَ."]]},{"id":"ri11_50","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٥٠","segs":[["matn","وَمَنْ دَخَلَ الْمَسْجِدَ عَلَى وُضُوءٍ فَلَا يَجْلِسْ حَتَّى يُصَلِّيَ رَكْعَتَيْنِ، إِنْ كَانَ وَقْتٌ يَجُوزُ فِيهِ الرُّكُوعُ، وَمَنْ دَخَلَ الْمَسْجِدَ وَلَمْ يَرْكَعِ الْفَجْرَ أَجْزَأَهُ لِذَلِكَ رَكْعَتَا الْفَجْرِ،"]]},{"id":"ri11_51","label":"بَابُ صِفَةِ الْعَمَلِ فِي الصَّلَوَاتِ الْمَفْرُوضَةِ وَمَا يَتَّصِلُ بِهَا مِنَ النَّوَافِلِ وَالسُّنَنِ · ٥١","segs":[["matn","وَإِنْ رَكَعَ الْفَجْرَ فِي بَيْتِهِ، ثُمَّ أَتَى الْمَسْجِدَ فَاخْتُلِفَ فِيهِ: فَقِيلَ: يَرْكَعُ، وَقِيلَ: لَا يَرْكَعُ، وَلَا صَلَاَةَ نَافِلَةً بَعْدَ الْفَجْرِ إِلَّا رَكْعَتَا الْفَجْرِ إِلَى طُلُوعِ الشَّمْسِ."]]}]},{"id":"ri12","title":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ","units":[{"id":"ri12_1","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ١","segs":[["matn","وَيَؤُمُّ النَّاسَ أَفْضَلُهُمْ وَأَفْقَهُهُمْ، وَلَا تَؤُمُّ الْمَرْأَةُ فِي فَرِيضَةٍ وَلَا نَافِلَةٍ لَا رِجَالًا وَلَا نِسَاءً، وَيَقْرَأُ مَعَ الْإِمَامِ فِيمَا يُسِرُّ فِيهِ، وَلَا يَقْرَأُ مَعَهُ فِيمَا يَجْهَرُ فِيهِ."]]},{"id":"ri12_2","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ٢","segs":[["matn","وَمَنْ أَدْرَكَ رَكْعَةً فَأَكْثَرَ فَقَدْ أَدْرَكَ الْجَمَاعَةَ؛ فَلْيَقْضِ بَعْدَ سَلَامِ الْإِمَامِ مَا فَاتَهُ عَلَى نَحْوِ مَا فَعَلَ الْإِمَامُ فِي الْقِرَاءَةِ، وَأَمَّا فِي الْقِيَامِ وَالْجُلُوسِ فَفِعْلُهُ كَفِعْلِ الْبَانِي الْمُصَلِّي وَحْدَهُ."]]},{"id":"ri12_3","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ٣","segs":[["matn","وَمَنْ صَلَّى وَحْدَهُ فَلَهُ أَنْ يُعِيدَ فِي الْجَمَاعَةِ لِلْفَضْلِ فِي ذَلِكَ، إِلَّا الْمَغْرِبَ وَحْدَهَا، وَمَنْ أَدْرَكَ رَكْعَةً فَأَكْثَرَ مِنْ صَلَاةِ الْجَمَاعَةِ فَلَا يُعِيدُهَا فِي جَمَاعَةٍ وَمَنْ لَمْ يُدْرِكْ إِلَّا التَّشَهُّدَ أَوِ السُّجُودَ فَلَهُ أَنْ يُعِيدَ فِي جَمَاعَةٍ."]]},{"id":"ri12_4","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ٤","segs":[["matn","وَالرَّجُلُ الْوَاحِدُ مَعَ الْإِمَامِ يَقُومُ عَنْ يَمِينِهِ، وَيَقُومُ الرَّجُلَانِ فَأَكْثَرُ خَلْفَهُ، فَإِنْ كَانَتِ امْرَأَةٌ مَعَهُمَا قَامَتْ خَلْفَهُمَا، وَإِنْ كَانَ مَعَهُمَا رَجُلٌ صَلَّى عَنْ يَمِينِ الْإِمَامِ وَالْمَرْأَةُ خَلْفَهُمَا،"]]},{"id":"ri12_5","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ٥","segs":[["matn","وَمَنْ صَلَّى بِزَوْجَتِهِ قَامَتْ خَلْفَهُ، وَالصَّبِيُّ إِنْ صَلَّى مَعَ رَجُلٍ وَاحِدٍ خَلْفَ الْإِمَامِ قَامَا خَلْفَهُ إِنْ كَانَ الصَّبِيُّ يَعْقِلُ: لَا يَذْهَبُ وَيَدَعُ مَنْ يَقِفُ مَعَهُ."]]},{"id":"ri12_6","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ٦","segs":[["matn","وَالْإِمَامُ الرَّاتِبُ إِنْ صَلَّى وَحْدَهُ قَامَ مَقَامَ الْجَمَاعَةِ، وَيُكْرَهُ فِي كُلِّ مَسْجِدٍ لَهُ إِمَامٌ رَاتِبٌ أَنْ تُجْمَعَ فِيهِ الصَّلَاةُ مَرَّتَيْنِ، وَمَنْ صَلَّى صَلَاةً فَلَا يَؤُمُّ فِيهَا أَحَدًا."]]},{"id":"ri12_7","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ٧","segs":[["matn","وَإِذَا سَهَا الْإِمَامُ وَسَجَدَ لِسَهْوِهِ فَلْيَتْبَعْهُ مَنْ لَمْ يَسْهُ مَعَهُ مِمَّنْ خَلْفَهُ، وَلَا يَرْفَعُ أَحَدٌ رَأْسَهُ قَبْلَ الْإِمَامِ، وَلَا يَفْعَلُ إِلَّا بَعْدَ فِعْلِهِ،"]]},{"id":"ri12_8","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ٨","segs":[["matn","وَيَفْتَتِحُ بَعْدَهُ، وَيَقُومُ مِنِ اثْنَتَيْنِ بَعْدَ قِيَامِهِ، وَيُسَلِّمُ بَعْدَ سَلَامِهِ، وَمَا سِوَى ذَلِكَ فَوَاسِعٌ أَنْ يَفْعَلَهُ مَعَهُ، وَبَعْدَهُ أَحْسَنُ."]]},{"id":"ri12_9","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ٩","segs":[["matn","وَكُلُّ سَهْوٍ سَهَاهُ الْمَأْمُومُ فَالْإِمَامُ يَحْمِلُهُ عَنْهُ إِلَّا رَكْعَةً أَوْ سَجْدَةً أَوْ تَكْبِيرَةَ الْإِحْرَامِ أَوِ السَّلَامَ أَوِ اعْتِقَادَ نِيَّةِ الْفَرِيضَةِ."]]},{"id":"ri12_10","label":"بَابٌ فِي الْإِمَامَةِ وَحُكْمِ الْإِمَامِ وَالْمَأْمُومِ · ١٠","segs":[["matn","وَإِذَا سَلَّمَ الْإِمَامُ فَلَا يَثْبُتُ بَعْدَ سَلَامِهِ؛ وَلْيَنْصَرِفْ، إِلَّا أَنْ يَكُونَ فِي مَحَلِّهِ فَذَلِكَ وَاسِعٌ."]]}]},{"id":"ri13","title":"بَابٌ جَامِعٌ فِي الصَّلَاةِ","units":[{"id":"ri13_1","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١","segs":[["matn","وَأَقَلُّ مَا يُجْزِئُ الْمَرْأَةَ مِنَ اللِّبَاسِ فِي الصَّلَاةِ الدِّرْعُ الْحَصِيفُ السَّابِغُ الَّذِي يَسْتُرُ ظُهُورَ قَدَمَيْهَا وَهُوَ الْقَمِيصُ وَالْخِمَارُ الْحَصِيفُ، وَيُجْزِئُ الرَّجُلَ فِي الصَّلَاةِ ثَوْبٌ وَاحِدٌ، وَلَا يُغَطِّي أَنْفَهُ أَوْ وَجْهَهُ فِي الصَّلَاةِ، أَوْ يَضُمُّ ثِيَابَهُ أَوْ يَكْفِتُ شَعْرَهُ."]]},{"id":"ri13_2","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢","segs":[["matn","وَكُلُّ سَهْوٍ فِي الصَّلَاةِ بِزِيَادَةٍ فَلْيَسْجُدْ لَهُ سَجْدَتَيْنِ بَعْدَ السَّلَامِ، يَتَشَهَّدُ لَهُمَا وَيُسَلِّمُ مِنْهُمَا، وَكُلُّ سَهْوٍ بِنَقْصٍ فَلْيَسْجُدْ لَهُ قَبْلَ السَّلَامِ إِذَا تَمَّ تَشَهُّدُهُ، ثُمَّ يَتَشَهَّدُ وَيُسَلِّمُ، وَقِيلَ: لَا يُعِيدُ التَّشَهُّدَ، وَمَنْ نَقَصَ وَزَادَ سَجَدَ قَبْلَ السَّلَامِ."]]},{"id":"ri13_3","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣","segs":[["matn","وَمَنْ نَسِيَ أَنْ يَسْجُدَ بَعْدَ السَّلَامِ فَلْيَسْجُدْ مَتَى مَا ذَكَرَهُ وَإِنْ طَالَ ذَلِكَ، وَإِنْ كَانَ قَبْلَ السَّلَامِ سَجَدَ إِنْ كَانَ قَرِيبًا،"]]},{"id":"ri13_4","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٤","segs":[["matn","وَإِنْ بَعُدَ ابْتَدَأَ صَلَاتَهُ، إِلَّا أَنْ يَكُونَ ذَلِكَ مِنْ نَقْصِ شَيْءٍ خَفِيفٍ كَالسُّورَةِ مَعَ أُمِّ الْقُرْآنِ أَوْ تَكْبِيرَتَيْنِ أَوِ التَّشَهُّدَيْنِ وَشِبْهَ ذَلِكَ فَلَا شَيْءَ عَلَيْهِ."]]},{"id":"ri13_5","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٥","segs":[["matn","وَلَا يُجْزِئُ سُجُودُ السَّهْوِ لِنَقْصِ رَكْعَةٍ وَلَا سَجْدَةٍ وَلَا لِتَرْكِ الْقِرَاءَةِ فِي الصَّلَاةِ كُلِّهَا أَوْ فِي رَكْعَتَيْنِ مِنْهَا،"]]},{"id":"ri13_6","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٦","segs":[["matn","وَكَذَلِكَ فِي تَرْكِ الْقِرَاءَةِ فِي رَكْعَةٍ مِنَ الصُّبْحِ، وَاخْتُلِفَ فِي السَّهْوِ عَنِ الْقِرَاءَةِ فِي رَكْعَةٍ مِنْ غَيْرِهَا؛ فَقِيلَ: يُجْزِئُ فِيهِ سُجُودُ السَّهْوِ قَبْلَ السَّلَامِ. وَقِيلَ: يُلْغِيهَا، وَيَأْتِي بِرَكْعَةٍ."]]},{"id":"ri13_7","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٧","segs":[["matn","وَقِيلَ: يَسْجُدُ قَبْلَ السَّلَامِ، وَلَا يَأْتِي بِرَكْعَةٍ، وَيُعِيدُ الصَّلَاةَ احْتِيَاطًا، وَهَذَا أَحْسَنُ ذَلِكَ إِنْ شَاءَ اللَّهُ تَعَالَى."]]},{"id":"ri13_8","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٨","segs":[["matn","وَمَنْ سَهَا عَنْ تَكْبِيرَةٍ أَوْ عَنْ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ مَرَّةً أَوِ الْقُنُوتِ فَلَا سُجُودَ عَلَيْهِ."]]},{"id":"ri13_9","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٩","segs":[["matn","وَمَنِ انْصَرَفَ مِنَ الصَّلَاةِ ثُمَّ ذَكَرَ أَنَّهُ بَقِيَ عَلَيْهِ شَيْءٌ مِنْهَا فَلْيَرْجِعْ إِنْ كَانَ بِقُرْبِ ذَلِكَ، فَيُكَبِّرُ تَكْبِيرَةً يُحْرِمُ بِهَا، ثُمَّ يُصَلِّي مَا بَقِيَ عَلَيْهِ، وَإِنْ تَبَاعَدَ ذَلِكَ أَوْ خَرَجَ مِنَ الْمَسْجِدِ ابْتَدَأَ صَلَاتَهُ، وَكَذَلِكَ مَنْ نَسِيَ السَّلَامَ."]]},{"id":"ri13_10","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٠","segs":[["matn","وَمَنْ لَمْ يَدْرِ مَا صَلَّى أَثَلَاثَ رَكَعَاتٍ أَمْ أَرْبَعًا بَنَى عَلَى الْيَقِينِ، وَصَلَّى مَا شَكَّ فِيهِ، وَأَتَى بِرَابِعَةٍ، وَسَجَدَ بَعْدَ سَلَامِهِ."]]},{"id":"ri13_11","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١١","segs":[["matn","وَمَنْ تَكَلَّمَ سَاهِيًا سَجَدَ بَعْدَ السَّلَامِ، وَمَنْ لَمْ يَدْرِ أَسَلَّمَ أَمْ لَمْ يُسَلِّمْ سَلَّمَ وَلَا سُجُودَ عَلَيْهِ."]]},{"id":"ri13_12","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٢","segs":[["matn","وَمَنِ اسْتَنْكَحَهُ الشَّكُّ فِي السَّهْوِ فَلْيَلْهَ عَنْهُ، وَلَا إِصْلَاَحَ عَلَيْهِ، وَلَكِنْ عَلَيْهِ أَنْ يَسْجُدَ بَعْدَ السَّلَامِ، وَهُوَ الَّذِي يَكْثُرُ ذَلِكَ مِنْهُ: يَشُكُّ كَثِيرًا أَنْ يَكُونَ سَهَا زَادَ أَوْ نَقَصَ، وَلَا يُوقِنُ فَلْيَسْجُدْ بَعْدَ السَّلَامِ فَقَطْ."]]},{"id":"ri13_13","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٣","segs":[["matn","وَإِذَا أَيْقَنَ بِالسَّهْوِ سَجَدَ بَعْدَ إِصْلَاِحِ صَلَاِتِهِ، فَإِنْ كَثُرَ ذَلِكَ مِنْهُ فَهُوَ يَعْتَرِيهِ كَثِيرًا أَصْلَحَ صَلَاتَهُ، وَلَمْ يَسْجُدْ لِسَهْوِهِ."]]},{"id":"ri13_14","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٤","segs":[["matn","وَمَنْ قَامَ مِنِ اثْنَتَيْنِ رَجَعَ مَا لَمْ يُفَارِقِ الْأَرْضَ بِيَدَيْهِ وَرُكْبَتَيْهِ، فَإِذَا فَارَقَهَا تَمَادَى وَلَمْ يَرْجِعْ، وَسَجَدَ قَبْلَ السَّلَامِ."]]},{"id":"ri13_15","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٥","segs":[["matn","وَمَنْ ذَكَرَ صَلَاةً صَلَّاهَا مَتَى مَا ذَكَرَهَا عَلَى نَحْوِ مَا فَاتَتْهُ، ثُمَّ أَعَادَ مَا كَانَ فِي وَقْتِهِ مِمَّا صَلَّى بَعْدَهَا، وَمَنْ عَلَيْهِ صَلَوَاتٌ كَثِيرَةٌ صَلَّاهَا فِي كُلِّ وَقْتٍ مِنْ لَيْلٍ أَوْ نَهَارٍ وَعِنْدَ طُلُوعِ الشَّمْسِ وَعِنْدَ غُرُوبِهَا وَكَيْفَمَا تَيَسَّرَ لَهُ."]]},{"id":"ri13_16","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٦","segs":[["matn","وَإِنْ كَانَتْ يَسِيرَةً أَقَلَّ مِنْ صَلَاةِ يَوْمٍ وَلَيْلَةٍ بَدَأَ بِهِنَّ وَإِنْ فَاتَ وَقْتُ مَا هُوَ فِي وَقْتِهِ، وَإِنْ كَثُرَتْ بَدَأَ بِمَا يَخَافُ فَوَاتَ وَقْتِهِ، وَمَنْ ذَكَرَ صَلَاةً فِي صَلَاةٍ فَسَدَتْ هَذِهِ عَلَيْهِ."]]},{"id":"ri13_17","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٧","segs":[["matn","وَمَنْ ضَحِكَ فِي الصَّلَاةِ أَعَادَهَا، وَلَمْ يُعِدِ الْوُضُوءَ، وَإِنْ كَانَ مَعَ إِمَامٍ تَمَادَى، وَأَعَادَ، وَلَا شَيْءَ عَلَيْهِ فِيِ التَّبَسُّمِ، وَالنَّفْخُ فِي الصَّلَاةِ كَالْكَلَامِ، وَالْعَامِدُ لِذَلِكَ مُفْسِدٌ لِصَلَاتِهِ."]]},{"id":"ri13_18","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٨","segs":[["matn","وَمَنْ أَخْطَأَ الْقِبْلَةَ أَعَادَ فِي الْوَقْتِ، وَكَذَلِكَ مَنْ صَلَّى بِثَوْبٍ نَجِسٍ أَوْ عَلَى مَكَانٍ نَجِسٍ، وَكَذَلِكَ مَنْ تَوَضَّأَ بِمَاءٍ نَجِسٍ مُخْتَلَفٍ فِي نَجَاسَتِهِ، وَأَمَّا مَنْ تَوَضَّأَ بِمَاءٍ قَدْ تَغَيَّرَ لَوْنُهُ أَوْ طَعْمُهُ أَوْ رِيحُهُ أَعَادَ صَلَاتَهُ أَبَدًا وَوُضُوءَهُ."]]},{"id":"ri13_19","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ١٩","segs":[["matn","وَرُخِّصَ فِي الْجَمْعِ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ لَيْلَةَ الْمَطَرِ، وَكَذَلِكَ فِي طِينٍ وَظُلْمَةٍ، يُؤَذِّنُ لِلْمَغْرِبِ أَوَّلَ الْوَقْتِ خَارِجَ الْمَسْجِدِ، ثُمَّ يُؤَخِّرُ قَلِيلًا فِي قَوْلِ مَالِكٍ،"]]},{"id":"ri13_20","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٠","segs":[["matn","ثُمَّ يُقِيمُ فِي دَاخِلِ الْمَسْجِدِ، وَيُصَلِّيهَا، ثُمَّ يُؤَذِّنُ لِلْعِشَاءِ فِي دَاخِلِ الْمَسْجِدِ، وَيُقِيمُ، ثُمَّ يُصَلِّيهَا، ثُمَّ يَنْصَرِفُونَ وَعَلَيْهِمْ إِسْفَارٌ قَبْلَ مَغِيبِ الشَّفَقِ."]]},{"id":"ri13_21","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢١","segs":[["matn","وَالْجَمْعُ بِعَرَفَةَ بَيْنَ الظُّهْرِ وَالْعَصْرِ عِنْدَ الزَّوَالِ سُنَّةٌ وَاجِبَةٌ، بِأَذَانٍ وَإِقَامَةٍ لِكُلِّ صَلَاةٍ، وَكَذَلِكَ فِي جَمْعِ الْمَغْرِبِ وَالْعِشَاءِ بِالْمُزْدَلِفَةِ إِذَا وَصَلَ إِلَيْهَا."]]},{"id":"ri13_22","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٢","segs":[["matn","وَإِذَا جَدَّ السَّيْرُ بِالْمُسَافِرِ فَلَهُ أَنْ يَجْمَعَ بَيْنَ الصَّلَاتَيْنِ فِي آخِرِ وَقْتِ الظُّهْرِ وَأَوَّلِ وَقْتِ الْعَصْرِ، وَكَذَلِكَ الْمَغْرِبُ وَالْعِشَاءُ، وَإِذَا ارْتَحَلَ فِي أَوَّلِ وَقْتِ الصَّلَاةِ الْأُولَى جَمَعَ حِينَئِذٍ."]]},{"id":"ri13_23","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٣","segs":[["matn","وَلِلْمَرِيضِ أَنْ يَجْمَعَ إِذَا خَافَ أَنْ يُغْلَبَ عَلَى عَقْلِهِ عِنْدَ الزَّوَالِ وَعِنْدَ الْغُرُوبِ، وَإِنْ كَانَ الْجَمْعُ أَرْفَقَ بِهِ لِبَطْنٍ بِهِ وَنَحْوِهِ جَمَعَ وَسَطَ وَقْتِ الظُّهْرِ، وَعِنْدَ غَيْبُوبَةِ الشَّفَقِ."]]},{"id":"ri13_24","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٤","segs":[["matn","وَالْمُغْمَى عَلَيْهِ لَا يَقْضِي مَا خَرَجَ وَقْتُهُ فِي إِغْمَائِهِ، وَيَقْضِي مَا أَفَاقَ فِي وَقْتِهِ مِمَّا يُدْرِكُ مِنْهُ رَكْعَةً فَأَكْثَرَ مِنَ الصَّلَوَاتِ."]]},{"id":"ri13_25","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٥","segs":[["matn","وَكَذَلِكَ الْحَائِضُ تَطْهُرُ، فَإِذَا بَقِيَ مِنَ النَّهَارِ بَعْدَ طُهْرِهَا بِغَيْرِ تَوَانٍ خَمْسُ رَكَعَاتٍ صَلَّتِ الظُّهْرَ وَالْعَصْرَ، وَإِنْ كَانَ الْبَاقِي مِنَ اللَّيْلِ أَرْبَعَ رَكَعَاتٍ صَلَّتِ الْمَغْرِبَ وَالْعِشَاءَ، وَإِنْ كَانَ مِنَ النَّهَارِ أَوْ مِنَ اللَّيْلِ أَقَلُّ مِنْ ذَلِكَ صَلَّتِ الصَّلَاةَ الْأَخِيرَةَ،"]]},{"id":"ri13_26","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٦","segs":[["matn","وَإِنْ حَاضَتْ لِهَذَا التَّقْدِيرِ لَمْ تَقْضِ مَا حَاضَتْ فِي وَقْتِهِ، وَإِنْ حَاضَتْ لِأَرْبَعِ رَكَعَاتٍ مِنَ النَّهَارِ فَأَقَلَّ إِلَى رَكْعَةٍ، أَوْ لِثَلَاثِ رَكَعَاتٍ مِنَ اللَّيْلِ إِلَى رَكْعَةٍ قَضَتِ الصَّلَاةَ الْأُولَى فَقَطْ، وَاخْتُلِفَ فِي حَيْضِهَا لِأَرْبَعِ رَكَعَاتٍ مِنَ اللَّيْلِ؛ فَقِيلَ مِثْلُ ذَلِكَ."]]},{"id":"ri13_27","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٧","segs":[["matn","وَقِيلَ: إِنَّهَا حَاضَتْ فِي وَقْتِهِمَا؛ فَلَا تَقْضِيهِمَا. وَمَنْ أَيْقَنَ بِالْوُضُوءِ وَشَكَّ فِي الْحَدَثِ ابْتَدَأَ الْوُضُوءَ، وَمَنْ ذَكَرَ مِنْ وُضُوئِهِ شَيْئًا مِمَّا هُوَ فَرِيضَةٌ مِنْهُ؛"]]},{"id":"ri13_28","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٨","segs":[["matn","فَإِنْ كَانَ بِالْقُرْبِ أَعَادَ ذَلِكَ وَمَا يَلِيهِ، وَإِنْ تَطَاوَلَ ذَلِكَ أَعَادَهُ فَقَطْ، وَإِنْ تَعَمَّدَ ذَلِكَ أَبْتَدَأَ الْوُضُوءَ إِنْ طَالَ ذَلِكَ، وَإِنْ كَانَ قَدْ صَلَّى فِي جَمِيعِ ذَلِكَ أَعَادَ صَلَاتَهُ أَبَدًا وَوُضُوءَهُ وَإِنْ ذَكَرَ مِثْلَ الْمَضْمَضَةِ وَالِاسْتِنْشَاقِ وَمَسْحِ الْأُذُنَيْنِ؛"]]},{"id":"ri13_29","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٢٩","segs":[["matn","فَإِنْ كَانَ قَرِيبًا فَعَلَ ذَلِكَ، وَلَمْ يُعِدْ مَا بَعْدَهُ، وَإِنْ تَطَاوَلَ فَعَلَ ذَلِكَ لِمَا يُسْتَقْبَلُ، وَلَمْ يُعِدْ مَا صَلَّى قَبْلَ أَنْ يَفْعَلَ ذَلِكَ."]]},{"id":"ri13_30","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٠","segs":[["matn","وَمَنْ صَلَّى عَلَى مَوْضِعٍ طَاهِرٍ مِنْ حَصِيرٍ وَبِمَوْضِعٍ آخَرَ مِنْهُ نَجَاسَةٌ فَلَا شَيْءَ عَلَيْهِ، وَالْمَرِيضُ إِذَا كَانَ عَلَى فِرَاشٍ نَجِسٍ فَلَا بَأْسَ أَنْ يَبْسُطَ عَلَيْهِ ثَوْبًا طَاهِرًا كَثِيفًا، وَيُصَلِّيَ عَلَيْهِ."]]},{"id":"ri13_31","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣١","segs":[["matn","وَصَلَاةُ الْمَرِيضِ إِنْ لَمْ يَقْدِرْ عَلَى الْقِيَامِ صَلَّى جَالِسًا إِنْ قَدَرَ عَلَى التَّرَبُّعِ، وَإِلَّا فَبِقَدْرِ طَاقَتِهِ، وَإِنْ لَمْ يَقْدِرْ عَلَى السُّجُودِ فَلْيُومِئْ بِالرُّكُوعِ وَالسُّجُودِ، وَيَكُونُ سُجُودُهُ أَخْفَضَ مِنْ رُكُوعِهِ،"]]},{"id":"ri13_32","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٢","segs":[["matn","وَإِنْ لَمْ يَقْدِرْ صَلَّى عَلَى جَنْبِهِ الْأَيْمَنِ إِيمَاءً، وَإِنْ لَمْ يَقْدِرْ إِلَّا عَلَى ظَهْرِهِ فَعَلَ ذَلِكَ، وَلَا يُؤَخِّرُ الصَّلَاةَ إِذَا كَانَ فِي عَقْلِهِ، وَلْيُصَلِّهَا بِقَدْرِ مَا يُطِيقُ."]]},{"id":"ri13_33","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٣","segs":[["matn","وَإِنْ لَمْ يَقْدِرْ عَلَى مَسِّ الْمَاءِ لِضَرَرٍ بِهِ أَوْ لِأَنَّهُ لَا يَجِدُ مَنْ يُنَاوِلُهُ إِيَّاهُ تَيَمَّمَ، فَإِنْ لَمْ يَجِدْ مَنْ يُنَاوِلُهُ تُرَابًا تَيَمَّمَ بِالْحَائِطِ إِلَى جَانِبِهِ إِنْ كَانَ طِينًا أَوْ عَلَيْهِ طِينٌ،"]]},{"id":"ri13_34","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٤","segs":[["matn","فَإِنْ كَانَ عَلَيْهِ جِصٌّ أَوْ جِيرٌ فَلَا يَتَيَمَّمُ بِهِ وَالْمُسَافِرُ يَأْخُذُهُ الْوَقْتُ فِي طِينٍ خَضْخَاضٍ لَا يَجِدُ أَيْنَ يُصَلِّي فَلْيَنْزِلْ عَنْ دَابَّتِهِ،"]]},{"id":"ri13_35","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٥","segs":[["matn","وَيُصَلِّي فِيهِ قَائِمًا، يُومِئُ بِالسُّجُودِ أَخْفَضَ مِنَ الرُّكُوعِ، فَإِنْ لَمْ يَقْدِرْ أَنْ يَنْزِلَ فِيهِ صَلَّى عَلَى دَابَّتِهِ إِلَى الْقِبْلَةِ."]]},{"id":"ri13_36","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٦","segs":[["matn","وَلِلْمُسَافِرِ أَنْ يَتَنَفَّلَ عَلَى دَابَّتِهِ فِي سَفَرِهِ حَيْثُمَا تَوَجَّهَتْ بِهِ إِنْ كَانَ سَفَرًا تُقْصَرُ فِيهِ الصَّلَاةُ، وَلْيُوتِرْ عَلَى دَابَّتِهِ إِنْ شَاءَ."]]},{"id":"ri13_37","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٧","segs":[["matn","وَلَا يُصَلِّي الْفَرِيضَةَ وَإِنْ كَانَ مَرِيضًا إِلَّا بِالْأَرْضِ، إِلَّا أَنْ يَكُونَ إِنْ نَزَلَ صَلَّى جَالِسًا إِيمَاءً لِمَرَضِهِ، فَلْيُصَلِّ عَلَى الدَّابَّةِ بَعْدَ أَنْ تُوقَفَ لَهُ، وَيَسْتَقْبِلَ بِهَا الْقِبْلَةَ."]]},{"id":"ri13_38","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٨","segs":[["matn","وَمَنْ رَعَفَ مَعَ الْإِمَامِ خَرَجَ فَغَسَلَ الدَّمَ، ثُمَّ بَنَى مَا لَمْ يَتَكَلَّمْ أَوْ يَمْشِ عَلَى نَجَاسَةٍ، وَلَا يَبْنِي عَلَى رَكْعَةٍ لَمْ تَتِمَّ بِسَجْدَتَيْهَا، وَلْيُلْغِهَا،"]]},{"id":"ri13_39","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٣٩","segs":[["matn","وَلَا يَنْصَرِفُ لِدَمٍ خَفِيفٍ، وَلْيَفْتِلْهُ بِأَصَابِعِهِ إِلَّا أَنْ يَسِيلَ أَوْ يَقْطُرَ، وَلَا يَبْنِي فِي قَيْءٍ وَلَا حَدَثٍ، وَمَنْ رَعَفَ بَعْدَ سَلَامِ الْإِمَامِ سَلَّمَ، وَانْصَرَفَ."]]},{"id":"ri13_40","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٤٠","segs":[["matn","وَإِنْ رَعَفَ قَبْلَ سَلَامِهِ انْصَرَفَ، وَغَسَلَ الدَّمَ، ثُمَّ رَجَعَ فَجَلَسَ، وَسَلَّمَ، وَلِلْرَّاعِفِ أَنْ يَبْنِيَ فِي مَنْزِلِهِ إِذَا يَئِسَ أَنْ يُدْرِكَ بَقِيَّةَ صَلَاةِ الْإِمَامِ، إِلَّا فِي الْجُمُعَةِ فَلَا يَبْنِي إِلَّا فِي الْجَامِعِ."]]},{"id":"ri13_41","label":"بَابٌ جَامِعٌ فِي الصَّلَاةِ · ٤١","segs":[["matn","وَيُغْسَلُ قَلِيلُ الدَّمِ مِنَ الثَّوْبِ، وَلَا تُعَادُ الصَّلَاةُ إِلَّا مِنْ كَثِيرِهِ. وَقَلِيلُ كُلِّ نَجَاسَةٍ غَيْرِهِ وَكَثِيرُهَا سَوَاءٌ، وَدَمُ الْبَرَاغِيثِ لَيْسَ عَلَيْهِ غَسْلُهُ إِلَّا أَنْ يَتَفَاحَشَ."]]}]},{"id":"ri14","title":"بَابٌ فِي سُجُودِ الْقُرْآنِ","units":[{"id":"ri14_1","label":"بَابٌ فِي سُجُودِ الْقُرْآنِ · ١","segs":[["matn","وَسُجُودُ الْقُرْآنِ إِحْدَى عَشْرَةَ سَجْدَةً، وَهِيَ الْعَزَائِمُ لَيْسَ فِي الْمُفَصَّلِ مِنْهَا شَيْءٌ، فِي المص عِنْدَ قَوْلِهِ: ﴿وَيُسَبِّحُونَهُ وَلَهُ يَسْجُدُونَ﴾، وَهُوَ آخِرُهَا، فَمَنْ كَانَ فِي صَلَاةٍ فَإِذَا سَجَدَهَا قَامَ فَقَرَأَ مِنَ الْأَنْفَالِ أَوْ مِنْ غَيْرِهَا مَا تَيَسَّرَ عَلَيْهِ، ثُمَّ رَكَعَ."]]},{"id":"ri14_2","label":"بَابٌ فِي سُجُودِ الْقُرْآنِ · ٢","segs":[["matn","وَسَجَدَ وَفِي الرَّعْدِ عِنْدَ قَوْلِهِ ﴿وَظِلَالُهُمْ بِالْغُدُوِّ وَالْآصَالِ﴾، وَفِي النَّحْلِ: ﴿يَخَافُونَ رَبَّهُمْ مِنْ فَوْقِهِمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ﴾، وَفِي بَنِي إِسْرَائِيلَ ﴿وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا﴾، وَفِي مَرْيَمَ ﴿إِذَا تُتْلَى عَلَيْهِمْ آيَاتُ الرَّحْمَنِ خَرُّوا سُجَّدًا وَبُكِيًّا﴾،"]]},{"id":"ri14_3","label":"بَابٌ فِي سُجُودِ الْقُرْآنِ · ٣","segs":[["matn","وَفِي الْحَجِّ أَوَّلُهَا ﴿وَمَنْ يُهِنِ اللَّهُ فَمَا لَهُ مِنْ مُكْرِمٍ إِنَّ اللَّهَ يَفْعَلُ مَا يَشَاءُ﴾، وَفِي الْفُرْقَانِ ﴿أَنَسْجُدُ لِمَا تَأْمُرُنَا وَزَادَهُمْ نُفُورًا﴾، وَفِي الْهُدْهُدِ ﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ رَبُّ الْعَرْشِ الْعَظِيمِ﴾."]]},{"id":"ri14_4","label":"بَابٌ فِي سُجُودِ الْقُرْآنِ · ٤","segs":[["matn","وَفِي الم تَنْزِيلُ ﴿وَسَبَّحُوا بِحَمْدِ رَبِّهِمْ وَهُمْ لَا يَسْتَكْبِرُونَ﴾، وَفِي ص ﴿فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ﴾، وَقِيلَ: عِنْدَ قَوْلِهِ: ﴿لَزُلْفَى وَحُسْنَ مَآبٍ﴾، وَفِي حم تَنْزِيلُ ﴿وَاسْجُدُوا لِلَّهِ الَّذِي خَلَقَهُنَّ إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ﴾."]]},{"id":"ri14_5","label":"بَابٌ فِي سُجُودِ الْقُرْآنِ · ٥","segs":[["matn","وَلَا يَسْجُدُ السَّجْدَةَ فِي التِّلَاوَةِ إِلَّا عَلَى وُضُوءٍ، وَيُكَبِّرُ لَهَا، وَلَا يُسَلِّمُ مِنْهَا، وَفِي التَّكْبِيرِ فِي الرَّفْعِ مِنْهَا سَعَةٌ، وَإِنْ كَبَّرَ فَهُوَ أَحَبُّ إِلَيْنَا،"]]},{"id":"ri14_6","label":"بَابٌ فِي سُجُودِ الْقُرْآنِ · ٦","segs":[["matn","وَيَسْجُدُهَا مَنْ قَرَأَهَا فِي الْفَرِيضَةِ وَالنَّافِلَةِ، وَيَسْجُدُهَا مَنْ قَرَأَهَا بَعْدَ الصُّبْحِ مَا لَمْ يُسْفِرْ، وَبَعْدَ الْعَصْرِ مَا لَمْ تَصْفَرَّ الشَّمْسُ."]]}]},{"id":"ri15","title":"بَابٌ فِي صَلَاةِ السَّفَرِ","units":[{"id":"ri15_1","label":"بَابٌ فِي صَلَاةِ السَّفَرِ · ١","segs":[["matn","وَمَنْ سَافَرَ مَسَافَةَ أَرْبَعَةِ بُرُدٍ وَهِيَ ثَمَانِيَةٌ وَأَرْبَعُونَ مِيلًا فَعَلَيْهِ أَنْ يَقْصُرَ الصَّلَاةَ؛"]]},{"id":"ri15_2","label":"بَابٌ فِي صَلَاةِ السَّفَرِ · ٢","segs":[["matn","فَيُصَلِّيَهَا رَكْعَتَيْنِ إِلَّا الْمَغْرِبَ فَلَا يَقْصُرُهَا، وَلَا يَقْصُرُ حَتَّى يُجَاوِزَ بُيُوتَ الْمِصْرِ وَتَصِيرَ خَلْفَهُ، لَيْسَ بَيْنَ يَدَيْهِ وَلَا بِحِذَائِهِ مِنْهَا شَيْءٌ، ثُمَّ لَا يُتِمُّ حَتَّى يَرْجِعَ إِلَيْهَا أَوْ يُقَارِبَهَا بِأَقَلَّ مِنَ الْمِيلِ."]]},{"id":"ri15_3","label":"بَابٌ فِي صَلَاةِ السَّفَرِ · ٣","segs":[["matn","وَإِنْ نَوَى الْمُسَافِرُ إِقَامَةَ أَرْبَعَةِ أَيَّامٍ بِمَوْضِعٍ أَوْ مَا يُصَلِّي فِيهِ عِشْرِينَ صَلَاةً أَتَمَّ الصَّلَاةَ حَتَّى يَظْعَنَ مِنْ مَكَانِهِ ذَلِكَ."]]},{"id":"ri15_4","label":"بَابٌ فِي صَلَاةِ السَّفَرِ · ٤","segs":[["matn","وَمَنْ خَرَجَ وَلَمْ يُصَلِّ الظُّهْرَ وَالْعَصْرَ، وَقَدْ بَقِيَ مِنَ النَّهَارِ قَدْرُ ثَلَاثِ رَكَعَاتٍ صَلَّاهُمَا سَفَرِيَّتَيْنِ، فَإِنْ بَقِيَ قَدْرُ مَا يُصَلِّي فِيهِ رَكْعَتَيْنِ أَوْ رَكْعَةً صَلَّى الظُّهْرَ حَضَرِيَّةً،"]]},{"id":"ri15_5","label":"بَابٌ فِي صَلَاةِ السَّفَرِ · ٥","segs":[["matn","وَالْعَصْرَ سَفَرِيَّةً، وَلَوْ دَخَلَ لِخَمْسِ رَكَعَاتٍ نَاسِيًا لَهُمَا صَلَّاهُمَا حَضَرِيَّتَيْنِ، فَإِنْ كَانَ بِقَدْرِ أَرْبَعِ رَكَعَاتٍ فَأَقَلَّ إِلَى رَكْعَةٍ صَلَّى الظُّهْرَ سَفَرِيَّةً وَالْعَصْرَ حَضَرِيَّةً."]]},{"id":"ri15_6","label":"بَابٌ فِي صَلَاةِ السَّفَرِ · ٦","segs":[["matn","وَإِنْ قَدِمَ فِي لَيْلٍ وَقَدْ بَقِيَ لِلْفَجْرِ رَكْعَةٌ فَأَكْثَرُ وَلَمْ يَكُنْ صَلَّى الْمَغْرِبَ وَالْعِشَاءَ صَلَّى الْمَغْرِبَ ثَلَاثًا وَالْعِشَاءَ حَضَرِيَّةً، وَلَوْ خَرَجَ وَقَدْ بَقِيَ مِنَ اللَّيْلِ رَكْعَةٌ فَأَكْثَرُ صَلَّى الْمَغْرِبَ ثُمَّ صَلَّى الْعِشَاءَ سَفَرِيَّةً."]]}]},{"id":"ri16","title":"بَابٌ فِي صَلَاةِ الْجُمُعَةِ","units":[{"id":"ri16_1","label":"بَابٌ فِي صَلَاةِ الْجُمُعَةِ · ١","segs":[["matn","وَالسَّعْيُ إِلَى الْجُمُعَةِ فَرِيضَةٌ، وَذَلِكَ عِنْدَ جُلُوسِ الْإِمَامِ عَلَى الْمِنْبَرِ وَأَخَذَ الْمُؤَذِّنُونَ فِي الْأَذَانِ، وَالسُّنَّةُ الْمُتَقَدِّمَةُ أَنْ يَصْعَدُوا حِينَئِذٍ عَلَى الْمَنَارِ؛"]]},{"id":"ri16_2","label":"بَابٌ فِي صَلَاةِ الْجُمُعَةِ · ٢","segs":[["matn","فَيُؤَذِّنُونَ، وَيَحْرُمُ حِينَئِذٍ الْبَيْعُ وَكُلُّ مَا يَشْغَلُ عَنِ السَّعْيِ إِلَيْهَا، وَهَذَا الْأَذَانُ الثَّانِي أَحْدَثَهُ بَنُو أُمَيَّةَ، وَالْجُمُعَةُ تَجِبُ بِالْمِصْرِ وَالْجَمَاعَةِ."]]},{"id":"ri16_3","label":"بَابٌ فِي صَلَاةِ الْجُمُعَةِ · ٣","segs":[["matn","وَالْخُطْبَةُ فِيهَا وَاجِبَةٌ قَبْلَ الصَّلَاةِ، وَيَتَوَكَّأُ الْإِمَامُ عَلَى قَوْسٍ أَوْ عَصًا وَيَجْلِسُ فِي أَوَّلِهَا وَفِي وَسَطِهَا، وَتُقَامُ الصَّلَاةُ عِنْدَ فَرَاغِهَا، وَيُصَلِّي الْإِمَامُ رَكْعَتَيْنِ يَجْهَرُ فِيهِمَا بِالْقِرَاءَةِ: يَقْرَأُ فِي الْأُولَى بِالْجُمُعَةِ وَنَحْوِهَا، وَفِي الثَّانِيَةِ ﴿بِهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ﴾ وَنَحْوِهَا."]]},{"id":"ri16_4","label":"بَابٌ فِي صَلَاةِ الْجُمُعَةِ · ٤","segs":[["matn","وَيَجِبُ السَّعْيُ إِلَيْهَا عَلَى مَنْ فِي الْمِصْرِ وَمَنْ عَلَى ثَلَاَثَةِ أَمْيَالٍ مِنْهُ فَأَقَلَّ، وَلَا تَجِبُ عَلَى مُسَافِرٍ وَلَا عَلَى أَهْلِ مِنًى وَلَا عَلَى عَبْدٍ وَلَا امْرَأَةٍ وَلَا صَبِيٍّ،"]]},{"id":"ri16_5","label":"بَابٌ فِي صَلَاةِ الْجُمُعَةِ · ٥","segs":[["matn","وَإِنْ حَضَرَهَا عَبْدٌ أَوِ امْرَأَةٌ فَلْيُصَلِّهَا، وَتَكُونُ النِّسَاءُ خَلْفَ صُفُوفِ الرِّجَالِ، وَلَا تَخْرُجُ إِلَيْهَا الشَّابَّةُ، وَيُنْصَتُ لِلْإِمَامِ فِي خُطْبَتِهِ، وَيَسْتَقْبِلُهُ النَّاسُ."]]},{"id":"ri16_6","label":"بَابٌ فِي صَلَاةِ الْجُمُعَةِ · ٦","segs":[["matn","وَالْغُسْلُ لَهَا وَاجِبٌ، وَالتَّهْجِيرُ حَسَنٌ، وَلَيْسَ ذَلِكَ فِي أَوَّلِ النَّهَارِ، وَلْيَتَطَيَّبْ لَهَا، وَيَلْبَسْ أَحْسَنَ ثِيَابِهِ، وَأَحَبُّ إِلَيْنَا أَنْ يَنْصَرِفَ بَعْدَ فَرَاغِهَا، وَلَا يَتَنَفَّلُ فِي الْمَسْجِدِ، وَلْيَتَنَفَّلْ إِنْ شَاءَ قَبْلَهَا، وَلَا يَفْعَلُ ذَلِكَ الْإِمَامُ، وَلْيَرْقَ الْمِنْبَرَ كَمَا يَدْخُلُ."]]}]},{"id":"ri17","title":"بَابٌ فِي صَلَاةِ الْخَوْفِ","units":[{"id":"ri17_1","label":"بَابٌ فِي صَلَاةِ الْخَوْفِ · ١","segs":[["matn","وَصَلَاةُ الْخَوْفِ فِي السَّفَرِ إِذَا خَافُوا الْعَدُوَّ أَنْ يَتَقَدَّمَ الْإِمَامُ بِطَائِفَةٍ، وَيَدَعَ طَائِفَةً مُوَاجِهَةً الْعَدُوَّ، فَيُصَلِّي الْإِمَامُ بِطَائِفَةٍ رَكْعَةً، ثُمَّ يَثْبُتُ قَائِمًا، وَيُصَلُّونَ لِأَنْفُسِهِمْ رَكْعَةً، ثُمَّ يُسَلِّمُونَ، فَيَقِفُونَ مَكَانَ أَصْحَابِهِمْ، ثُمَّ يَأْتِي أَصْحَابُهُمْ،"]]},{"id":"ri17_2","label":"بَابٌ فِي صَلَاةِ الْخَوْفِ · ٢","segs":[["matn","فَيُحْرِمُونَ خَلْفَ الْإِمَامِ، فَيُصَلِّي بِهِمُ الرَّكْعَةَ الثَّانِيَةَ، ثُمَّ يَتَشَهَّدُ وَيُسَلِّمُ، ثُمَّ يَقْضُونَ الرَّكْعَةَ الَّتِي فَاتَتْهُمْ، وَيَنْصَرِفُونَ هَكَذَا يَفْعَلُ فِي صَلَاةِ الْفَرَائِضِ كُلِّهَا إِلَّا الْمَغْرِبَ؛ فَإِنَّهُ يُصَلِّي بِالطَّائِفَةِ الْأُولَى رَكْعَتَيْنِ وَبِالثَّانِيَةِ رَكْعَةً."]]},{"id":"ri17_3","label":"بَابٌ فِي صَلَاةِ الْخَوْفِ · ٣","segs":[["matn","وَإِنْ صَلَّى بِهِمْ فِي الْحَضَرِ لِشِدَّةِ خَوْفٍ صَلَّى فِي الظُّهْرِ وَالْعَصْرِ وَالْعِشَاءِ بِكُلِّ طَائِفَةٍ رَكْعَتَيْنِ، وَلِكُلِّ صَلَاةٍ أَذَانٌ وَإِقَامَةٌ."]]},{"id":"ri17_4","label":"بَابٌ فِي صَلَاةِ الْخَوْفِ · ٤","segs":[["matn","وَإِذَا اشْتَدَّ الْخَوْفُ عَنْ ذَلِكَ صَلُّوْا وُحْدَانًا بِقَدْرِ طَاقَتِهِمْ مُشَاةً أَوْ رُكْبَانًا، مَاشِينَ أَوْ سَاعِينَ، مُسْتَقْبِلِي الْقِبْلَةِ وَغَيْرَ مُسْتَقْبِلِيهَا."]]}]},{"id":"ri18","title":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى","units":[{"id":"ri18_1","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ١","segs":[["matn","وَصَلَاةُ الْعِيدَيْنِ سُنَّةٌ وَاجِبَةٌ، يَخْرُجُ لَهَا الْإِمَامُ وَالنَّاسُ ضَحْوَةً بِقَدْرِ مَا إِذَا وَصَلَ حَانَتِ الصَّلَاةُ."]]},{"id":"ri18_2","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ٢","segs":[["matn","وَلَيْسَ فِيهَا أَذَانٌ وَلَا إِقَامَةٌ، فَيُصَلِّي بِهِمْ رَكْعَتَيْنِ: يَقْرَأُ فِيهِمَا جَهْرًا بِأُمِّ الْقُرْآنِ وَسَبِّحِ ﴿اسْمَ رَبِّكَ الْأَعْلَى﴾ وَالشَّمْسُ وَضُحَاهَا وَنَحْوِهِمَا وَيُكَبِّرُ فِي الْأُولَى سَبْعًا قَبْلَ الْقِرَاءَةِ يَعُدُّ فِيهَا تَكْبِيرَةَ الْإِحْرَامِ، وَفِي الثَّانِيَةِ خَمْسَ تَكْبِيرَاتٍ لَا يَعُدُّ فِيهَا تَكْبِيرَةَ الْقِيَامِ."]]},{"id":"ri18_3","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ٣","segs":[["matn","وَفِي كُلِّ رَكْعَةٍ سَجْدَتَانِ ثُمَّ يَتَشَهَّدُ وَيُسَلِّمُ. ثُمَّ يَرْقَى الْمِنْبَرَ وَيَخْطُبُ، وَيَجْلِسُ فِي أَوَّلِ خُطْبَتِهِ وَوَسَطِهَا، ثُمَّ يَنْصَرِفُ. وَيُسْتَحَبُّ أَنْ يَرْجِعَ مِنْ طَرِيقٍ غَيْرِ الطَّرِيقِ الَّتِي أَتَى مِنْهَا، وَالنَّاسُ كَذَلِكَ."]]},{"id":"ri18_4","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ٤","segs":[["matn","وَإِنْ كَانَ فِي الْأَضْحَى خَرَجَ بِأُضْحِيَّتِهِ إِلَى الْمُصَلَّى فَذَبَحَهَا أَوْ نَحَرَهَا؛"]]},{"id":"ri18_5","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ٥","segs":[["matn","لِيَعْلَمَ ذَلِكَ النَّاسُ، فَيَذْبَحُونَ بَعْدَهُ، وَلْيَذْكُرِ اللَّهَ فِي خُرُوجِهِ مِنْ بَيْتِهِ فِي الْفِطْرِ وَالْأَضْحَى جَهْرًا، حَتَّى يَأْتِيَ الْمُصَلَّى الْإِمَامُ، وَالنَّاسُ كَذَلِكَ، فَإِذَا دَخَلَ الْإِمَامُ لِلصَّلَاةِ قَطَعُوا ذَلِكَ، وَيُكَبِّرُونَ بِتَكْبِيرِ الْإِمَامِ فِي خُطْبَتِهِ، وَيُنْصِتُونَ لَهُ فِيمَا سِوَى ذَلِكَ."]]},{"id":"ri18_6","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ٦","segs":[["matn","فَإِنْ كَانَتْ أَيَّامَ النَّحْرِ فَلْيُكَبِّرِ النَّاسُ دُبُرَ الصَّلَوَاتِ مِنْ صَلَاِةِ الظُّهْرِ مِنْ يَوْمِ النَّحْرِ إِلَى صَلَاةِ الصُّبْحِ مِنَ الْيَوْمِ الرَّابِعِ مِنْهُ، وَهُوَ آخِرُ أَيَّامِ مِنًى، يُكَبِّرُ إِذَا صَلَّى الصُّبْحَ ثُمَّ يَقْطَعُ."]]},{"id":"ri18_7","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ٧","segs":[["matn","وَالتَّكْبِيرُ دُبُرَ الصَّلَوَاتِ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، وَإِنْ جَمَعَ مَعَ التَّكْبِيرِ تَهْلِيلًا وَتَحْمِيدًا فَحَسَنٌ؛"]]},{"id":"ri18_8","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ٨","segs":[["matn","يَقُولُ إِنْ شَاءَ ذَلِكَ: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، وَلِلَّهِ الْحَمْدُ، وَقَدْ رُوِيَ عَنْ مَالِكٍ هَذَا وَالْأَوَّلُ، وَالْكُلُّ وَاسِعٌ."]]},{"id":"ri18_9","label":"بَابٌ فِي صَلَاةِ الْعِيدَيْنِ وَالتَّكْبِيرِ أَيَّامَ مِنًى · ٩","segs":[["matn","وَالْأَيَّامُ الْمَعْلُومَاتُ أَيَّامُ النَّحْرِ الثَّلَاثَةُ، وَالْأَيَّامُ الْمَعْدُودَاتُ أَيَّامُ مِنًى، وَهِيَ ثَلَاثَةُ أَيَّامٍ بَعْدَ يَوْمِ النَّحْرِ، وَالْغُسْلُ لِلْعِيدَيْنِ حَسَنٌ، وَلَيْسَ بِلَازِمٍ، وَيُسْتَحَبُّ فِيهِمَا الطِّيبُ وَالْحَسَنُ مِنَ الثِّيَابِ."]]}]},{"id":"ri19","title":"بَابٌ فِي صَلَاةِ الْخُسُوفِ","units":[{"id":"ri19_1","label":"بَابٌ فِي صَلَاةِ الْخُسُوفِ · ١","segs":[["matn","وَصَلَاةُ الْخُسُوفِ سُنَّةٌ وَاجِبَةٌ، إِذَا خَسَفَتِ الشَّمْسُ خَرَجَ الْإِمَامُ إِلَى الْمَسْجِدِ، فَافْتَتَحَ الصَّلَاةَ بِالنَّاسِ بِغَيْرِ أَذَانٍ وَلَا إِقَامَةٍ، ثُمَّ قَرَأَ قِرَاءَةً طَوِيلَةً سِرًّا بِنَحْوِ سُورَةِ الْبَقَرَةِ،"]]},{"id":"ri19_2","label":"بَابٌ فِي صَلَاةِ الْخُسُوفِ · ٢","segs":[["matn","ثُمَّ يَرْكَعُ رُكُوعًا طَوِيلًا نَحْوَ ذَلِكَ، ثُمَّ يَرْفَعُ رَأْسَهُ يَقُولُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، ثُمَّ يَقْرَأُ دُونَ قِرَاءَتِهِ الْأُولَى، ثُمَّ يَرْكَعُ نَحْوَ قِرَاءَتِهِ الثَّانِيَةِ،"]]},{"id":"ri19_3","label":"بَابٌ فِي صَلَاةِ الْخُسُوفِ · ٣","segs":[["matn","ثُمَّ يَرْفَعُ رَأْسَهُ يَقُولُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، ثُمَّ يَسْجُدُ سَجْدَتَيْنِ تَامَّتَيْنِ، ثُمَّ يَقُومُ، فَيَقْرَأُ دُونَ قِرَاءَتِهِ الَّتِي تَلِي ذَلِكَ، ثُمَّ يَرْكَعُ نَحْوَ قِرَاءَتِهِ،"]]},{"id":"ri19_4","label":"بَابٌ فِي صَلَاةِ الْخُسُوفِ · ٤","segs":[["matn","ثُمَّ يَرْفَعُ كَمَا ذَكَرْنَا، ثُمَّ يَقْرَأُ دُونَ قِرَاءَتِهِ هَذِهِ، ثُمَّ يَرْكَعُ نَحْوَ ذَلِكَ، ثُمَّ يَرْفَعُ كَمَا ذَكَرْنَا، ثُمَّ يَسْجُدُ كَمَا ذَكَرْنَا، ثُمَّ يَتَشَهَّدُ وَيُسَلِّمُ."]]},{"id":"ri19_5","label":"بَابٌ فِي صَلَاةِ الْخُسُوفِ · ٥","segs":[["matn","وَلِمَنْ شَاءَ أَنْ يُصَلِّيَ فِي بَيْتِهِ مِثْلَ ذَلِكَ فَلْيَفْعَلْ، وَلَيْسَ فِي صَلَاةِ خُسُوفِ الْقَمَرِ جَمَاعَةٌ، وَلْيُصَلِّ النَّاسُ عِنْدَ ذَلِكَ أَفْذَاذًا وَالْقِرَاءَةُ فِيهَا جَهْرًا كَسَائِرِ رُكُوعِ النَّوَافِلِ، وَلَيْسَ فِي أَثَرِ صَلَاةِ خُسُوفِ الشَّمْسِ خُطْبَةٌ مُرَتَّبَةٌ، وَلَا بَأْسَ أَنْ يَعِظَ النَّاسَ وَيُذَكِّرَهُمْ."]]}]},{"id":"ri20","title":"بَابٌ فِي صَلَاةِ الِاسْتِسْقَاءِ","units":[{"id":"ri20_1","label":"بَابٌ فِي صَلَاةِ الِاسْتِسْقَاءِ · ١","segs":[["matn","وَصَلَاةُ الِاسْتِسْقَاءِ سُنَّةٌ تُقَامُ، يَخْرُجُ لَهَا الْإِمَامُ كَمَا يَخْرُجُ لِلْعِيدَيْنِ ضَحْوَةً، فَيُصَلِّي بِالنَّاسِ رَكْعَتَيْنِ يَجْهَرُ فِيهِمَا بِالْقِرَاءَةِ، يَقْرَأُ ﴿بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى﴾، ﴿وَالشَّمْسِ وَضُحَاهَا﴾، وَفِي كُلِّ رَكْعَةٍ سَجْدَتَانِ وَرَكْعَةٌ وَاحِدَةٌ، وَيَتَشَهَّدُ وَيُسَلِّمُ."]]},{"id":"ri20_2","label":"بَابٌ فِي صَلَاةِ الِاسْتِسْقَاءِ · ٢","segs":[["matn","ثُمَّ يَسْتَقْبِلُ النَّاسَ بِوَجْهِهِ، فَيَجْلِسُ جَلْسَةً، فَإِذَا اطْمَأَنَّ النَّاسُ قَامَ مُتَوَكِّئًا عَلَى قَوْسٍ أَوْ عَصًا فَخَطَبَ، ثُمَّ جَلَسَ، ثُمَّ قَامَ فَخَطَبَ، فَإِذَا فَرَغَ اسْتَقْبَلَ الْقِبْلَةَ،"]]},{"id":"ri20_3","label":"بَابٌ فِي صَلَاةِ الِاسْتِسْقَاءِ · ٣","segs":[["matn","فَحَوَّلَ رِدَاءَهُ يَجْعَلُ مَا عَلَى مَنْكِبِهِ الْأَيْمَنِ عَلَى الْأَيْسَرِ، وَمَا عَلَى الْأَيْسَرِ عَلَى الْأَيْمَنِ، وَلَا يَقْلِبُ ذَلِكَ، وَلْيَفْعَلِ النَّاسُ مِثْلَهُ وَهُوَ قَائِمٌ، وَهُمْ قُعُودٌ ثُمَّ يَدْعُو كَذَلِكَ، ثُمَّ يَنْصَرِفُ وَيَنْصَرِفُونَ."]]},{"id":"ri20_4","label":"بَابٌ فِي صَلَاةِ الِاسْتِسْقَاءِ · ٤","segs":[["matn","وَلَا يُكَبِّرُ فِيهَا وَلَا فِي الْخُسُوفِ غَيْرَ تَكْبِيرَةِ الْإِحْرَامِ وَالْخَفْضِ وَالرَّفْعِ، وَلَا أَذَانَ فِيهَا وَلَا إِقَامَةَ."]]}]},{"id":"ri21","title":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ","units":[{"id":"ri21_1","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ١","segs":[["matn","وَيُسْتَحَبُّ اسْتِقْبَالُ الْقِبْلَةِ بِالْمُحْتَضَرِ وَإِغْمَاضُهُ إِذَا قَضَى، وَيُلَقَّنُ لَا إِلَهَ إِلَّا اللَّهُ عِنْدَ الْمَوْتِ، وَإِنْ قُدِرَ عَلَى أَنْ يَكُونَ طَاهِرًا وَمَا عَلَيْهِ طَاهِرٌ فَهُوَ أَحْسَنُ،"]]},{"id":"ri21_2","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ٢","segs":[["matn","وَيُسْتَحَبُّ أَنْ لَا يَقْرَبَهُ حَائِضٌ وَلَا جُنُبٌ وَأَرْخَصَ بَعْضُ الْعُلَمَاءِ فِي الْقِرَاءَةِ عِنْدَ رَأْسِهِ بِسُورَةِ يس، وَلَمْ يَكُنْ ذَلِكَ عِنْدَ مَالِكٍ أَمْرًا مَعْمُولًا بِهِ، وَلَا بَأْسَ بِالْبُكَاءِ بِالدُّمُوعِ حِينَئِذٍ، وَحَسُنَ التَّعَزِّي وَالتَّصَبُّرُ أَجْمَلُ لِمَنِ اسْتَطَاعَ، وَيُنْهَى عَنِ الصُّرَاخِ وَالنِّيَاحَةِ."]]},{"id":"ri21_3","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ٣","segs":[["matn","وَلَيْسَ فِي غُسْلِ الْمَيِّتِ حَدٌّ، وَلَكِنْ يُنْقَى، وَيُغَسَّلُ وِتْرًا بِمَاءٍ وَسِدْرٍ، وَيُجْعَلُ فِي الْأَخِيرَةِ كَافُورٌ وَتُسْتَرُ عَوْرَتُهُ، وَلَا تُقَلَّمُ أَظْفَارُهُ،"]]},{"id":"ri21_4","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ٤","segs":[["matn","وَلَا يُحْلَقُ شَعْرُهُ وَيُعْصَرُ بَطْنُهُ عَصْرًا رَفِيقًا، وَإِنْ وُضِّئَ وُضُوءَ الصَّلَاةِ فَحَسَنٌ، وَلَيْسَ بِوَاجِبٍ، وَيُقْلَبُ لِجَنْبِهِ فِي الْغُسْلِ أَحْسَنُ، وَإِنْ أُجْلِسَ فَذَلِكَ وَاسِعٌ."]]},{"id":"ri21_5","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ٥","segs":[["matn","وَلَا بَأْسَ بِغُسْلِ أَحَدِ الزَّوْجَيْنِ صَاحِبَهُ مِنْ غَيْرِ ضَرُورَةٍ، وَالْمَرْأَةُ تَمُوتُ فِي السَّفَرِ لَا نِسَاءَ مَعَهَا وَلَا مَحْرَمَ مِنَ الرِّجَالِ فَلْيُيَمِّمْ رَجُلٌ وَجْهَهَا وَكَفَّيْهَا،"]]},{"id":"ri21_6","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ٦","segs":[["matn","وَلَوْ كَانَ الْمَيِّتُ رَجُلًا يَمَّمَ النِّسَاءُ وَجْهَهُ وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ إِنْ لَمْ يَكُنْ مَعَهُنَّ رَجُلٌ يُغَسِّلُهُ وَلَا امْرَأَةٌ مِنْ مَحَارِمِهِ،"]]},{"id":"ri21_7","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ٧","segs":[["matn","فَإِنْ كَانَتِ امْرَأَةٌ مِنْ مَحَارِمِهِ غَسَّلَتْهُ وَسَتَرَتْ عَوْرَتَهُ، وَإِنْ كَانَ مَعَ الْمَيِّتَةِ ذُو مَحْرَمٍ غَسَّلَهَا مِنْ فَوْقِ ثَوْبٍ يَسْتُرُ جَمِيعَ جَسَدِهَا."]]},{"id":"ri21_8","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ٨","segs":[["matn","وَيُسْتَحَبُّ أَنْ يُكَفَّنَ الْمَيِّتُ فِي وِتْرٍ: ثَلَاثَةِ أَثْوَابٍ أَوْ خَمْسَةٍ أَوْ سَبْعَةٍ، وَمَا جُعِلَ لَهُ مِنْ أُزْرَةٍ وَقَمِيصٍ وَعِمَامَةٍ فَذَلِكَ مَحْسُوبٌ فِي عَدَدِ الْأَثْوَابِ الْوِتْرِ،"]]},{"id":"ri21_9","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ٩","segs":[["matn","وَقَدْ كُفِّنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ثَلَاثَةِ أَثْوَابٍ بِيضٍ سَحُولِيَّةٍ، أُدْرِجَ فِيهَا إِدْرَاجًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَا بَأْسَ أَنْ يُقَمَّصَ الْمَيِّتُ وَيُعَمَّمَ، وَيَنْبَغِي أَنْ يُحَنَّطَ، وَيُجْعَلُ الْحَنُوطُ بَيْنَ أَكْفَانِهِ وَفِي جَسَدِهِ وَمَوَاضِعِ السُّجُودِ مِنْهُ."]]},{"id":"ri21_10","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ١٠","segs":[["matn","وَلَا يُغَسَّلُ الشَّهِيدُ فِي الْمُعْتَرَكِ، وَلَا يُصَلَّى عَلَيْهِ، وَيُدْفَنُ بِثِيَابِهِ، وَيُصَلَّى عَلَى قَاتِلِ نَفْسِهِ، وَيُصَلَّى عَلَى مَنْ قَتَلَهُ الْإِمَامُ فِي حَدٍّ أَوْ قَوَدٍ، وَلَا يُصَلِّي عَلَيْهِ الْإِمَامُ، وَلَا يُتْبَعُ الْمَيِّتُ بِمِجْمَرٍ، وَالْمَشْيُ أَمَامَ الْجِنَازَةِ أَفْضَلُ."]]},{"id":"ri21_11","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ١١","segs":[["matn","وَيُجْعَلُ الْمَيِّتُ فِي قَبْرِهِ عَلَى شِقِّهِ الْأَيْمَنِ، وَيُنْصَبُ عَلَيْهِ اللَّبِنُ، وَيَقُولُ حِينَئِذٍ: اللَّهُمَّ إِنَّ صَاحِبَنَا قَدْ نَزَلَ بِكَ وَخَلَّفَ الدُّنْيَا وَرَاءَ ظَهْرِهِ، وَافْتَقَرَ إِلَى مَا عِنْدَكَ،"]]},{"id":"ri21_12","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ١٢","segs":[["matn","اللَّهُمَّ ثَبِّتْ عِنْدَ الْمَسْأَلَةِ مَنْطِقَهُ، وَلَا تَبْتَلِهِ فِي قَبْرِهِ بِمَا لَا طَاقَةَ لَهُ بِهِ، وَأَلْحِقْهُ بِنَبِيِّهِ، مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيُكْرَهُ الْبِنَاءُ عَلَى الْقُبُورِ وَتَجْصِيصُهَا."]]},{"id":"ri21_13","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ١٣","segs":[["matn","وَلَا يُغَسِّلُ الْمُسْلِمُ أَبَاهُ الْكَافِرَ، وَلَا يُدْخِلُهُ قَبْرَهُ، إِلَّا أَنْ يَخَافَ أَنْ يَضِيعَ فَلْيُوَارِهِ."]]},{"id":"ri21_14","label":"بَابُ مَا يُفْعَلُ بِالْمُحْتَضَرِ وَفِي غُسْلِ الْمَيِّتِ وَكَفَنِهِ وَتَحْنِيطِهِ وَحَمْلِهِ وَدَفْنِهِ · ١٤","segs":[["matn","وَاللَّحْدُ أَحَبُّ إِلَى أَهْلِ الْعِلْمِ مِنَ الشَّقِّ، وَهُوَ أَنْ يُحْفَرَ لِلْمَيِّتِ تَحْتَ الْجَرْفِ فِي حَائِطِ قِبْلَةِ الْقَبْرِ؛ وَذَلِكَ إِذَا كَانَتْ تُرْبَةً صُلْبَةً: لَا تَتَهَيَّلُ وَلَا تَتَقَطَّعُ وَكَذَلِكَ فُعِلَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]}]},{"id":"ri22","title":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ","units":[{"id":"ri22_1","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ١","segs":[["matn","وَالتَّكْبِيرُ عَلَى الْجِنَازَةِ أَرْبَعُ تَكْبِيرَاتٍ، يَرْفَعُ يَدَيْهِ فِي أُولَاهُنَّ، وَإِنْ رَفَعَ فِي كُلِّ تَكْبِيرَةٍ فَلَا بَأْسَ، وَإِنْ شَاءَ دَعَا بَعْدَ الْأَرْبَعِ ثُمَّ يُسَلِّمُ،"]]},{"id":"ri22_2","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ٢","segs":[["matn","وَإِنْ شَاءَ سَلَّمَ بَعْدَ الرَّابِعَةِ مَكَانَهُ، وَيَقِفُ الْإِمَامُ فِي الرَّجُلِ عِنْدَ وَسَطِهِ، وَفِي الْمَرْأَةِ عِنْدَ مَنْكِبَيْهَا، وَالسَّلَامُ مِنَ الصَّلَاةِ عَلَى الْجَنَائِزِ تَسْلِيمَةٌ وَاحِدَةٌ خَفِيَّةٌ لِلْإِمَامِ وَالْمَأْمُومِ."]]},{"id":"ri22_3","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ٣","segs":[["matn","وَفِي الصَّلَاةِ عَلَى الْمَيِّتِ قِيرَاطٌ مِنَ الْأَجْرِ، وَقِيرَاطٌ فِي حُضُورِ دَفْنِهِ، وَذَلِكَ فِي التَّمْثِيلِ مِثْلُ جَبَلِ أُحُدٍ ثَوَابًا."]]},{"id":"ri22_4","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ٤","segs":[["matn","وَيُقَالُ فِي الدُّعَاءِ عَلَى الْمَيِّتِ غَيْرُ شَيْءٍ، مَحْدُودٍ وَذَلِكَ كُلُّهُ وَاسِعٌ، وَمِنْ مُسْتَحْسَنِ مَا قِيلَ فِي ذَلِكَ أَنْ يُكَبِّرَ ثُمَّ يَقُولَ: الْحَمْدُ لِلَّهِ الَّذِي أَمَاتَ وَأَحْيَا، وَالْحَمْدُ لِلَّهِ الَّذِي يُحْيِي الْمَوْتَى،"]]},{"id":"ri22_5","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ٥","segs":[["matn","لَهُ الْعَظَمَةُ وَالْكِبْرِيَاءُ، وَالْمُلْكُ وَالْقُدْرَةُ وَالسَّنَاءُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ وَرَحِمْتَ وَبَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ."]]},{"id":"ri22_6","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ٦","segs":[["matn","اللَّهُمَّ إِنَّهُ عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ، أَنْتَ خَلَقْتَهُ وَرَزَقْتَهُ، وَأَنْتَ أَمَتَّهُ، وَأَنْتَ تُحْيِيهِ، وَأَنْتَ أَعْلَمُ بِسِرِّهِ وَعَلَانِيَتِهِ، جِئْنَاكَ شُفَعَاءَ لَهُ، فَشَفِّعْنَا فِيهِ، اللَّهُمَّ إِنَّا نَسْتَجِيرُ بِحَبْلِ جِوَارِكَ لَهُ؛"]]},{"id":"ri22_7","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ٧","segs":[["matn","إِنَّكَ ذُو وَفَاءٍ وَذِمَّةٍ، اللَّهُمَّ قِهِ مِنْ فِتْنَةِ الْقَبْرِ وَمِنْ عَذَابِ جَهَنَّمَ."]]},{"id":"ri22_8","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ٨","segs":[["matn","اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ، وَاعْفُ عَنْهُ وَعَافِهِ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِمَاءٍ وَثَلْجٍ وَبَرَدٍ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ،"]]},{"id":"ri22_9","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ٩","segs":[["matn","وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، اللَّهُمَّ إِنْ كَانَ مُحْسِنًا فَزِدْ فِي إِحْسَانِهِ، وَإِنْ كَانَ مُسِيئًا فَتَجَاوَزْ عَنْهُ."]]},{"id":"ri22_10","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ١٠","segs":[["matn","اللَّهُمَّ إِنَّهُ قَدْ نَزَلَ بِكَ وَأَنْتَ خَيْرُ مَنْزُولٍ بِهِ فَقِيرٌ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ، الَّلَّهُمَّ ثَبِّتْ عِنْدَ الْمَسْأَلَةِ مَنْطِقَهُ، وَلَا تَبْتَلِهِ فِي قَبْرِهِ بِمَا لَا طَاقَةَ لَهُ بِهِ، اللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ، وَلَا تَفْتِنَّا بَعْدَهُ."]]},{"id":"ri22_11","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ١١","segs":[["matn","تَقُولُ هَذَا بِأَثَرِ كُلِّ تَكْبِيرَةٍ. وَتَقُولُ بَعْدَ الرَّابِعَةِ: اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَحَاضِرِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا، إِنَّكَ تَعْلَمُ مُتَقَلَّبَنَا وَمَثْوَانَا، وَلِوَالِدَيْنَا وَلِمَنْ سَبَقَنَا بِالْإِيمَانِ، وَلِلْمُسْلِمِينَ وَالْمُسْلِمَاتِ، وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ الْأَحْيَاءِ مِنْهُمْ وَالْأَمْوَاتِ، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِيمَانِ،"]]},{"id":"ri22_12","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ١٢","segs":[["matn","وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِسْلَامِ، وَأَسْعِدْنَا بِلِقَائِكَ، وَطَيِّبْنَا لِلْمَوْتِ، وَطَيِّبْهُ لَنَا، وَاجْعَلْ فِيهِ رَاحَتَنَا وَمَسَرَّتَنَا، ثُمَّ تُسَلِّمُ وَإِنْ كَانَتِ امْرَأَةً قُلْتَ: اللَّهُمَّ إِنَّهَا أَمَتُكَ، ثُمَّ تَتَمَادَى بِذِكْرِهَا عَلَى التَّأْنِيثِ غَيْرَ أَنَّكَ لَا تَقُولُ: وَأَبْدِلْهَا زَوْجًا خَيْرًا مِنْ زَوْجِهَا؛"]]},{"id":"ri22_13","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ١٣","segs":[["matn","لِأَنَّهَا قَدْ تَكُونُ زَوْجًا فِي الْجَنَّةِ لِزَوْجِهَا فِي الدُّنْيَا، وَنِسَاءُ الْجَنَّةِ مَقْصُورَاتٌ عَلَى أَزْوَاجِهِنَّ، لَا يَبْغِينَ بِهِمْ بَدَلًا، وَالرَّجُلُ قَدْ يَكُونُ لَهُ زَوْجَاتٌ كَثِيرَةٌ فِي الْجَنَّةِ، وَلَا يَكُونُ لِلْمَرْأَةِ أَزْوَاجٌ."]]},{"id":"ri22_14","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ١٤","segs":[["matn","وَلَا بَأْسَ أَنْ تُجْمَعَ الْجَنَائِزُ فِي صَلَاةٍ وَاحِدَةٍ، وَيَلِيَ الْإِمَامَ الرِّجَالُ إِنْ كَانَ فِيهِمْ نِسَاءٌ، وَإِنْ كَانُوا رِجَالًا جُعِلَ أَفْضَلُهُمْ مِمَّا يَلِي الْإِمَامَ، وَجُعِلَ مِنْ دُونِهِ النِّسَاءُ،"]]},{"id":"ri22_15","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ١٥","segs":[["matn","وَالصِّبْيَانُ مِنْ وَرَاءِ ذَلِكَ إِلَى الْقِبْلَةِ، وَلَا بَأْسَ أَنْ يُجْعَلُوا صَفًّا وَاحِدًا، وَيُقَرَّبُ إِلَى الْإِمَامِ أَفْضَلُهُمْ، وَأَمَّا دَفْنُ الْجَمَاعَةِ فِي قَبْرٍ وَاحِدٍ فَيُجْعَلُ أَفْضَلُهُمْ مِمَّا يَلِي الْقِبْلَةَ."]]},{"id":"ri22_16","label":"بَابٌ فِي الصَّلَاةِ عَلَى الْجَنَائِزِ وَالدُّعَاءِ لِلْمَيِّتِ · ١٦","segs":[["matn","وَمَنْ دُفِنَ وَلَمْ يُصَلَّ عَلَيْهِ وَوُورِيَ، فَإِنَّهُ يُصَلَّى عَلَى قَبْرِهِ، وَلَا يُصَلَّى عَلَى مَنْ قَدْ صُلِّيَ عَلَيْهِ، وَيُصَلَّى عَلَى أَكْثَرِ الْجَسَدِ، وَاخْتُلِفَ فِي الصَّلَاِةِ عَلَى مِثْلِ الْيَدِ وَالرِّجْلِ."]]}]},{"id":"ri23","title":"بَابٌ فِي الدُّعَاءِ لِلطِّفْلِ وَالصَّلَاةِ عَلَيْهِ وَغُسْلِهِ","units":[{"id":"ri23_1","label":"بَابٌ فِي الدُّعَاءِ لِلطِّفْلِ وَالصَّلَاةِ عَلَيْهِ وَغُسْلِهِ · ١","segs":[["matn","تُثْنِي عَلَى اللَّهِ، تَبَارَكَ وَتَعَالَى وَتُصَلِّي عَلَى نَبِيِّهِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ تَقُولُ: اللَّهُمَّ إِنَّهُ عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ أَنْتَ خَلَقْتَهُ وَرَزَقْتَهُ، وَأَنْتَ أَمَتَّهُ، وَأَنْتَ تُحْيِيهِ، اللَّهُمَّ فَاجْعَلْهُ لِوَالِدِيهِ سَلَفًا وَذُخْرًا، وَفَرَطًا وَأَجْرًا،"]]},{"id":"ri23_2","label":"بَابٌ فِي الدُّعَاءِ لِلطِّفْلِ وَالصَّلَاةِ عَلَيْهِ وَغُسْلِهِ · ٢","segs":[["matn","وَثَقِّلْ بِهِ مَوَازِينَهُمْ، وَأَعْظِمْ بِهِ أُجُورَهُمْ، وَلَا تَحْرِمْنَا وَإِيَّاهُمْ أَجْرَهُ، وَلَا تَفْتِنَّا وَإِيَّاهُمْ بَعْدَهُ، اللَّهُمَّ أَلْحِقْهُ بِصَالِحِ سَلَفِ الْمُؤْمِنِينَ فِي كَفَالَةِ إِبْرَاهِيمَ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَعَافِهِ مِنْ فِتْنَةِ الْقَبْرِ وَمِنْ عَذَابِ جَهَنَّمَ."]]},{"id":"ri23_3","label":"بَابٌ فِي الدُّعَاءِ لِلطِّفْلِ وَالصَّلَاةِ عَلَيْهِ وَغُسْلِهِ · ٣","segs":[["matn","تَقُولُ ذَلِكَ فِي كُلِّ تَكْبِيرَةٍ، وَتَقُولُ بَعْدَ الرَّابِعَةِ: اللَّهُمَّ اغْفِرْ لِأَسْلَافِنَا وَأَفْرَاطِنَا وَلِمَنْ سَبَقَنَا بِالْإِيمَانِ، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِيمَانِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِسْلَامِ، وَاغْفِرْ لِلْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ الْأَحْيَاءِ مِنْهُمْ وَالْأَمْوَاتِ، ثُمَّ تُسَلِّمُ."]]},{"id":"ri23_4","label":"بَابٌ فِي الدُّعَاءِ لِلطِّفْلِ وَالصَّلَاةِ عَلَيْهِ وَغُسْلِهِ · ٤","segs":[["matn","وَلَا يُصَلَّى عَلَى مَنْ لَمْ يَسْتَهِلَّ صَارِخًا، وَلَا يَرِثُ وَلَا يُورَثُ، وَيُكْرَهُ أَنْ يُدْفَنَ السِّقْطُ فِي الدُّورِ."]]},{"id":"ri23_5","label":"بَابٌ فِي الدُّعَاءِ لِلطِّفْلِ وَالصَّلَاةِ عَلَيْهِ وَغُسْلِهِ · ٥","segs":[["matn","وَلَا بَأْسَ أَنْ يُغَسِّلَ النِّسَاءُ الصَّبِيَّ الصَّغِيرَ ابْنَ سِتِّ سِنِينَ أَوْ سَبْعٍ، وَلَا يُغَسِّلُ الرِّجَالُ الصَّبِيَّةَ، وَاخْتُلِفَ فِيهَا إِنْ كَانَتْ لَمْ تَبْلُغْ أَنْ تُشْتَهَى، وَالْأَوَّلُ أَحَبُّ إِلَيْنَا."]]}]},{"id":"ri24","title":"بَابٌ فِي الصِّيَامِ","units":[{"id":"ri24_1","label":"بَابٌ فِي الصِّيَامِ · ١","segs":[["matn","وَصَوْمُ شَهْرِ رَمَضَانَ فَرِيضَةٌ، يُصَامُ لِرُؤْيَةِ الْهِلَالِ، وَيُفْطَرُ لِرُؤْيَتِهِ، كَانَ ثَلَاثِينَ يَوْمًا أَوْ تِسْعَةً وَعِشْرِينَ يَوْمًا، فَإِنْ غُمَّ الْهِلَالُ فَيُعَدُّ ثَلَاثِينَ يَوْمًا مِنْ غُرَّةِ الشَّهْرِ الَّذِي قَبْلَهُ، ثُمَّ يُصَامُ، وَكَذَلِكَ فِي الْفِطْرِ."]]},{"id":"ri24_2","label":"بَابٌ فِي الصِّيَامِ · ٢","segs":[["matn","وَيُبَيِّتُ الصِّيَامَ فِي أَوَّلِهِ، وَلَيْسَ عَلَيْهِ الْبَيَاتُ فِي بَقِيَّتِهِ، وَيُتِمُّ الصِّيَامَ إِلَى اللَّيْلِ، وَمِنَ السُّنَّةِ تَعْجِيلُ الْفِطْرِ وَتَأْخِيرُ السُّحُورِ، وَإِنْ شَكَّ فِي الْفَجْرِ فَلَا يَأْكُلْ."]]},{"id":"ri24_3","label":"بَابٌ فِي الصِّيَامِ · ٣","segs":[["matn","وَلَا يُصَامُ يَوْمُ الشَّكِّ لِيَحْتَاطَ بِهِ مِنْ رَمَضَانَ، وَمَنْ صَامَهُ كَذَلِكَ لَمْ يُجْزِهِ وَإِنْ وَافَقَهُ مِنْ رَمَضَانَ، وَلِمَنْ شَاءَ صَوْمَهُ تَطَوُّعًا أَنْ يَفْعَلَ،"]]},{"id":"ri24_4","label":"بَابٌ فِي الصِّيَامِ · ٤","segs":[["matn","وَمَنْ أَصْبَحَ فَلَمْ يَأْكُلْ وَلَمْ يَشْرَبْ، ثُمَّ تَبَيَّنَ لَهُ أَنَّ ذَلِكَ الْيَوْمَ مِنْ رَمَضَانَ لَمْ يُجْزِهِ، وَلْيُمْسِكْ عَنِ الْأَكْلِ فِي بَقِيَّتِهِ، وَيَقْضِيهِ."]]},{"id":"ri24_5","label":"بَابٌ فِي الصِّيَامِ · ٥","segs":[["matn","وَإِذَا قَدِمَ الْمُسَافِرُ مُفْطِرًا أَوْ طَهُرَتِ الْحَائِضُ نَهَارًا فَلَهُمَا الْأَكْلُ فِي بَقِيَّةِ يَوْمِهِمَا، وَمَنْ أَفْطَرَ فِي تَطَوُّعِهِ عَامِدًا، أَوْ سَافَرَ فِيهِ فَأَفْطَرَ لِسَفَرِهِ فَعَلَيْهِ الْقَضَاءُ، وَإِنْ أَفْطَرَ سَاهِيًا فَلَا قَضَاءَ عَلَيْهِ بِخِلَافِ الْفَرِيضَةِ."]]},{"id":"ri24_6","label":"بَابٌ فِي الصِّيَامِ · ٦","segs":[["matn","وَلَا بَأْسَ بِالسِّوَاكِ لِلصَّائِمِ فِي جَمِيعِ نَهَارِهِ وَلَا تُكْرَهُ لَهُ الْحِجَامَةُ إِلَّا خِيفَةَ التَّغْرِيرِ، وَمَنْ ذَرَعَهُ الْقَيْءُ فِي رَمَضَانَ فَلَا قَضَاءَ عَلَيْهِ، وَإِنِ اسْتَقَاءَ فَقَاءَ فَعَلَيْهِ الْقَضَاءُ."]]},{"id":"ri24_7","label":"بَابٌ فِي الصِّيَامِ · ٧","segs":[["matn","وَإِذَا خَافَتِ الْحَامِلُ عَلَى مَا فِي بَطْنِهَا أَفْطَرَتْ وَلَمْ تُطْعِمْ، وَقَدْ قِيلَ: تُطْعِمُ، وَلِلْمُرْضِعِ إِنْ خَافَتْ عَلَى وَلَدِهَا، وَلَمْ تَجِدْ مَنْ تَسْتَأْجِرُهُ، لَهُ أَوْ لَمْ يَقْبَلْ غَيْرَهَا أَنْ تُفْطِرَ وَتُطْعِمَ."]]},{"id":"ri24_8","label":"بَابٌ فِي الصِّيَامِ · ٨","segs":[["matn","وَيُسْتَحَبُّ لِلشَّيْخِ الْكَبِيرِ إِذَا أَفْطَرَ أَنْ يُطْعِمَ، وَالْإِطْعَامُ فِي هَذَا كُلِّهِ مُدٌّ عَنْ كُلِّ يَوْمٍ يَقْضِيهِ. وَكَذَلِكَ يُطْعِمُ مَنْ فَرَّطَ فِي قَضَاءِ رَمَضَانَ حَتَّى دَخَلَ عَلَيْهِ رَمَضَانُ آخَرُ."]]},{"id":"ri24_9","label":"بَابٌ فِي الصِّيَامِ · ٩","segs":[["matn","وَلَا صِيَامَ عَلَى الصِّبْيَانِ حَتَّى يَحْتَلِمَ الْغُلَامُ، وَتَحِيضَ الْجَارِيَةُ، وَبِالْبُلُوغِ لَزِمَتْهُمْ أَعْمَالُ الْأَبْدَانِ فَرِيضَةً، قَالَ اللَّهُ سُبْحَانَهُ ﴿وَإِذَا بَلَغَ الْأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا﴾."]]},{"id":"ri24_10","label":"بَابٌ فِي الصِّيَامِ · ١٠","segs":[["matn","وَمَنْ أَصْبَحَ جُنُبًا وَلَمْ يَتَطَهَّرْ أَوِ امْرَأَةٌ حَائِضٌ طَهُرَتْ قَبْلَ الْفَجْرِ فَلَمْ يَغْتَسِلَا إِلَّا بَعْدَ الْفَجْرِ أَجْزَأَهُمَا صَوْمُ ذَلِكَ الْيَوْمِ."]]},{"id":"ri24_11","label":"بَابٌ فِي الصِّيَامِ · ١١","segs":[["matn","وَلَا يَجُوزُ صِيَامُ يَوْمِ الْفِطْرِ وَلَا يَوْمِ النَّحْرِ، وَلَا يَصُومُ الْيَوْمَيْنِ اللَّذَيْنِ بَعْدَ يَوْمِ النَّحْرِ إِلَّا الْمُتَمَتِّعُ الَّذِي لَا يَجِدُ هَدْيًا، وَالْيَوْمُ الرَّابِعُ لَا يَصُومُهُ مُتَطَوِّعٌ، وَيَصُومُهُ مَنْ نَذَرَهُ أَوْ مَنْ كَانَ فِي صِيَامٍ مُتَتَابِعٍ قَبْلَ ذَلِكَ."]]},{"id":"ri24_12","label":"بَابٌ فِي الصِّيَامِ · ١٢","segs":[["matn","وَمَنْ أَفْطَرَ فِي نَهَارِ رَمَضَانَ نَاسِيًا فَعَلَيْهِ الْقَضَاءُ فَقَطْ، وَكَذَلِكَ مَنْ أَفْطَرَ فِيهِ لِضَرُورَةٍ مِنْ مَرَضٍ، وَمَنْ سَافَرَ سَفَرًا تُقْصَرُ فِيهِ الصَّلَاةُ فَلَهُ أَنْ يُفْطِرَ وَإِنْ لَمْ تَنَلْهُ ضَرُورَةٌ، وَعَلَيْهِ الْقَضَاءُ، وَالصَّوْمُ أَحَبُّ إِلَيْنَا."]]},{"id":"ri24_13","label":"بَابٌ فِي الصِّيَامِ · ١٣","segs":[["matn","وَمَنْ سَافَرَ أَقَلَّ مِنْ أَرْبَعَةِ بُرُدٍ؛ فَظَنَّ أَنَّ الْفِطْرَ مُبَاحٌ لَهُ فَأَفْطَرَ فَلَا كَفَّارَةَ عَلَيْهِ، وَعَلَيْهِ الْقَضَاءُ، وَكُلُّ مَنْ أَفْطَرَ مُتَأَوِّلًا فَلَا كَفَّارَةَ عَلَيْهِ، وَإِنَّمَا الْكَفَّارَةُ عَلَى مَنْ أَفْطَرَ مُتَعَمِّدًا بِأَكْلٍ أَوْ شُرْبٍ أَوْ جِمَاعٍ مَعَ الْقَضَاءِ."]]},{"id":"ri24_14","label":"بَابٌ فِي الصِّيَامِ · ١٤","segs":[["matn","وَالْكَفَّارَةُ فِي ذَلِكَ إِطْعَامُ سِتِّينَ مِسْكِينًا لِكُلِّ مِسْكِينٍ مُدٌّ بِمُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؛ فَذَلِكَ أَحَبُّ إِلَيْنَا، وَلَهُ أَنْ يُكَفِّرَ بِعِتْقِ رَقَبَةٍ أَوْ صِيَامِ شَهْرَيْنِ مُتَتَابِعَيْنِ، وَلَيْسَ عَلَى مَنْ أَفْطَرَ فِي قَضَاءِ رَمَضَانَ مُتَعَمِّدًا كَفَّارَةٌ."]]},{"id":"ri24_15","label":"بَابٌ فِي الصِّيَامِ · ١٥","segs":[["matn","وَمَنْ أُغْمِيَ عَلَيْهِ لَيْلًا فَأَفَاقَ بَعْدَ طُلُوعِ الْفَجْرِ فَعَلَيْهِ قَضَاءُ الصَّوْمِ، وَلَا يَقْضِي مِنَ الصَّلَوَاتِ إِلَّا مَا أَفَاقَ فِي وَقْتِهِ."]]},{"id":"ri24_16","label":"بَابٌ فِي الصِّيَامِ · ١٦","segs":[["matn","وَيَنْبَغِي لِلصَّائِمِ أَنْ يَحْفَظَ لِسَانَهُ وَجَوَارِحَهُ، وَيُعَظِّمَ مِنْ شَهْرِ رَمَضَانَ مَا عَظَّمَ اللَّهُ سُبْحَانَهُ وَتَعَالَى، وَلَا يَقْرَبُ الصَّائِمُ النِّسَاءَ بِوَطْءٍ وَلَا مُبَاشَرَةٍ وَلَا قُبْلَةٍ لِلَذَّةٍ فِي نَهَارِ رَمَضَانَ،"]]},{"id":"ri24_17","label":"بَابٌ فِي الصِّيَامِ · ١٧","segs":[["matn","وَلَا يَحْرُمُ ذَلِكَ عَلَيْهِ فِي لَيْلِهِ، وَلَا بَأْسَ أَنْ يُصْبِحَ جُنُبًا مِنَ الْوَطْءِ، وَمَنِ الْتَذَّ فِي نَهَارِ رَمَضَانَ بِمُبَاشَرَةٍ أَوْ قُبْلَةٍ فَأَمْذَى لِذَلِكَ فَعَلَيْهِ الْقَضَاءُ."]]},{"id":"ri24_18","label":"بَابٌ فِي الصِّيَامِ · ١٨","segs":[["matn","وَإِنْ تَعَمَّدَ ذَلِكَ حَتَّى أَمْنَى فَعَلَيْهِ الْكَفَّارَةُ وَمَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ،"]]},{"id":"ri24_19","label":"بَابٌ فِي الصِّيَامِ · ١٩","segs":[["matn","وَإِنْ قُمْتَ فِيهِ بِمَا تَيَسَّرَ فَذَلِكَ مَرْجُوٌّ فَضْلُهُ وَتَكْفِيرُ الذُّنُوبِ بِهِ، وَالْقِيَامُ فِيهِ فِي مَسَاجِدِ الْجَمَاعَاتِ بِإِمَامٍ، وَمَنْ شَاءَ قَامَ فِي بَيْتِهِ، وَهُوَ أَحْسَنُ لِمَنْ قَوِيَتْ نِيَّتُهُ وَحْدَهُ."]]},{"id":"ri24_20","label":"بَابٌ فِي الصِّيَامِ · ٢٠","segs":[["matn","وَكَانَ السَّلَفُ الصَّالِحُ يَقُومُونَ فِيهِ فِي الْمَسَاجِدِ بِعِشْرِينَ رَكْعَةً، ثُمَّ يُوتِرُونَ بِثَلَاثٍ، وَيَفْصِلُونَ بَيْنَ الشَّفْعِ وَالْوَتْرِ بِسَلَامٍ، ثُمَّ صَلَّوْا بَعْدَ ذَلِكَ سِتًّا وَثَلَاثِينَ رَكْعَةً غَيْرَ الشَّفْعِ وَالْوَتْرِ، وَكُلُّ ذَلِكَ وَاسِعٌ، وَيُسَلِّمُ مِنْ كُلِّ رَكْعَتَيْنِ."]]},{"id":"ri24_21","label":"بَابٌ فِي الصِّيَامِ · ٢١","segs":[["matn","وَقَالَتْ عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا: مَا زَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَمَضَانَ وَلَا فِي غَيْرِهِ عَلَى اثْنَتَيْ عَشْرَةَ رَكْعَةً بَعْدَهَا الْوِتْرُ."]]}]},{"id":"ri25","title":"بَابٌ فِي الِاعْتِكَافِ","units":[{"id":"ri25_1","label":"بَابٌ فِي الِاعْتِكَافِ · ١","segs":[["matn","وَالِاعْتِكَافُ مِنْ نَوَافِلِ الْخَيْرِ، وَالْعُكُوفُ الْمُلَازَمَةُ، وَلَا اعْتِكَافَ إِلَّا بِصِيَامٍ، وَلَا يَكُونُ إِلَّا مُتَتَابِعًا، وَلَا يَكُونُ إِلَّا فِي الْمَسَاجِدِ كَمَا قَالَ اللَّهُ سُبْحَانَهُ وَتَعَالَى."]]},{"id":"ri25_2","label":"بَابٌ فِي الِاعْتِكَافِ · ٢","segs":[["matn","وَأَنْتُمْ عَاكِفُونَ فِي الْمَسَاجِدِ فَإِنْ كَانَ بَلَدٌ فِيهِ الْجُمُعَةُ فَلَا يَكُونُ إِلَّا فِي الْجَامِعِ، إِلَّا أَنْ يَنْذِرَ أَيَّامًا لَا تَأْخُذُهُ فِيهَا الْجُمُعَةُ،"]]},{"id":"ri25_3","label":"بَابٌ فِي الِاعْتِكَافِ · ٣","segs":[["matn","وَأَقَلُّ مَا هُوَ أَحَبُّ إِلَيْنَا مِنَ الِاعْتِكَافِ عَشْرَةُ أَيَّامٍ، وَمَنْ نَذَرَ اعْتِكَافَ يَوْمٍ فَأَكْثَرَ لَزِمَهُ، وَإِنْ نَذَرَ لَيْلَةً لَزِمَهُ يَوْمٌ وَلَيْلَةٌ."]]},{"id":"ri25_4","label":"بَابٌ فِي الِاعْتِكَافِ · ٤","segs":[["matn","وَمَنْ أَفْطَرَ فِيهِ مُتَعَمِّدًا فَلْيَبْتَدِئِ اعْتِكَافَهُ، وَكَذَلِكَ مَنْ جَامَعَ فِيهِ لَيْلًا أَوْ نَهَارًا نَاسِيًا أَوْ مُتَعَمِّدًا."]]},{"id":"ri25_5","label":"بَابٌ فِي الِاعْتِكَافِ · ٥","segs":[["matn","وَإِنْ مَرِضَ خَرَجَ إِلَى بَيْتِهِ، فَإِذَا صَحَّ بَنَى عَلَى مَا تَقَدَّمَ، وَكَذَلِكَ إِنْ حَاضَتِ الْمُعْتَكِفَةُ، وَحُرْمَةُ الِاعْتِكَافِ عَلَيْهِمَا فِي الْمَرَضِ وَعَلَى الْحَائِضِ فِي الْحَيْضِ،"]]},{"id":"ri25_6","label":"بَابٌ فِي الِاعْتِكَافِ · ٦","segs":[["matn","فَإِذَا طَهُرَتِ الْحَائِضُ أَوْ أَفَاقَ الْمَرِيضُ فِي لَيْلٍ أَوْ نَهَارٍ رَجَعَا سَاعَتَئِذٍ إِلَى الْمَسْجِدِ، وَلَا يَخْرُجُ الْمُعْتَكِفُ مِنْ مُعْتَكَفِهِ إِلَّا لِحَاجَةِ الْإِنْسَانِ."]]},{"id":"ri25_7","label":"بَابٌ فِي الِاعْتِكَافِ · ٧","segs":[["matn","وَلْيَدْخُلْ مُعْتَكَفَهُ قَبْلَ غُرُوبِ الشَّمْسِ مِنَ اللَّيْلَةِ الَّتِي يُرِيدُ أَنْ يَبْتَدِئَ فِيهَا اعْتِكَافَهُ، وَلَا يَعُودُ مَرِيضًا، وَلَا يُصَلِّي عَلَى جِنَازَةٍ، وَلَا يَخْرُجُ لِتِجَارَةٍ، وَلَا شَرْطَ فِي الِاعْتِكَافِ، وَلَا بَأْسَ أَنْ يَكُونَ إِمَامَ الْمَسْجِدِ، وَلَهُ أَنْ يَتَزَوَّجَ أَوْ يَعْقِدَ نِكَاحَ غَيْرِهِ."]]},{"id":"ri25_8","label":"بَابٌ فِي الِاعْتِكَافِ · ٨","segs":[["matn","وَمَنِ اعْتَكَفَ أَوَّلَ الشَّهْرِ أَوْ وَسَطَهُ خَرَجَ مِنِ اعْتِكَافِهِ بَعْدَ غُرُوبِ الشَّمْسِ مِنْ آخِرِهِ، وَإِنِ اعْتَكَفَ بِمَا يَتَّصِلُ فِيهِ اعْتِكَافُهُ بِيَوْمِ الْفِطْرِ فَلْيَبِتْ لَيْلَةَ الْفِطْرِ فِي الْمَسْجِدِ حَتَّى يَغْدُوَ مِنْهُ إِلَى الْمُصَلَّى."]]}]},{"id":"ri26","title":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ","units":[{"id":"ri26_1","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١","segs":[["matn","وَزَكَاةُ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ فَرِيضَةٌ، فَأَمَّا زَكَاةُ الْحَرْثِ فَيَوْمَ حَصَادِهِ، وَالْعَيْنُ وَالْمَاشِيَةُ فَفِي كُلِّ حَوْلٍ مَرَّةً."]]},{"id":"ri26_2","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٢","segs":[["matn","وَلَا زَكَاةَ مِنَ الْحَبِّ وَالتَّمْرِ فِي أَقَلَّ مِنْ خَمْسَةِ أَوْسُقٍ، وَذَلِكَ سِتَّةُ أَقْفِزَةٍ وَرُبُعُ قَفِيزٍ، وَالْوَسْقُ سِتُّونَ صَاعًا بِصَاعِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ أَرْبَعَةُ أَمْدَادٍ بِمُدِّهِ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ وَيُجْمَعُ الْقَمْحُ وَالشَّعِيرُ وَالسُّلْتُ فِي الزَّكَاةِ،"]]},{"id":"ri26_3","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٣","segs":[["matn","فَإِذَا اجْتَمَعَ مِنْ جَمِيعِهَا خَمْسَةُ أَوْسُقٍ فَلْيُزَكِّ ذَلِكَ، وَكَذَلِكَ تُجْمَعُ أَصْنَافُ الْقَطْنِيَّةِ وَكَذَلِكَ تُجْمَعُ أَصْنَافُ التَّمْرِ، وَكَذَلِكَ أَصْنَافُ الزَّبِيبِ، وَالْأُرْزُ وَالدُّخْنُ وَالذُّرَةُ كُلُّ وَاحِدٍ مِنْهَا صِنْفٌ لَا يُضَمُّ إِلَى الْآخَرِ فِي الزَّكَاةِ."]]},{"id":"ri26_4","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٤","segs":[["matn","وَإِذَا كَانَ فِي الْحَائِطِ أَصْنَافٌ مِنَ التَّمْرِ أَدَّى الزَّكَاةَ عَنِ الْجَمِيعِ مِنْ وَسَطِهِ، وَيُزَكَّى الزَّيْتُونُ إِذَا بَلَغَ حَبُّهُ خَمْسَةَ أَوْسُقٍ أَخْرَجَ مِنْ زَيْتِهِ،"]]},{"id":"ri26_5","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٥","segs":[["matn","وَيُخْرِجُ مِنَ الْجُلْجُلَانِ وَحَبِّ الْفُجْلِ مِنْ زَيْتِهِ، فَإِنْ بَاعَ ذَلِكَ أَجْزَأَهُ أَنْ يُخْرِجَ مِنْ ثَمَنِهِ إِنْ شَاءَ اللَّهُ، وَلَا زَكَاةَ فِي الْفَوَاكِهِ وَالْخُضَرِ."]]},{"id":"ri26_6","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٦","segs":[["matn","وَلَا زَكَاةَ مِنَ الذَّهَبِ فِي أَقَلَّ مِنْ عِشْرِينَ دِينَارًا، فَإِذَا بَلَغَتْ عِشْرِينَ دِينَارًا فَفِيهَا نِصْفُ دِينَارٍ رُبْعُ الْعُشْرِ،"]]},{"id":"ri26_7","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٧","segs":[["matn","فَمَا زَادَ فَبِحِسَابِ ذَلِكَ وَإِنْ قَلَّ، وَلَا زَكَاةَ مِنَ الْفِضَّةِ فِي أَقَلَّ مِنْ مِائَتَيْ دِرْهَمٍ، وَذَلِكَ خَمْسُ أَوَاقٍ، وَالْأُوقِيَّةُ أَرْبَعُونَ دِرْهَمًا مِنْ وَزْنِ سَبْعَةٍ؛"]]},{"id":"ri26_8","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٨","segs":[["matn","أَعْنِي أَنَّ السَّبْعَةَ دَنَانِيرَ وَزْنُهَا عَشْرَةُ دَرَاهِمَ، فَإِذَا بَلَغَتْ هَذِهِ الدَّرَاهِمُ مِائَتَيْ دِرْهَمٍ فَفِيهَا رُبْعُ عُشْرِهَا خَمْسَةُ دَرَاهِمَ، فَمَا زَادَ فَبِحِسَابِ ذَلِكَ."]]},{"id":"ri26_9","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٩","segs":[["matn","وَيُجْمَعُ الذَّهَبُ وَالْفِضَّةُ فِي الزَّكَاةِ؛ فَمَنْ كَانَ لَهُ مِائَةُ دِرْهَمٍ وَعَشْرَةُ دَنَانِيرَ فَلْيُخْرِجْ مِنْ كُلِّ مَالٍ رُبْعَ عُشْرِهِ."]]},{"id":"ri26_10","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٠","segs":[["matn","وَلَا زَكَاةَ فِي الْعُرُوضِ حَتَّى تَكُونَ لِلتِّجَارَةِ، فَإِذَا بِعْتَهَا بَعْدَ حَوْلٍ فَأَكْثَرَ مِنْ يَوْمِ أَخَذْتَ ثَمَنَهَا أَوْ زَكَّيْتَهُ فَفِي ثَمَنِهَا الزَّكَاةُ لِحَوْلٍ وَاحِدٍ، أَقَامَتْ قَبْلَ الْبَيْعِ حَوْلًا أَوْ أَكْثَرَ، إِلَّا أَنْ تَكُونَ مُدِيرًا لَا يَسْتَقِرُّ بِيَدِكَ عَيْنٌ وَلَا عَرْضٌ؛"]]},{"id":"ri26_11","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١١","segs":[["matn","فَإِنَّكَ تُقَوِّمُ عُرُوضَكَ كُلَّ عَامٍ، وَتُزَكِّي ذَلِكَ مَعَ مَا بِيَدِكَ مِنَ الْعَيْنِ، وَحَوْلُ رِبْحِ الْمَالِ حَوْلُ أَصْلِهِ، وَكَذَلِكَ حَوْلُ نَسْلِ الْأَنْعَامِ حَوْلُ الْأُمَّهَاتِ."]]},{"id":"ri26_12","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٢","segs":[["matn","وَمَنْ لَهُ مَالٌ تَجِبُ فِيهِ الزَّكَاةُ وَعَلَيْهِ دَيْنٌ مِثْلُهُ أَوْ يَنْقُصُهُ عَنْ مِقْدَارِ مَالِ الزَّكَاةِ فَلَا زَكَاةَ عَلَيْهِ،"]]},{"id":"ri26_13","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٣","segs":[["matn","إِلَّا أَنْ يَكُونَ عِنْدَهُ مِمَّا لَا يُزَكَّى مِنْ عُرُوضٍ مُقْتَنَاةٍ أَوْ رَقِيقٍ أَوْ حَيَوَانٍ مُقْتَنَاةٍ أَوْ عَقَارٍ أَوْ رَيْعٍ مَا فِيهِ وَفَاءٌ لِدَيْنِهِ فَلْيُزَكِّ مَا بِيَدِهِ مِنَ الْمَالِ،"]]},{"id":"ri26_14","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٤","segs":[["matn","فَإِنْ لَمْ تَفِ عُرُوضُهُ بِدَيْنِهِ حَسَبَ بَقِيَّةَ دَيْنِهِ فِيمَا بِيَدِهِ، فَإِنْ بَقِيَ بَعْدَ ذَلِكَ مَا فِيهِ الزَّكَاةُ زَكَّاهُ. وَلَا يُسْقِطُ الدَّيْنُ زَكَاةَ حَبٍّ وَلَا تَمْرٍ وَلَا مَاشِيَةٍ."]]},{"id":"ri26_15","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٥","segs":[["matn","وَلَا زَكَاةَ عَلَيْهِ فِي دَيْنٍ حَتَّى يَقْبِضَهُ، وَإِنْ أَقَامَ أَعْوَامًا فَإِنَّمَا يُزَكِّيهِ لِعَامٍ وَاحِدٍ بَعْدَ قَبْضِهِ، وَكَذَلِكَ الْعَرْضُ حَتَّى يَبِيعَهُ، وَإِنْ كَانَ الدَّيْنُ أَوِ الْعَرْضُ مِنْ مِيرَاثٍ فَلْيَسْتَقْبِلْ حَوْلًا بِمَا يَقْبِضُ مِنْهُ."]]},{"id":"ri26_16","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٦","segs":[["matn","وَعَلَى الْأَصَاغِرِ الزَّكَاةُ فِي أَمْوَالِهِمْ فِي الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ، وَزَكَاةُ الْفِطْرِ."]]},{"id":"ri26_17","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٧","segs":[["matn","وَلَا زَكَاةَ عَلَى عَبْدٍ وَلَا عَلَى مَنْ فِيهِ بَقِيَّةُ رِقٍّ فِي ذَلِكَ كُلِّهِ، فَإِذَا أُعْتِقَ فَلْيَأْتَنِفْ حَوْلًا مِنْ يَوْمِئِذٍ بِمَا يَمْلِكُ مِنْ مَالِهِ."]]},{"id":"ri26_18","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٨","segs":[["matn","وَلَا زَكَاةَ عَلَى أَحَدٍ فِي عَبْدِهِ وَخَادِمِهِ وَفَرَسِهِ وَدَارِهِ وَلَا مَا يُتَّخَذُ لِلْقُنْيَةِ مِنَ الرِّبَاعِ وَالْعُرُوضِ وَلَا فِيمَا يُتَّخَذُ لِلِّبَاسِ مِنَ الْحُلِيِّ."]]},{"id":"ri26_19","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ١٩","segs":[["matn","وَمَنْ وَرِثَ عَرْضًا أَوْ وُهِبَ لَهُ أَوْ رَفَعَ مِنْ أَرْضِهِ زَرْعًا فَزَكَّاهُ فَلَا زَكَاةَ عَلَيْهِ فِي شَيْءٍ مِنْ ذَلِكَ حَتَّى يُبَاعَ، وَيَسْتَقْبِلَ بِهِ حَوْلًا مِنْ يَوْمِ يَقْبِضُ ثَمَنَهُ."]]},{"id":"ri26_20","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٢٠","segs":[["matn","وَفِيمَا يَخْرُجُ مِنَ الْمَعْدِنِ مِنْ ذَهَبٍ أَوْ فِضَّةٍ الزَّكَاةُ إِذَا بَلَغَ وَزْنَ عِشْرِينَ دِينَارًا أَوْ خَمْسَ أَوَاقٍ فِضَّةً؛"]]},{"id":"ri26_21","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٢١","segs":[["matn","فَفِي ذَلِكَ رُبُعُ الْعُشْرِ يَوْمَ خُرُوجِهِ، وَكَذَلِكَ فِيمَا يَخْرُجُ بَعْدَ ذَلِكَ مُتَّصِلًا بِهِ وَإِنْ قَلَّ، فَإِنِ انْقَطَعَ نَيْلُهُ بِيَدِهِ، وَابْتَدَأَ غَيْرَهُ لَمْ يُخْرِجْ شَيْئًا حَتَّى يَبْلُغَ مَا فِيهِ الزَّكَاةُ."]]},{"id":"ri26_22","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٢٢","segs":[["matn","وَتُؤْخَذُ الْجِزْيَةُ مِنْ رِجَالِ أَهْلِ الذِّمَّةِ الْأَحْرَارِ الْبَالِغِينَ، وَلَا تُؤْخَذُ مِنْ نِسَائِهِمْ وَصِبْيَانِهِمْ وَعَبِيدِهِمْ، وَتُؤْخَذُ مِنَ الْمَجُوسِ وَمِنْ نَصَارَى الْعَرَبِ، وَالْجِزْيَةُ عَلَى أَهْلِ الذَّهَبِ أَرْبَعَةُ دَنَانِيرَ، وَعَلَى أَهْلِ الْوَرِقِ أَرْبَعُونَ دِرْهَمًا، وَيُخَفَّفُ عَنِ الْفَقِيرِ."]]},{"id":"ri26_23","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٢٣","segs":[["matn","وَيُؤْخَذُ مِمَّنْ تَجَرَ مِنْهُمْ مِنْ أُفُقٍ إِلَى أُفُقٍ عُشْرُ ثَمَنِ مَا يَبِيعُونَهُ، وَإِنِ اخْتَلَفُوا فِي السَّنَةِ مِرَارًا،"]]},{"id":"ri26_24","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٢٤","segs":[["matn","وَإِنْ حَمَلُوا الطَّعَامَ خَاصَّةً إِلَى مَكَّةَ وَالْمَدِينَةِ خَاصَّةً أُخِذَ مِنْهُمْ نِصْفُ الْعُشْرِ مِنْ ثَمَنِهِ، وَيُؤْخَذُ مِنْ تُجَّارِ الْحَرْبِيِّينَ الْعُشْرُ إِلَّا أَنْ يَنْزِلُوا عَلَى أَكْثَرَ مِنْ ذَلِكَ."]]},{"id":"ri26_25","label":"بَابٌ فِي زَكَاةِ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ وَمَا يَخْرُجُ مِنَ الْمَعْدِنِ وَذِكْرِ الْجِزْيَةِ وَمَا يُؤْخَذُ مِنْ تُجَّارِ أَهْلِ الذِّمَّةِ وَالْحَرْبِيِّينَ · ٢٥","segs":[["matn","وَفِي الرِّكَازِ وَهُوَ دِفْنُ الْجَاهِلِيَّةِ الْخُمُسُ عَلَى مَنْ أَصَابَهُ."]]}]},{"id":"ri27","title":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ","units":[{"id":"ri27_1","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ١","segs":[["matn","وَزَكَاةُ الْإِبِلِ وَالْبَقَرِ وَالْغَنَمِ فَرِيضَةٌ، وَلَا زَكَاةَ مِنَ الْإِبِلِ فِي أَقَلَّ مِنْ خَمْسِ ذَوْدٍ وَهِيَ خَمْسٌ مِنَ الْإِبِلِ فَفِيهَا شَاةٌ جَذَعَةٌ أَوْ ثَنِيَّةٌ مِنْ جُلِّ غَنَمِ أَهْلِ ذَلِكَ الْبَلَدِ مِنْ ضَأْنٍ أَوْ مَعْزٍ إِلَى تِسْعٍ،"]]},{"id":"ri27_2","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ٢","segs":[["matn","ثُمَّ فِي الْعَشْرِ شَاتَانِ إِلَى أَرْبَعَةَ عَشَرَ ثُمَّ فِي خَمْسَةَ عَشَرَ ثَلَاثُ شِيَاهٍ إِلَى تِسْعَةَ عَشَرَ فَإِذَا كَانَتْ عِشْرِينَ فَأَرْبَعُ شِيَاهٍ إِلَى أَرْبَعٍ وَعِشْرِينَ،"]]},{"id":"ri27_3","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ٣","segs":[["matn","ثُمَّ فِي خَمْسٍ وَعِشْرِينَ بِنْتُ مَخَاضٍ، وَهِيَ بِنْتُ سَنَتَيْنِ، فَإِنْ لَمْ تَكُنْ فِيهَا فَابْنُ لَبُونٍ ذَكَرٌ إَلَى خَمْسٍ وَثَلَاثِينَ،"]]},{"id":"ri27_4","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ٤","segs":[["matn","ثُمَّ فِي سِتٍّ وَثَلَاثِينَ بِنْتُ لَبُونٍ وَهِيَ بِنْتُ ثَلَاثِ سِنِينَ إِلَى خَمْسٍ وَأَرْبَعِينَ، ثُمَّ فِي سِتٍّ وَأَرْبَعِينَ حِقَّةٌ وَهِيَ الَّتِي يَصْلُحُ عَلَى ظَهْرِهَا الْحَمْلُ، وَيَطْرُقُهَا الْفَحْلُ، وَهِيَ بِنْتُ أَرْبَعِ سِنِينَ إِلَى سِتِّينَ،"]]},{"id":"ri27_5","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ٥","segs":[["matn","ثُمَّ فِي إِحْدَى وَسِتِّينَ جَذَعَةٌ وَهِيَ بِنْتُ خَمْسِ سِنِينَ إِلَى خَمْسٍ وَسَبْعِينَ، ثُمَّ فِي سِتٍّ وَسَبْعِينَ بِنْتَا لَبُونٍ إِلَى تِسْعِينَ،"]]},{"id":"ri27_6","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ٦","segs":[["matn","ثُمَّ فِي إِحْدَى وَتِسْعِينَ حِقَّتَانِ إِلَى عِشْرِينَ وَمِائَةٍ، فَمَا زَادَ عَلَى ذَلِكَ فَفِي كُلِّ خَمْسِينَ حِقَّةٌ، وَفِي كُلِّ أَرْبَعِينَ بِنْتُ لَبُونٍ."]]},{"id":"ri27_7","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ٧","segs":[["matn","وَلَا زَكَاةَ مِنَ الْبَقَرِ فِي أَقَلَّ مِنْ ثَلَاثِينَ فَإِذَا بَلَغَتْهَا فَفِيهَا تَبِيعٌ عِجْلٌ جَذَعٌ قَدْ أَوْفَى سَنَتَيْنِ، ثُمَّ كَذَلِكَ حَتَّى تَبْلُغَ أَرْبَعِينَ فَيَكُونُ فِيهَا مُسِنَّةٌ،"]]},{"id":"ri27_8","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ٨","segs":[["matn","وَلَا تُؤْخَذُ إِلَّا أُنْثَى، وَهِيَ بِنْتُ أَرْبَعِ سِنِينَ، وَهِيَ ثَنِيَّةٌ، فَمَا زَادَ فَفِي كُلِّ أَرْبَعِينَ مُسِنَّةٌ، وَفِي كُلِّ ثَلَاثِينَ تَبِيعٌ. وَلَا زَكَاةَ فِي الْغَنَمِ حَتَّى تَبْلُغَ أَرْبَعِينَ شَاةً؛"]]},{"id":"ri27_9","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ٩","segs":[["matn","فَإِذَا بَلَغَتْهَا فَفِيهَا شَاةٌ جَذَعَةٌ أَوْ ثَنِيَّةٌ، إِلَى عِشْرِينَ وَمِائَةٍ، فَإِذَا بَلَغَتْ إِحْدَى وَعِشْرِينَ وَمِائَةً فَفِيهَا شَاتَانِ إِلَى مِائَتَيْ شَاةٍ،"]]},{"id":"ri27_10","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ١٠","segs":[["matn","فَإِذَا زَادَتْ وَاحِدَةً فَفِيهَا ثَلَاثُ شِيَاهٍ إِلَى ثَلَاثِمِائَةٍ فَمَا زَادَ فَفِي كُلِّ مِائَةٍ شَاةٌ، وَلَا زَكَاةَ فِي الْأَوْقَاصِ، وَهِيَ مَا بَيْنَ الْفَرِيضَتَيْنِ مِنْ كُلِّ الْأَنْعَامِ."]]},{"id":"ri27_11","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ١١","segs":[["matn","وَيُجْمَعُ الضَّأْنُ وَالْمَعْزُ فِي الزَّكَاةِ، وَالْجَوَامِيسُ وَالْبَقَرُ، وَالْبُخْتُ وَالْعِرَابُ. وَكُلُّ خَلِيطَيْنِ فَإِنَّهُمَا يَتَرَادَّانِ بَيْنَهُمَا بِالسَّوِيَّةِ، وَلَا زَكَاةَ عَلَى مَنْ لَمْ تَبْلُغْ حِصَّتُهُ عَدَدَ الزَّكَاةِ، وَلَا يُفَرَّقُ بَيْنَ مُجْتَمِعٍ،"]]},{"id":"ri27_12","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ١٢","segs":[["matn","وَلَا يُجْمَعُ بَيْنَ مُفْتَرِقٍ خَشْيَةَ الصَّدَقَةِ، وَذَلِكَ إِذَا قَرُبَ الْحَوْلُ، فَإِذَا كَانَ يَنْقُصُ أَدَاؤُهُمَا بِافْتِرَاقِهِمَا أَوْ بِاجْتِمَاعِهِمَا أُخِذَا بِمَا كَانَا عَلَيْهِ قَبْلَ ذَلِكَ."]]},{"id":"ri27_13","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ١٣","segs":[["matn","وَلَا تُؤْخَذُ فِي الصَّدَقَةِ السَّخْلَةُ، وَتُعَدُّ عَلَى رَبِّ الْغَنَمِ، وَلَا تُؤْخَذُ الْعَجَاجِيلُ فِي الْبَقَرِ، وَلَا الْفُصْلَانُ فِي الْإِبِلِ وَتُعَدُّ عَلَيْهِمْ،"]]},{"id":"ri27_14","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ١٤","segs":[["matn","وَلَا يُؤْخَذُ تَيْسٌ وَلَا هَرِمَةٌ وَلَا الْمَاخِضُ، وَلَا فَحْلُ الْغَنَمِ وَلَا شَاةُ الْعَلَفِ وَلَا الَّتِي تُرَبِّي وَلَدَهَا وَلَا خِيَارُ أَمْوَالِ النَّاسِ."]]},{"id":"ri27_15","label":"بَابٌ فِي زَكَاةِ الْمَاشِيَةِ · ١٥","segs":[["matn","وَلَا يُؤْخَذُ فِي ذَلِكَ عَرْضٌ وَلَا ثَمَنٌ، فَإِنْ أَجْبَرَهُ الْمُصَدِّقُ عَلَى أَخْذِ الثَّمَنِ فِي الْأَنْعَامِ وَغَيْرِهَا أَجْزَأَهُ إِنْ شَاءَ اللَّهُ وَلَا يُسْقِطُ الدَّيْنُ زَكَاةَ حَبٍّ وَلَا تَمْرٍ وَلَا مَاشِيَةٍ."]]}]},{"id":"ri28","title":"بَابٌ فِي زَكَاةِ الْفِطْرِ","units":[{"id":"ri28_1","label":"بَابٌ فِي زَكَاةِ الْفِطْرِ · ١","segs":[["matn","وَزَكَاةُ الْفِطْرِ سُنَّةٌ، وَاجِبَةٌ فَرَضَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى كُلِّ كَبِيرٍ أَوْ صَغِيرٍ، ذَكَرٍ أَوْ أُنْثَى، حُرٍّ أَوْ عَبْدٍ مِنَ الْمُسْلِمِينَ صَاعًا عَنْ كُلِّ نَفْسٍ بِصَاعِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"ri28_2","label":"بَابٌ فِي زَكَاةِ الْفِطْرِ · ٢","segs":[["matn","وَتُؤَدَّى مِنْ جُلِّ عَيْشِ أَهْلِ ذَلِكَ الْبَلَدِ مِنْ بُرٍّ أَوْ شَعِيرٍ أَوْ سُلْتٍ أَوْ تَمْرٍ أَوْ أَقِطٍ أَوْ زَبِيبٍ أَوْ دُخْنٍ أَوْ ذُرَةٍ أَوْ أُرْزٍ، وَقِيلَ: إِنْ كَانَ الْعَلَسُ قُوتَ قَوْمٍ أُخْرِجَتْ مِنْهُ، وَهُوَ حَبٌّ صَغِيرٌ يَقْرُبُ مِنْ خِلْقَةِ الْبُرِّ."]]},{"id":"ri28_3","label":"بَابٌ فِي زَكَاةِ الْفِطْرِ · ٣","segs":[["matn","وَيُخْرِجُ عَنِ الْعَبْدِ سَيِّدُهُ، وَالصَّغِيرُ لَا مَالَ لَهُ يُخْرِجُ عَنْهُ وَالِدُهُ، وَيُخْرِجُ الرَّجُلُ زَكَاةَ الْفِطْرِ عَنْ كُلِّ مُسْلِمٍ تَلْزَمُهُ نَفَقَتُهُ."]]},{"id":"ri28_4","label":"بَابٌ فِي زَكَاةِ الْفِطْرِ · ٤","segs":[["matn","وَعَنْ مُكَاتَبِهِ وَإِنْ كَانَ لَا يُنْفِقُ عَلَيْهِ؛ لِأَنَّهُ عَبْدٌ لَهُ بَعْدُ وَيُسْتَحَبُّ إِخْرَاجُهَا إِذَا طَلَعَ الْفَجْرُ مِنْ يَوْمِ الْفِطْرِ، وَيُسْتَحَبُّ الْفِطْرُ فِيهِ قَبْلَ الْغُدُوِّ إِلَى الْمُصَلَّى، وَلَيْسَ ذَلِكَ فِي الْأَضْحَى، وَيُسْتَحَبُّ فِي الْعِيدَيْنِ أَنْ يَمْضِيَ مِنْ طَرِيقٍ، وَيَرْجِعَ مِنْ أُخْرَى."]]}]},{"id":"ri29","title":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ","units":[{"id":"ri29_1","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١","segs":[["matn","وَحَجُّ بَيْتِ اللَّهِ الْحَرَامِ الَّذِي بِبَكَّةِ فَرِيضَةٌ عَلَى كُلِّ مَنِ اسْتَطَاعَ إِلَى ذَلِكَ سَبِيلًا مِنَ الْمُسْلِمِينَ الْأَحْرَارِ الْبَالِغِينَ مَرَّةً فِي عُمُرِهِ، وَالسَّبِيلُ: الطَّرِيقُ السَّابِلَةُ، وَالزَّادُ الْمُبَلِّغُ إِلَى مَكَّةَ، وَالْقُوَّةُ عَلَى الْوُصُولِ إِلَى مَكَّةَ إِمَّا رَاكِبًا أَوْ رَاجِلًا مَعَ صِحَّةِ الْبَدَنِ."]]},{"id":"ri29_2","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢","segs":[["matn","وَإِنَّمَا يُؤْمَرُ أَنْ يُحْرِمَ مِنَ الْمِيقَاتِ، وَمِيقَاتُ أَهْلِ الشَّامِ وَمِصْرَ وَالْمَغْرِبِ الْجُحْفَةُ، فَإِنْ مَرُّوا بِالْمَدِينَةِ فَالْأَفْضَلُ لَهُمْ أَنْ يُحْرِمُوا مِنْ مِيقَاتِ أَهْلِهَا مِنْ ذِي الْحُلَيْفَةِ،"]]},{"id":"ri29_3","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٣","segs":[["matn","وَمِيقَاتُ أَهْلِ الْعِرَاقِ ذَاتُ عِرْقٍ، وَأَهْلِ الْيَمَنِ يَلَمْلَمُ، وَأَهْلِ نَجْدٍ مِنْ قَرْنٍ، وَمَنْ مَرَّ مِنْ هَؤُلَاءِ بِالْمَدِينَةِ فَوَاجِبٌ عَلَيْهِ أَنْ يُحْرِمَ مِنْ ذِي الْحُلَيْفَةِ؛ إِذْ لَا يَتَعَدَّاهُ إِلَى مِيقَاتٍ لَهُ."]]},{"id":"ri29_4","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٤","segs":[["matn","وَيُحْرِمُ الْحَاجُّ أَوِ الْمُعْتَمِرُ بِإِثْرِ صَلَاةِ فَرِيضَةٍ أَوْ نَافِلَةٍ، يَقُولُ: لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ، وَالْمُلْكَ لَا شَرِيكَ لَكَ،"]]},{"id":"ri29_5","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٥","segs":[["matn","وَيَنْوِي مَا أَرَادَ مِنْ حَجٍّ أَوْ عُمْرَةٍ، وَيُؤْمَرُ أَنْ يَغْتَسِلَ عِنْدَ الْإِحْرَامِ قَبْلَ أَنْ يُحْرِمَ، وَيَتَجَرَّدَ مِنْ مَخِيطِ الثِّيَابِ، وَيُسْتَحَبُّ لَهُ أَنْ يَغْتَسِلَ لِدُخُولِ مَكَّةَ،"]]},{"id":"ri29_6","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٦","segs":[["matn","وَلَا يَزَالُ يُلَبِّي دُبُرَ الصَّلَوَاتِ وَعِنْدَ كُلِّ شَرَفٍ وَعِنْدَ مُلَاقَاةِ الرِّفَاقِ، وَلَيْسَ عَلَيْهِ كَثْرَةُ الْإِلْحَاحِ بِذَلِكَ، فَإِذَا دَخَلَ مَكَّةَ أَمْسَكَ عَنِ التَّلْبِيَةِ حَتَّى يَطُوفَ وَيَسْعَى،"]]},{"id":"ri29_7","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٧","segs":[["matn","ثُمَّ يُعَاوِدُهَا حَتَّى تَزُولَ الشَّمْسُ مِنْ يَوْمِ عَرَفَةَ، وَيَرُوحَ إِلَى مُصَلَّاهَا، وَيُسْتَحَبُّ أَنْ يَدْخُلَ مَكَّةَ مِنْ كَدَاءِ: الثَّنِيَّةِ الَّتِي بِأَعْلَى مَكَّةَ، وَإِذَا خَرَجَ خَرَجَ مِنْ كُدًى، وَإِنْ لَمْ يَفْعَلْ فِي الْوَجْهَيْنِ فَلَا حَرَجَ."]]},{"id":"ri29_8","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٨","segs":[["matn","قَالَ: فَإِذَا دَخَلَ مَكَّةَ فَلْيَدْخُلِ الْمَسْجِدَ الْحَرَامَ، وَمُسْتَحْسَنٌ أَنْ يَدْخُلَ مِنْ بَابِ بَنِي شَيْبَةَ، فَيَسْتَلِمَ الْحَجَرَ الْأَسْوَدَ بِفِيهِ إِنْ قَدَرَ، وَإِلَّا وَضَعَ يَدَهُ عَلَيْهِ، ثُمَّ وَضَعَهَا عَلَى فِيهِ مِنْ غَيْرِ تَقْبِيلٍ."]]},{"id":"ri29_9","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٩","segs":[["matn","ثُمَّ يَطُوفُ وَالْبَيْتُ عَلَى يَسَارِهِ سَبْعَةَ أَطْوَافٍ: ثَلَاثَةً خَبَبًا ثُمَّ أَرْبَعَةً مَشْيًا، وَيَسْتَلِمُ الرُّكْنَ كُلَّمَا مَرَّ بِهِ كَمَا ذَكَرْنَا، وَيُكَبِّرُ، وَلَا يَسْتَلِمُ الرُّكْنَ الْيَمَانِيَ بِفِيهِ،"]]},{"id":"ri29_10","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٠","segs":[["matn","وَلَكِنْ بِيَدِهِ، ثُمَّ يَضَعُهَا عَلَى فِيهِ، مِنْ غَيْرِ تَقْبِيلٍ فَإِذَا تَمَّ طَوَافُهُ رَكَعَ عِنْدَ الْمَقَامِ رَكْعَتَيْنِ، ثُمَّ اسْتَلَمَ الْحَجَرَ إِنْ قَدَرَ."]]},{"id":"ri29_11","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١١","segs":[["matn","ثُمَّ يَخْرُجُ إِلَى الصَّفَا، فَيَقِفُ عَلَيْهِ لِلدُّعَاءِ، ثُمَّ يَسْعَى إِلَى الْمَرْوَةِ، وَيَخُبُّ فِي بَطْنِ الْمَسِيلِ، فَإِذَا أَتَى الْمَرْوَةَ وَقَفَ عَلَيْهَا لِلدُّعَاءِ، ثُمَّ يَسْعَى إِلَى الصَّفَا؛ يَفْعَلُ ذَلِكَ سَبْعَ مَرَّاتٍ، فَيَقِفُ بِذَلِكَ أَرْبَعَ وَقَفَاتٍ عَلَى الصَّفَا وَأَرْبَعًا عَلَى الْمَرْوَةِ."]]},{"id":"ri29_12","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٢","segs":[["matn","ثُمَّ يَخْرُجُ يَوْمَ التَّرْوِيَةِ إِلَى مِنًى فَيُصَلِّي بِهَا الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ وَالصُّبْحَ، ثُمَّ يَمْضِي إِلَى عَرَفَاتٍ، وَلَا يَدَعُ التَّلْبِيَةَ فِي هَذَا كُلِّهِ،"]]},{"id":"ri29_13","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٣","segs":[["matn","حَتَّى تَزُولَ الشَّمْسُ مِنْ يَوْمِ عَرَفَةَ، وَيَرُوحُ إِلَى مُصَلَّاهَا، وَلْيَتَطَهَّرْ قَبْلَ رَوَاحِهِ، فَيَجْمَعُ بَيْنَ الظُّهْرِ وَالْعَصْرِ مَعَ الْإِمَامِ."]]},{"id":"ri29_14","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٤","segs":[["matn","ثُمَّ يَرُوحُ مَعَهُ إِلَى مَوْقِفِ عَرَفَةَ، فَيَقِفُ مَعَهُ إِلَى غُرُوبِ الشَّمْسِ، ثُمَّ يَدْفَعُ بِدَفْعِهِ إِلَى الْمُزْدَلِفَةِ، فَيُصَلِّي مَعَهُ بِالْمُزْدَلِفَةِ الْمَغْرِبَ وَالْعِشَاءَ وَالصُّبْحَ، ثُمَّ يَقِفُ مَعَهُ بِالْمَشْعَرِ الْحَرَامِ يَوْمَئِذٍ بِهَا."]]},{"id":"ri29_15","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٥","segs":[["matn","ثُمَّ يَدْفَعُ بِقُرْبِ طُلُوُعِ الشَّمْسِ إِلَى مِنًى، وَيُحَرِّكُ دَابَّتَهُ بِبَطْنِ مُحَسِّرٍ، فَإِذَا وَصَلَ إِلَى مِنًى رَمَى جَمْرَةَ الْعَقَبَةِ بِسَبْعِ حَصَيَاتٍ مِثْلَ حَصَى الْخَذْفِ، وَيُكَبِّرُ مَعَ كُلِّ حَصَاةٍ، ثُمَّ يَنْحَرُ إِنْ كَانَ مَعَهُ هَدْيٌ، ثُمَّ يَحْلِقُ."]]},{"id":"ri29_16","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٦","segs":[["matn","ثُمَّ يَأْتِي الْبَيْتَ فَيُفِيضُ وَيَطُوفُ سَبْعًا، وَيَرْكَعُ، ثُمَّ يُقِيمُ بِمِنًى ثَلَاثَةَ أَيَّامٍ، فَإِذَا زَالَتِ الشَّمْسُ مِنْ كُلِّ يَوْمٍ مِنْهَا رَمَى الْجَمْرَةَ الَّتِي تَلِي مِنًى بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ،"]]},{"id":"ri29_17","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٧","segs":[["matn","ثُمَّ يَرْمِي الْجَمْرَتَيْنِ كُلَّ جَمْرَةٍ بِمِثْلِ ذَلِكَ، وَيُكَبِّرُ مَعَ كُلِّ حَصَاةٍ، وَيَقِفُ لِلدُّعَاءِ بِإِثْرِ الرَّمْيِ فِي الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ، وَلَا يَقِفُ عِنْدَ جَمْرَةِ الْعَقَبَةِ، وَلْيَنْصَرِفْ."]]},{"id":"ri29_18","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٨","segs":[["matn","فَإِذَا رَمَى فِي الْيَوْمِ الثَّالِثِ وَهُوَ رَابِعُ يَوْمِ النَّحْرِ انْصَرَفَ إِلَى مَكَّةَ، وَقَدْ تَمَّ حَجُّهُ، وَإِنْ شَاءَ تَعَجَّلَ فِي يَوْمَيْنِ مِنْ أَيَّامِ مِنًى، فَرَمَى وَانْصَرَفَ، فَإِذَا خَرَجَ مِنْ مَكَّةَ طَافَ لِلْوَدَاعِ، وَرَكَعَ، وَانْصَرَفَ."]]},{"id":"ri29_19","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ١٩","segs":[["matn","وَالْعُمْرَةُ يَفْعَلُ فِيهَا كَمَا ذَكَرْنَا أَوَّلًا إِلَى تَمَامِ السَّعْيِ بَيْنَ الصَّفَا وَالْمَرْوَةِ، ثُمَّ يَحْلِقُ رَأْسَهُ، وَقَدْ تَمَّتْ عُمْرَتُهُ."]]},{"id":"ri29_20","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٠","segs":[["matn","وَالْحِلَاقُ أَفْضَلُ فِي الْحَجِّ وَالْعُمْرَةِ، وَالتَّقْصِيرُ يُجْزِئُ، وَلْيُقَصِّرْ مِنْ جَمِيعِ شَعْرِهِ، وَسُنَّةُ الْمَرْأَةِ التَّقْصِيرُ."]]},{"id":"ri29_21","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢١","segs":[["matn","وَلَا بَأْسَ أَنْ يَقْتُلَ الْمُحْرِمُ الْفَأْرَةَ وَالْحَيَّةَ وَالْعَقْرَبَ وَشِبْهَهَا وَالْكَلْبَ الْعَقُورَ وَمَا يَعْدُو مِنَ الذِّئَابِ وَالسِّبَاعِ، وَنَحْوِهَا، وَيَقْتُلُ مِنَ الطَّيْرِ مَا يُتَّقَى أَذَاهُ مِنَ الْغِرْبَانِ وَالْأَحْدِيَةِ فَقَطْ."]]},{"id":"ri29_22","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٢","segs":[["matn","وَيَجْتَنِبُ فِي حَجِّهِ وَعُمْرَتِهِ النِّسَاءَ وَالطِّيبَ وَمَخِيطَ الثِّيَابِ وَالصَّيْدَ وَقَتْلَ الدَّوَابِّ وَإِلْقَاءَ التَّفَثِ، وَلَا يُغَطِّي رَأْسَهُ فِي الْإِحْرَامِ، وَلَا يَحْلِقُهُ إِلَّا مِنْ ضَرُورَةٍ،"]]},{"id":"ri29_23","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٣","segs":[["matn","ثُمَّ يَفْتَدِي بِصِيَامِ ثَلَاثَةِ أَيَّامٍ أَوْ إِطْعَامِ سِتَّةِ مَسَاكِينَ مُدَّيْنِ لِكُلِّ مِسْكِينٍ، بِمُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْ يَنْسُكُ بِشَاةٍ يَذْبَحُهَا حَيْثُ شَاءَ مِنَ الْبِلَادِ."]]},{"id":"ri29_24","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٤","segs":[["matn","وَتَلْبَسُ الْمَرْأَةُ الْخُفَّيْنِ وَالثِّيَابَ فِي إِحْرَامِهَا، وَتَجْتَنِبُ مَا سِوَى ذَلِكَ مِمَّا يَجْتَنِبُهُ الرَّجُلُ، وَإِحْرَامُ الْمَرْأَةِ فِي وَجْهِهَا وَكَفَّيْهَا، وَإِحْرَامُ الرَّجُلِ فِي وَجْهِهِ وَرَأْسِهِ."]]},{"id":"ri29_25","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٥","segs":[["matn","وَلَا يَلْبَسُ الرَّجُلُ الْخُفَّيْنِ فِي الْإِحْرَامِ إِلَّا أَنْ لَا يَجِدَ نَعْلَيْنِ فَلْيَقْطَعْهُمَا أَسْفَلَ مِنَ الْكَعْبَيْنِ."]]},{"id":"ri29_26","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٦","segs":[["matn","وَالْإِفْرَادُ بِالْحَجِّ أَفْضَلُ عِنْدَنَا مِنَ التَّمَتُّعِ وَمِنَ الْقِرَانِ، فَمَنْ قَرَنَ أَوْ تَمَتَّعَ مِنْ غَيْرِ أَهْلِ مَكَّةَ فَعَلَيْهِ هَدْيٌ، يَذْبَحُهُ أَوْ يَنْحَرُهُ بِمِنًى إِنْ أَوْقَفَهُ بِعَرَفَةَ،"]]},{"id":"ri29_27","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٧","segs":[["matn","وَإِنْ لَمْ يُوقِفْهُ بِعَرَفَةَ فَلْيَنْحَرْهُ بِمَكَّةَ بِالْمَرْوَةِ بَعْدَ أَنْ يَدْخُلَ بِهِ مِنَ الْحِلِّ، فَإِنْ لَمْ يَجِدْ هَدْيًا فَصِيَامُ ثَلَاثَةِ أَيَّامٍ فِي الْحَجِّ يَعْنِي مِنْ وَقْتِ يُحْرِمُ إِلَى يَوْمِ عَرَفَةَ، فَإِنْ فَاتَهُ ذَلِكَ صَامَ أَيَّامَ مِنًى وَسَبْعَةً إِذَا رَجَعَ."]]},{"id":"ri29_28","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٨","segs":[["matn","وَصِفَةُ التَّمَتُّعِ أَنْ يُحْرِمَ بِعُمْرَةٍ، ثُمَّ يَحِلَّ مِنْهَا فِي أَشْهُرِ الْحَجِّ، ثُمَّ يَحُجُّ مِنْ عَامِهِ قَبْلَ الرُّجُوعِ إِلَى أُفُقِهِ أَوْ إِلَى مِثْلِ أُفُقِهِ فِي الْبُعْدِ،"]]},{"id":"ri29_29","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٢٩","segs":[["matn","وَلِهَذَا أَنْ يُحْرِمَ مِنْ مَكَّةَ إِنْ كَانَ بِهَا، وَلَا يُحْرِمُ مِنْهَا مَنْ أَرَادَ أَنْ يَعْتَمِرَ حَتَّى يَخْرُجَ إِلَى الْحِلِّ."]]},{"id":"ri29_30","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٣٠","segs":[["matn","وَصِفَةُ الْقِرَانِ أَنْ يُحْرِمَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا، وَيَبْدَأُ بِالْعُمْرَةِ فِي نِيَّتِهِ، وَإِذَا أَرْدَفَ الْحَجَّ عَلَى الْعُمْرَةِ قَبْلَ أَنْ يَطُوفَ وَيَرْكَعَ فَهُوَ قَارِنٌ،"]]},{"id":"ri29_31","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٣١","segs":[["matn","وَلَيْسَ عَلَى أَهْلِ مَكَّةَ هَدْيٌ فِي تَمَتُّعٍ وَلَا قِرَانٍ، وَمَنْ حَلَّ مِنْ عُمْرَتِهِ قَبْلَ أَشْهُرِ الْحَجِّ، ثُمَّ حَجَّ مِنْ عَامِهِ فَلَيْسَ بِمُتَمَتِّعٍ."]]},{"id":"ri29_32","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٣٢","segs":[["matn","وَمَنْ أَصَابَ صَيْدًا فَعَلَيْهِ جَزَاءُ مِثْلِ مَا قَتَلَ مِنَ النَّعَمِ يَحْكُمُ بِهِ ذَوَا عَدْلٍ مِنْ فُقَهَاءِ الْمُسْلِمِينَ، وَمَحَلُّهُ مِنًى إِنْ وَقَفَ بِهِ بِعَرَفَةَ، وَإِلَّا فَمَكَّةُ وَيَدْخُلُ بِهِ مِنَ الْحِلِّ، وَلَهُ أَنْ يَخْتَارَ ذَلِكَ أَوْ كَفَّارَةَ طَعَامِ مَسَاكِينَ؛"]]},{"id":"ri29_33","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٣٣","segs":[["matn","أَنْ يَنْظُرَ إِلَى قِيمَةِ الصَّيْدِ طَعَامًا فَيَتَصَدَّقَ بِهِ، أَوْ عَدْلَ ذَلِكَ صِيَامًا؛ أَنْ يَصُومَ عَنْ كُلِّ مُدٍّ يَوْمًا وَلِكَسْرِ الْمُدِّ يَوْمًا كَامِلًا."]]},{"id":"ri29_34","label":"بَابٌ فِي الْحَجِّ وَالْعُمْرَةِ · ٣٤","segs":[["matn","وَالْعُمْرَةُ سُنَّةٌ مُؤَكَّدَةٌ مَرَّةً فِي الْعُمُرِ، وَيُسْتَحَبُّ لِمَنِ انْصَرَفَ مِنْ مَكَّةَ مِنْ حَجٍّ أَوْ عُمْرَةٍ أَنْ يَقُولَ: آيِبُونَ تَائِبُونَ عَابِدُونَ، لِرَبِّنَا حَامِدُونَ. صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ."]]}]},{"id":"ri30","title":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ","units":[{"id":"ri30_1","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١","segs":[["matn","وَالْأُضْحِيَّةُ سُنَّةٌ وَاجِبَةٌ عَلَى مَنِ اسْتَطَاعَهَا، وَأَقَلُّ مَا يُجْزِئُ فِيهَا مِنَ الْأَسْنَانِ الْجَذَعُ مِنَ الضَّأْنِ وَهُوَ ابْنُ سَنَةٍ، وَقِيلَ: ابْنُ ثَمَانِيَةِ أَشْهُرٍ، وَقِيلَ: ابْنُ عَشَرَةِ أَشْهُرٍ وَالثَّنِيُّ مِنَ الْمَعْزِ وَهُوَ مَا أَوْفَى سَنَةً وَدَخَلَ فِي الثَّانِيَةِ،"]]},{"id":"ri30_2","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢","segs":[["matn","وَلَا يُجْزِئُ فِي الضَّحَايَا مِنَ الْمَعْزِ وَالْبَقَرِ وَالْإِبِلِ إِلَّا الثَّنِيُّ، وَالثَّنِيُّ مِنَ الْبَقَرِ مَا دَخَلَ فِي السَّنَةِ الرَّابِعَةِ، وَالثَّنِيُّ مِنَ الْإِبِلِ ابْنُ سِتِّ سِنِينَ."]]},{"id":"ri30_3","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٣","segs":[["matn","وَفُحُولُ الضَّأْنِ فِي الضَّحَايَا أَفْضَلُ مِنْ خُصْيَانِهَا، وَخُصْيَانُهَا أَفْضَلُ مِنْ إِنَاثِهَا، وَإِنَاثُهَا أَفْضَلُ مِنْ ذُكُورِ الْمَعْزِ وَمِنْ إِنَاثِهَا وَفُحُولُ الْمَعْزِ أَفْضَلُ مِنْ إِنَاثِهَا،"]]},{"id":"ri30_4","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٤","segs":[["matn","وَإِنَاثُ الْمَعْزِ أَفْضَلُ مِنَ الْإِبِلِ وَالْبَقَرِ فِي الضَّحَايَا، وَأَمَّا فِي الْهَدَايَا فَالْإِبِلُ أَفْضَلُ ثُمَّ الْبَقَرُ ثُمَّ الضَّأْنُ ثُمَّ الْمَعْزُ."]]},{"id":"ri30_5","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٥","segs":[["matn","وَلَا يَجُوزُ فِي شَيْءٍ مِنْ ذَلِكَ عَوْرَاءُ وَلَا مَرِيضَةٌ وَلَا الْعَرْجَاءُ الْبَيِّنُ ضِلْعُهَا، وَلَا الْعَجْفَاءُ الَّتِي لَا شَحْمَ فِيهَا، وَيُتَّقَى فِيهَا الْعَيْبُ كُلُّهُ،"]]},{"id":"ri30_6","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٦","segs":[["matn","وَلَا الْمَشْقُوقَةُ الْأُذُنِ إِلَّا أَنْ يَكُونَ يَسِيرًا، وَكَذَلِكَ الْقَطْعُ، وَمَكْسُورَةُ الْقَرْنِ إِنْ كَانَ يُدْمِي فَلَا يَجُوزُ، وَإِنْ لَمْ يُدْمِ فَذَلِكَ جَائِزٌ."]]},{"id":"ri30_7","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٧","segs":[["matn","وَلْيَلِ الرَّجُلُ ذَبْحَ أُضْحِيَّتِهِ بِيَدِهِ بَعْدَ ذَبْحِ الْإِمَامِ أَوْ نَحْرِهِ يَوْمَ النَّحْرِ ضَحْوَةً، وَمَنْ ذَبَحَ قَبْلَ أَنْ يَذْبَحَ الْإِمَامُ أَوْ يَنْحَرَ أَعَادَ أُضْحِيَّتَهُ، وَمَنْ لَا إِمَامَ لَهُمْ فَلْيَتَحَرَّوْا صَلَاةَ أَقْرَبِ الْأَئِمَّةِ إِلَيْهِمْ وَذَبْحَهُ."]]},{"id":"ri30_8","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٨","segs":[["matn","وَمَنْ ضَحَّى بِلَيْلٍ أَوْ أَهْدَى لَمْ يُجْزِهِ، وَأَيَّامُ النَّحْرِ ثَلَاثَةٌ يُذْبَحُ فِيهَا أَوْ يُنْحَرُ إِلَى غُرُوبِ الشَّمْسِ مِنْ آخِرِهَا، وَأَفْضَلُ أَيَّامِ النَّحْرِ أَوَّلُهَا،"]]},{"id":"ri30_9","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٩","segs":[["matn","وَمَنْ فَاتَهُ الذَّبْحُ فِي الْيَوْمِ الْأَوَّلِ إِلَى الزَّوَالِ فَقَدْ قَالَ بَعْضُ أَهْلِ الْعِلْمِ: يُسْتَحَبُّ لَهُ أَنْ يَصْبِرَ إِلَى ضُحَى الْيَوْمِ الثَّانِي، وَلَا يُبَاعُ شَيْءٌ مِنَ الْأُضْحِيَّةِ: جِلْدٌ وَلَا غَيْرُهُ."]]},{"id":"ri30_10","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٠","segs":[["matn","وَتُوَجَّهُ الذَّبِيحَةُ عِنْدَ الذَّبْحِ إِلَى الْقِبْلَةِ، وَلْيَقُلِ الذَّابِحُ: بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ، وَإِنْ زَادَ فِي الْأُضْحِيَّةِ: رَبَّنَا تَقَبَّلْ مِنَّا فَلَا بَأْسَ بِذَلِكَ،"]]},{"id":"ri30_11","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١١","segs":[["matn","وَمَنْ نَسِيَ التَّسْمِيَةَ فِي ذَبْحِ أُضْحِيَّةٍ أَوْ غَيْرِهَا فَإِنَّهَا تُؤْكَلُ، وَإِنْ تَعَمَّدَ تَرْكَ التَّسْمِيَةِ لَمْ تُؤْكَلْ، وَكَذَلِكَ عِنْدَ إِرْسَالِ الْجَوَارِحِ عَلَى الصَّيْدِ."]]},{"id":"ri30_12","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٢","segs":[["matn","وَلَا يُبَاعُ مِنَ الْأُضْحِيَّةِ وَالْعَقِيقَةِ وَالنُّسُكِ لَحْمٌ وَلَا جِلْدٌ وَلَا وَدَكٌ وَلَا عَصَبٌ وَلَا غَيْرُ ذَلِكَ، وَيَأْكُلُ الرَّجُلُ مِنْ أُضْحِيَّتِهِ وَيَتَصَدَّقُ مِنْهَا أَفْضَلُ لَهُ، وَلَيْسَ بِوَاجِبٍ عَلَيْهِ."]]},{"id":"ri30_13","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٣","segs":[["matn","وَلَا يَأْكُلُ مِنْ فِدْيَةِ الْأَذَى وَجَزَاءِ الصَّيْدِ وَنَذْرِ الْمَسَاكِينِ وَمَا عَطِبَ مِنْ هَدْيِ التَّطَوُّعِ قَبْلَ مَحِلِّهِ، وَيَأْكُلُ مِمَّا سِوَى ذَلِكَ إِنْ شَاءَ."]]},{"id":"ri30_14","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٤","segs":[["matn","وَالذَّكَاةُ قَطْعُ الْحُلْقُومِ وَالْأَوْدَاجِ، وَلَا يُجْزِئُ أَقَلُّ مِنْ ذَلِكَ، وَإِنْ رَفَعَ يَدَهُ بَعْدَ قَطْعِ بَعْضِ ذَلِكَ، ثُمَّ أَعَادَ يَدَهُ فَأَجْهَزَ فَلَا تُؤْكَلُ، وَإِنْ تَمَادَى حَتَّى قَطَعَ الرَّأْسَ أَسَاءَ وَلْتُؤْكَلْ."]]},{"id":"ri30_15","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٥","segs":[["matn","وَمَنْ ذَبَحَ مِنَ الْقَفَا لَمْ تُؤْكَلْ."]]},{"id":"ri30_16","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٦","segs":[["matn","وَالْبَقَرُ تُذْبَحُ، فَإِنْ نُحِرَتْ أُكِلَتْ، وَالْإِبِلُ تُنْحَرُ، فَإِنْ ذُبِحَتْ لَمْ تُؤْكَلْ، وَقَدِ اخْتُلِفَ فِي أَكْلِهَا، وَالْغَنَمُ تُذْبَحُ فَإِنْ نُحِرَتْ لَمْ تُؤْكَلْ، وَقَدِ اخْتُلِفَ أَيْضًا فِي ذَلِكَ وَذَكَاةُ مَا فِي الْبَطْنِ ذَكَاةُ أُمِّهِ إِذَا تَمَّ خَلْقُهُ وَنَبَتَ شَعْرُهُ."]]},{"id":"ri30_17","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٧","segs":[["matn","وَالْمُنْخَنِقَةُ بِحَبْلٍ وَنَحْوِهِ وَالْمَوْقُوذَةُ بِعَصًا وَشِبْهِهَا وَالْمُتَرَدِّيَةُ وَالنَّطِيحَةُ وَأَكِيلَةُ السَّبُعِ إِنْ بَلَغَ ذَلِكَ مِنْهَا فِي هَذِهِ الْوُجُوهِ مَبْلَغًا لَا تَعِيشُ مَعَهُ لَمْ تُؤْكَلْ بِذَكَاةٍ."]]},{"id":"ri30_18","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٨","segs":[["matn","وَلَا بَأْسَ لِلْمُضْطَرِّ أَنْ يَأْكُلَ الْمَيْتَةَ، وَيَشْبَعَ وَيَتَزَوَّدَ، فَإِنِ اسْتَغْنَى عَنْهَا طَرَحَهَا، وَلَا بَأْسَ بِالِانْتِفَاعِ بِجِلْدِهَا إِذَا دُبِغَ، وَلَا يُصَلَّى عَلَيْهِ، وَلَا يُبَاعُ."]]},{"id":"ri30_19","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ١٩","segs":[["matn","وَلَا بَأْسَ بِالصَّلَاةِ عَلَى جُلُودِ السِّبَاعِ إِذَا ذُكِّيَتْ وَبَيْعِهَا، وَيُنْتَفَعُ بِصُوفِ الْمَيْتَةِ وَشَعْرِهَا وَمَا يُنْزَعُ مِنْهَا فِي حَالِ الْحَيَاةِ، وَأَحَبُّ إِلَيْنَا أَنْ يُغْسَلَ، وَلَا يُنْتَفَعُ بِرِيشِهَا وَلَا بِقَرْنِهَا وَأَظْلَافِهَا وَأَنْيَابِهَا، وَكُرِهَ الِانْتِفَاعُ بِأَنْيَابِ الْفِيلِ، وَقَدِ اخْتُلِفَ فِي ذَلِكَ."]]},{"id":"ri30_20","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢٠","segs":[["matn","وَمَا مَاتَتْ فِيهِ فَأْرَةٌ مِنْ سَمْنٍ أَوْ زَيْتٍ أَوْ عَسَلٍ ذَائِبٍ طُرِحَ وَلَمْ يُؤْكَلْ، وَلَا بَأْسَ أَنْ يُسْتَصْبَحَ بِالزَّيْتِ وَشِبْهِهِ فِي غَيْرِ الْمَسَاجِدِ وَلْيُتَحَفَّظْ مِنْهُ،"]]},{"id":"ri30_21","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢١","segs":[["matn","وَإِنْ كَانَ جَامِدًا طُرِحَتْ وَمَا حَوْلَهَا وَأُكِلَ مَا بَقِيَ، قَالَ سَحْنُونٌ: إِلَّا أَنْ يَطُولَ مُقَامُهَا فِيهِ فَإِنَّهُ يُطْرَحُ كُلُّهُ. وَلَا بَأْسَ بِطَعَامِ أَهْلِ الْكِتَابِ، وَذَبَائِحِهِمْ."]]},{"id":"ri30_22","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢٢","segs":[["matn","وَكُرِهَ أَكْلُ شُحُومِ الْيَهُودِ مِنْهُمْ مِنْ غَيْرِ تَحْرِيمٍ، وَلَا يُؤْكَلُ مَا ذَكَّاهُ الْمَجُوسِيُّ، وَمَا كَانَ مِمَّا لَيْسَ فِيهِ ذَكَاةٌ مِنْ طَعَامِهِمْ فَلَيْسَ بِحَرَامٍ."]]},{"id":"ri30_23","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢٣","segs":[["matn","وَالصَّيْدُ لِلَّهْوِ مَكْرُوهٌ، وَالصَّيْدُ لِغَيْرِ اللَّهْوِ مُبَاحٌ، وَكُلُّ مَا قَتَلَهُ كَلْبُكَ الْمُعَلَّمُ أَوْ بَازُكَ الْمُعَلَّمُ فَجَائِزٌ أَكْلُهُ إِذَا أَرْسَلْتَهُ عَلَيْهِ،"]]},{"id":"ri30_24","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢٤","segs":[["matn","وَكَذَلِكَ مَا أَنْفَذَتِ الْجَوَارِحُ مَقَاتِلَهُ قَبْلَ قُدْرَتِكَ عَلَى ذَكَاتِهِ، وَمَا أَدْرَكْتَهُ قَبْلَ إِنْفَاذِهَا لِمَقَاتِلِهِ لَمْ يُؤْكَلْ إِلَّا بِذَكَاةٍ، وَكُلُّ مَا صِدْتَهُ بِسَهْمِكَ أَوْ رُمْحِكَ فَكُلْهُ،"]]},{"id":"ri30_25","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢٥","segs":[["matn","فَإِنْ أَدْرَكْتَ ذَكَاتَهُ فَذَكِّهِ، وَإِنْ فَاتَ بِنَفْسِهِ فَكُلْهُ إِذَا قَتَلَهُ سَهْمُكَ مَا لَمْ يَبِتْ عَنْكَ، وَقِيلَ: إِنَّمَا ذَلِكَ فِيمَا بَاتَ عَنْكَ مِمَّا قَتَلَتْهُ الْجَوَارِحُ، وَأَمَّا السَّهْمُ يُوجَدُ فِي مَقَاتِلِهِ فَلَا بَأْسَ بِأَكْلِهِ، وَلَا تُؤْكَلُ الْإِنْسِيَّةُ بِمَا يُؤْكَلُ بِهِ الصَّيْدُ."]]},{"id":"ri30_26","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢٦","segs":[["matn","وَالْعَقِيقَةُ سُنَّةٌ مُسْتَحَبَّةٌ، وَيُعَقُّ عَنِ الْمَوْلُودِ يَوْمَ سَابِعِهِ بِشَاةٍ مِثْلَ مَا ذَكَرْنَا مِنْ سِنِّ الْأُضْحِيَّةِ وَصِفَتِهَا، وَلَا يُحْسَبُ فِي السَّبْعَةِ الْأَيَّامِ الْيَوْمُ الَّذِي وُلِدَ فِيهِ، وَتُذْبَحُ ضَحْوَةً، وَلَا يُمَسُّ الصَّبِيُّ بِشَيْءٍ مِنْ دَمِهَا،"]]},{"id":"ri30_27","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢٧","segs":[["matn","وَيُؤْكَلُ مِنْهَا وَيُتَصَدَّقُ، وَتُكْسَرُ عِظَامُهَا، وَإِنْ حُلِقَ شَعْرُ رَأْسِ الْمَوْلُودِ وَتُصُدِّقَ بِوَزْنِهِ مِنْ ذَهَبٍ أَوْ فِضَّةٍ فَذَلِكَ مُسْتَحَبٌّ حَسَنٌ، وَإِنْ خُلِّقَ رَأْسُهُ بِخَلُوقٍ بَدَلًا مِنَ الدَّمِ الَّذِي كَانَتْ تَفْعَلُهُ الْجَاهِلِيَّةُ فَلَا بَأْسَ بِذَلِكَ."]]},{"id":"ri30_28","label":"بَابٌ فِي الضَّحَايَا وَالذَّبَائِحِ وَالْعَقِيقَةِ وَالصَّيْدِ وَالْخِتَانِ وَمَا يَحْرُمُ مِنَ الْأَطْعِمَةِ وَالْأَشْرِبَةِ · ٢٨","segs":[["matn","وَالْخِتَانُ سُنَّةٌ فِي الذُّكُورِ وَاجِبَةٌ، وَالْخِفَاضُ فِي النِّسَاءِ مَكْرُمَةٌ."]]}]},{"id":"ri31","title":"بَابٌ فِي الْجِهَادِ","units":[{"id":"ri31_1","label":"بَابٌ فِي الْجِهَادِ · ١","segs":[["matn","وَالْجِهَادُ فَرِيضَةٌ، يَحْمِلُهُ بَعْضُ النَّاسِ عَنْ بَعْضٍ، وَأَحَبُّ إِلَيْنَا أَنْ لَا يُقَاتَلَ الْعَدُوُّ حَتَّى يُدْعَوْا إِلَى دِينِ اللَّهِ إِلَّا أَنْ يُعَاجِلُونَا: فَإِمَّا أَنْ يُسْلِمُوا، أَوْ يُؤَدُّوا الْجِزْيَةَ، وَإِلَّا قُوتِلُوا."]]},{"id":"ri31_2","label":"بَابٌ فِي الْجِهَادِ · ٢","segs":[["matn","وَإِنَّمَا تُقْبَلُ مِنْهُمُ الْجِزْيَةُ إِذَا كَانُوا حَيْثُ تَنَالُهُمْ أَحْكَامُنَا، فَأَمَّا إِنْ بَعُدُوا مِنَّا فَلَا تُقْبَلُ مِنْهُمُ الْجِزْيَةُ إِلَّا أَنْ يَرْتَحِلُوا إِلَى بِلَادِنَا، وَإِلَّا قُوتِلُوا."]]},{"id":"ri31_3","label":"بَابٌ فِي الْجِهَادِ · ٣","segs":[["matn","وَالْفِرَارُ مِنَ الْعَدُوِّ مِنَ الْكَبَائِرِ إِذَا كَانُوا مِثْلَيْ عَدَدِ الْمُسْلِمِينَ فَأَقَلَّ، فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَلَا بَأْسَ بِذَلِكَ، وَيُقَاتَلُ الْعَدُوُّ مَعَ كُلِّ بَرٍّ وَفَاجِرٍ مِنَ الْوُلَاةِ."]]},{"id":"ri31_4","label":"بَابٌ فِي الْجِهَادِ · ٤","segs":[["matn","وَلَا بَأْسَ بِقَتْلِ مَنْ أُسِرَ مِنَ الْأَعْلَاجِ، وَلَا يُقْتَلُ أَحَدٌ بَعْدَ أَمَانٍ، وَلَا يُخْفَرُ لَهُمْ بِعَهْدٍ، وَلَا يُقْتَلُ النِّسَاءُ وَالصِّبْيَانُ، وَيُجْتَنَبُ قَتْلُ الرُّهْبَانِ وَالْأَحْبَارِ،"]]},{"id":"ri31_5","label":"بَابٌ فِي الْجِهَادِ · ٥","segs":[["matn","إِلَّا أَنْ يُقَاتِلُوا، وَكَذَلِكَ الْمَرْأَةُ تُقْتَلُ إِذَا قَاتَلَتْ، وَيَجُوزُ أَمَانُ أَدْنَى الْمُسْلِمِينَ عَلَى بَقِيَّتِهِمْ، وَكَذَلِكَ الْمَرْأَةُ وَالصَّبِيُّ إِذَا عَقَلَ الْأَمَانَ، وَقِيلَ: إِنْ أَجَازَ ذَلِكَ الْإِمَامُ جَازَ."]]},{"id":"ri31_6","label":"بَابٌ فِي الْجِهَادِ · ٦","segs":[["matn","وَمَا غَنِمَ الْمُسْلِمُونَ بِإِيجَافٍ فَلْيَأْخُذِ الْإِمَامُ خُمُسَهُ، وَيَقْسِمُ الْأَرْبَعَةَ الْأَخْمَاسَ بَيْنَ أَهْلِ الْجَيْشِ، وَقَسْمُ ذَلِكَ بِبَلَدِ الْحَرْبِ أَوْلَى،"]]},{"id":"ri31_7","label":"بَابٌ فِي الْجِهَادِ · ٧","segs":[["matn","وَإِنَّمَا يُخَمَّسُ وَيُقْسَمُ مَا أُوجِفَ عَلَيْهِ بِالْخَيْلِ وَالرِّكَابِ وَمَا غُنِمَ بِقِتَالٍ، وَلَا بَأْسَ أَنْ يُؤْكَلَ مِنَ الْغَنِيمَةِ قَبْلَ أَنْ يُقْسَمَ الطَّعَامُ وَالْعَلَفُ لِمَنِ احْتَاجَ إِلَى ذَلِكَ."]]},{"id":"ri31_8","label":"بَابٌ فِي الْجِهَادِ · ٨","segs":[["matn","وَإِنَّمَا يُسْهَمُ لِمَنْ حَضَرَ الْقِتَالَ، أَوْ تَخَلَّفَ عَنِ الْقِتَالِ فِي شُغْلِ الْمُسْلِمِينَ مِنْ أَمْرِ جِهَادِهِمْ، وَيُسْهَمُ لِلْمَرِيضِ وَلِلْفَرَسِ الرَّهِيصِ، وَيُسْهَمُ لِلْفَرَسِ سَهْمَانِ، وَسَهْمٌ لِرَاكِبِهِ،"]]},{"id":"ri31_9","label":"بَابٌ فِي الْجِهَادِ · ٩","segs":[["matn","وَلَا يُسْهَمُ لِعَبْدٍ وَلَا لِامْرَأَةٍ وَلَا لِصَبِيٍّ، إِلَّا أَنْ يُطِيقَ الصَّبِيُّ الَّذِي لَمْ يَحْتَلِمِ الْقِتَالَ، وَيُجِيزَهُ الْإِمَامُ، وَيُقَاتِلَ، فَيُسْهَمُ لَهُ، وَلَا يُسْهَمُ لِلْأَجِيرِ إِلَّا أَنْ يُقَاتِلَ."]]},{"id":"ri31_10","label":"بَابٌ فِي الْجِهَادِ · ١٠","segs":[["matn","وَمَنْ أَسْلَمَ مِنَ الْعَدُوِّ عَلَى شَيْءٍ فِي يَدِهِ مِنْ أَمْوَالِ الْمُسْلِمِينَ فَهُوَ لَهُ حَلَالٌ، وَمَنِ اشْتَرَى شَيْئًا مِنْهَا مِنْ مَالِ الْعَدُوِّ لَمْ يَأْخُذْهُ رَبُّهُ إِلَّا بِالثَّمَنِ،"]]},{"id":"ri31_11","label":"بَابٌ فِي الْجِهَادِ · ١١","segs":[["matn","وَمَا وَقَعَ فِي الْمَقَاسِمِ مِنْهَا فَرَبُّهُ أَحَقُّ بِهِ بِالثَّمَنِ، وَمَا لَمْ يَقَعْ فِي الْمَقَاسِمِ فَرَبُّهُ أَحَقُّ بِهِ بِلَا ثَمَنٍ."]]},{"id":"ri31_12","label":"بَابٌ فِي الْجِهَادِ · ١٢","segs":[["matn","وَلَا نَفَلَ إِلَّا مِنَ الْخُمُسِ عَلَى الِاجْتِهَادِ مِنَ الْإِمَامِ، وَلَا يَكُونُ ذَلِكَ قَبْلَ الْقَسْمِ. وَالسَّلَبُ مِنَ النَّفَلِ."]]},{"id":"ri31_13","label":"بَابٌ فِي الْجِهَادِ · ١٣","segs":[["matn","وَالرِّبَاطُ فِيهِ فَضْلٌ كَبِيرٌ، وَذَلِكَ بِقَدْرِ كَثْرَةِ خَوْفِ أَهْلِ ذَلِكَ الثَّغْرِ وَكَثْرَةِ تَحَرُّزِهِمْ مِنْ عَدُوِّهِمْ."]]},{"id":"ri31_14","label":"بَابٌ فِي الْجِهَادِ · ١٤","segs":[["matn","وَلَا يُغْزَى بِغَيْرِ إِذْنِ الْأَبَوَيْنِ، إِلَّا أَنْ يَفْجَأَ الْعَدُوُّ مَدِينَةَ قَوْمٍ، وَيُغِيرُونَ عَلَيْهِمْ؛ فَفَرْضٌ عَلَيْهِمْ دَفْعُهُمْ، وَلَا يُسْتَأْذَنُ الْأَبَوَانِ فِي مِثْلِ هَذَا."]]}]},{"id":"ri32","title":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ","units":[{"id":"ri32_1","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١","segs":[["matn","وَمَنْ كَانَ حَالِفًا فَلْيَحْلِفْ بِاللَّهِ أَوْ لِيَصْمُتْ، وَيُؤَدَّبُ مَنْ حَلَفَ بِطَلَاقٍ أَوْ عَتَاقٍ وَيَلْزَمُهُ، وَلَا ثُنْيَا وَلَا كَفَّارَةَ إِلَّا فِي الْيَمِينِ بِاللَّهِ عَزَّ وَجَلَّ أَوْ بِشَيْءٍ مِنْ أَسْمَائِهِ وَصِفَاتِهِ."]]},{"id":"ri32_2","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٢","segs":[["matn","وَمَنِ اسْتَثْنَى فَلَا كَفَّارَةَ عَلَيْهِ إِذَا قَصَدَ الِاسْتِثْنَاءَ، وَقَالَ: إِنْ شَاءَ اللَّهُ، وَوَصَلَهَا بِيَمِينِهِ قَبْلَ أَنْ يَصْمُتَ، وَإِلَّا لَمْ يَنْفَعْهُ ذَلِكَ."]]},{"id":"ri32_3","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٣","segs":[["matn","وَالْأَيْمَانُ بِاللَّهِ أَرْبَعَةٌ: فَيَمِينَانِ تُكَفَّرَانِ؛ وَهُوَ أَنْ يَحْلِفَ بِاللَّهِ إِنْ فَعَلْتُ، أَوْ يَحْلِفَ لَيَفْعَلَنَّ."]]},{"id":"ri32_4","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٤","segs":[["matn","وَيَمِينَانِ لَا تُكَفَّرَانِ: إِحْدَاهُمَا لَغْوُ الْيَمِينِ، وَهُوَ أَنْ يَحْلِفَ عَلَى شَيْءٍ يَظُنُّهُ كَذَلِكَ فِي يَقِينِهِ، ثُمَّ يَتَبَيَّنُ لَهُ خِلَافُهُ؛"]]},{"id":"ri32_5","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٥","segs":[["matn","فَلَا كَفَّارَةَ عَلَيْهِ وَلَا إِثْمَ، وَالْأُخْرَى الْحَالِفُ مُتَعَمِّدًا لِلْكَذِبِ أَوْ شَاكًّا فَهُوَ آثِمٌ، وَلَا تُكَفِّرُ ذَلِكَ الْكَفَّارَةُ، وَلْيَتُبْ مِنْ ذَلِكَ إِلَى اللَّهِ سُبْحَانَهُ وَتَعَالَى."]]},{"id":"ri32_6","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٦","segs":[["matn","وَالْكَفَّارَةُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنَ الْمُسْلِمِينَ الْأَحْرَارِ مُدًّا لِكُلِّ مِسْكِينٍ بِمُدِّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَحَبُّ إِلَيْنَا أَنْ لَوْ زَادَ عَلَى الْمُدِّ مِثْلَ ثُلُثِ مُدٍّ أَوْ نِصْفِ مُدٍّ،"]]},{"id":"ri32_7","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٧","segs":[["matn","وَذَلِكَ بِقَدْرِ مَا يَكُونُ مِنْ وَسَطِ عَيْشِهِمْ فِي غَلَاءٍ أَوْ رُخْصٍ، وَمَنْ أَخْرَجَ مُدًّا عَلَى كُلِّ حَالٍ أَجْزَأَهُ."]]},{"id":"ri32_8","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٨","segs":[["matn","وَإِنْ كَسَاهُمْ كَسَاهُمْ لِلرَّجُلِ قَمِيصٌ، وَلِلْمَرْأَةِ قَمِيصٌ وَخِمَارٌ، أَوْ عِتْقُ رَقَبَةٍ مُؤْمِنَةٍ، فَإِنْ لَمْ يَجِدْ ذَلِكَ وَلَا إِطْعَامًا فَلْيَصُمْ ثَلَاثَةَ أَيَّامٍ يُتَابِعُهُنَّ، فَإِنْ فَرَّقَهُنَّ أَجْزَأَهُ."]]},{"id":"ri32_9","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٩","segs":[["matn","وَلَهُ أَنْ يُكَفِّرَ قَبْلَ الْحِنْثِ أَوْ بَعْدَهُ، وَبَعْدَ الْحِنْثِ أَحَبُّ إِلَيْنَا."]]},{"id":"ri32_10","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٠","segs":[["matn","وَمَنْ نَذَرَ أَنْ يُطِيعَ اللَّهَ فَلْيُطِعْهُ، وَمَنْ نَذَرَ أَنْ يَعْصِيَ اللَّهَ فَلَا يَعْصِهِ، وَلَا شَيْءَ عَلَيْهِ، وَمَنْ نَذَرَ صَدَقَةَ مَالِ غَيْرِهِ أَوْ عِتْقَ عَبْدِ غَيْرِهِ لَمْ يَلْزَمْهُ شَيْءٌ، وَمَنْ قَالَ:"]]},{"id":"ri32_11","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١١","segs":[["matn","إِنْ فَعَلْتُ كَذَا فَعَلَيَّ نَذْرُ كَذَا وَكَذَا لِشَيْءٍ يَذْكُرُهُ مِنْ فِعْلِ الْبِرِّ مِنْ صَلَاةٍ أَوْ صَوْمٍ أَوْ حَجٍّ أَوْ عُمْرَةٍ أَوْ صَدَقَةِ شَيْءٍ سَمَّاهُ فَذَلِكَ يَلْزَمُهُ إِنْ حَنِثَ كَمَا يَلْزَمُهُ لَوْ نَذَرَهُ مُجَرَّدًا مِنْ غَيْرِ يَمِينٍ،"]]},{"id":"ri32_12","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٢","segs":[["matn","وَإِنْ لَمْ يُسَمِّ لِنَذْرِهِ مَخْرَجًا مِنَ الْأَعْمَالِ فَعَلَيْهِ كَفَّارَةُ يَمِينٍ."]]},{"id":"ri32_13","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٣","segs":[["matn","وَمَنْ نَذَرَ مَعْصِيَةً مِنْ قَتْلِ نَفْسٍ أَوْ شُرْبِ خَمْرٍ أَوْ شِبْهِهِ أَوْ مَا لَيْسَ بِطَاعَةٍ وَلَا مَعْصِيَةٍ فَلَا شَيْءَ عَلَيْهِ وَلْيَسْتَغْفِرِ اللَّهَ،"]]},{"id":"ri32_14","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٤","segs":[["matn","وَإِنْ حَلَفَ بِاللَّهِ لَيَفْعَلَنَّ مَعْصِيَةً فَلْيُكَفِّرْ عَنْ يَمِينِهِ، وَلَا يَفْعَلْ ذَلِكَ، وَإِنْ تَجَرَّأَ وَفَعَلَهُ أَثِمَ، وَلَا كَفَّارَةَ عَلَيْهِ لِيَمِينِهِ."]]},{"id":"ri32_15","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٥","segs":[["matn","وَمَنْ قَالَ: عَلَيَّ عَهْدُ اللَّهِ وَمِيثَاقُهُ فِي يَمِينٍ فَحَنِثَ فَعَلَيْهِ كَفَّارَتَانِ، وَلَيْسَ عَلَى مَنْ وَكَّدَ الْيَمِينَ فَكَرَّرَهَا فِي شَيْءٍ وَاحِدٍ غَيْرُ كَفَّارَةٍ وَاحِدَةٍ."]]},{"id":"ri32_16","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٦","segs":[["matn","وَمَنْ قَالَ: أَشْرَكْتُ بِاللَّهِ، أَوْ هُوَ يَهُودِيٌّ أَوْ نَصْرَانِيٌّ إِنْ فَعَلَ كَذَا فَلَا يَلْزَمُهُ غَيْرُ الِاسْتِغْفَارِ."]]},{"id":"ri32_17","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٧","segs":[["matn","وَمَنْ حَرَّمَ عَلَى نَفْسِهِ شَيْئًا مِمَّا أَحَلَّ اللَّهُ لَهُ فَلَا شَيْءَ عَلَيْهِ، إِلَّا فِي زَوْجَتِهِ فَإِنَّهَا تَحْرُمُ عَلَيْهِ إِلَّا بَعْدَ زَوْجٍ،"]]},{"id":"ri32_18","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٨","segs":[["matn","وَمَنْ جَعَلَ مَالَهُ صَدَقَةً أَوْ هَدْيًا أَجْزَأَهُ ثُلُثُهُ، وَمَنْ حَلَفَ بِنَحْرِ وَلَدِهِ فَإِنْ ذَكَرَ مَقَامَ إِبْرَاهِيمَ أَهْدَى هَدْيًا يُذْبَحُ بِمَكَّةَ، وَتُجْزِئُهُ شَاةٌ، وَإِنْ لَمْ يَذْكُرِ الْمَقَامَ فَلَا شَيْءَ عَلَيْهِ."]]},{"id":"ri32_19","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ١٩","segs":[["matn","وَمَنْ حَلَفَ بِالْمَشْيِ إِلَى مَكَّةَ فَحَنِثَ فَعَلَيْهِ الْمَشْيُ مِنْ مَوْضِعِ حَلِفِهِ فَلْيَمْشِ إِنْ شَاءَ فِي حَجٍّ أَوْ عُمْرَةٍ، فَإِنْ عَجَزَ عَنِ الْمَشْيِ رَكِبَ،"]]},{"id":"ri32_20","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٢٠","segs":[["matn","ثُمَّ يَرْجِعُ ثَانِيَةً إِنْ قَدَرَ، فَيَمْشِي أَمَاكِنَ رُكُوبِهِ، فَإِنْ عَلِمَ أَنَّهُ لَا يَقْدِرُ قَعَدَ وَأَهْدَى، وَقَالَ عَطَاءٌ: لَا يَرْجِعُ ثَانِيَةً وَإِنْ قَدَرَ، وَيُجْزِئُهُ الْهَدْيُ."]]},{"id":"ri32_21","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٢١","segs":[["matn","وَإِذَا كَانَ صَرُورَةً جَعَلَ ذَلِكَ فِي عُمْرَةٍ، فَإِذَا طَافَ وَسَعَى وَقَصَّرَ أَحْرَمَ مِنْ مَكَّةَ بِفَرِيضَةٍ، وَكَانَ مُتَمَتِّعًا، وَالْحِلَاقُ فِي غَيْرِ هَذَا أَفْضَلُ، وَإِنَّمَا يُسْتَحَبُّ لَهُ التَّقْصِيرُ فِي هَذَا اسْتِبْقَاءً لِلشَّعْثِ فِي الْحَجِّ."]]},{"id":"ri32_22","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٢٢","segs":[["matn","وَمَنْ نَذَرَ مَشْيًا إِلَى الْمَدِينَةِ أَوْ إِلَى بَيْتِ الْمَقْدِسِ أَتَاهُمَا رَاكِبًا إِنْ نَوَى الصَّلَاةَ بِمَسْجِدَيْهِمَا، وَإِلَّا فَلَا شَيْءَ عَلَيْهِ،"]]},{"id":"ri32_23","label":"بَابٌ فِي الْأَيْمَانِ وَالنُّذُورِ · ٢٣","segs":[["matn","وَأَمَّا غَيْرُ هَذِهِ الثَّلَاثَةِ مَسَاجِدَ فَلَا يَأْتِيهَا مَاشِيًا وَلَا رَاكِبًا لِصَلَاةٍ نَذَرَهَا، وَلْيُصَلِّ بِمَوْضِعِهِ، وَمَنْ نَذَرَ رِبَاطًا بِمَوْضِعٍ مِنَ الثُّغُورِ فَذَلِكَ عَلَيْهِ أَنْ يَأْتِيَهُ."]]}]},{"id":"ri33","title":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ","units":[{"id":"ri33_1","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١","segs":[["matn","وَلَا نِكَاحَ إِلَّا بِوَلِيٍّ وَصَدَاقٍ وَشَاهِدَيْ عَدْلٍ، فَإِنْ لَمْ يُشْهِدَا فِي الْعَقْدِ فَلَا يَبْنِي بِهَا حَتَّى يُشْهِدَا. وَأَقَلُّ الصَّدَاقِ رُبُعُ دِينَارٍ."]]},{"id":"ri33_2","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢","segs":[["matn","وَلِلْأَبِ إِنْكَاحُ ابْنَتِهِ الْبِكْرِ بِغَيْرِ إِذْنِهَا وَإِنْ بَلَغَتْ وَإِنْ شَاءَ شَاوَرَهَا، وَأَمَّا غَيْرُ الْأَبِ فِي الْبِكْرِ: وَصِيٌّ أَوْ غَيْرُهُ فَلَا يُزَوِّجُهَا حَتَّى تَبْلُغَ وَتَأْذَنَ، وَإِذْنُهَا صُمَاتُهَا، وَلَا يُزَوِّجُ الثَّيِّبَ أَبٌ وَلَا غَيْرُهُ إِلَّا بِرِضَاهَا، وَتَأْذَنُ بِالْقَوْلِ."]]},{"id":"ri33_3","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣","segs":[["matn","وَلَا تُنْكَحُ الْمَرْأَةُ إِلَّا بِإِذْنِ وَلِيِّهَا أَوْ ذِي الرَّأْيِ مِنْ أَهْلِهَا كَالرَّجُلِ مِنْ عَشِيرَتِهَا أَوِ السُّلْطَانِ."]]},{"id":"ri33_4","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤","segs":[["matn","وَقَدِ اخْتُلِفَ فِي الدَّنِيَّةِ أَنْ تُوَلِّيَ أَجْنَبِيًّا، وَالِابْنُ أَوْلَى مِنَ الْأَبِ، وَالْأَبُ أَوْلَى مِنَ الْأَخِ، وَمَنْ قَرُبَ مِنَ الْعَصَبَةِ أَحَقُّ، وَإِنْ زَوَّجَهَا الْبَعِيدُ مَضَى ذَلِكَ،"]]},{"id":"ri33_5","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٥","segs":[["matn","وَلِلْوَصِيِّ أَنْ يُزَوِّجَ الطِّفْلَ فِي وِلَايَتِهِ، وَلَا يُزَوِّجُ الصَّغِيرَةَ إِلَّا أَنْ يَأْمُرَهُ الْأَبُ بِإِنْكَاحِهَا، وَلَيْسَ ذَوُو الْأَرْحَامِ مِنَ الْأَوْلِيَاءِ، وَالْأَوْلِيَاءُ مِنَ الْعَصَبَةِ."]]},{"id":"ri33_6","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٦","segs":[["matn","وَلَا يَخْطُبُ أَحَدٌ عَلَى خِطْبَةِ أَخِيهِ، وَلَا يَسُومُ عَلَى سَوْمِهِ، وَذَلِكَ إِذَا رَكَنَا وَتَقَارَبَا."]]},{"id":"ri33_7","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٧","segs":[["matn","وَلَا يَجُوزُ نِكَاحُ الشِّغَارِ، وَهُوَ الْبُضْعُ بِالْبُضْعِ، وَلَا نِكَاحٌ بِغَيْرِ صَدَاقٍ، وَلَا نِكَاحُ الْمُتْعَةِ، وَهُوَ النِّكَاحُ إِلَى أَجَلٍ، وَلَا النِّكَاحُ فِي الْعِدَّةِ، وَلَا مَا جَرَّ إِلَى غَرَرٍ فِي عَقْدٍ أَوْ صَدَاقٍ وَلَا بِمَا لَا يَجُوزُ بَيْعُهُ."]]},{"id":"ri33_8","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٨","segs":[["matn","وَمَا فَسَدَ مِنَ النِّكَاحِ لِصَدَاقِهِ فُسِخَ قَبْلَ الْبِنَاءِ، فَإِنْ دَخَلَ بِهَا مَضَى، وَكَانَ فِيهِ صَدَاقُ الْمِثْلِ، وَمَا فَسَدَ مِنَ النِّكَاحِ لِعَقْدِهِ،"]]},{"id":"ri33_9","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٩","segs":[["matn","وَفُسِخَ بَعْدَ الْبِنَاءِ فَفِيهِ الْمُسَمَّى، وَتَقَعُ بِهِ الْحُرْمَةُ كَمَا تَقَعُ بِالنِّكَاحِ الصَّحِيحِ، وَلَكِنْ لَا تَحِلُّ بِهِ الْمُطَلَّقَةُ ثَلَاثًا وَلَا يُحَصَّنُ بِهِ الزَّوْجَانِ."]]},{"id":"ri33_10","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٠","segs":[["matn","وَحَرَّمَ اللَّهُ سُبْحَانَهُ مِنَ النِّسَاءِ سَبْعًا بِالْقَرَابَةِ وَسَبْعًا بِالرَّضَاعِ وَالصِّهْرِ فَقَالَ: عَزَّ وَجَلَّ ﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالَاتُكُمْ وَبَنَاتُ الْأَخِ وَبَنَاتُ الْأُخْتِ﴾ فَهَؤُلَاءِ مِنَ الْقَرَابَةِ، وَاللَّوَاتِي مِنَ الرَّضَاعِ وَالصِّهْرِ قَوْلُهُ تَعَالَى:"]]},{"id":"ri33_11","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١١","segs":[["matn","﴿وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ وَأُمَّهَاتُ نِسَائِكُمْ وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ وَأَنْ تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ﴾ وَقَالَ:"]]},{"id":"ri33_12","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٢","segs":[["matn","تَعَالَى ﴿وَلَا تَنْكِحُوا مَا نَكَحَ آبَاؤُكُمْ مِنَ النِّسَاءِ﴾. وَحَرَّمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالرَّضَاعِ مَا يَحْرُمُ مِنَ النَّسَبِ، وَنَهَى أَنْ تُنْكَحَ الْمَرْأَةُ عَلَى عَمَّتِهَا أَوْ خَالَتِهَا."]]},{"id":"ri33_13","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٣","segs":[["matn","فَمَنْ نَكَحَ امْرَأَةً حَرُمَتْ بِالْعَقْدِ دُونَ أَنْ تُمَسَّ عَلَى آبَائِهِ وَأَبْنَائِهِ، وَحَرُمَتْ عَلَيْهِ أُمَّهَاتُهَا، وَلَا تَحْرُمُ عَلَيْهِ بَنَاتُهَا حَتَّى يَدْخُلَ بِالْأُمِّ، أَوْ يَتَلَذَّذَ بِهَا بِنِكَاحٍ أَوْ مِلْكِ يَمِينٍ أَوْ بِشُبْهَةٍ مِنْ نِكَاحٍ أَوْ مِلْكٍ، وَلَا يَحْرُمُ بِالزِّنَا حَلَالٌ."]]},{"id":"ri33_14","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٤","segs":[["matn","وَحَرَّمَ اللَّهُ سُبْحَانَهُ وَطْءَ الْكَوَافِرِ مِمَّنْ لَيْسَ مِنْ أَهْلِ الْكِتَابِ بِمِلْكٍ أَوْ نِكَاحٍ، وَيَحِلُّ وَطْءُ الْكِتَابِيَّاتِ بِالْمِلْكِ، وَيَحِلُّ وَطْءُ حَرَائِرِهِنَّ بِالنِّكَاحِ، وَلَا يَحِلُّ وَطْءُ إِمَائِهِنَّ بِالنِّكَاحِ لِحُرٍّ وَلَا لِعَبْدٍ."]]},{"id":"ri33_15","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٥","segs":[["matn","وَلَا تَتَزَوَّجُ الْمَرْأَةُ عَبْدَهَا وَلَا عَبْدَ وَلَدِهَا، وَلَا الرَّجُلُ أَمَتَهُ وَلَا أَمَةَ وَلَدِهِ، وَلَهُ أَنْ يَتَزَوَّجَ أَمَةَ وَالِدِهِ وَأَمَةَ أُمِّهِ."]]},{"id":"ri33_16","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٦","segs":[["matn","وَلَهُ أَنْ يَتَزَوَّجَ بِنْتَ امْرَأَةِ أَبِيهِ مِنْ رَجُلٍ غَيْرِهِ، وَتَتَزَوَّجُ الْمَرْأَةُ ابْنَ زَوْجَةِ أَبِيهَا مِنْ رَجُلٍ غَيْرِهِ."]]},{"id":"ri33_17","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٧","segs":[["matn","وَيَجُوزُ لِلْحُرِّ وَالْعَبْدِ نِكَاحُ أَرْبَعِ حَرَائِرَ مُسْلِمَاتٍ أَوْ كِتَابِيَّاتٍ، وَلِلْعَبْدِ نِكَاحُ أَرْبَعِ إِمَاءٍ مُسْلِمَاتٍ، وَلِلْحُرِّ ذَلِكَ إِنْ خَشِيَ الْعَنَتَ وَلَمْ يَجِدْ لِلْحَرَائِرِ طَوْلًا."]]},{"id":"ri33_18","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٨","segs":[["matn","وَلْيَعْدِلْ بَيْنَ نِسَائِهِ، وَعَلَيْهِ النَّفَقَةُ وَالسُّكْنَى بِقَدْرِ وُجْدِهِ، وَلَا قَسْمَ فِي الْمَبِيتِ لِأَمَتِهِ وَلَا لِأُمِّ وَلَدِهِ، وَلَا نَفَقَةَ لِلزَّوْجَةِ حَتَّى يَدْخُلَ بِهَا أَوْ يُدْعَى إِلَى الدُّخُولِ وَهِيَ مِمَّنْ يُوطَأُ مِثْلُهَا."]]},{"id":"ri33_19","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ١٩","segs":[["matn","وَنِكَاحُ التَّفْوِيضِ جَائِزٌ، وَهُوَ أَنْ يَعْقِدَاهُ وَلَا يَذْكُرَانِ صَدَاقًا، ثُمَّ لَا يَدْخُلُ بِهَا حَتَّى يَفْرِضَ لَهَا، فَإِنْ فَرَضَ لَهَا صَدَاقَ الْمِثْلِ لَزِمَهَا، وَإِنْ كَانَ أَقَلَّ فَهِيَ مُخَيَّرَةٌ، فَإِنْ كَرِهَتْهُ فُرِّقَ بَيْنَهُمَا إِلَّا أَنْ يُرْضِيَهَا، أَوْ يَفْرِضَ لَهَا صَدَاقَ مِثْلِهَا فَيَلْزَمُهَا."]]},{"id":"ri33_20","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٠","segs":[["matn","وَإِذَا ارْتَدَّ أَحَدُ الزَّوْجَيْنِ انْفَسَخَ النِّكَاحُ بِطَلَاقٍ، وَقَدْ قِيلَ: بِغَيْرِ طَلَاقٍ، وَإِذَا أَسْلَمَ الْكَافِرَانِ ثَبَتَا عَلَى نِكَاحِهِمَا، وَإِنْ أَسْلَمَ أَحَدُهُمَا فَذَلِكَ فَسْخٌ بِغَيْرِ طَلَاقٍ،"]]},{"id":"ri33_21","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢١","segs":[["matn","فَإِنْ أَسْلَمَتْ هِيَ كَانَ أَحَقَّ بِهَا إِنْ أَسْلَمَ فِي الْعِدَّةِ، وَإِنْ أَسْلَمَ هُوَ وَكَانَتْ كِتَابِيَّةً ثَبَتَ عَلَيْهَا، فَإِنْ كَانَتْ مَجُوسِيَّةً فَأَسْلَمَتْ بَعْدَهُ مَكَانَهَا كَانَا زَوْجَيْنِ، وَإِنْ تَأَخَّرَ ذَلِكَ فَقَدْ بَانَتْ مِنْهُ."]]},{"id":"ri33_22","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٢","segs":[["matn","وَإِذَا أَسْلَمَ مُشْرِكٌ وَعِنْدَهُ أَكْثَرُ مِنْ أَرْبَعٍ فَلْيَخْتَرْ أَرْبَعًا وَيُفَارِقْ بَاقِيَهُنَّ. وَمَنْ لَاعَنَ زَوْجَتَهُ لَمْ تَحِلَّ لَهُ أَبَدًا، وَكَذَلِكَ الَّذِي يَتَزَوَّجُ الْمَرْأَةَ فِي عِدَّتِهَا، وَيَطَؤُهَا فِي عِدَّتِهَا."]]},{"id":"ri33_23","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٣","segs":[["matn","وَلَا نِكَاحَ لِعَبْدٍ وَلَا لِأَمَةٍ إِلَّا أَنْ يَأْذَنَ السَّيِّدُ، وَلَا تَعْقِدُ امْرَأَةٌ وَلَا عَبْدٌ وَلَا مَنْ عَلَى غَيْرِ دِينِ الْإِسْلَامِ نِكَاحَ امْرَأَةٍ."]]},{"id":"ri33_24","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٤","segs":[["matn","وَلَا يَجُوزُ أَنْ يَتَزَوَّجَ الرَّجُلُ امْرَأَةً لِيُحِلَّهَا لِمَنْ طَلَّقَهَا ثَلَاثًا، وَلَا يُحِلُّهَا ذَلِكَ، وَلَا يَجُوزُ نِكَاحُ الْمُحْرِمِ لِنَفْسِهِ، وَلَا يَعْقِدُ نِكَاحًا لِغَيْرِهِ."]]},{"id":"ri33_25","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٥","segs":[["matn","وَلَا يَجُوزُ نِكَاحُ الْمَرِيضِ، وَيُفْسَخُ، وَإِنْ بَنَى بِهَا فَلَهَا الصَّدَاقُ فِي الثُّلُثِ مُبَدَّأً وَلَا مِيرَاثَ لَهَا، وَلَوْ طَلَّقَ الْمَرِيضُ امْرَأَتَهُ لَزِمَهُ ذَلِكَ، وَكَانَ لَهَا الْمِيرَاثُ مِنْهُ إِنْ مَاتَ فِي مَرَضِهِ ذَلِكَ."]]},{"id":"ri33_26","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٦","segs":[["matn","وَمَنْ طَلَّقَ امْرَأَتَهُ ثَلَاثًا لَمْ تَحِلَّ لَهُ بِمِلْكٍ وَلَا نِكَاحٍ حَتَّى تَنْكِحَ زَوْجًا غَيْرَهُ، وَطَلَاقُ الثَّلَاثِ فِي كَلِمَةٍ وَاحِدَةٍ بِدْعَةٌ، وَيَلْزَمُ إِنْ وَقَعَ."]]},{"id":"ri33_27","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٧","segs":[["matn","وَطَلَاقُ السُّنَّةِ مُبَاحٌ، وَهُوَ أَنْ يُطَلِّقَهَا فِي طُهْرٍ لَمْ يَقْرَبْهَا فِيهِ طَلْقَةً، ثُمَّ لَا يُتْبِعُهَا طَلَاقًا حَتَّى تَنْقَضِيَ الْعِدَّةُ."]]},{"id":"ri33_28","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٨","segs":[["matn","وَلَهُ الرَّجْعَةُ فِي الَّتِي تَحِيضُ مَا لَمْ تَدْخُلْ فِي الْحَيْضَةِ الثَّالِثَةِ فِي الْحُرَّةِ أَوِ الثَّانِيَةِ فِي الْأَمَةِ،"]]},{"id":"ri33_29","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٢٩","segs":[["matn","فَإِنْ كَانَتْ مِمَّنْ لَمْ تَحِضْ أَوْ مِمَّنْ قَدْ يَئِسَتْ مِنَ الْمَحِيضِ طَلَّقَهَا مَتَى شَاءَ، وَكَذَلِكَ الْحَامِلُ، وَتُرْتَجَعُ الْحَامِلُ مَا لَمْ تَضَعْ وَالْمُعْتَدَّةُ بِالشُّهُورِ مَا لَمْ تَنْقَضِ الْعِدَّةُ."]]},{"id":"ri33_30","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٠","segs":[["matn","وَالْأَقْرَاءُ هِيَ الْأَطْهَارُ، وَيُنْهَى أَنْ يُطَلِّقَ فِي الْحَيْضِ، فَإِنْ طَلَّقَ لَزِمَهُ، وَيُجْبَرُ عَلَى الرَّجْعَةِ مَا لَمْ تَنْقَضِ الْعِدَّةُ، وَالَّتِي لَمْ يَدْخُلْ بِهَا يُطَلِّقُهَا مَتَى شَاءَ، وَالْوَاحِدَةُ تُبِينُهَا، وَالثَّلَاثُ تُحَرِّمُهَا إِلَّا بَعْدَ زَوْجٍ."]]},{"id":"ri33_31","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣١","segs":[["matn","وَمَنْ قَالَ لِزَوْجَتِهِ: أَنْتِ طَالِقٌ فَهِيَ وَاحِدَةٌ حَتَّى يَنْوِيَ أَكْثَرَ مِنْ ذَلِكَ. وَالْخُلْعُ طَلْقَةٌ لَا رَجْعَةَ فِيهَا وَإِنْ لَمْ يُسَمِّ طَلَاقًا إِذَا أَعْطَتْهُ شَيْئًا فَخَلَعَهَا بِهِ مِنْ نَفْسِهِ."]]},{"id":"ri33_32","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٢","segs":[["matn","وَمَنْ قَالَ لِزَوْجَتِهِ: أَنْتِ طَالِقٌ أَلْبَتَّةَ، فَهِيَ ثَلَاثٌ؛ دَخَلَ بِهَا أَوْ لَمْ يَدْخُلْ، وَإِنْ قَالَ: بَرِيَّةٌ أَوْ خَلِيَّةٌ أَوْ حَرَامٌ أَوْ حَبْلُكِ عَلَى غَارِبِكِ فَهِيَ ثَلَاثٌ فِي الَّتِي دَخَلَ بِهَا، وَيُنَوَّى فِي الَّتِي لَمْ يَدْخُلْ بِهَا."]]},{"id":"ri33_33","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٣","segs":[["matn","وَالْمُطَلَّقَةُ قَبْلَ الْبِنَاءِ لَهَا نِصْفُ الصَّدَاقِ، إِلَّا أَنْ تَعْفُوَ عَنْهُ هِيَ إِنْ كَانَتْ ثَيِّبًا، وَإِنْ كَانَتْ بِكْرًا فَذَلِكَ إِلَى أَبِيهَا، وَكَذَلِكَ السَّيِّدُ فِي أَمَتِهِ."]]},{"id":"ri33_34","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٤","segs":[["matn","وَمَنْ طَلَّقَ فَيَنْبَغِي لَهُ أَنْ يُمَتِّعَ، وَلَا يُجْبَرُ، وَالَّتِي لَمْ يَدْخُلْ بِهَا وَقَدْ فَرَضَ لَهَا فَلَا مُتْعَةَ لَهَا، وَلَا لِلْمُخْتَلِعَةِ."]]},{"id":"ri33_35","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٥","segs":[["matn","وَإِنْ مَاتَ عَنِ الَّتِي لَمْ يَفْرِضْ لَهَا وَلَمْ يَبْنِ بِهَا فَلَهَا الْمِيرَاثُ، وَلَا صَدَاقَ لَهَا، وَلَوْ دَخَلَ بِهَا كَانَ لَهَا صَدَاقُ الْمِثْلِ إِنْ لَمْ تَكُنْ رَضِيَتْ بِشَيْءٍ مَعْلُومٍ."]]},{"id":"ri33_36","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٦","segs":[["matn","وَتُرَدُّ الْمَرْأَةُ مِنَ الْجُنُونِ وَالْجُذَامِ وَالْبَرَصِ وَدَاءِ الْفَرْجِ، فَإِنْ دَخَلَ بِهَا وَلَمْ يَعْلَمْ وَأَدَّى صَدَاقَهَا، وَرَجَعَ بِهِ عَلَى أَبِيهَا، وَكَذَلِكَ إِنْ زَوَّجَهَا أَخُوهَا،"]]},{"id":"ri33_37","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٧","segs":[["matn","وَإِنْ زَوَّجَهَا وَلِيٌّ لَيْسَ بِقَرِيبِ الْقَرَابَةِ فَلَا شَيْءَ عَلَيْهِ، وَلَا يَكُونُ لَهَا إِلَّا رُبُعُ دِينَارٍ، وَيُؤَخَّرُ الْمُعْتَرَضُ سَنَةً، فَإِنْ وَطِئَ وَإِلَّا فُرِّقَ بَيْنَهُمَا إِنْ شَاءَتْ."]]},{"id":"ri33_38","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٨","segs":[["matn","وَالْمَفْقُودُ يُضْرَبُ لَهُ أَجَلُ أَرْبَعِ سِنِينَ مِنْ يَوْمِ تَرْفَعُ ذَلِكَ وَيَنْتَهِي الْكَشْفُ عَنْهُ، ثُمَّ تَعْتَدُّ كَعِدَّةِ الْمَيِّتِ، ثُمَّ تَتَزَوَّجُ إِنْ شَاءَتْ، وَلَا يُوَرَثُ مَالُهُ حَتَّى يَأْتِيَ عَلَيْهِ مِنَ الزَّمَانِ مَا لَا يَعِيشُ إِلَى مِثْلِهِ."]]},{"id":"ri33_39","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٣٩","segs":[["matn","وَلَا تُخْطَبُ الْمَرْأَةُ فِي عِدَّتِهَا، وَلَا بَأْسَ بِالتَّعْرِيضِ بِالْقَوْلِ الْمَعْرُوفِ. وَمَنْ نَكَحَ بِكْرًا فَلَهُ أَنْ يُقِيمَ عِنْدَهَا سَبْعًا دُونَ سَائِرِ نِسَائِهِ، وَفِي الثَّيِّبِ ثَلَاثَةَ أَيَّامٍ."]]},{"id":"ri33_40","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٠","segs":[["matn","وَلَا يَجْمَعُ بَيْنَ الْأُخْتَيْنِ فِي مِلْكِ الْيَمِينِ فِي الْوَطْءِ، فَإِنْ شَاءَ وَطْءَ الْأُخْرَى فَلْيُحَرِّمْ عَلَيْهِ فَرْجَ الْأُولَى بِبَيْعٍ أَوْ كِتَابَةٍ أَوْ عِتْقٍ وَشِبْهِهِ،"]]},{"id":"ri33_41","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤١","segs":[["matn","مِمَّا تَحْرُمُ بِهِ وَمَنْ وَطِئَ أَمَةً بِمِلْكٍ لَمْ تَحِلَّ لَهُ أُمُّهَا وَلَا ابْنَتُهَا، وَتَحْرُمُ عَلَى آبَائِهِ وَأَبْنَائِهِ كَتَحْرِيمِ النِّكَاحِ. وَالطَّلَاقُ بِيَدِ الْعَبْدِ دُونَ السَّيِّدِ، وَلَا طَلَاقَ لِصَبِيٍّ."]]},{"id":"ri33_42","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٢","segs":[["matn","وَالْمُمَلَّكَةُ وَالْمُخَيَّرَةُ لَهُمَا أَنْ يَقْضِيَا مَا دَامَتَا فِي الْمَجْلِسِ، وَلَهُ أَنْ يُنَاكِرَ الْمُمَلَّكَةَ خَاصَّةً فِيمَا فَوْقَ الْوَاحِدَةِ، وَلَيْسَ لَهَا فِي التَّخْيِيرِ أَنْ تَقْضِيَ إِلَّا بِالثَّلَاثِ، ثُمَّ لَا نُكْرَةَ لَهُ فِيهَا."]]},{"id":"ri33_43","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٣","segs":[["matn","وَكُلُّ حَالِفٍ عَلَى تَرْكِ الْوَطْءِ أَكْثَرَ مِنْ أَرْبَعَةِ أَشْهُرٍ فَهُوَ مُولٍ، وَلَا يَقَعُ عَلَيْهِ الطَّلَاقُ إِلَّا بَعْدَ أَجَلِ الْإِيلَاءِ وَهُوَ أَرْبَعَةُ أَشْهُرٍ لِلْحُرِّ، وَشَهْرَانِ لِلْعَبْدِ حَتَّى يُوقِفَهُ السُّلْطَانُ."]]},{"id":"ri33_44","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٤","segs":[["matn","وَمَنْ تَظَاهَرَ مِنِ امْرَأَتِهِ فَلَا يَطَؤُهَا حَتَّى يُكَفِّرَ بِعِتْقِ رَقَبَةٍ مُؤْمِنَةٍ سَلِيمَةٍ مِنَ الْعُيُوبِ لَيْسَ فِيهَا شِرْكٌ وَلَا طَرَفٌ مِنْ حُرِّيَّةٍ، فَإِنْ لَمْ يَجِدْ صَامَ شَهْرَيْنِ مُتَتَابِعَيْنِ، فَإِنْ لَمْ يَسْتَطِعْ أَطْعَمَ سِتِّينَ مِسْكِينًا مُدَّيْنِ لِكُلِّ مِسْكِينٍ،"]]},{"id":"ri33_45","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٥","segs":[["matn","وَلَا يَطَؤُهَا فِي لَيْلٍ أَوْ نَهَارٍ حَتَّى تَنْقَضِيَ الْكَفَّارَةُ، فَإِنْ فَعَلَ ذَلِكَ فَلْيَتُبْ إِلَى اللَّهِ عَزَّ وَجَلَّ،"]]},{"id":"ri33_46","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٦","segs":[["matn","فَإِنْ كَانَ وَطْؤُهُ بَعْدَ أَنْ فَعَلَ بَعْضَ الْكَفَّارَةِ بِإِطْعَامٍ أَوْ صَوْمٍ فَلْيَبْتَدِئْهَا، وَلَا بَأْسَ بِعِتْقِ الْأَعْوَرِ فِي الظِّهَارِ وَوَلَدِ الزِّنَا، وَيُجْزِئُ الصَّغِيرُ، وَمَنْ صَلَّى وَصَامَ أَحَبُّ إِلَيْنَا."]]},{"id":"ri33_47","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٧","segs":[["matn","وَاللِّعَانُ بَيْنَ كُلِّ زَوْجَيْنِ فِي نَفْيِ حَمْلٍ يُدَّعَى قَبْلَهُ الِاسْتِبْرَاءُ أَوْ رُؤْيَةُ الزِّنَا كَالْمِرْوَدِ فِي الْمُكْحُلَةِ، وَاخْتُلِفَ فِي اللِّعَانِ فِي الْقَذْفِ،"]]},{"id":"ri33_48","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٨","segs":[["matn","وَإِذَا افْتَرَقَا بِاللِّعَانِ لَمْ يَتَنَاكَحَا أَبَدًا، وَيَبْدَأُ الزَّوْجُ فَيَلْتَعِنُ أَرْبَعَ شَهَادَاتٍ بِاللَّهِ ثُمَّ يُخَمِّسُ بِاللَّعْنَةِ، ثُمَّ تَلْتَعِنُ هِيَ أَرْبَعًا أَيْضًا، وَتُخَمِّسُ بِالْغَضَبِ كَمَا ذَكَرَ اللَّهُ سُبْحَانَهُ، وَتَعَالَى."]]},{"id":"ri33_49","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٤٩","segs":[["matn","وَإِنْ نَكَلَتْ هِيَ رُجِمَتْ إِنْ كَانَتْ حُرَّةً مُحْصَنَةً بِوَطْءٍ تَقَدَّمَ مِنْ هَذَا الزَّوْجِ أَوْ زَوْجٍ غَيْرِهِ، وَإِلَّا جُلِدَتْ مِائَةَ جَلْدَةٍ، وَإِنْ نَكَلَ الزَّوْجُ جُلِدَ حَدَّ الْقَذْفِ ثَمَانِينَ، وَلَحِقَ بِهِ الْوَلَدُ."]]},{"id":"ri33_50","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٥٠","segs":[["matn","وَلِلْمَرْأَةِ أَنْ تَفْتَدِيَ مِنْ زَوْجِهَا بِصَدَاقِهَا أَوْ أَقَلَّ أَوْ أَكْثَرَ إِذَا لَمْ يَكُنْ عَنْ ضَرَرٍ بِهَا، فَإِنْ كَانَ عَنْ ضَرَرٍ بِهَا رَجَعَتْ بِمَا أَعْطَتْهُ، وَلَزِمَهُ الْخُلْعُ، وَالْخُلْعُ طَلْقَةٌ لَا رَجْعَةَ فِيهَا، إِلَّا بِنِكَاحٍ جَدِيدٍ بِرِضَاهَا."]]},{"id":"ri33_51","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٥١","segs":[["matn","وَالْمُعْتَقَةُ تَحْتَ الْعَبْدِ لَهَا الْخِيَارُ أَنْ تُقِيمَ مَعَهُ أَوْ تُفَارِقَهُ، وَمَنِ اشْتَرَى زَوْجَتَهُ انْفَسَخَ نِكَاحُهُ، وَطَلَاقُ الْعَبْدِ طَلْقَتَانِ، وَعِدَّةُ الْأَمَةِ حَيْضَتَانِ، وَكَفَّارَاتُ الْعَبْدِ كَالْحُرِّ بِخِلَافِ مَعَانِي الْحُدُودِ وَالطَّلَاقِ."]]},{"id":"ri33_52","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٥٢","segs":[["matn","وَكُلُّ مَا وَصَلَ إِلَى جَوْفِ الرَّضِيعِ فِي الْحَوْلَيْنِ مِنَ اللَّبَنِ فَإِنَّهُ يُحَرِّمُ وَإِنْ مَصَّةً وَاحِدَةً، وَلَا يُحَرِّمُ مَا أُرْضِعَ بَعْدَ الْحَوْلَيْنِ إِلَّا مَا قَرُبَ مِنْهُمَا كَالشَّهْرِ وَنَحْوِهِ، وَقِيلَ: وَالشَّهْرَيْنِ،"]]},{"id":"ri33_53","label":"بَابٌ فِي النِّكَاحِ وَالطَّلَاقِ وَالرَّجْعَةِ وَالظِّهَارِ وَالْإِيلَاءِ وَاللِّعَانِ وَالْخُلْعِ وَالرَّضَاعِ · ٥٣","segs":[["matn","وَلَوْ فُصِلَ قَبْلَ الْحَوْلَيْنِ فِصَالًا اسْتَغْنَى فِيهِ بِالطَّعَامِ لَمْ يُحَرِّمْ مَا أُرْضِعَ بَعْدَ ذَلِكَ، وَيُحَرِّمُ بِالْوَجُورِ وَالسَّعُوطِ، وَمَنْ أَرْضَعَتْ صَبِيًّا فَبَنَاتُ تِلْكَ الْمَرْأَةِ وَبَنَاتُ فَحْلِهَا مَا تَقَدَّمَ أَوْ تَأَخَّرَ إِخْوَةٌ لَهُ، وَلِأَخِيهِ نِكَاحُ بَنَاتِهَا."]]}]},{"id":"ri34","title":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ","units":[{"id":"ri34_1","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١","segs":[["matn","وَعِدَّةُ الْحُرَّةِ الْمُطَلَّقَةِ ثَلَاثَةُ قُرُوءٍ كَانَتْ مُسْلِمَةً أَوْ كِتَابِيَّةً، وَالْأَمَةُ وَمَنْ فِيهَا بَقِيَّةُ رِقٍّ قُرْءَانِ؛"]]},{"id":"ri34_2","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ٢","segs":[["matn","كَانَ الزَّوْجُ فِي جَمِيعِهِنَّ حُرًّا أَوْ عَبْدًا، وَالْأَقْرَاءُ هِيَ الْأَطْهَارُ الَّتِي بَيْنَ الدَّمَيْنِ، فَإِنْ كَانَتْ مِمَّنْ لَمْ تَحِضْ أَوْ مِمَّنْ قَدْ يَئِسَتْ مِنَ الْمَحِيضِ فَثَلَاثَةُ أَشْهُرٍ فِي الْحُرَّةِ وَالْأَمَةِ، وَعِدَّةُ الْحُرَّةِ الْمُسْتَحَاضَةِ أَوِ الْأَمَةِ فِي الطَّلَاقِ سَنَةٌ."]]},{"id":"ri34_3","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ٣","segs":[["matn","وَعِدَّةُ الْحَامِلِ فِي وَفَاةٍ أَوْ طَلَاقٍ وَضْعُ حَمْلِهَا كَانَتْ حُرَّةً أَوْ أَمَةً، أَوْ كِتَابِيَّةً، وَالْمُطَلَّقَةُ الَّتِي لَمْ يُدْخَلْ بِهَا لَا عِدَّةَ عَلَيْهَا."]]},{"id":"ri34_4","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ٤","segs":[["matn","وَعِدَّةُ الْحُرَّةِ مِنَ الْوَفَاةِ أَرْبَعَةُ أَشْهُرٍ وَعَشْرٌ كَانَتْ صَغِيرَةً أَوْ كَبِيرَةً، دَخَلَ بِهَا أَوْ لَمْ يَدْخُلْ، مُسْلِمَةً كَانَتْ أَوْ كِتَابِيَّةً،"]]},{"id":"ri34_5","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ٥","segs":[["matn","وَفِي الْأَمَةِ وَمَنْ فِيهَا بَقِيَّةُ رِقٍّ شَهْرَانِ وَخَمْسُ لَيَالٍ مَا لَمْ تَرْتَبِ الْكَبِيرَةُ ذَاتُ الْحَيْضِ بِتَأْخِيرِهِ عَنْ وَقْتِهِ فَتَقْعُدُ حَتَّى تَذْهَبَ الرِّيبَةُ، وَأَمَّا الَّتِي لَا تَحِيضُ لِصِغَرٍ أَوْ كِبَرٍ وَقَدْ بُنِيَ بِهَا فَلَا تُنْكَحُ فِي الْوَفَاةِ إِلَّا بَعْدَ ثَلَاثَةِ أَشْهُرٍ."]]},{"id":"ri34_6","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ٦","segs":[["matn","وَالْإِحْدَادُ أَنْ لَا تَقْرَبَ الْمُعْتَدَّةُ مِنَ الْوَفَاةِ شَيْئًا مِنَ الزِّينَةِ بِحُلِيٍّ أَوْ كُحْلٍ أَوْ غَيْرِهِ، وَتَجْتَنِبَ الصِّبَاغَ كُلَّهُ إِلَّا الْأَسْوَدَ، وَتَجْتَنِبُ الطِّيبَ كُلَّهُ، وَلَا تَخْتَضِبُ بِحِنَّاءٍ، وَلَا تَقْرَبُ دُهْنًا مُطَيَّبًا، وَلَا تَمْتَشِطُ بِمَا يَخْتَمِرُ فِي رَأْسِهَا."]]},{"id":"ri34_7","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ٧","segs":[["matn","وَعَلَى الْأَمَةِ وَالْحُرَّةِ الصَّغِيرَةِ وَالْكَبِيرَةِ الْإِحْدَادُ. وَاخْتُلِفَ فِي الْكِتَابِيَّةِ."]]},{"id":"ri34_8","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ٨","segs":[["matn","وَلَيْسَ عَلَى الْمُطَلَّقَةِ إِحْدَادٌ، وَتُجْبَرُ الْحُرَّةُ الْكِتَابِيَّةُ عَلَى الْعِدَّةِ مِنَ الْمُسْلِمِ فِي الْوَفَاةِ وَالطَّلَاقِ، وَعِدَّةُ أُمِّ الْوَلَدِ مِنْ وَفَاةِ سَيِّدِهَا حَيْضَةٌ، وَكَذَلِكَ إِذَا أَعْتَقَهَا، فَإِنْ قَعَدَتْ عَنِ الْحَيْضِ فَثَلَاثَةُ أَشْهُرٍ."]]},{"id":"ri34_9","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ٩","segs":[["matn","وَاسْتِبْرَاءُ الْأَمَةِ فِي انْتِقَالِ الْمِلْكِ حَيْضَةٌ: انْتَقَلَ الْمِلْكُ بِبَيْعٍ أَوْ هِبَةٍ أَوْ سَبْيٍ أَوْ غَيْرِ ذَلِكَ، وَمَنْ هِيَ فِي حِيَازَتِهِ قَدْ حَاضَتْ عِنْدَهُ ثُمَّ إِنَّهُ اشْتَرَاهَا فَلَا اسْتِبْرَاءَ عَلَيْهَا إِنْ لَمْ تَكُنْ تَخْرُجُ،"]]},{"id":"ri34_10","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٠","segs":[["matn","وَاسْتِبْرَاءُ الصَّغِيرَةِ فِي الْبَيْعِ إِنْ كَانَتْ تُوطَأُ ثَلَاثَةُ أَشْهُرٍ وَالْيَائِسَةُ مِنَ الْمَحِيضِ ثَلَاثَةُ أَشْهُرٍ، وَالَّتِي لَا تُوطَأُ فَلَا اسْتِبْرَاءَ فِيهَا."]]},{"id":"ri34_11","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١١","segs":[["matn","وَمَنِ ابْتَاعَ حَامِلًا مِنْ غَيْرِهِ أَوْ مَلَكَهَا بِغَيْرِ الْبَيْعِ فَلَا يَقْرَبُهَا وَلَا يَتَلَذَّذُ مِنْهَا بِشَيْءٍ حَتَّى تَضَعَ."]]},{"id":"ri34_12","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٢","segs":[["matn","وَالسُّكْنَى لِكُلِّ مُطَلَّقَةٍ مَدْخُولٍ بِهَا، وَلَا نَفَقَةَ إِلَّا لِلَّتِي طَلُقَتْ دُونَ الثَّلَاثِ، وَلِلْحَامِلِ كَانَتْ مُطَلَّقَةً وَاحِدَةً أَوْ ثَلَاثًا، وَلَا نَفَقَةَ لِلْمُخْتَلِعَةِ إِلَّا فِي الْحَمْلِ، وَلَا نَفَقَةَ لِلْمُلَاعَنَةِ وَإِنْ كَانَتْ حَامِلًا، وَلَا نَفَقَةَ لِكُلِّ مُعْتَدَّةٍ مِنْ وَفَاةٍ،"]]},{"id":"ri34_13","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٣","segs":[["matn","وَلَهَا السُّكْنَى إِنْ كَانَتِ الدَّارُ لِلْمَيِّتِ أَوْ قَدْ نَقَدَ كِرَاءَهَا، وَلَا تَخْرُجُ مِنْ بَيْتِهَا فِي طَلَاقٍ أَوْ وَفَاةٍ حَتَّى تُتِمَّ الْعِدَّةَ،"]]},{"id":"ri34_14","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٤","segs":[["matn","إِلَّا أَنْ يُخْرِجَهَا رَبُّ الدَّارِ، وَلَمْ يَقْبَلْ مِنَ الْكِرَاءِ مَا يُشْبِهُ فَلْتَخْرُجْ، وَتُقِيمُ بِالْمَوْضِعِ الَّذِي تَنْتَقِلُ إِلَيْهِ حَتَّى تَنْقَضِيَ الْعِدَّةُ."]]},{"id":"ri34_15","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٥","segs":[["matn","وَالْمَرْأَةُ تُرْضِعُ وَلَدَهَا فِي الْعِصْمَةِ إِلَّا أَنْ يَكُونَ مِثْلُهَا لَا يُرْضِعُ، وَلِلْمُطَلَّقَةِ رَضَاعُ وَلَدِهَا عَلَى أَبِيهِ، وَلَهَا أَنْ تَأْخُذَ أُجْرَةَ رَضَاعِهَا إِنْ شَاءَتْ."]]},{"id":"ri34_16","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٦","segs":[["matn","وَالْحَضَانَةُ لِلْأُمِّ بَعْدَ الطَّلَاقِ إِلَى احْتِلَامِ الذَّكَرِ وَنِكَاحِ الْأُنْثَى وَدُخُولِهَا، وَذَلِكَ بَعْدَ الْأُمِّ إِنْ مَاتَتْ أَوْ نُكِحَتْ لِلْجَدَّةِ ثُمَّ لِلْخَالَةِ، فَإِنْ لَمْ يَكُنْ مِنْ ذَوِي رَحِمِ الْأُمِّ أَحَدٌ فَالْأَخَوَاتُ وَالْعَمَّاتُ، فَإِنْ لَمْ يَكُونُوا فَالْعَصَبَةُ."]]},{"id":"ri34_17","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٧","segs":[["matn","وَلَا يَلْزَمُ الرَّجُلَ النَّفَقَةُ إِلَّا عَلَى زَوْجَتِهِ كَانَتْ غَنِيَّةً أَوْ فَقِيرَةً، وَعَلَى أَبَوَيْهِ الْفَقِيرَيْنِ، وَعَلَى صِغَارِ وَلَدِهِ الَّذِينَ لَا مَالَ لَهُمْ: عَلَى الذُّكُورِ حَتَّى يَحْتَلِمُوا وَلَا زَمَانَةَ بِهِمْ،"]]},{"id":"ri34_18","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٨","segs":[["matn","وَعَلَى الْإِنَاثِ حَتَّى يَنْكِحْنَ، وَيَدْخُلَ بِهِنَّ أَزْوَاجُهُنَّ، وَلَا نَفَقَةَ لِمَنْ سِوَى هَؤُلَاءِ مِنَ الْأَقَارِبِ، وَإِنِ اتَّسَعَ فَعَلَيْهِ إِخْدَامُ زَوْجَتِهِ، وَعَلَيْهِ أَنْ يُنْفِقَ عَلَى عَبِيدِهِ وَيُكَفِّنَهُمْ إِذَا مَاتُوا."]]},{"id":"ri34_19","label":"بَابٌ فِي الْعِدَّةِ وَالنَّفَقَةِ وَالِاسْتِبْرَاءِ · ١٩","segs":[["matn","وَاخْتُلِفَ فِي كَفَنِ الزَّوْجَةِ فَقَالَ ابْنُ الْقَاسِمِ: فِي مَالِهَا، وَقَالَ عَبْدُ الْمَلِكِ: فِي مَالِ الزَّوْجِ، وَقَالَ سَحْنُونٌ: إِنْ كَانَتْ مَلِيَّةً فَفِي مَالِهَا، وَإِنْ كَانَتْ فَقِيرَةً فَفِي مَالِ الزَّوْجِ."]]}]},{"id":"ri35","title":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ","units":[{"id":"ri35_1","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١","segs":[["matn","﴿وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا﴾، وَكَانَ رِبَا الْجَاهِلِيَّةِ فِي الدُّيُونِ إِمَّا أَنْ يَقْضِيَهُ، وَإِمَّا أَنْ يُرْبَى لَهُ فِيهِ."]]},{"id":"ri35_2","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢","segs":[["matn","وَمِنَ الرِّبَا فِي غَيْرِ النَّسِيئَةِ بَيْعُ الْفِضَّةِ بِالْفِضَّةِ يَدًا بِيَدٍ مُتَفَاضِلًا، وَكَذَلِكَ الذَّهَبُ بِالذَّهَبِ، وَلَا يَجُوزُ فِضَّةٌ بِفِضَّةٍ وَلَا ذَهَبٌ بِذَهَبٍ إِلَّا مِثْلًا بِمِثْلٍ يَدًا بِيَدٍ، وَالْفِضَّةُ بِالذَّهَبِ رِبًا إِلَّا يَدًا بِيَدٍ."]]},{"id":"ri35_3","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣","segs":[["matn","وَالطَّعَامُ مِنَ الْحُبُوبِ وَالْقُطْنِيَّةِ وَشَبَهِهَا مِمَّا يُدَّخَرُ مِنْ قُوتٍ أَوْ إِدَامٍ لَا يَجُوزُ الْجِنْسُ مِنْهُ بِجِنْسِهِ إِلَّا مِثْلًا بِمِثْلٍ يَدًا بِيَدٍ،"]]},{"id":"ri35_4","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤","segs":[["matn","وَلَا يَجُوزُ فِيهِ تَأْخِيرٌ، وَلَا يَجُوزُ طَعَامٌ بِطَعَامٍ إِلَى أَجَلٍ كَانَ مِنْ جِنْسِهِ أَوْ مِنْ خِلَافِهِ، كَانَ مِمَّا يُدَّخَرُ أَوْ لَا يُدَّخَرُ."]]},{"id":"ri35_5","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥","segs":[["matn","وَلَا بَأْسَ بِالْفَوَاكِهِ وَالْبُقُولِ وَمَا لَا يُدَّخَرُ مُتَفَاضِلًا وَإِنْ كَانَ مِنْ جِنْسٍ وَاحِدٍ يَدًا بِيَدٍ، وَلَا يَجُوزُ التَّفَاضُلُ فِي الْجِنْسِ الْوَاحِدِ فِيمَا يُدَّخَرُ مِنَ الْفَوَاكِهِ الْيَابِسَةِ وَسَائِرِ الْإِدَامِ وَالطَّعَامِ وَالشَّرَابِ إِلَّا الْمَاءَ وَحْدَهُ،"]]},{"id":"ri35_6","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٦","segs":[["matn","وَمَا اخْتَلَفَتْ أَجْنَاسُهُ مِنْ ذَلِكَ وَمِنْ سَائِرِ الْحُبُوبِ وَالثِّمَارِ وَالطَّعَامِ فَلَا بَأْسَ بِالتَّفَاضُلِ فِيهِ يَدًا بِيَدٍ، وَلَا يَجُوزُ التَّفَاضُلُ فِي الْجِنْسِ الْوَاحِدِ مِنْهُ إِلَّا فِي الْخُضَرِ وَالْفَوَاكِهِ."]]},{"id":"ri35_7","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٧","segs":[["matn","وَالْقَمْحُ وَالشَّعِيرُ وَالسُّلْتُ كَجِنْسٍ وَاحِدٍ فِيمَا يَحِلُّ مِنْهُ وَيَحْرُمُ، وَالزَّبِيبُ كُلُّهُ صِنْفٌ وَالتَّمْرُ كُلُّهُ صِنْفٌ وَالْقُطْنِيَّةُ أَصْنَافٌ فِي الْبُيُوعِ، وَاخْتَلَفَ فِيهَا قَوْلُ مَالِكٍ، وَلَمْ يَخْتَلِفْ قَوْلُهُ فِي الزَّكَاةِ أَنَّهَا صِنْفٌ وَاحِدٌ."]]},{"id":"ri35_8","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٨","segs":[["matn","وَلُحُومُ ذَوَاتِ الْأَرْبَعِ مِنَ الْأَنْعَامِ وَالْوَحْشِ صِنْفٌ، وَلُحُومُ الطَّيْرِ كُلُّهُ صِنْفٌ، وَلُحُومُ دَوَابِّ الْمَاءِ كُلُّهَا صِنْفٌ، وَمَا تَوَلَّدَ مِنْ لُحُومِ الْجِنْسِ الْوَاحِدِ مِنْ شَحْمٍ فَهُوَ كَلَحْمِهِ، وَأَلْبَانُ ذَلِكَ الصِّنْفِ وَجُبْنُهُ وَسَمْنُهُ صِنْفٌ."]]},{"id":"ri35_9","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٩","segs":[["matn","وَمَنِ ابْتَاعَ طَعَامًا فَلَا يَجُوزُ بَيْعُهُ قَبْلَ أَنْ يَسْتَوْفِيَهُ إِذَا كَانَ شِرَاؤُهُ ذَلِكَ عَلَى وَزْنٍ أَوْ كَيْلٍ أَوْ عَدَدٍ بِخِلَافِ الْجُزَافِ، وَكَذَلِكَ كُلُّ طَعَامٍ أَوْ إِدَامٍ أَوْ شَرَابٍ إِلَّا الْمَاءَ وَحْدَهُ."]]},{"id":"ri35_10","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٠","segs":[["matn","وَمَا يَكُونُ مِنَ الْأَدْوِيَةِ وَالزَّرَارِيعِ الَّتِي لَا يُعْتَصَرُ مِنْهَا زَيْتٌ فَلَا يَدْخُلُ ذَلِكَ فِيمَا يَحْرُمُ مِنْ بَيْعِ الطَّعَامِ قَبْلَ قَبْضِهِ أَوِ التَّفَاضُلِ فِي الْجِنْسِ الْوَاحِدِ مِنْهُ."]]},{"id":"ri35_11","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١١","segs":[["matn","وَلَا بَأْسَ بِبَيْعِ الطَّعَامِ الْقَرْضِ قَبْلَ أَنْ يَسْتَوْفِيَهُ وَلَا بَأْسَ بِالشَّرِكَةِ وَالتَّوْلِيَةِ وَالْإِقَالَةِ فِي الطَّعَامِ الْمَكِيلِ قَبْلَ قَبْضِهِ."]]},{"id":"ri35_12","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٢","segs":[["matn","وَكُلُّ عَقْدِ بَيْعٍ أَوْ إِجَارَةٍ أَوْ كِرَاءٍ بِخَطَرٍ أَوْ غَرَرٍ فِي ثَمَنٍ أَوْ مَثْمُونٍ أَوْ أَجَلٍ فَلَا يَجُوزُ، وَلَا يَجُوزُ بَيْعُ الْغَرَرِ وَلَا بَيْعُ شَيْءٍ مَجْهُولٍ وَلَا إِلَى أَجَلٍ مَجْهُولٍ."]]},{"id":"ri35_13","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٣","segs":[["matn","وَلَا يَجُوزُ فِي الْبُيُوعِ التَّدْلِيسُ وَلَا الْغِشُّ وَلَا الْخِلَابَةُ وَلَا الْخَدِيعَةُ وَلَا كِتْمَانُ الْعُيُوبِ وَلَا خَلْطُ دَنِيءٍ بِجَيِّدٍ، وَلَا أَنْ يَكْتُمَ مِنْ أَمْرِ سِلْعَتِهِ مَا إِذَا ذَكَرَهُ كَرِهَهُ الْمُبْتَاعُ أَوْ كَانَ ذِكْرُهُ أَبْخَسَ لَهُ فِي الثَّمَنِ."]]},{"id":"ri35_14","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٤","segs":[["matn","وَمَنِ ابْتَاعَ عَبْدًا فَوَجَدَ بِهِ عَيْبًا فَلَهُ أَنْ يَحْبِسَهُ وَلَا شَيْءَ لَهُ، أَوْ يَرُدَّهُ وَيَأْخُذَ ثَمَنَهُ،"]]},{"id":"ri35_15","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٥","segs":[["matn","إِلَّا أَنْ يَدْخُلَهُ عِنْدَهُ عَيْبٌ مُفْسِدٌ فَلَهُ أَنْ يَرْجِعَ بِقِيمَةِ الْعَيْبِ الْقَدِيمِ مِنَ الثَّمَنِ، أَوْ يَرُدَّهُ وَيَرُدَّ مَا نَقَصَهُ الْعَيْبُ عِنْدَهُ، وَإِنْ رَدَّ عَبْدًا بِعَيْبٍ وَقَدِ اسْتَغَلَّهُ فَلَهُ غَلَّتُهُ."]]},{"id":"ri35_16","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٦","segs":[["matn","وَالْبَيْعُ عَلَى الْخِيَارِ جَائِزٌ إِذَا ضَرَبَا لِذَلِكَ أَجَلًا قَرِيبًا إِلَى مَا تُخْتَبَرُ فِيهِ تِلْكَ السِّلْعَةُ أَوْ مَا تَكُونُ فِيهِ الْمَشُورَةُ، وَلَا يَجُوزُ النَّقْدُ فِي الْخِيَارِ وَلَا فِي عُهْدَةِ الثَّلَاثِ وَلَا فِي الْمُوَاضَعَةِ بِشَرْطٍ، وَالنَّفَقَةُ فِي ذَلِكَ وَالضَّمَانُ عَلَى الْبَائِعِ."]]},{"id":"ri35_17","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٧","segs":[["matn","وَإِنَّمَا يُتَوَاضَعُ لِلِاسْتِبْرَاءِ الْجَارِيَةُ الَّتِي لِلْفِرَاشِ فِي الْأَغْلَبِ أَوِ الَّتِي أَقَرَّ الْبَائِعُ بِوَطْئِهَا وَإِنْ كَانَتْ وَخْشًا، وَلَا تَجُوزُ الْبَرَاءَةُ مِنَ الْحَمْلِ إِلَّا حَمْلًا ظَاهِرًا."]]},{"id":"ri35_18","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٨","segs":[["matn","وَالْبَرَاءَةُ فِي الرَّقِيقِ جَائِزَةٌ مِمَّا لَمْ يَعْلَمِ الْبَائِعُ، وَلَا يُفَرَّقُ بَيْنَ الْأُمِّ وَوَلَدِهَا فِي الْبَيْعِ حَتَّى يُثْغِرَ."]]},{"id":"ri35_19","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ١٩","segs":[["matn","وَكُلُّ بَيْعٍ فَاسِدٍ فَضَمَانُهُ مِنَ الْبَائِعِ، فَإِنْ قَبَضَهُ الْمُبْتَاعُ فَضَمَانُهُ مِنَ الْمُبْتَاعِ مِنْ يَوْمِ قَبْضِهِ،"]]},{"id":"ri35_20","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٠","segs":[["matn","فَإِنْ حَالَ سُوقُهُ أَوْ تَغَيَّرَ فِي بَدَنِهِ فَعَلَيْهِ قِيمَتُهُ يَوْمَ قَبْضِهِ وَلَا يَرُدُّهُ، وَإِنْ كَانَ مِمَّا يُوزَنُ أَوْ يُكَالُ فَلْيَرُدَّ مِثْلَهُ، وَلَا يُفِيتُ الرِّبَاعُ حَوَالَةَ الْأَسْوَاقِ."]]},{"id":"ri35_21","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢١","segs":[["matn","وَلَا يَجُوزُ سَلَفٌ يَجُرُّ مَنْفَعَةً، وَلَا يَجُوزُ بَيْعٌ وَسَلَفٌ، وَكَذَلِكَ مَا قَارَنَ السَّلَفَ مِنْ إِجَارَةٍ أَوْ كِرَاءٍ، وَالسَّلَفُ جَائِزٌ فِي كُلِّ شَيْءٍ إِلَّا فِي الْجَوَارِي."]]},{"id":"ri35_22","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٢","segs":[["matn","وَكَذَلِكَ تُرَابُ الْفِضَّةِ وَلَا تَجُوزُ الْوَضِيعَةُ مِنَ الدَّيْنِ عَلَى تَعْجِيلِهِ، وَلَا التَّأْخِيرُ بِهِ عَلَى الزِّيَادَةِ فِيهِ، وَلَا تَعْجِيلُ عَرْضٍ عَلَى الزِّيَادَةِ فِيهِ إِذَا كَانَ مِنْ بَيْعٍ، وَلَا بَأْسَ بِتَعْجِيلِهِ ذَلِكَ مِنْ قَرْضٍ إِذَا كَانَتِ الزِّيَادَةُ فِي الصِّفَةِ،"]]},{"id":"ri35_23","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٣","segs":[["matn","وَمَنْ رَدَّ فِي الْقَرْضِ أَكْثَرَ عَدَدًا فِي مَجْلِسِ الْقَضَاءِ فَقَدِ اخْتُلِفَ فِي ذَلِكَ إِذَا لَمْ يَكُنْ فِيهِ شَرْطٌ وَلَا وَأْيٌ وَلَا عَادَةٌ، فَأَجَازَهُ أَشْهَبُ، وَكَرِهَهُ ابْنُ الْقَاسِمِ وَلَمْ يُجِزْهُ."]]},{"id":"ri35_24","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٤","segs":[["matn","وَمَنْ عَلَيْهِ دَنَانِيرُ أَوْ دَرَاهِمُ مِنْ بَيْعٍ أَوْ قَرْضٍ مُؤَجَّلٍ فَلَهُ أَنْ يُعَجِّلَهُ قَبْلَ أَجَلِهِ، وَكَذَلِكَ لَهُ أَنْ يُعَجِّلَ الْعُرُوضَ وَالطَّعَامَ مِنْ قَرْضٍ لَا مِنْ بَيْعٍ."]]},{"id":"ri35_25","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٥","segs":[["matn","وَلَا يَجُوزُ بَيْعُ ثَمَرٍ أَوْ حَبٍّ لَمْ يَبْدُ صَلَاحُهُ، وَيَجُوزُ بَيْعُهُ إِذَا بَدَا صَلَاحُ بَعْضِهِ، وَإِنْ نَخْلَةً مِنْ نَخِيلٍ كَثِيرَةٍ."]]},{"id":"ri35_26","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٦","segs":[["matn","وَلَا يَجُوزُ بَيْعُ مَا فِي الْأَنْهَارِ وَالْبِرَكِ مِنَ الْحِيتَانِ، وَلَا بَيْعُ الْجَنِينِ فِي بَطْنِ أُمِّهِ، وَلَا بَيْعُ مَا فِي بُطُونِ سَائِرِ الْحَيَوَانَاتِ، وَلَا بَيْعُ نِتَاجِ مَا تُنْتَجُ النَّاقَةُ، وَلَا بَيْعُ مَا فِي ظُهُورِ الْإِبِلِ، وَلَا بَيْعُ الْآبِقِ وَالْبَعِيرِ الشَّارِدِ."]]},{"id":"ri35_27","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٧","segs":[["matn","وَنُهِيَ عَنْ بَيْعِ الْكِلَابِ، وَاخْتُلِفَ فِي بَيْعِ مَا أُذِنَ فِي اتِّخَاذِهِ مِنْهَا، وَأَمَّا مَنْ قَتَلَهُ فَعَلَيْهِ قِيمَتُهُ. وَلَا يَجُوزُ بَيْعُ اللَّحْمِ بِالْحَيَوَانِ مِنْ جِنْسِهِ، وَلَا بَيْعَتَانِ فِي بَيْعَةٍ؛"]]},{"id":"ri35_28","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٨","segs":[["matn","وَذَلِكَ أَنْ يَشْتَرِيَ سِلْعَةً إِمَّا بِخَمْسَةٍ نَقْدًا أَوْ عَشَرَةٍ إِلَى أَجَلٍ قَدْ لَزِمَتْهُ بِأَحَدِ الثَّمَنَيْنِ، وَلَا يَجُوزُ بَيْعُ التَّمْرِ بِالرُّطَبِ وَلَا الزَّبِيبِ بِالْعِنَبِ لَا مُتَفَاضِلًا وَلَا مِثْلًا بِمِثْلٍ، وَلَا رَطْبٍ بِيَابِسٍ مِنْ جِنْسِهِ مِنْ سَائِرِ الثِّمَارِ وَالْفَوَاكِهِ،"]]},{"id":"ri35_29","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٢٩","segs":[["matn","وَهُوَ مِمَّا نُهِيَ عَنْهُ مِنَ الْمُزَابَنَةِ، وَلَا يُبَاعُ جُزَافٌ بِمَكِيلٍ مِنْ صِنْفِهِ وَلَا جُزَافٌ بِجُزَافٍ مِنْ صِنْفِهِ إِلَّا أَنْ يَتَبَيَّنَ الْفَضْلُ بَيْنَهُمَا إِنْ كَانَ مِمَّا يَجُوزُ التَّفَاضُلُ فِي الْجِنْسِ الْوَاحِدِ مِنْهُ."]]},{"id":"ri35_30","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٠","segs":[["matn","وَلَا بَأْسَ بِبَيْعِ الشَّيْءِ الْغَائِبِ عَلَى الصِّفَةِ، وَلَا يُنْقَدُ فِيهِ بِشَرْطٍ، إِلَّا أَنْ يَقْرُبَ مَكَانُهُ، أَوْ يَكُونَ مِمَّا يُؤْمَنُ تَغَيُّرُهُ مِنْ دَارٍ أَوْ أَرْضٍ أَوْ شَجَرٍ فَيَجُوزُ النَّقْدُ فِيهِ."]]},{"id":"ri35_31","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣١","segs":[["matn","وَالْعُهْدَةُ جَائِزَةٌ فِي الرَّقِيقِ إِنِ اشْتُرِطَتْ أَوْ كَانَتْ جَارِيَةً بِالْبَلَدِ فَعُهْدَةُ الثَّلَاثِ الضَّمَانُ فِيهَا مِنَ الْبَائِعِ مِنْ كُلِّ شَيْءٍ، وَعُهْدَةُ السَّنَةِ مِنَ الْجُنُونِ وَالْجُذَامِ وَالْبَرَصِ."]]},{"id":"ri35_32","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٢","segs":[["matn","وَلَا بَأْسَ بِالسَّلَمِ فِي الْعُرُوضِ وَالرَّقِيقِ وَالْحَيَوَانِ وَالطَّعَامِ وَالْإِدَامِ بِصِفَةٍ مَعْلُومَةٍ وَأَجَلٍ مَعْلُومٍ وَيُعَجِّلُ رَأْسَ الْمَالِ، أَوْ يُؤَخِّرُهُ إَلَى مِثْلِ يَوْمَيْنِ أَوْ ثَلَاثَةٍ وَإِنْ كَانَ بِشَرْطٍ، وَأَجَلُ السَّلَمِ أَحَبُّ إِلَيْنَا أَنْ يَكُونَ خَمْسَةَ عَشَرَ يَوْمًا،"]]},{"id":"ri35_33","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٣","segs":[["matn","أَوْ عَلَى أَنْ يُقْبَضَ بِبَلَدٍ آخَرَ وَإِنْ كَانَتْ مَسَافَتُهُ يَوْمَيْنِ أَوْ ثَلَاثَةً، وَمَنْ أَسْلَمَ إِلَى ثَلَاثَةِ أَيَّامٍ يَقْبِضُهُ بِبَلَدٍ أَسْلَمَ فِيهِ فَقَدْ أَجَازَهُ غَيْرُ وَاحِدٍ مِنَ الْعُلَمَاءِ، وَكَرِهَهُ آخَرُونَ."]]},{"id":"ri35_34","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٤","segs":[["matn","وَلَا يَجُوزُ أَنْ يَكُونَ رَأْسُ الْمَالِ مِنْ جِنْسِ مَا أَسْلَمَ فِيهِ، وَلَا يُسْلَمُ شَيْءٌ فِي جِنْسِهِ، أَوْ فِيمَا يَقْرُبُ مِنْهُ، إِلَّا أَنْ يُقْرِضَهُ شَيْئًا فِي مِثْلِهِ صِفَةً وَمِقْدَارًا، وَالنَّفْعُ لِلْمُتَسَلِّفِ."]]},{"id":"ri35_35","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٥","segs":[["matn","وَلَا يَجُوزُ دَيْنٌ بِدَيْنٍ، وَتَأْخِيرُ رَأْسِ الْمَالِ بِشَرْطٍ إِلَى مَحَلِّ السَّلَمِ أَوْ مَا بَعُدَ مِنَ الْعُقْدَةِ مِنْ ذَلِكَ، وَلَا يَجُوزُ فَسْخُ دَيْنٍ فِي دَيْنٍ،"]]},{"id":"ri35_36","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٦","segs":[["matn","وَهُوَ أَنْ يَكُونَ لَكَ شَيْءٌ فِي ذِمَّتِهِ، فَتَفْسَخَهُ فِي شَيْءٍ آخَرَ لَا تَتَعَجَّلُهُ، وَلَا يَجُوزُ بَيْعُ مَا لَيْسَ عِنْدَكَ عَلَى أَنْ يَكُونَ عَلَيْكَ حَالًّا."]]},{"id":"ri35_37","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٧","segs":[["matn","وَإِذَا بِعْتَ سِلْعَةً بِثَمَنٍ مُؤَجَّلٍ فَلَا تَشْتَرِهَا بِأَقَلَّ مِنْهُ نَقْدًا أَوْ إِلَى أَجَلٍ دُونَ الْأَجَلِ، الْأَوَّلِ وَلَا بِأَكْثَرَ مِنْهُ إِلَى أَبْعَدَ مِنْ أَجَلِهِ، وَأَمَّا إِلَى الْأَجَلِ نَفْسِهِ فَذَلِكَ كُلُّهُ جَائِزٌ، وَتَكُونُ مُقَاصَّةً."]]},{"id":"ri35_38","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٨","segs":[["matn","وَلَا بَأْسَ بِشِرَاءِ الْجُزَافِ فِيمَا يُكَالُ أَوْ يُوزَنُ سِوَى الدَّنَانِيرِ وَالدَّرَاهِمِ مَا كَانَ مَسْكُوكًا، وَأَمَّا نِقَارُ الذَّهَبِ وَالْفِضَّةِ فَذَلِكَ فِيهِمَا جَائِزٌ، وَلَا يَجُوزُ شِرَاءُ الرَّقِيقِ وَالثِّيَابِ جُزَافًا وَلَا مَا يُمْكِنُ عَدَدُهُ بِلَا مَشَقَّةٍ جُزَافًا."]]},{"id":"ri35_39","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٣٩","segs":[["matn","وَمَنْ بَاعَ نَخْلًا قَدْ أُبِّرَتْ فَثَمَرُهَا لِلْبَائِعِ إِلَّا أَنْ يَشْتَرِطَهُ الْمُبْتَاعُ، وَكَذَلِكَ غَيْرُهَا مِنَ الثِّمَارِ، وَالْإِبَارُ التَّذْكِيرُ، وَإِبَارُ الزَّرْعِ خُرُوجُهُ مِنَ الْأَرْضِ."]]},{"id":"ri35_40","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٠","segs":[["matn","وَمَنْ بَاعَ عَبْدًا وَلَهُ مَالٌ فَمَالُهُ لِلْبَائِعِ، إِلَّا أَنْ يَشْتَرِطَهُ الْمُبْتَاعُ."]]},{"id":"ri35_41","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤١","segs":[["matn","وَلَا بَأْسَ بِشِرَاءِ مَا فِي الْعِدْلِ عَلَى الْبَرْنَامَجِ بِصِفَةٍ مَعْلُومَةٍ، وَلَا يَجُوزُ شِرَاءُ ثَوْبٍ لَا يُنْشَرُ وَلَا يُوصَفُ، أَوْ فِي لَيْلٍ مُظْلِمٍ لَا يَتَأَمَّلَانِهِ وَلَا يَعْرِفَانِ مَا فِيهِ، وَكَذَلِكَ الدَّابَّةُ فِي لَيْلٍ مُظْلِمٍ."]]},{"id":"ri35_42","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٢","segs":[["matn","وَلَا يَسُومُ أَحَدٌ عَلَى سَوْمِ أَخِيهِ وَذَلِكَ إِذَا رَكَنَا وَتَقَارَبَا لَا فِي أَوَّلِ التَّسَاوُمِ، وَالْبَيْعُ يَنْعَقِدُ بِالْكَلَامِ وَإِنْ لَمْ يَفْتَرِقِ الْمُتَبَايِعَانِ. وَالْإِجَارَةُ جَائِزَةٌ إِذَا ضَرَبَا لَهَا أَجَلًا، وَسَمَّيَا الثَّمَنَ."]]},{"id":"ri35_43","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٣","segs":[["matn","وَلَا يُضْرَبُ فِي الْجُعْلِ أَجَلٌ فِي رَدِّ آبِقٍ أَوْ بَعِيرٍ شَارِدٍ أَوْ حَفْرِ بِئْرٍ أَوْ بَيْعِ ثَوْبٍ وَنَحْوِهِ، وَلَا شَيْءَ لَهُ إِلَّا بِتَمَامِ الْعَمَلِ،"]]},{"id":"ri35_44","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٤","segs":[["matn","وَالْأَجِيرُ عَلَى الْبَيْعِ إِذَا تَمَّ الْأَجَلُ وَلَمْ يَبِعْ وَجَبَ لَهُ جَمِيعُ الْأَجْرِ، وَإِنْ بَاعَ فِي نِصْفِ الْأَجَلِ فَلَهُ نِصْفُ الْإِجَارَةِ."]]},{"id":"ri35_45","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٥","segs":[["matn","وَالْكِرَاءُ كَالْبَيْعِ فِيمَا يَحِلُّ وَيَحْرُمُ، وَمَنِ اكْتَرَى دَابَّةً بِعَيْنِهَا إِلَى بَلَدٍ فَمَاتَتِ انْفَسَخَ الْكِرَاءُ فِيمَا بَقِيَ، وَكَذَلِكَ الْأَجِيرُ يَمُوتُ، وَالدَّارُ تَنْهَدِمُ قَبْلَ تَمَامِ مُدَّةِ الْكِرَاءِ."]]},{"id":"ri35_46","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٦","segs":[["matn","وَلَا بَأْسَ بِتَعْلِيمِ الْمُعَلِّمِ الْقُرْآنَ عَلَى الْحِذَاقِ، وَمُشَارَطَةِ الطَّبِيبِ عَلَى الْبُرْءِ وَلَا يُنْتَقَضُ الْكِرَاءُ بِمَوْتِ الرَّاكِبِ أَوِ السَّاكِنِ وَلَا بِمَوْتِ غَنَمِ الرِّعَايَةِ، وَلْيَأْتِ بِمِثْلِهَا، وَمَنِ اكْتَرَى كِرَاءً مَضْمُونًا فَمَاتَتِ الدَّابَّةُ فَلْيَأْتِ بِغَيْرِهَا،"]]},{"id":"ri35_47","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٧","segs":[["matn","وَإِنْ مَاتَ الرَّاكِبُ لَمْ يَنْفَسِخِ الْكِرَاءُ، وَلْيَكْتَرُوا مَكَانَهُ غَيْرَهُ، وَمَنِ اكْتَرَى مَاعُونًا أَوْ غَيْرَهُ فَلَا ضَمَانَ عَلَيْهِ فِي هَلَاكِهِ بِيَدِهِ، وَهُوَ مُصَدَّقٌ إِلَّا أَنْ يَتَبَيَّنَ كَذِبُهُ."]]},{"id":"ri35_48","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٨","segs":[["matn","وَالصُّنَّاعُ ضَامِنُونَ لِمَا غَابُوا عَلَيْهِ: عَمِلُوهُ بِأَجْرٍ أَوْ بِغَيْرِ أَجْرٍ، وَلَا ضَمَانَ عَلَى صَاحِبِ الْحَمَّامِ، وَلَا ضَمَانَ عَلَى صَاحِبِ السَّفِينَةِ، وَلَا كِرَاءَ لَهُ إِلَّا عَلَى الْبَلَاغِ."]]},{"id":"ri35_49","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٤٩","segs":[["matn","وَلَا بَأْسَ بِالشِّرْكَةِ بِالْأَبْدَانِ إِذَا عَمِلَا فِي مَوْضِعٍ وَاحِدٍ عَمَلًا وَاحِدًا أَوْ مُتَقَارِبًا، وَتَجُوزُ الشِّرْكَةُ بِالْأَمْوَالِ عَلَى أَنْ يَكُونَ الرِّبْحُ بَيْنَهُمَا بِقَدْرِ مَا أَخْرَجَ كُلُّ وَاحِدٍ،"]]},{"id":"ri35_50","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٠","segs":[["matn","مِنْهُمَا وَالْعَمَلُ عَلَيْهِمَا بِقَدْرِ مَا شَرَطَا مِنَ الرِّبْحِ لِكُلِّ وَاحِدٍ، وَلَا يَجُوزُ أَنْ يَخْتَلِفَ رَأْسُ الْمَالِ، وَيَسْتَوِيَا فِي الرِّبْحِ."]]},{"id":"ri35_51","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥١","segs":[["matn","وَالْقِرَاضُ جَائِزٌ بِالدَّنَانِيرِ وَالدَّرَاهِمِ، وَقَدْ أُرْخِصَ فِيهِ بِنِقَارِ الذَّهَبِ وَالْفِضَّةِ، وَلَا يَجُوزُ بِالْعُرُوضِ، وَيَكُونُ إِنْ نَزَلَ أَجِيرًا فِي بَيْعِهَا وَعَلَى قِرَاضِ مِثْلِهِ فِي الثَّمَنِ،"]]},{"id":"ri35_52","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٢","segs":[["matn","وَلِلْعَامِلِ كِسْوَتُهُ وَطَعَامُهُ إِذَا سَافَرَ فِي الْمَالِ الَّذِي لَهُ بَالٌ، وَإِنَّمَا يُكْتَسَى فِي السَّفَرِ الْبَعِيدِ، وَلَا يَقْتَسِمَانِ الرِّبْحَ حَتَّى يَنِضَّ رَأْسُ الْمَالِ."]]},{"id":"ri35_53","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٣","segs":[["matn","وَالْمُسَاقَاةُ جَائِزَةٌ فِي الْأُصُولِ عَلَى مَا تَرَاضَيَا عَلَيْهِ مِنَ الْأَجْزَاءِ، وَالْعَمَلُ كُلُّهُ عَلَى الْمُسَاقِي، وَلَا يَشْتَرِطُ عَلَيْهِ عَمَلًا غَيْرَ عَمَلِ الْمُسَاقَاةِ،"]]},{"id":"ri35_54","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٤","segs":[["matn","وَلَا عَمَلَ شَيْءٍ يُنْشِئُهُ فِي الْحَائِطِ، إِلَّا مَا لَا بَالَ لَهُ مِنْ سَدِّ الْحَظِيرَةِ وَإِصْلَاحِ الضَّفِيرَةِ وَهِيَ مُجْتَمَعُ الْمَاءِ مِنْ غَيْرِ أَنْ يُنْشِئَ بِنَاءَهَا."]]},{"id":"ri35_55","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٥","segs":[["matn","وَالتَّذْكِيرُ عَلَى الْعَامِلِ، وَتَنْقِيَةُ مَنَاقِعِ الشَّجَرِ وَإِصْلَاحُ مَسْقَطِ الْمَاءِ مِنَ الْغَرْبِ وَتَنْقِيَةُ الْعَيْنِ وَشِبْهُ ذَلِكَ جَائِزٌ أَنْ يُشْتَرَطَ عَلَى الْعَامِلِ، وَلَا تَجُوزُ الْمُسَاقَاةُ عَلَى إِخْرَاجِ مَا فِي الْحَائِطِ مِنَ الدَّوَابِّ، وَمَا مَاتَ مِنْهَا فَعَلَى رَبِّهِ خَلَفُهُ،"]]},{"id":"ri35_56","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٦","segs":[["matn","وَنَفَقَةُ الدَّوَابِّ وَالْأُجَرَاءِ عَلَى الْعَامِلِ، وَعَلَيْهِ زَرِيعَةُ الْبَيَاضِ الْيَسِيرِ، وَلَا بَأْسَ أَنْ يُلْغَى ذَلِكَ لِلْعَامِلِ، وَهُوَ أَحَلُّهُ، وَإِنْ كَانَ الْبَيَاضُ كَثِيرًا لَمْ يَجُزْ أَنْ يَدْخُلَ فِي مُسَاقَاةِ النَّخْلِ، إِلَّا أَنْ يَكُونَ قَدْرَ الثُّلُثِ مِنَ الْجَمِيعِ فَأَقَلَّ."]]},{"id":"ri35_57","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٧","segs":[["matn","وَالشَّرِكَةُ فِي الزَّرْعِ جَائِزَةٌ إِذَا كَانَتِ الزَّرِيعَةُ مِنْهُمَا جَمِيعًا، وَالرِّبْحُ بَيْنَهُمَا: وَإِذَا كَانَتِ الْأَرْضُ لِأَحَدِهِمَا وَالْعَمَلُ عَلَى الْآخَرِ، أَوِ الْعَمَلُ بَيْنَهُمَا وَاكْتَرَيَا الْأَرْضَ، أَوْ كَانَتْ بَيْنَهُمَا، أَمَّا إِنْ كَانَ الْبَذْرُ مِنْ عِنْدِ أَحَدِهِمَا،"]]},{"id":"ri35_58","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٨","segs":[["matn","وَمِنْ عِنْدِ الْآخَرِ الْأَرْضُ وَالْعَمَلُ عَلَيْهِ، أَوْ عَلَيْهِمَا، وَالرِّبْحُ بَيْنَهُمَا لَمْ يَجُزْ، وَلَوْ كَانَا اكْتَرَيَا الْأَرْضَ، وَالْبَذْرُ مِنْ عِنْدِ وَاحِدٍ، وَعَلَى الْآخَرِ الْعَمَلُ جَازَ إِذَا تَقَارَبَتْ قِيمَةُ ذَلِكَ، وَلَا يُنْقَدُ فِي كِرَاءِ أَرْضٍ غَيْرِ مَأْمُونَةٍ قَبْلَ أَنْ تُرْوَى."]]},{"id":"ri35_59","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٥٩","segs":[["matn","وَمَنِ ابْتَاعَ ثَمَرَةً فِي رُءُوسِ الشَّجَرِ فَأُجِيحَ بِبَرْدٍ أَوْ جَرَادٍ أَوْ جَلِيدٍ أَوْ غَيْرِهِ، فَإِنْ أُجِيحَ قَدْرُ الثُّلُثِ فَأَكْثَرُ وُضِعَ عَنِ الْمُشْتَرِي قَدْرُ ذَلِكَ مِنَ الثَّمَنِ،"]]},{"id":"ri35_60","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٦٠","segs":[["matn","وَمَا نَقَصَ عَنِ الثُّلُثِ فَمِنَ الْمُبْتَاعِ، وَلَا جَائِحَةَ فِي الزَّرْعِ وَلَا فِيمَا اشْتُرِيَ بَعْدَ أَنْ يَبِسَ مِنَ الثِّمَارِ، وَتُوضَعُ جَائِحَةُ الْبُقُولِ، وَإِنْ قَلَّتْ، وَقِيلَ: لَا يُوضَعُ إِلَّا قَدْرُ الثُّلُثِ."]]},{"id":"ri35_61","label":"بَابٌ فِي الْبُيُوعِ وَمَا شَاكَلَ الْبُيُوعَ · ٦١","segs":[["matn","وَمَنْ أَعْرَى ثَمَرَ نَخَلَاتٍ لِرَجُلٍ مِنْ جِنَانِهِ فَلَا بَأْسَ أَنْ يَشْتَرِيَهَا إِذَا أَزْهَتْ بِخِرْصِهَا تَمْرًا يُعْطِيهِ ذَلِكَ عِنْدَ الْجِذَاذِ إِنْ كَانَ فِيهَا خَمْسَةُ أَوْسُقٍ فَأَقَلُّ، وَلَا يَجُوزُ شِرَاءُ أَكْثَرَ مِنْ خَمْسَةِ أَوْسُقٍ إِلَّا بِالْعَيْنِ وَالْعَرْضِ."]]}]},{"id":"ri36","title":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ","units":[{"id":"ri36_1","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١","segs":[["matn","وَيَحِقُّ عَلَى مَنْ لَهُ مَا يُوصِي فِيهِ أَنْ يُعِدَّ وَصِيَّتَهُ، وَلَا وَصِيَّةَ لِوَارِثٍ، وَالْوَصَايَا خَارِجَةٌ مِنَ الثُّلُثِ، وَيُرَدُّ مَا زَادَ عَلَيْهِ إِلَّا أَنْ يُجِيزَهُ الْوَرَثَةُ."]]},{"id":"ri36_2","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٢","segs":[["matn","وَالْعِتْقُ بِعَيْنِهِ مُبَدَّأٌ عَلَيْهَا، وَالْمُدَبَّرُ فِي الصِّحَّةِ مُبَدَّأٌ عَلَى مَا فِي الْمَرَضِ مِنْ عِتْقٍ وَغَيْرِهِ، وَعَلَى مَا فَرَّطَ فِيهِ مِنَ الزَّكَاةِ، فَأَوْصَى بِهِ؛ فَإِنَّ ذَلِكَ فِي ثُلُثِهِ مُبَدَّأٌ عَلَى الْوَصَايَا، وَمُدَبَّرُ الصِّحَّةِ مُبَدَّأٌ عَلَيْهِ."]]},{"id":"ri36_3","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٣","segs":[["matn","وَإِذَا ضَاقَ الثُّلُثُ تَحَاصَّ أَهْلُ الْوَصَايَا الَّتِي لَا تَبْدِئَةَ فِيهَا، وَلِلرَّجُلِ الرُّجُوعُ عَنْ وَصِيَّتِهِ مِنْ عِتْقٍ وَغَيْرِهِ."]]},{"id":"ri36_4","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٤","segs":[["matn","وَالتَّدْبِيرُ أَنْ يَقُولَ الرَّجُلُ لِعَبْدِهِ أَنْتَ مُدَبَّرٌ، أَوْ أَنْتَ حُرٌّ عَنْ دُبُرٍ مِنِّي، ثُمَّ لَا يَجُوزُ لَهُ بَيْعُهُ وَلَهُ خِدْمَتُهُ، وَلَهُ انْتِزَاعُ مَالِهِ مَا لَمْ يَمْرَضْ، وَلَهُ وَطْؤُهَا إِنْ كَانَتْ أَمَةً،"]]},{"id":"ri36_5","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٥","segs":[["matn","وَلَا يَطَأُ الْمُعْتَقَةَ إِلَى أَجَلٍ، وَلَا يَبِيعُهَا، وَلَهُ أَنْ يَسْتَخْدِمَهَا، وَلَهُ أَنْ يَنْتَزِعَ مَالَهَا مَا لَمْ يَقْرُبِ الْأَجَلُ، وَإِذَا مَاتَ فَالْمُدَبَّرُ مِنْ ثُلُثِهِ، وَالْمُعْتَقُ إِلَى أَجَلٍ مِنْ رَأْسِ مَالِهِ."]]},{"id":"ri36_6","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٦","segs":[["matn","وَالْمُكَاتَبُ عَبْدٌ مَا بَقِيَ عَلَيْهِ شَيْءٌ، وَالْكِتَابَةُ جَائِزَةٌ عَلَى مَا رَضِيَهُ الْعَبْدُ وَالسَّيِّدُ مِنَ الْمَالِ مُنَجَّمًا قَلَّتِ النُّجُومُ أَوْ كَثُرَتْ، فَإِنْ عَجَزَ رَجَعَ رَقِيقًا، وَحَلَّ لَهُ مَا أَخَذَ مِنْهُ، وَلَا يُعَجِّزُهُ إِلَّا السُّلْطَانُ بَعْدَ التَّلَوُّمِ إِذَا امْتَنَعَ مِنَ التَّعْجِيزِ."]]},{"id":"ri36_7","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٧","segs":[["matn","وَكُلُّ ذَاتِ رَحِمٍ فَوَلَدُهَا بِمَنْزِلَتِهَا مِنْ مُكَاتَبَةٍ أَوْ مُدَبَّرَةٍ أَوْ مُعْتَقَةٍ إِلَى أَجَلٍ أَوْ مَرْهُونَةٍ، وَوَلَدُ أُمِّ الْوَلَدِ مِنْ غَيْرِ السَّيِّدِ بِمَنْزِلَتِهَا."]]},{"id":"ri36_8","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٨","segs":[["matn","وَمَالُ الْعَبْدِ لَهُ إِلَّا أَنْ يَنْتَزِعَهُ السَّيِّدُ، فَإِنْ أَعْتَقَهُ أَوْ كَاتَبَهُ، وَلَمْ يَسْتَثْنِ مَالَهُ فَلَيْسَ لَهُ أَنْ يَنْتَزِعَهُ وَلَيْسَ لَهُ وَطْءُ مُكَاتَبَتِهِ."]]},{"id":"ri36_9","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٩","segs":[["matn","وَمَا حَدَثَ لِلْمُكَاتَبِ وَالْمُكَاتَبَةِ مِنْ وَلَدٍ دَخَلَ مَعَهُمَا فِي الْكِتَابَةِ، وَعَتَقَ بِعِتْقِهِمَا."]]},{"id":"ri36_10","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٠","segs":[["matn","وَتَجُوزُ كِتَابَةُ الْجَمَاعَةِ، وَلَا يُعْتَقُونَ إِلَّا بِأَدَاءِ الْجَمِيعِ، وَلَيْسَ لِلْمُكَاتَبِ عِتْقٌ وَلَا إِتْلَافُ مَالِهِ حَتَّى يُعْتَقَ، وَلَا يَتَزَوَّجُ وَلَا يُسَافِرُ السَّفَرَ الْبَعِيدَ بِغَيْرِ إِذْنِ سَيِّدِهِ."]]},{"id":"ri36_11","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١١","segs":[["matn","وَإِذَا مَاتَ وَلَهُ وَلَدٌ قَامَ مَقَامَهُ، وَأَدَّى مِنْ مَالِهِ مَا بَقِيَ عَلَيْهِ حَالًّا، وَوَرِثَ مَنْ مَعَهُ مِنْ وَلَدِهِ مَا بَقِيَ، وَإِنْ لَمْ يَكُنْ فِي الْمَالِ وَفَاءٌ فَإِنَّ وَلَدَهُ يَسْعَوْنَ فِيهِ،"]]},{"id":"ri36_12","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٢","segs":[["matn","وَيُؤَدُّونَ نُجُومًا إِنْ كَانُوا كِبَارًا، وَإِنْ كَانُوا صِغَارًا وَلَيْسَ فِي الْمَالِ قَدْرُ النُّجُومِ إِلَى بُلُوغِهِمُ السَّعْيَ رَقُّوا، وَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ مَعَهُ فِي كِتَابَتِهِ وَرِثَهُ سَيِّدُهُ."]]},{"id":"ri36_13","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٣","segs":[["matn","وَمَنْ أَوْلَدَ أَمَةً فَلَهُ أَنْ يَسْتَمْتِعَ مِنْهَا فِي حَيَاتِهِ، وَتُعْتَقُ مِنْ رَأْسِ مَالِهِ بَعْدَ مَمَاتِهِ وَلَا يَجُوزُ بَيْعُهَا، وَلَا لَهُ عَلَيْهَا خِدْمَةٌ وَلَا غَلَّةٌ، وَلَهُ ذَلِكَ فِي وَلَدِهَا مِنْ غَيْرِهِ، وَهُوَ بِمَنْزِلَةِ أُمِّهِ فِي الْعِتْقِ يُعْتَقُ بِعِتْقِهَا."]]},{"id":"ri36_14","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٤","segs":[["matn","وَكُلُّ مَا أَسْقَطَتْهُ مِمَّا يُعْلَمُ أَنَّهُ وَلَدٌ فَهِيَ بِهِ أُمُّ وَلَدٍ، وَلَا يَنْفَعُهُ الْعَزْلُ إِذَا أَنْكَرَ وَلَدَهَا، وَأَقَرَّ بِالْوَطْءِ، فَإِنِ ادَّعَى اسْتِبْرَاءً لَمْ يَطَأْ بَعْدَهُ لَمْ يَلْحَقْ بِهِ مَا جَاءَ مِنْ وَلَدٍ."]]},{"id":"ri36_15","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٥","segs":[["matn","وَلَا يَجُوزُ عِتْقُ مَنْ أَحَاطَ الدَّيْنُ بِمَالِهِ، وَمَنْ أَعْتَقَ بَعْضَ عَبْدِهِ اسْتَتَمَّ عَلَيْهِ، وَإِنْ كَانَ لِغَيْرِهِ مَعَهُ فِيهِ شَرِكَةٌ قُوِّمَ عَلَيْهِ نَصِيبُ شَرِيكِهِ بِقِيمَتِهِ يَوْمَ يُقَامُ عَلَيْهِ وَعَتَقَ،"]]},{"id":"ri36_16","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٦","segs":[["matn","فَإِنْ لَمْ يُوجَدْ لَهُ مَالٌ بَقِيَ سَهْمُ الشَّرِيكِ رَقِيقًا، وَمَنْ مَثَّلَ بِعَبْدِهِ مُثْلَةً بَيِّنَةً مِنْ قَطْعِ جَارِحَةٍ وَنَحْوِهِ عَتَقَ عَلَيْهِ."]]},{"id":"ri36_17","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٧","segs":[["matn","وَمَنْ مَلَكَ أَبَوَيْهِ أَوْ أَحَدًا مِنْ وَلَدِهِ أَوْ وَلَدِ وَلَدِهِ أَوْ وَلَدِ بَنَاتِهِ أَوْ جَدَّهُ أَوْ جَدَّتَهُ أَوْ أَخَاهُ لِأُمٍّ أَوْ لِأَبٍ أَوْ لَهُمَا جَمِيعًا عَتَقَ عَلَيْهِ."]]},{"id":"ri36_18","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٨","segs":[["matn","وَمَنْ أَعْتَقَ حَامِلًا كَانَ جَنِينُهَا حُرًّا مَعَهَا، وَلَا يُعْتَقُ فِي الرِّقَابِ الْوَاجِبَةِ مَنْ فِيهِ مَعْنًى مِنْ عِتْقٍ بِتَدْبِيرٍ أَوْ كِتَابَةٍ أَوْ غَيْرِهِمَا، وَلَا أَعْمَى وَلَا أَقْطَعُ الْيَدِ وَشِبْهُهُ وَلَا مَنْ عَلَى غَيْرِ الْإِسْلَامِ، وَلَا يَجُوزُ عِتْقُ الصَّبِيِّ وَلَا الْمَوْلَى عَلَيْهِ."]]},{"id":"ri36_19","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ١٩","segs":[["matn","وَالْوَلَاءُ لِمَنْ أَعْتَقَ، وَلَا يَجُوزُ بَيْعُهُ وَلَا هِبَتُهُ، وَمَنْ أَعْتَقَ عَبْدًا عَنْ رَجُلٍ فَالْوَلَاءُ لِلرَّجُلِ، وَلَا يَكُونُ الْوَلَاءُ لِمَنْ أَسْلَمَ عَلَى يَدَيْهِ، وَهُوَ لِلْمُسْلِمِينَ،"]]},{"id":"ri36_20","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٢٠","segs":[["matn","وَوَلَاءُ مَا أَعْتَقَتِ الْمَرْأَةُ لَهَا وَوَلَاءُ مَنْ يَجُرُّهُ مِنْ وَلَدٍ أَوْ عَبْدٍ أَعْتَقَتْهُ، وَلَا تَرِثُ مَا أَعْتَقَ غَيْرُهَا مِنْ أَبٍ أَوِ ابْنٍ أَوْ زَوْجٍ أَوْ غَيْرِهِ، وَمِيرَاثُ السَّائِبَةِ لِجَمَاعَةِ الْمُسْلِمِينَ."]]},{"id":"ri36_21","label":"بَابٌ فِي الْوَصَايَا وَالْمُدَبَّرِ وَالْمُكَاتَبِ وَالْمُعْتَقِ وَأُمِّ الْوَلَدِ وَالْوَلَاءِ · ٢١","segs":[["matn","وَالْوَلَاءُ لِلْأَقْعَدِ مِنْ عُصْبَةِ الْمَيِّتِ الْأَوَّلِ، فَإِنْ تَرَكَ ابْنَيْنِ فَوَرِثَا وَلَاءَ مَوْلًى لِأَبِيهِمَا، ثُمَّ مَاتَ أَحَدُهُمَا وَتَرَكَ بَنِينَ رَجَعَ الْوَلَاءُ إِلَيَّ أَخِيهِ دُونَ بَنِيهِ، وَإِنْ مَاتَ وَاحِدٌ مِنْهُمَا، وَتَرَكَ وَلَدًا، وَمَاتَ أَخُوهُ، وَتَرَكَ وَلَدَيْنِ فَالْوَلَاءُ بَيْنَ الثَّلَاثَةِ أَثْلَاثًا."]]}]},{"id":"ri37","title":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ","units":[{"id":"ri37_1","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١","segs":[["matn","وَإِنَّمَا الشُّفْعَةُ فِي الْمُشَاعِ، وَلَا شُفْعَةَ فِيمَا قَدْ قُسِمَ وَلَا لِجَارٍ وَلَا فِي طَرِيقٍ وَلَا عَرْصَةِ دَارٍ قَدْ قُسِمَتْ بُيُوتُهَا، وَلَا فِي فَحْلِ نَخْلٍ أَوْ بِئْرٍ إِذَا قُسِمَتِ النَّخْلُ أَوِ الْأَرْضُ،"]]},{"id":"ri37_2","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٢","segs":[["matn","وَلَا شُفْعَةَ إِلَّا فِي الْأَرْضِ وَمَا يَتَّصِلُ بِهَا مِنَ الْبِنَاءِ وَالشَّجَرِ، وَلَا شُفْعَةَ لِلْحَاضِرِ بَعْدَ السَّنَةِ، وَالْغَائِبُ عَلَى شُفْعَتِهِ وَإِنْ طَالَتْ غَيْبَتُهُ،"]]},{"id":"ri37_3","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٣","segs":[["matn","وَعُهْدَةُ الشَّفِيعِ عَلَى الْمُشْتَرِي، وَيُوقَفُ الشَّفِيعُ فَإِمَّا أَخَذَ أَوْ تَرَكَ، وَلَا تُوهَبُ الشُّفْعَةُ وَلَا تُبَاعُ، وَتُقْسَمُ بَيْنَ الشُّرَكَاءِ بِقَدْرِ الْأَنْصِبَاءِ."]]},{"id":"ri37_4","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٤","segs":[["matn","وَلَا تَتِمُّ هِبَةٌ وَلَا صَدَقَةٌ وَلَا حَبْسٌ إِلَّا بِالْحِيَازَةِ، فَإِنْ مَاتَ قَبْلَ أَنْ تُحَازَ عَنْهُ فَهِيَ مِيرَاثٌ، إَلَّا أَنْ يَكُونَ ذَلِكَ فِي الْمَرَضِ فَذَلِكَ نَافِذٌ مِنَ الثُّلُثِ إِنْ كَانَ لِغَيْرِ وَارِثٍ، وَالْهِبَةُ لِصِلَةِ الرَّحِمِ أَوْ لِفَقِيرٍ كَالصَّدَقَةِ لَا رُجُوعَ فِيهَا."]]},{"id":"ri37_5","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٥","segs":[["matn","وَمَنْ تَصَدَّقَ عَلَى وَلَدِهِ فَلَا رُجُوعَ لَهُ، وَلَهُ أَنْ يَعْتَصِرَ مَا وَهَبَ لِوَلَدِهِ الصَّغِيرِ أَوِ الْكَبِيرِ مَا لَمْ يُنْكَحْ لِذَلِكَ أَوْ يُدَايَنْ أَوْ يُحْدِثُ فِي الْهِبَةِ حَدَثًا، وَالْأُمُّ تَعْتَصِرُ مَا دَامَ الْأَبُ حَيًّا،"]]},{"id":"ri37_6","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٦","segs":[["matn","فَإِذَا مَاتَ لَمْ تَعْتَصِرْ وَلَا يُعْتَصَرُ مِنْ يَتِيمٍ، وَالْيُتْمُ مِنْ قِبَلِ الْأَبِ، وَمَا وَهَبَهُ لِابْنِهِ الصَّغِيرِ فَحِيَازَتُهُ لَهُ جَائِزَةٌ إِذَا لَمْ يَسْكُنْ ذَلِكَ، أَوْ يَلْبَسْهُ إِنْ كَانَ ثَوْبًا، وَإِنَّمَا يَجُوزُ لَهُ مَا يُعْرَفُ بِعَيْنِهِ، وَأَمَّا الْكَبِيرُ فَلَا تَجُوزُ حِيَازَتُهُ لَهُ."]]},{"id":"ri37_7","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٧","segs":[["matn","وَلَا يَرْجِعُ الرَّجُلُ فِي صَدَقَتِهِ، وَلَا تَرْجِعُ إِلَيْهِ إِلَّا بِالْمِيرَاثِ. وَلَا بَأْسَ أَنْ يَشْرَبَ مِنْ لَبَنِ مَا تَصَدَّقَ بِهِ، وَلَا يَشْتَرِي مَا تَصَدَّقَ بِهِ."]]},{"id":"ri37_8","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٨","segs":[["matn","وَالْمَوْهُوبُ لِلْعِوَضِ إِمَّا أَثَابَ الْقِيمَةَ أَوْ رَدَّ الْهِبَةَ، فَإِنْ فَاتَتْ فَعَلَيْهِ قِيمَتُهَا. وَذَلِكَ إِذَا كَانَ يَرَى أَنَّهُ أَرَادَ الثَّوَابَ مِنَ الْمَوْهُوبِ لَهُ."]]},{"id":"ri37_9","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٩","segs":[["matn","وَيُكْرَهُ أَنْ يَهَبَ لِبَعْضِ وَلَدِهِ مَالَهُ كُلَّهُ، وَأَمَّا الشَّيْءُ مِنْهُ فَذَلِكَ سَائِغٌ."]]},{"id":"ri37_10","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٠","segs":[["matn","وَلَا بَأْسَ أَنْ يَتَصَدَّقَ عَلَى الْفُقَرَاءِ بِمَالِهِ كُلِّهِ لِلَّهِ وَمَنْ وَهَبَ هِبَةً فَلَمْ يَحُزْهَا الْمَوْهُوبُ لَهُ حَتَّى مَرِضَ الْوَاهِبُ أَوْ أَفْلَسَ فَلَيْسَ لَهُ حِينَئِذٍ قَبْضُهَا، وَلَوْ مَاتَ الْمَوْهُوبُ لَهُ كَانَ لِوَرَثَتِهِ الْقِيَامُ فِيهَا عَلَى الْوَاهِبِ الصَّحِيحِ."]]},{"id":"ri37_11","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١١","segs":[["matn","وَمَنْ حَبَسَ دَارًا فَهِيَ عَلَى مَا جَعَلَهَا عَلَيْهِ إِنْ حِيزَتْ قَبْلَ مَوْتِهِ، وَلَوْ كَانَتْ حَبْسًا عَلَى وَلَدِهِ الصَّغِيرِ جَازَتْ حِيَازَتُهُ لَهُ إِلَى أَنْ يَبْلُغَ،"]]},{"id":"ri37_12","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٢","segs":[["matn","وَلْيُكْرِهَا لَهُ، وَلَا يَسْكُنُهَا، فَإِنْ لَمْ يَدَعْ سُكْنَاهَا حَتَّى مَاتَ بَطَلَتْ، وَإِنِ انْقَرَضَ مَنْ حُبِّسَتْ عَلَيْهِ رَجَعَتْ حُبُسًا عَلَى أَقْرَبِ النَّاسِ بِالْمُحَبِّسِ يَوْمَ الْمَرْجِعِ."]]},{"id":"ri37_13","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٣","segs":[["matn","وَمَنْ أَعْمَرَ رَجُلًا حَيَاتَهُ دَارًا رَجَعَتْ بَعْدَ مَوْتِ السَّاكِنِ مِلْكًا لِرَبِّهَا، وَكَذَلِكَ إِنْ أَعْمَرَ عَقِبَهُ فَانْقَرَضُوا بِخِلَافِ الْحُبُسِ، فَإِنْ مَاتَ الْمُعْمِرُ يَوْمَئِذٍ كَانَتْ لِوَرَثَتِهِ يَوْمَ مَوْتِهِ مِلْكًا."]]},{"id":"ri37_14","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٤","segs":[["matn","وَمَنْ مَاتَ مِنْ أَهْلِ الْحُبُسِ فَنَصِيبُهُ عَلَى مَنْ بَقِيَ وَيُؤْثَرُ فِي الْحُبُسِ أَهْلُ الْحَاجَةِ بِالسُّكْنَى وَالْغَلَّةِ، وَمَنْ سَكَنَ فَلَا يَخْرُجُ لِغَيْرِهِ إِلَّا أَنْ يَكُونَ فِي أَصْلِ الْحُبُسِ شَرْطٌ فَيُمْضَى،"]]},{"id":"ri37_15","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٥","segs":[["matn","وَلَا يُبَاعُ الْحُبُسُ وَإِنْ خَرِبَ، وَيُبَاعُ الْفَرَسُ الْحُبُسُ يَكْلَبُ، وَيُجْعَلُ ثَمَنُهُ فِي مِثْلِهِ أَوْ يُعَانُ بِهِ فِيهِ، وَاخْتُلِفَ فِي الْمُعَاوَضَةِ بِالرَّبْعِ الْخَرِبِ بِرَبْعٍ غَيْرِ خَرِبٍ."]]},{"id":"ri37_16","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٦","segs":[["matn","وَالرَّهْنُ جَائِزٌ، وَلَا يَتِمُّ إِلَّا بِالْحِيَازَةِ، وَلَا تَنْفَعُ الشَّهَادَةُ فِي حِيَازَتِهِ إِلَّا بِمُعَايَنَةِ الْبَيِّنَةِ، وَضَمَانُ الرَّهْنِ مِنَ الْمُرْتَهِنِ فِيمَا يُغَابُ عَلَيْهِ، وَلَا يَضْمَنُ مَا لَا يُغَابُ عَلَيْهِ،"]]},{"id":"ri37_17","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٧","segs":[["matn","وَثَمَرَةُ النَّخْلِ الرَّهْنِ لِلرَّاهِنِ، وَكَذَلِكَ غَلَّةُ الدُّورِ، وَالْوَلَدُ رَهْنٌ مَعَ الْأَمَةِ الرَّهْنِ تَلِدُهُ بَعْدَ الرَّهْنِ، وَلَا يَكُونُ مَالُ الْعَبْدِ رَهْنًا إِلَّا بِشَرْطٍ، وَمَا هَلَكَ بِيَدِ أَمِينٍ فَهُوَ مِنَ الرَّاهِنِ."]]},{"id":"ri37_18","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٨","segs":[["matn","وَالْعَارِيَّةُ مُؤَدَّاةٌ، يَضْمَنُ مَا يُغَابُ عَلَيْهِ، وَلَا يَضْمَنُ مَا لَا يُغَابُ عَلَيْهِ مِنْ عَبْدٍ أَوْ دَابَّةٍ إِلَّا أَنْ يَتَعَدَّى."]]},{"id":"ri37_19","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ١٩","segs":[["matn","وَالْمُودَعُ إِنْ قَالَ: رَدَدْتُ الْوَدِيعَةَ إِلَيْكَ صُدِّقَ، إِلَّا أَنْ يَكُونَ قَبَضَهَا بِإِشْهَادٍ، وَإِنْ قَالَ: ذَهَبَتْ فَهُوَ مُصَدَّقٌ بِكُلِّ حَالٍ، وَالْعَارِيَّةُ لَا يُصَدَّقُ فِي هَلَاكِهَا فِيمَا يُغَابُ عَلَيْهِ، وَمَنْ تَعَدَّى عَلَى وَدِيعَةٍ ضَمِنَهَا،"]]},{"id":"ri37_20","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٢٠","segs":[["matn","وَإِنْ كَانَتْ دَنَانِيرَ فَرَدَّهَا فِي صُرَّتِهَا، ثُمَّ هَلَكَتْ فَقَدِ اخْتُلِفَ فِي تَضْمِينِهِ، وَمَنِ اتَّجَرَ بِوَدِيعَةٍ فَذَلِكَ مَكْرُوهٌ، وَالرِّبْحُ لَهُ إِنْ كَانَتْ عَيْنًا، وَإِنْ بَاعَ الْوَدِيعَةَ وَهِيَ عَرْضٌ فَرَبُّهَا مُخَيَّرٌ فِي الثَّمَنِ أَوِ الْقِيمَةِ يَوْمَ التَّعَدِّي."]]},{"id":"ri37_21","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٢١","segs":[["matn","وَمَنْ وَجَدَ لُقَطَةً فَلْيُعَرِّفْهَا سَنَةً بِمَوْضِعٍ يَرْجُو التَّعْرِيفَ بِهَا، فَإِنْ تَمَّتْ سَنَةٌ وَلَمْ يَأْتِ لَهَا أَحَدٌ فَإِنْ شَاءَ حَبَسَهَا، وَإِنْ شَاءَ تَصَدَّقَ بِهَا وَضَمِنَهَا لِرَبِّهَا إِنْ جَاءَ، وَإِنِ انْتَفَعَ بِهَا ضَمِنَهَا،"]]},{"id":"ri37_22","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٢٢","segs":[["matn","وَإِنْ هَلَكَتْ قَبْلَ السَّنَةِ أَوْ بَعْدَهَا بِغَيْرِ تَحْرِيكٍ لَمْ يَضْمَنْهَا، وَإِذَا عَرَفَ طَالِبُهَا الْعِفَاصَ وَالْوِكَاءَ أَخَذَهَا، وَلَا يَأْخُذُ الرَّجُلُ ضَالَّةَ الْإِبِلِ مِنَ الصَّحْرَاءِ، وَلَهُ أَخْذُ الشَّاةِ وَأَكْلُهَا إِنْ كَانَتْ بِفَيْفَاءَ لَا عِمَارَةَ فِيهَا."]]},{"id":"ri37_23","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٢٣","segs":[["matn","وَمَنِ اسْتَهْلَكَ عَرْضًا فَعَلَيْهِ قِيمَتُهُ، وَكُلُّ مَا يُوزَنُ أَوْ يُكَالُ فَعَلَيْهِ مِثْلُهُ."]]},{"id":"ri37_24","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٢٤","segs":[["matn","وَالْغَاصِبُ ضَامِنٌ لِمَا غَصَبَ، فَإِنْ رَدَّ ذَلِكَ بِحَالِهِ فَلَا شَيْءَ عَلَيْهِ، وَإِنْ تَغَيَّرَ فِي يَدِهِ فَرَبُّهُ مُخَيَّرٌ بَيْنَ أَخْذِهِ بِنَقْصِهِ أَوْ تَضْمِينِهِ الْقِيمَةَ، وَلَوْ كَانَ النَّقْصُ بِتَعَدِّيهِ خُيِّرَ أَيْضًا فِي أَخْذِهِ وَأَخْذِ مَا نَقَصَهُ، وَقَدِ اخْتُلِفَ فِي ذَلِكَ."]]},{"id":"ri37_25","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٢٥","segs":[["matn","وَلَا غَلَّةَ لِلْغَاصِبِ، وَيَرُدُّ مَا أَكَلَ مِنْ غَلَّةٍ أَوِ انْتَفَعَ وَعَلَيْهِ الْحَدُّ إِنْ وَطِئَ وَوَلَدُهُ رَقِيقٌ لِرَبِّ الْأَمَةِ،"]]},{"id":"ri37_26","label":"بَابٌ فِي الشُّفْعَةِ وَالْهِبَةِ وَالصَّدَقَةِ وَالْحَبْسِ وَالرَّهْنِ وَالْعَارِيَّةِ وَالْوَدِيعَةِ وَاللُّقَطَةِ وَالْغَصْبِ · ٢٦","segs":[["matn","وَلَا يَطِيبُ لِغَاصِبِ الْمَالِ رِبْحُهُ حَتَّى يَرُدَّ رَأْسَ الْمَالِ عَلَى رَبِّهِ، وَلَوْ تَصَدَّقَ بِالرِّبْحِ كَانَ أَحَبَّ إِلَى بَعْضِ أَصْحَابِ مَالِكٍ، وَفِي بَابِ الْأَقْضِيَةِ شَيْءٌ مِنْ هَذَا الْمَعْنَى."]]}]},{"id":"ri38","title":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ","units":[{"id":"ri38_1","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١","segs":[["matn","وَلَا تُقْتَلُ نَفْسٌ بِنَفْسٍ إِلَّا بِبَيِّنَةٍ عَادِلَةٍ أَوْ بِاعْتِرَافٍ أَوْ بِالْقَسَامَةِ إِذَا وَجَبَتْ يُقْسِمُ الْوُلَاةُ خَمْسِينَ يَمِينًا، وَيَسْتَحِقُّونَ الدَّمَ، وَلَا يَحْلِفُ فِي الْعَمْدِ أَقَلُّ مِنْ رَجُلَيْنِ، وَلَا يُقْتَلُ بِالْقَسَامَةِ أَكْثَرُ مِنْ رَجُلٍ وَاحِدٍ."]]},{"id":"ri38_2","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢","segs":[["matn","وَإِنَّمَا تَجِبُ الْقَسَامَةُ بِقَوْلِ الْمَيِّتِ: دَمِي عِنْدَ فُلَانٍ، أَوْ بِشَاهِدٍ عَلَى الْقَتْلِ، أَوْ بِشَاهِدَيْنِ عَلَى الْجُرْحِ، ثُمَّ يَعِيشُ بَعْدَ ذَلِكَ، وَيَأْكُلُ وَيَشْرَبُ."]]},{"id":"ri38_3","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣","segs":[["matn","وَإِذَا نَكَلَ مُدَّعُو الدَّمِ حَلَفَ الْمُدَّعَى عَلَيْهِمْ خَمْسِينَ يَمِينًا، فَإِنْ لَمْ يَجِدْ مَنْ يَحْلِفُ مِنْ وُلَاتِهِ مَعَهُ غَيْرَ الْمُدَّعَى عَلَيْهِ وَحْدَهُ حَلَفَ الْخَمْسِينَ،"]]},{"id":"ri38_4","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤","segs":[["matn","وَلَوِ ادُّعِيَ الْقَتْلُ عَلَى جَمَاعَةٍ حَلَفَ كُلُّ وَاحِدٍ خَمْسِينَ يَمِينًا، وَيَحْلِفُ مِنَ الْوُلَاةِ فِي طَلَبِ الدَّمِ خَمْسُونَ رَجُلًا خَمْسِينَ يَمِينًا، وَإِنْ كَانُوا أَقَلَّ قُسِمَتْ عَلَيْهِمُ الْأَيْمَانُ،"]]},{"id":"ri38_5","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥","segs":[["matn","وَلَا تَحْلِفُ امْرَأَةٌ فِي الْعَمْدِ، وَتَحْلِفُ الْوَرَثَةُ فِي الْخَطَإِ بِقَدْرِ مَا يَرِثُونَ مِنَ الدِّيَةِ مِنْ رَجُلٍ أَوِ امْرَأَةٍ، وَإِنِ انْكَسَرَتْ يَمِينٌ عَلَيْهِمْ حَلَفَهَا أَكْثَرُهُمْ نَصِيبًا مِنْهَا،"]]},{"id":"ri38_6","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٦","segs":[["matn","وَإِذَا حَضَرَ بَعْضُ وَرَثَةِ دِيَةِ الْخَطَإِ لَمْ يَكُنْ لَهُ بُدٌّ أَنْ يَحْلِفَ جَمِيعَ الْأَيْمَانِ، ثُمَّ يَحْلِفُ مَنْ يَأْتِي بَعْدَهُ بِقَدْرِ نَصِيبِهِ مِنَ الْمِيرَاثِ."]]},{"id":"ri38_7","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٧","segs":[["matn","وَيَحْلِفُونَ فِي الْقَسَامَةِ قِيَامًا، وَيُجْلَبُ إِلَى مَكَّةَ وَالْمَدِينَةِ وَبَيْتِ الْمَقْدِسِ أَهْلُ أَعْمَالِهَا لِلْقَسَامَةِ، وَلَا يُجْلَبُ فِي غَيْرِهَا إِلَّا مِنَ الْأَمْيَاِلِ الْيَسِيرَةِ."]]},{"id":"ri38_8","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٨","segs":[["matn","وَلَا قَسَامَةَ فِي جُرْحٍ وَلَا فِي عَبْدٍ، وَلَا بَيْنَ أَهْلِ الْكِتَابِ، وَلَا فِي قَتِيلٍ بَيْنَ الصَّفَّيْنِ أَوْ وُجِدَ فِي مَحَلَّةِ قَوْمٍ."]]},{"id":"ri38_9","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٩","segs":[["matn","وَقَتْلُ الْغِيلَةِ لَا عَفْوَ فِيهِ، وَلِلرَّجُلِ الْعَفْوُ عَنْ دَمِهِ الْعَمْدِ إِنْ لَمْ يَكُنْ قَتْلَ غِيلَةٍ؛"]]},{"id":"ri38_10","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٠","segs":[["matn","وَعَفْوُهُ عَنِ الْخَطَإِ فِي ثُلُثِهِ، وَإِنْ عَفَا أَحَدُ الْبَنِينَ فَلَا قَتْلَ، وَلِمَنْ بَقِيَ نَصِيبُهُمْ مِنَ الدِّيَةِ، وَلَا عَفْوَ لِلْبَنَاتِ مَعَ الْبَنِينَ، وَمَنْ عُفِيَ عَنْهُ فِي الْعَمْدِ ضُرِبَ مِائَةً، وَحُبِسَ عَامًا."]]},{"id":"ri38_11","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١١","segs":[["matn","وَالدِّيَةُ عَلَى أَهْلِ الْإِبِلِ مِائَةٌ مِنَ الْإِبِلِ، وَعَلَى أَهْلِ الذَّهَبِ أَلْفُ دِينَارٍ، وَعَلَى أَهْلِ الْوَرِقِ اثْنَا عَشَرَ أَلْفَ دِرْهَمٍ."]]},{"id":"ri38_12","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٢","segs":[["matn","وَدِيَةُ الْعَمْدِ إِذَا قُبِلَتْ خَمْسٌ وَعِشْرُونَ حِقَّةً وَخَمْسٌ وَعِشْرُونَ جَذَعَةً وَخَمْسٌ وَعِشْرُونَ بِنْتَ لَبُونٍ وَخَمْسٌ وَعِشْرُونَ بِنْتَ مَخَاضٍ."]]},{"id":"ri38_13","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٣","segs":[["matn","وَدِيَةُ الْخَطَإِ مُخَمَّسَةٌ: عِشْرُونَ مِنْ كُلِّ مَا ذَكَرْنَا وَعِشْرُونَ بَنُو لَبُونٍ ذُكُورًا وَإِنَّمَا تُغَلَّظُ الدِّيَةُ فِي الْأَبِ يَرْمِي ابْنَهُ بِحَدِيدَةٍ فَيَقْتُلُهُ فَلَا يُقْتَلُ بِهِ،"]]},{"id":"ri38_14","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٤","segs":[["matn","وَيَكُونُ عَلَيْهِ ثَلَاثُونَ جَذَعَةً وَثَلَاثُونَ حِقَّةً وَأَرْبَعُونَ خَلِفَةً فِي بُطُونِهَا أَوْلَادُهَا، وَقِيلَ: ذَلِكَ عَلَى عَاقِلَتِهِ، وَقِيلَ: ذَلِكَ فِي مَالِهِ."]]},{"id":"ri38_15","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٥","segs":[["matn","وَدِيَةُ الْمَرْأَةِ عَلَى النِّصْفِ مِنْ دِيَةِ الرَّجُلِ، وَكَذَلِكَ دِيَةُ الْكِتَابِيِّينَ، وَنِسَاؤُهُمْ عَلَى النِّصْفِ مِنْ ذَلِكَ، وَالْمَجُوسِيُّ دِيَتُهُ ثَمَانُمِائَةِ دِرْهَمٍ، وَنِسَاؤُهُمْ عَلَى النِّصْفِ مِنْ ذَلِكَ، وَدِيَةُ جِرَاحِهِمْ كَذَلِكَ."]]},{"id":"ri38_16","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٦","segs":[["matn","وَفِي الْيَدَيْنِ الدِّيَةُ، وَكَذَلِكَ فِي الرِّجْلَيْنِ أَوِ الْعَيْنَيْنِ، وَفِي كُلِّ وَاحِدَةٍ مِنْهُمَا نِصْفُهَا، وَفِي الْأَنْفِ يُقْطَعُ مَارِنُهُ الدِّيَةُ، وَفِي السَّمْعِ الدِّيَةُ، وَفِي الْعَقْلِ الدِّيَةُ، وَفِي الصُّلْبِ يَنْكَسِرُ الدِّيَةُ، وَفِي الْأُنْثَيَيْنِ الدِّيَةُ، وَفِي الْحَشَفَةِ الدِّيَةُ، وَفِي اللِّسَانِ الدِّيَةُ،"]]},{"id":"ri38_17","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٧","segs":[["matn","وَفِيمَا مَنَعَ مِنْهُ الْكَلَامَ الدِّيَةُ، وَفِي ثَدْيَيِ الْمَرْأَةِ الدِّيَةُ، وَفِي عَيْنِ الْأَعْوَرِ الدِّيَةُ، وَفِي الْمُوضِحَةِ خَمْسٌ مِنَ الْإِبِلِ، وَفِي السِّنِّ خَمْسٌ، وَفِي كُلِّ أُصْبُعٍ عَشْرٌ وَفِي الْأُنْمُلَةِ ثَلَاثٌ وَثُلُثٌ، وَفِي كُلِّ أُنْمُلَةٍ مِنَ الْإِبْهَامَيْنِ خَمْسٌ مِنَ الْإِبِلِ."]]},{"id":"ri38_18","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٨","segs":[["matn","وَفِي الْمُنَقِّلَةِ عُشْرٌ وَنِصْفُ عُشْرٍ وَالْمُوضِحَةُ مَا أَوْضَحَ الْعَظْمَ. وَالْمُنَقِّلَةُ مَا طَارَ فَرَاشُهَا مِنَ الْعَظْمِ، وَلَمْ تَصِلْ إِلَى الدِّمَاغِ، وَمَا وَصَلَ إِلَيْهِ فَهِيَ الْمَأْمُومَةُ؛"]]},{"id":"ri38_19","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ١٩","segs":[["matn","فَفِيهَا ثُلُثُ الدِّيَةِ، وَكَذَلِكَ الْجَائِفَةُ، وَلَيْسَ فِيمَا دُونَ الْمُوضِحَةِ إِلَّا الِاجْتِهَادُ، وَكَذَلِكَ فِي جِرَاحِ الْجَسَدِ، وَلَا يُعْقَلُ جُرْحٌ إِلَّا بَعْدَ الْبُرْءِ، وَمَا بَرِئَ عَلَى غَيْرِ شَيْنٍ مِمَّا دُونَ الْمُوضِحَةِ فَلَا شَيْءَ فِيهِ."]]},{"id":"ri38_20","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٠","segs":[["matn","وَفِي الْجِرَاحِ الْقِصَاصُ فِي الْعَمْدِ إِلَّا فِي الْمَتَالِفِ مِثْلِ الْمَأْمُومَةِ وَالْجَائِفَةِ وَالْمُنَقِّلَةِ وَالْفَخِذِ وَالْأُنْثَيَيْنِ وَالصُّلْبِ وَنَحْوِهِ فَفِي كُلِّ ذَلِكَ الدِّيَةُ."]]},{"id":"ri38_21","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢١","segs":[["matn","وَلَا تَحْمِلُ الْعَاقِلَةُ قَتْلَ عَمْدٍ وَلَا اعْتِرَافًا بِهِ، وَتَحْمِلُ مِنْ جِرَاحِ الْخَطَإِ مَا كَانَ قَدْرَ الثُّلُثِ فَأَكْثَرَ، وَمَا كَانَ دُونَ الثُّلُثِ فَفِي مَالِ الْجَانِي،"]]},{"id":"ri38_22","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٢","segs":[["matn","وَأَمَّا الْمَأْمُومَةُ وَالْجَائِفَةُ عَمْدًا فَقَالَ مَالِكٌ: ذَلِكَ عَلَى الْعَاقِلَةِ، وَقَالَ أَيْضًا: إِنَّ ذَلِكَ فِي مَالِهِ إِلَّا أَنْ يَكُونَ عَدِيمًا؛"]]},{"id":"ri38_23","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٣","segs":[["matn","فَتَحْمِلُهُ الْعَاقِلَةُ؛ لِأَنَّهُمَا لَا يُقَادُ مِنْ عَمْدِهِمَا، وَكَذَلِكَ مَا بَلَغَ ثُلُثَ الدِّيَةِ مِمَّا لَا يُقَادُ مِنْهُ؛ لِأَنَّهُ مُتْلِفٌ، وَلَا تَعْقِلُ الْعَاقِلَةُ مَنْ قَتَلَ نَفْسَهُ عَمْدًا أَوْ خَطَأً."]]},{"id":"ri38_24","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٤","segs":[["matn","وَتُعَاقِلُ الْمَرْأَةُ الرَّجُلَ إِلَى ثُلُثِ دِيَةِ الرَّجُلِ، فَإِذَا بَلَغَتْهَا رَجَعَتْ إِلَى عَقْلِهَا، وَالنَّفَرُ يَقْتُلُونَ رَجُلًا فَإِنَّهُمْ يُقْتَلُونَ بِهِ، وَالسَّكْرَانُ إِنْ قَتَلَ قُتِلَ."]]},{"id":"ri38_25","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٥","segs":[["matn","وَإِنْ قَتَلَ مَجْنُونٌ رَجُلًا فَالدِّيَةُ عَلَى عَاقِلَتِهِ، وَعَمْدُ الصَّبِيِّ كَالْخَطَإِ، وَذَلِكَ عَلَى عَاقِلَتِهِ إِنْ كَانَ ثُلُثَ الدِّيَةِ فَأَكْثَرَ، وَإِلَّا فَفِي مَالِهِ."]]},{"id":"ri38_26","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٦","segs":[["matn","وَتُقْتَلُ الْمَرْأَةُ بِالرَّجُلِ، وَالرَّجُلُ بِهَا، وَيُقْتَصُّ لِبَعْضِهِمْ مِنْ بَعْضٍ فِي الْجِرَاحِ."]]},{"id":"ri38_27","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٧","segs":[["matn","وَلَا يُقْتَلُ حُرٌّ بِعَبْدٍ، وَيُقْتَلُ بِهِ الْعَبْدُ، وَلَا يُقْتَلُ مُسْلِمٌ بِكَافِرٍ، وَيُقْتَلُ بِهِ الْكَافِرُ، وَلَا قِصَاصَ بَيْنَ حُرٍّ وَعَبْدٍ، فِي جُرْحٍ."]]},{"id":"ri38_28","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٨","segs":[["matn","وَلَا بَيْنَ مُسْلِمٍ وَكَافِرٍ وَالسَّائِقُ وَالْقَائِدُ وَالرَّاكِبُ ضَامِنُونَ لِمَا وَطِئَتِ الدَّابَّةُ، وَمَا كَانَ مِنْهَا مِنْ غَيْرِ فِعْلِهِمْ أَوْ وَهِيَ وَاقِفَةٌ لِغَيْرِ شَيْءٍ فُعِلَ بِهَا فَذَلِكَ هَدَرٌ، وَمَا مَاتَ فِي بِئْرٍ أَوْ مَعْدِنٍ مِنْ غَيْرِ فِعْلِ أَحَدٍ فَهُوَ هَدَرٌ."]]},{"id":"ri38_29","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٢٩","segs":[["matn","وَتُنَجَّمُ الدِّيَةُ عَلَى الْعَاقِلَةِ فِي ثَلَاثِ سِنِينَ، وَثُلُثُهَا فِي سَنَةٍ، وَنِصْفُهَا فِي سَنَتَيْنِ، وَالِدِّيَةُ مَوْرُوثَةٌ عَلَى الْفَرَائِضِ."]]},{"id":"ri38_30","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٠","segs":[["matn","وَفِي جَنِينِ الْحُرَّةِ غُرَّةٌ: عَبْدٌ أَوْ وَلِيدَةٌ تُقَوَّمُ بِخَمْسِينَ دِينَارًا أَوْ سِتِّمِائَةِ دِرْهَمٍ، وَتُورَثُ عَلَى كِتَابِ اللَّهِ وَلَا يَرِثُ قَاتِلُ الْعَمْدِ مِنْ مَالٍ وَلَا دِيَةٍ، وَقَاتِلُ الْخَطَإِ يَرِثُ مِنَ الْمَالِ دُونَ الدِّيَةِ."]]},{"id":"ri38_31","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣١","segs":[["matn","وَفِي جَنِينِ الْأَمَةِ مِنْ سَيِّدِهَا مَا فِي جَنِينِ الْحُرَّةِ وَإِنْ كَانَ مِنْ غَيْرِهِ فَفِيهِ عُشْرُ قِيمَتِهَا، وَمَنْ قَتَلَ عَبْدًا فَعَلَيْهِ قِيمَتُهُ."]]},{"id":"ri38_32","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٢","segs":[["matn","وَتُقْتَلُ الْجَمَاعَةُ بِالْوَاحِدِ فِي الْحِرَابَةِ وَالْغِيلَةِ وَإِنْ وَلِيَ الْقَتْلَ بَعْضُهُمْ."]]},{"id":"ri38_33","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٣","segs":[["matn","وَكَفَّارَةُ الْقَتْلِ فِي الْخَطَإِ وَاجِبَةٌ: عِتْقُ رَقَبَةٍ مُؤْمِنَةٍ، فَإِنْ لَمْ يَجِدْ فَصِيَامُ شَهْرَيْنِ مُتَتَابِعَيْنِ، وَيُؤْمَرُ بِذَلِكَ إِنْ عُفِيَ عَنْهُ فِي الْعَمْدِ؛ فَهُوَ خَيْرٌ لَهُ."]]},{"id":"ri38_34","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٤","segs":[["matn","وَيُقْتَلُ الزِّنْدِيقُ، وَلَا تُقْبَلُ تَوْبَتُهُ، وَهُوَ الَّذِي يُسِرُّ الْكُفْرَ، وَيُظْهِرُ الْإِسْلَامَ. وَكَذَلِكَ السَّاحِرُ، وَلَا تُقْبَلُ تَوْبَتُهُ."]]},{"id":"ri38_35","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٥","segs":[["matn","وَيُقْتَلُ مَنِ ارْتَدَّ إِلَّا أَنْ يَتُوبَ، وَيُؤَخَّرُ لِلتَّوْبَةِ ثَلَاثًا، وَكَذَلِكَ الْمَرْأَةُ، وَمَنْ لَمْ يَرْتَدَّ، وَأَقَرَّ بِالصَّلَاةِ، وَقَالَ: لَا أُصَلِّي أُخِّرَ حَتَّى يَمْضِيَ وَقْتُ صَلَاةٍ وَاحِدَةٍ؛"]]},{"id":"ri38_36","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٦","segs":[["matn","فَإِنْ لَمْ يُصَلِّهَا قُتِلَ، وَمَنِ امْتَنَعَ مِنَ الزَّكَاةِ أُخِذَتْ مِنْهُ كَرْهًا، وَمَنْ تَرَكَ الْحَجَّ فَاللَّهُ حَسْبُهُ. وَمَنْ تَرَكَ الصَّلَاةَ جَحْدًا لَهَا فَهُوَ كَالْمُرْتَدِّ يُسْتَتَابُ ثَلَاثًا فَإِنْ لَمْ يَتُبْ قُتِلَ."]]},{"id":"ri38_37","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٧","segs":[["matn","وَمَنْ سَبَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُتِلَ، وَلَا تُقْبَلُ تَوْبَتُهُ، وَمَنْ سَبَّهُ مِنْ أَهْلِ الذِّمَّةِ بِغَيْرِ مَا بِهِ كُفْرٌ أَوْ سَبَّ اللَّهَ عَزَّ وَجَلَّ بِغَيْرِ مَا بِهِ كُفْرٌ قُتِلَ إِلَّا أَنْ يُسْلِمَ، وَمِيرَاثُ الْمُرْتَدِّ لِجَمَاعَةِ الْمُسْلِمِينَ."]]},{"id":"ri38_38","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٨","segs":[["matn","وَالْمُحَارِبُ لَا عَفْوَ فِيهِ إِذَا ظُفِرَ بِهِ، فَإِنْ قَتَلَ أَحَدًا فَلَا بُدَّ مِنْ قَتْلِهِ، وَإِنْ لَمْ يَقْتُلْ فَيَسَعُ الْإِمَامُ فِيهِ اجْتِهَادَهُ بِقَدْرِ جُرْمِهِ وَكَثْرَةِ مُقَامِهِ فِي فَسَادِهِ: فَإِمَّا قَتَلَهُ، أَوْ صَلَبَهُ ثُمَّ قَتَلَهُ،"]]},{"id":"ri38_39","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٣٩","segs":[["matn","أَوْ يُقَطِّعُهُ مِنْ خِلَافٍ، أَوْ يَنْفِيهِ إِلَى بَلَدٍ يُسْجَنُ بِهَا حَتَّى يَتُوبَ، فَإِنْ لَمْ يُقْدَرْ عَلَيْهِ حَتَّى جَاءَ تَائِبًا، وُضِعَ عَنْهُ كُلُّ حَقٍّ هُوَ لِلَّهِ مِنْ ذَلِكَ، وَأُخِذَ بِحُقُوقِ النَّاسِ مِنْ مَالٍ أَوْ دَمٍ."]]},{"id":"ri38_40","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٠","segs":[["matn","وَكُلُّ وَاحِدٍ مِنَ اللُّصُوصِ ضَامِنٌ لِجَمِيعِ مَا سَلَبُوهُ مِنَ الْأَمْوَالِ، وَتُقْتَلُ الْجَمَاعَةُ بِالْوَاحِدِ فِي الْحِرَابَةِ وَالْغِيلَةِ وَإِنْ وَلِيَ الْقَتْلَ وَاحِدٌ مِنْهُمْ، وَيُقْتَلُ الْمُسْلِمُ بِقَتْلِ الذِّمِّيِّ قَتْلَ غِيلَةٍ أَوْ حِرَابَةٍ."]]},{"id":"ri38_41","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤١","segs":[["matn","وَمَنْ زَنَى مِنْ حُرٍّ مُحْصَنٍ رُجِمَ حَتَّى يَمُوتَ، وَالْإِحْصَانُ أَنْ يَتَزَوَّجَ امْرَأَةً نِكَاحًا صَحِيحًا وَيَطَأَهَا وَطْئًا صَحِيحًا، فَإِنْ لَمْ يُحْصَنْ جُلِدَ مِائَةَ جَلْدَةٍ،"]]},{"id":"ri38_42","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٢","segs":[["matn","وَغَرَّبَهُ الْإِمَامُ إِلَى بَلَدٍ آخَرَ، وَحُبِسَ فِيهِ عَامًا، وَعَلَى الْعَبْدِ فِي الزِّنَا خَمْسُونَ جَلْدَةً، وَكَذَلِكَ الْأَمَةُ وَإِنْ كَانَا مُتَزَوِّجَيْنِ، وَلَا تَغْرِيبَ عَلَيْهِمَا وَلَا عَلَى امْرَأَةٍ."]]},{"id":"ri38_43","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٣","segs":[["matn","وَلَا يُحَدُّ الزَّانِي إِلَّا بِاعْتِرَافٍ أَوْ بِحَمْلٍ يَظْهَرُ أَوْ بِشَهَادَةِ أَرْبَعَةِ رِجَالٍ أَحْرَارٍ بَالِغِينَ عُدُولٍ يَرَوْنَهُ كَالْمِرْوَدِ فِي الْمُكْحُلَةِ، وَيَشْهَدُونَ فِي وَقْتٍ وَاحِدٍ، وَإِنْ لَمْ يُتِمَّ أَحَدُهُمُ الصِّفَةَ حُدَّ الثَّلَاثَةُ الَّذِينَ أَتَمُّوهَا."]]},{"id":"ri38_44","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٤","segs":[["matn","وَلَا حَدَّ عَلَى مَنْ لَمْ يَحْتَلِمْ، وَيُحَدُّ وَاطِئُ أَمَةِ وَالِدِهِ، وَلَا يُحَدُّ وَاطِئُ أَمَةِ وَلَدِهِ، وَتُقَوَّمُ عَلَيْهِ وَإِنْ لَمْ تَحْمِلْ،"]]},{"id":"ri38_45","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٥","segs":[["matn","وَيُؤَدَّبُ الشَّرِيكُ فِي الْأَمَةِ يَطَؤُهَا، وَيَضْمَنُ قِيمَتَهَا إِنْ كَانَ لَهُ مَالٌ، فَإِنْ لَمْ تَحْمِلْ فَالشَّرِيكُ بِالْخِيَارِ بَيْنَ أَنْ يَتَمَاسَكَ أَوْ تُقَوَّمَ عَلَيْهِ."]]},{"id":"ri38_46","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٦","segs":[["matn","وَإِنْ قَالَتِ امْرَأَةٌ بِهَا حَمْلٌ: اسْتُكْرِهْتُ لَمْ تُصَدَّقْ، وَحُدَّتْ، إِلَّا أَنْ تُعْرَفَ بَيِّنَةٌ أَنَّهَا احْتُمِلَتْ حَتَّى غَابَ عَلَيْهَا أَوْ جَاءَتْ مُسْتَغِيثَةً عِنْدَ النَّازِلَةِ، أَوْ جَاءَتْ تُدْمِي، وَالنَّصْرَانِيُّ إِذَا غَصَبَ الْمُسْلِمَةَ فِي الزِّنَا قُتِلَ، وَإِنْ رَجَعَ الْمُقِرُّ بِالزِّنَا أُقِيلَ، وَتُرِكَ."]]},{"id":"ri38_47","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٧","segs":[["matn","وَيُقِيمُ الرَّجُلُ عَلَى عَبْدِهِ وَأَمَتِهِ حَدَّ الزِّنَا إِذَا ظَهَرَ حَمْلٌ، أَوْ قَامَتْ بَيِّنَةٌ غَيْرِهِ: أَرْبَعَةُ شُهَدَاءَ، أَوْ كَانَ إِقْرَارٌ، وَلَكِنْ إِنْ كَانَ لِلْأَمَةِ زَوْجٌ حُرٌّ أَوْ عَبْدٌ لِغَيْرِهِ فَلَا يُقِيمُ الْحَدَّ عَلَيْهَا إِلَّا السُّلْطَانُ."]]},{"id":"ri38_48","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٨","segs":[["matn","وَمَنْ عَمِلَ عَمَلَ قَوْمِ لُوطٍ بِذَكَرٍ بَالِغٍ أَطَاعَهُ رُجِمَا أُحْصِنَا أَوْ لَمْ يُحْصَنَا."]]},{"id":"ri38_49","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٤٩","segs":[["matn","وَعَلَى الْقَاذِفِ الْحُرِّ الْحَدُّ ثَمَانُونَ، وَعَلَى الْعَبْدِ أَرْبَعُونَ فِي الْقَذْفِ، وَخَمْسُونَ فِي الزِّنَا، وَالْكَافِرُ يُحَدُّ فِي الْقَذْفِ ثَمَانِينَ، وَلَا حَدَّ عَلَى قَاذِفِ عَبْدٍ أَوْ كَافِرٍ، وَيُحَدُّ قَاذِفُ الصَّبِيَّةِ بِالزِّنَا إِنْ كَانَ مِثْلُهَا يُوطَأُ،"]]},{"id":"ri38_50","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٠","segs":[["matn","وَلَا يُحَدُّ قَاذِفُ الصَّبِيِّ، وَلَا حَدَّ عَلَى مَنْ لَمْ يَبْلُغْ فِي قَذْفٍ وَلَا وَطْءٍ، وَمَنْ نَفَى رَجُلًا مِنْ نَسَبِهِ فَعَلَيْهِ الْحَدُّ، وَفِي التَّعْرِيضِ الْحَدُّ، وَمَنْ قَالَ لِرَجُلٍ: يَا لُوطِيُّ حُدَّ."]]},{"id":"ri38_51","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥١","segs":[["matn","وَمَنْ قَذَفَ جَمَاعَةً فَحَدٌّ وَاحِدٌ يَلْزَمُهُ لِمَنْ قَامَ بِهِ مِنْهُمْ، ثُمَّ لَا شَيْءَ عَلَيْهِ."]]},{"id":"ri38_52","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٢","segs":[["matn","وَمَنْ كَرَّرَ شُرْبَ الْخَمْرِ أَوِ الزِّنَا فَحَدٌّ وَاحِدٌ فِي ذَلِكَ كُلِّهِ، وَكَذَلِكَ مَنْ قَذَفَ جَمَاعَةً وَمَنْ لَزِمَتْهُ حُدُودٌ وَقَتْلٌ فَالْقَتْلُ يُجْزِئُ عَنْ ذَلِكَ إِلَّا فِي الْقَذْفِ؛ فَلْيُحَدَّ قَبْلَ أَنْ يُقْتَلَ."]]},{"id":"ri38_53","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٣","segs":[["matn","وَمَنْ شَرِبَ خَمْرًا أَوْ نَبِيذًا مُسْكِرًا حُدَّ ثَمَانِينَ سَكِرَ أَوْ لَمْ يَسْكَرْ، وَلَا سِجْنَ عَلَيْهِ، وَيُجَرَّدُ الْمَحْدُودُ، وَلَا تُجَرَّدُ الْمَرْأَةُ إِلَّا مِمَّا يَقِيهَا الضَّرْبَ، وَيُجْلَدَانِ قَاعِدَيْنِ، وَلَا تُحَدُّ حَامِلٌ حَتَّى تَضَعَ، وَلَا مَرِيضٌ مُثَقَّلٌ، حَتَّى يَبْرَأَ."]]},{"id":"ri38_54","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٤","segs":[["matn","وَلَا يُقْتَلُ وَاطِئُ الْبَهِيمَةِ، وَلْيُعَاقَبْ. وَمَنْ سَرَقَ رُبْعَ دِينَارٍ ذَهَبًا أَوْ مَا قِيمَتُهُ يَوْمَ السَّرِقَةِ ثَلَاثَةُ دَرَاهِمَ مِنَ الْعُرُوضِ أَوْ وَزْنَ ثَلَاثَةِ دَرَاهِمَ فِضَّةً قُطِعَ إِذَا سَرَقَ مِنْ حِرْزٍ، وَلَا قَطْعَ فِي الْخُلْسَةِ،"]]},{"id":"ri38_55","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٥","segs":[["matn","وَيُقْطَعُ فِي ذَلِكَ يَدُ الرَّجُلِ وَالْمَرْأَةِ وَالْعَبْدِ، ثُمَّ إِنْ سَرَقَ قُطِعَتْ رِجْلُهُ مِنْ خِلَافٍ، ثُمَّ إِنْ سَرَقَ فَيَدُهُ، ثُمَّ إِنْ سَرَقَ فَرِجْلُهُ، ثُمَّ إِنْ سَرَقَ جُلِدَ وَسُجِنَ."]]},{"id":"ri38_56","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٦","segs":[["matn","وَمَنْ أَقَرَّ بِسَرِقَةٍ قُطِعَ، وَإِنْ رَجَعَ أُقِيلَ، وَغَرِمَ السَّرِقَةَ إِنْ كَانَتْ مَعَهُ، وَإِلَّا اتُّبِعَ بِهَا، وَمَنْ أَخَذَ فِي الْحِرْزِ لَمْ يُقْطَعْ حَتَّى يُخْرِجَ السَّرِقَةَ مِنَ الْحِرْزِ،"]]},{"id":"ri38_57","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٧","segs":[["matn","وَكَذَلِكَ الْكَفَنُ مِنَ الْقَبْرِ، وَمَنْ سَرَقَ مِنْ بَيْتٍ أُذِنَ لَهُ فِي دُخُولِهِ لَمْ يُقْطَعْ، وَلَا يُقْطَعُ الْمُخْتَلِسُ."]]},{"id":"ri38_58","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٨","segs":[["matn","وَإِقْرَارُ الْعَبْدِ فِيمَا يَلْزَمُهُ فِي بَدَنِهِ مِنْ حَدٍّ أَوْ قَطْعٍ يَلْزَمُهُ، وَمَا كَانَ فِي رَقَبَتِهِ فَلَا إِقْرَارَ لَهُ، وَلَا قَطْعَ فِي ثَمَرٍ مُعَلَّقٍ، وَلَا فِي الْجُمَّارِ فِي النَّخْلِ، وَلَا فِي الْغَنَمِ الرَّاعِيَةِ حَتَّى تُسْرَقَ مِنْ مُرَاحِهَا، وَكَذَلِكَ التَّمْرُ مِنَ الْأَنْدَرِ."]]},{"id":"ri38_59","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٥٩","segs":[["matn","وَلَا يُشْفَعُ لِمَنْ بَلَغَ الْإِمَامَ فِي السَّرِقَةِ وَالزِّنَا، وَاخْتُلِفَ فِي ذَلِكَ فِي الْقَذْفِ، وَمَنْ سَرَقَ مِنَ الْكُمِّ قُطِعَ، وَمَنْ سَرَقَ مِنَ الْهُرْيِ وَبَيْتِ الْمَالِ وَالْمَغْنَمِ فَلْيُقْطَعْ، وَقِيلَ:"]]},{"id":"ri38_60","label":"بَابٌ فِي أَحْكَامِ الدِّمَاءِ وَالْحُدُودِ · ٦٠","segs":[["matn","إِنْ سَرَقَ فَوْقَ حَقِّهِ مِنَ الْمَغْنَمِ بِثَلَاثَةِ دَرَاهِمَ قُطِعَ، وَيُتَّبَعُ السَّارِقُ إِذَا قُطِعَ بِقِيمَةِ مَا فَاتَ مِنَ السَّرِقَةِ فِي مَلَائِهِ، وَلَا يُتَّبَعُ فِي عُدْمِهِ، وَيُتَّبَعُ فِي عُدْمِهِ بِمَا لَا يُقْطَعُ فِيهِ مِنَ السَّرِقَةِ."]]}]},{"id":"ri39","title":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ","units":[{"id":"ri39_1","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١","segs":[["matn","وَالْبَيِّنَةُ عَلَى الْمُدَّعِي، وَالْيَمِينُ عَلَى مَنْ أَنْكَرَ، وَلَا يَمِينَ حَتَّى تَثْبُتَ الْخُلْطَةُ أَوِ الظِّنَّةُ، كَذَلِكَ قَضَى حُكَّامُ أَهْلِ الْمَدِينَةِ، وَقَدْ قَالَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ:"]]},{"id":"ri39_2","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢","segs":[["matn","تَحْدُثُ لِلنَّاسِ أَقْضِيَةٌ بِقَدْرِ مَا أَحْدَثُوا مِنَ الْفُجُورِ، وَإِذَا نَكَلَ الْمُدَّعَى عَلَيْهِ لَمْ يُقْضَ لِلطَّالِبِ حَتَّى يَحْلِفَ فِيمَا يَدَّعِي فِيهِ مَعْرِفَةً."]]},{"id":"ri39_3","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٣","segs":[["matn","وَالْيَمِينُ: بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، وَيَحْلِفُ قَائِمًا، وَعِنْدَ مِنْبَرِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رُبُعِ دِينَارٍ فَأَكْثَرَ، وَفِي غَيْرِ الْمَدِينَةِ يَحْلِفُ فِي ذَلِكَ فِي الْجَامِعِ وَمَوْضِعٍ يُعَظَّمُ مِنْهُ،"]]},{"id":"ri39_4","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٤","segs":[["matn","وَيَحْلِفُ الْكَافِرُ بِاللَّهِ حَيْثُ يُعَظِّمُ، وَإِذَا وَجَدَ الطَّالِبُ بَيِّنَةً بَعْدَ يَمِينِ الْمَطْلُوبِ لَمْ يَكُنْ عَلِمَ بِهَا قُضِيَ لَهُ بِهَا، وَإِنْ كَانَ عَلِمَ بِهَا فَلَا تُقْبَلُ مِنْهُ، وَقَدْ قِيلَ: تُقْبَلُ مِنْهُ."]]},{"id":"ri39_5","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٥","segs":[["matn","وَيُقْضَى بِشَاهِدٍ وَيَمِينٍ فِي الْأَمْوَالِ، وَلَا يُقْضَى بِذَلِكَ فِي نِكَاحٍ أَوْ طَلَاقٍ أَوْ حَدٍّ وَلَا فِي دَمِ عَمْدٍ أَوْ نَفْسٍ إِلَّا مَعَ الْقَسَامَةِ فِي النَّفْسِ، وَقَدْ قِيلَ: يُقْضَى بِذَلِكَ فِي الْجِرَاحِ."]]},{"id":"ri39_6","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٦","segs":[["matn","وَلَا تَجُوزُ شَهَادَةُ النِّسَاءِ إِلَّا فِي الْأَمْوَالِ، وَمِائَةُ امْرَأَةٍ كَامْرَأَتَيْنِ، وَذَلِكَ كَرَجُلٍ وَاحِدٍ؛ يُقْضَى بِذَلِكَ مَعَ رَجُلٍ أَوْ مَعَ الْيَمِينِ فِيمَا يَجُوزُ فِيهِ شَاهِدٌ وَيَمِينٌ، وَشَهَادَةُ امْرَأَتَيْنِ فَقَطْ فِيمَا لَا يَطَّلِعُ عَلَيْهِ الرِّجَالُ مِنَ الْوِلَادَةِ وَالِاسْتِهْلَالِ وَشِبْهِهِ جَائِزَةٌ."]]},{"id":"ri39_7","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٧","segs":[["matn","وَلَا تَجُوزُ شَهَادَةُ خَصْمٍ وَلَا ظَنِينٍ، وَلَا يُقْبَلُ إِلَّا الْعُدُولُ، وَلَا تَجُوزُ شَهَادَةُ الْمَحْدُودِ وَلَا شَهَادَةُ عَبْدٍ وَلَا صَبِيٍّ وَلَا كَافِرٍ، وَإِذَا تَابَ الْمَحْدُودُ فِي الزِّنَا قُبِلَتْ شَهَادَتُهُ إِلَّا فِي الزِّنَا، وَلَا تَجُوزُ شَهَادَةُ الِابْنِ لِلْأَبَوَيْنِ وَلَا هُمَا لَهُ،"]]},{"id":"ri39_8","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٨","segs":[["matn","وَلَا الزَّوْجِ لِلزَّوْجَةِ، وَلَا هِيَ لَهُ، وَتَجُوزُ شَهَادَةُ الْأَخِ الْعَدْلِ لِأَخِيهِ، وَلَا تَجُوزُ شَهَادَةُ مُجَرَّبٍ فِي كَذِبٍ أَوْ مُظْهِرٍ لِكَبِيرَةٍ، وَلَا جَارٍّ لِنَفْسِهِ وَلَا دَافِعٍ عَنْهَا، وَلَا وَصِيٍّ لِيَتِيمِهِ، وَتَجُوزُ شَهَادَتُهُ عَلَيْهِ."]]},{"id":"ri39_9","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٩","segs":[["matn","وَلَا يَجُوزُ تَعْدِيلُ النِّسَاءِ وَلَا تَجْرِيحُهُنَّ، وَلَا يُقْبَلُ فِي التَّزْكِيَةِ إِلَّا مَنْ يَقُولُ: عَدْلٌ رِضًا، وَلَا يُقْبَلُ فِي ذَلِكَ وَلَا فِي التَّجْرِيحِ وَاحِدٌ."]]},{"id":"ri39_10","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٠","segs":[["matn","وَتُقْبَلُ شَهَادَةُ الصِّبْيَانِ فِي الْجِرَاحِ قَبْلَ أَنْ يَفْتَرِقُوا أَوْ يَدْخُلَ بَيْنَهُمْ كَبِيرٌ. وَإِذَا اخْتَلَفَ الْمُتَبَايِعَانِ اسْتُحْلِفَ الْبَائِعُ، ثُمَّ يَأْخُذُ الْمُبْتَاعُ أَوْ يَحْلِفُ، وَيَبْرَأُ وَإِذَا اخْتَلَفَ الْمُتَدَاعِيَانِ فِي شَيْءٍ بِأَيْدِيهِمَا حَلَفَا؛"]]},{"id":"ri39_11","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١١","segs":[["matn","وَقُسِمَ بَيْنَهُمَا، وَإِنْ أَقَامَا بَيِّنَتَيْنِ قُضِيَ بِأَعْدَلِهِمَا، فَإِنِ اسْتَوَيَا حَلَفَا وَكَانَ بَيْنَهُمَا، وَإِذَا رَجَعَ الشَّاهِدُ بَعْدَ الْحُكْمِ أُغْرِمَ مَا أَتْلَفَ بِشَهَادَتِهِ إِنِ اعْتَرَفَ أَنَّهُ شَهِدَ بِزُورٍ، قَالَهُ أَصْحَابُ مَالِكٍ."]]},{"id":"ri39_12","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٢","segs":[["matn","وَمَنْ قَالَ: رَدَدْتُ إِلَيْكَ مَا وَكَّلْتَنِي عَلَيْهِ، أَوْ عَلَى بَيْعِهِ، أَوْ دَفَعْتُ إِلَيْكَ ثَمَنَهُ، أَوْ وَدِيعَتَكَ، أَوْ قِرَاضَكَ فَالْقَوْلُ قَوْلُهُ، وَمَنْ قَالَ: دَفَعْتُ إِلَى فُلَانٍ كَمَا أَمَرْتَنِي، فَأَنْكَرَ فُلَانٌ فَعَلَى الدَّافِعِ الْبَيِّنَةُ وَإِلَّا ضَمِنَ،"]]},{"id":"ri39_13","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٣","segs":[["matn","وَكَذَلِكَ عَلَى وَلِيِّ الْأَيْتَامِ الْبَيِّنَةُ أَنَّهُ أَنْفَقَ عَلَيْهِمْ أَوْ دَفَعَ إِلَيْهِمْ وَإِنْ كَانُوا فِي حَضَانَتِهِ صُدِّقَ فِي النَّفَقَةِ فِيمَا يُشْبِهُ وَالصُّلْحُ جَائِزٌ إِلَّا مَا جَرَّ إِلَى حَرَامٍ،"]]},{"id":"ri39_14","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٤","segs":[["matn","وَيَجُوزُ عَلَى الْإِقْرَارِ وَالْإِنْكَارِ، وَالْأَمَةُ الْغَارَّةُ تَتَزَوَّجُ عَلَى إِنَّهَا حُرَّةٌ، فَلِسَيِّدِهَا أَخْذُهَا وَأَخْذُ قِيمَةِ الْوَلَدِ يَوْمَ الْحُكْمِ لَهُ."]]},{"id":"ri39_15","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٥","segs":[["matn","وَمَنِ اسْتَحَقَّ أَمَةً قَدْ وَلَدَتْ فَلَهُ قِيمَتُهَا وَقِيمَةُ الْوَلَدِ يَوْمَ الْحُكْمِ، وَقِيلَ: يَأْخُذُهَا وَقِيمَةَ الْوَلَدِ، وَقِيلَ: لَهُ قِيمَتُهَا فَقَطْ، إِلَّا أَنْ يَخْتَارَ الثَّمَنَ، فَيَأْخُذَهُ مِنَ الْغَاصِبِ الَّذِي بَاعَهَا، وَلَوْ كَانَتْ بِيَدِ غَاصِبٍ فَعَلَيْهِ الْحَدُّ، وَوَلَدُهُ رَقِيقٌ مَعَهَا لِرَبِّهَا."]]},{"id":"ri39_16","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٦","segs":[["matn","وَمُسْتَحِقُّ الْأَرْضِ بَعْدَ أَنْ عَمَرَتْ يَدْفَعُ قِيمَةَ الْعِمَارَةِ قَائِمًا، فَإِنْ أَبَى دَفَعَ إِلَيْهِ الْمُشْتَرِي قِيمَةَ الْبُقْعَةِ بَرَاحًا فَإِنْ أَبَى كَانَا شَرِيكَيْنِ بِقِيمَةِ مَا لِكُلِّ وَاحِدٍ."]]},{"id":"ri39_17","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٧","segs":[["matn","وَالْغَاصِبُ يُؤْمَرُ بِقَلْعِ بِنَائِهِ وَزَرْعِهِ وَشَجَرِهِ، وَإِنْ شَاءَ أَعْطَاهُ رَبُّهَا قِيمَةَ ذَلِكَ النُّقْضِ وَالشَّجَرِ مُلْقًى بَعْدَ قِيمَةِ أَجْرِ مَنْ يَقْلَعُ ذَلِكَ، وَلَا شَيْءَ عَلَيْهِ فِيمَا لَا قِيمَةَ لَهُ بَعْدَ الْقَلْعِ وَالْهَدْمِ، وَيَرُدُّ الْغَاصِبُ الْغَلَّةَ،"]]},{"id":"ri39_18","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٨","segs":[["matn","وَلَا يَرُدُّهَا غَيْرُ الْغَاصِبِ، وَالْوَلَدُ فِي الْحَيَوَانِ وَفِي الْأَمَةِ إِذَا كَانَ الْوَلَدُ مِنْ غَيْرِ السَّيِّدِ يَأْخُذُهُ الْمُسْتَحِقُّ لِلْأُمَّهَاتِ مِنْ يَدِ مُبْتَاعٍ أَوْ غَيْرِهِ، وَمَنْ غَصَبَ أَمَةً، ثُمَّ وَطِئَهَا؛ فَوَلَدُهُ رَقِيقٌ، وَعَلَيْهِ الْحَدُّ."]]},{"id":"ri39_19","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ١٩","segs":[["matn","وَإِصْلَاحُ السُّفْلِ عَلَى صَاحِبِ السُّفْلِ، وَالْخَشَبُ لِلسَّقْفِ عَلَيْهِ، وَتَعْلِيقُ الْغُرَفِ عَلَيْهِ إِذَا وَهِيَ السُّفْلُ وَهُدِمَ حَتَّى يُصْلَحَ، وَيُجْبَرُ عَلَى أَنْ يُصْلِحَ أَوْ يَبِيعَ مِمَّنْ يُصْلِحُ؛"]]},{"id":"ri39_20","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٠","segs":[["matn","وَلَا ضَرَرَ وَلَا ضِرَارَ فَلَا يَفْعَلُ مَا يَضُرُّ بِجَارِهِ مِنْ فَتْحِ كُوَّةٍ قَرِيبَةٍ يَكْشِفُ جَارَهُ مِنْهَا، أَوْ فَتْحِ بَابٍ قُبَالَةَ بَابِهِ، أَوْ حَفْرِ مَا يَضُرُّ بِجَارِهِ فِي حَفْرِهِ وَإِنْ كَانَ فِي مِلْكِهِ، وَيُقْضَى بِالْحَائِطِ لِمَنْ إِلَيْهِ الْقِمْطُ وَالْعُقُودُ."]]},{"id":"ri39_21","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢١","segs":[["matn","وَلَا يُمْنَعُ فَضْلُ الْمَاءِ لِيُمْنَعَ بِهِ الْكَلَأُ، وَأَهْلُ آبَارِ الْمَاشِيَةِ أَحَقُّ بِهَا حَتَّى يَسْقُوا، ثُمَّ النَّاسُ فِيهَا سَوَاءٌ، وَمَنْ كَانَ فِي أَرْضِهِ عَيْنٌ أَوْ بِئْرٌ فَلَهُ مَنْعُهَا،"]]},{"id":"ri39_22","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٢","segs":[["matn","إِلَّا أَنْ تَنْهَدِمَ بِئْرُ جَارِهِ وَلَهُ زَرْعٌ يَخَافُ عَلَيْهِ فَلَا يَمْنَعُهُ فَضْلَهُ، وَاخْتُلِفَ هَلْ عَلَيْهِ فِي ذَلِكَ ثَمَنٌ أَمْ لَا؟"]]},{"id":"ri39_23","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٣","segs":[["matn","وَيَنْبَغِي أَنْ لَا يَمْنَعَ الرَّجُلُ جَارَهُ أَنْ يَغْرِزَ خَشَبَهُ فِي جِدَارِهِ، وَلَا يُقْضَى عَلَيْهِ."]]},{"id":"ri39_24","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٤","segs":[["matn","وَمَا أَفْسَدَتِ الْمَاشِيَةُ مِنَ الزَّرْعِ وَالْحَوَائِطِ بِاللَّيْلِ فَذَلِكَ عَلَى أَرْبَابِ الْمَاشِيَةِ، وَلَا شَيْءَ عَلَيْهِمْ فِي فَسَادِ النَّهَارِ."]]},{"id":"ri39_25","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٥","segs":[["matn","وَمَنْ وَجَدَ سِلْعَتَهُ فِي التَّفْلِيسِ فَإِمَّا حَاصَصَ وَإِلَّا أَخَذَ سِلْعَتَهُ إِنْ كَانَتْ تُعْرَفُ بِعَيْنِهَا، وَهُوَ فِي الْمَوْتِ أُسْوَةُ الْغُرَمَاءِ."]]},{"id":"ri39_26","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٦","segs":[["matn","وَالضَّامِنُ غَارِمٌ، وَحَمِيلُ الْوَجْهِ إِنْ لَمْ يَأْتِ بِهِ غَرِمَ حَتَّى يَشْتَرِطَ أَنْ لَا يَغْرَمَ."]]},{"id":"ri39_27","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٧","segs":[["matn","وَمَنْ أُحِيلَ بِدَيْنٍ فَرَضِيَ فَلَا رُجُوعَ لَهُ عَلَى الْأَوَّلِ وَإِنْ أَفْلَسَ هَذَا، إِلَّا أَنْ يَغُرَّهُ مِنْهُ، وَإِنَّمَا الْحَوَالَةُ عَلَى أَصْلِ دَيْنٍ، وَإِلَّا فَهِيَ حَمَالَةٌ، وَلَا يَغْرَمُ الْحَمِيلُ إِلَّا فِي عُدْمِ الْغَرِيمِ أَوْ غَيْبَتِهِ."]]},{"id":"ri39_28","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٨","segs":[["matn","وَيَحِلُّ بِمَوْتِ الْمَطْلُوبِ أَوْ تَفْلِيسِهِ كُلُّ دَيْنٍ عَلَيْهِ، وَلَا يَحِلُّ مَا كَانَ لَهُ عَلَى غَيْرِهِ، وَلَا تُبَاعُ رَقَبَةُ الْمَأْذُونِ فِيمَا عَلَيْهِ، وَلَا يُتَّبَعُ بِهِ سَيِّدُهُ."]]},{"id":"ri39_29","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٢٩","segs":[["matn","وَيُحْبَسُ الْمِدْيَانُ لِيُسْتَبْرَأَ وَلَا حَبْسَ عَلَى مُعْدِمٍ. وَمَا انْقَسَمَ بِلَا ضَرَرٍ قُسِمَ مِنْ رَبْعٍ وَعَقَارٍ، وَمَا لَمْ يَنْقَسِمْ بِغَيْرِ ضَرَرٍ فَمَنْ دَعَا إِلَى الْبَيْعِ أُجْبِرَ عَلَيْهِ مَنْ أَبَاهُ،"]]},{"id":"ri39_30","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٣٠","segs":[["matn","وَقَسْمُ الْقُرْعَةِ لَا يَكُونُ إِلَّا فِي صِنْفٍ وَاحِدٍ، وَلَا يُؤَدِّي أَحَدُ الشُّرَكَاءِ ثَمَنًا، وَإِنْ كَانَ فِي ذَلِكَ تَرَاجُعٌ لَمْ يَجُزِ الْقَسْمُ إِلَّا بِتَرَاضٍ."]]},{"id":"ri39_31","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٣١","segs":[["matn","وَوَصِيُّ الْوَصِيِّ كَالْوَصِيِّ، وَلِلْوَصِيِّ أَنْ يَتَّجِرَ بِأَمْوَالِ الْيَتَامَى وَيُزَوِّجَ إِمَاءَهُمْ، وَمَنْ أَوْصَى إِلَى غَيْرِ مَأْمُونٍ فَإِنَّهُ يُعْزَلُ، وَيُبْدَأُ بِالْكَفَنِ ثُمَّ الدَّيْنِ ثُمَّ الْوَصِيَّةِ ثُمَّ الْمِيرَاثِ."]]},{"id":"ri39_32","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٣٢","segs":[["matn","وَمَنْ حَازَ دَارًا عَلَى حَاضِرٍ عَشْرَ سِنِينَ تُنْسَبُ إِلَيْهِ وَصَاحِبُهَا حَاضِرٌ عَالِمٌ لَا يَدَّعِي شَيْئًا فَلَا قِيَامَ لَهُ، وَلَا حِيَازَةَ بَيْنَ الْأَقَارِبِ وَالْأَصْهَارِ فِي مِثْلِ هَذِهِ الْمُدَّةِ."]]},{"id":"ri39_33","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٣٣","segs":[["matn","وَلَا يَجُوزُ إِقْرَارُ الْمَرِيضِ لِوَارِثِهِ بِدَيْنٍ أَوْ بِقَبْضِهِ. وَمَنْ أَوْصَى بِحَجٍّ أَنُفِذَ وَالْوَصِيَّةُ بِالصَّدَقَةِ أَحَبُّ إِلَيْنَا، وَإِذَا مَاتَ أَجِيرُ الْحَجِّ قَبْلَ أَنْ يَصِلَ فَلَهُ بِحِسَابِ مَا سَارَ، وَيَرُدُّ مَا بَقِيَ،"]]},{"id":"ri39_34","label":"بَابٌ فِي الْأَقْضِيَةِ وَالشَّهَادَاتِ · ٣٤","segs":[["matn","وَمَا هَلَكَ بِيَدِهِ فَهُوَ مِنْهُ إِلَّا أَنْ يَأْخُذَ الْمَالَ عَلَى أَنْ يُنْفِقَ عَلَى الْبَلَاغِ فَالضَّمَانُ مِنَ الَّذِينَ وَاجَرُوهُ، وَيَرُدُّ مَا فَضَلَ إِنْ فَضَلَ شَيْءٌ."]]}]},{"id":"ri40","title":"بَابٌ فِي الْفَرَائِضِ","units":[{"id":"ri40_1","label":"بَابٌ فِي الْفَرَائِضِ · ١","segs":[["matn","وَلَا يَرِثُ مِنَ الرِّجَالِ إِلَّا عَشَرَةٌ: الِابْنُ، وَابْنُ الِابْنِ وَإِنْ سَفَلَ، وَالْأَبُ وَالْجَدُّ لِلْأَبِ وَإِنْ عَلَا وَالْأَخُ وَابْنُ الْأَخِ وَإِنْ بَعُدَ، وَالْعَمُّ وَابْنُ الْعَمِّ وَإِنْ بَعُدَ، وَالزَّوْجُ، وَمَوْلَى النِّعْمَةِ."]]},{"id":"ri40_2","label":"بَابٌ فِي الْفَرَائِضِ · ٢","segs":[["matn","وَلَا يَرِثُ مِنَ النِّسَاءِ غَيْرُ سَبْعٍ: الْبِنْتُ وَبِنْتُ الِابْنِ وَالْأُمُّ وَالْجَدَّةُ وَالْأُخْتُ وَالزَّوْجَةُ وَمَوْلَاةُ النِّعْمَةِ."]]},{"id":"ri40_3","label":"بَابٌ فِي الْفَرَائِضِ · ٣","segs":[["matn","فَمِيرَاثُ الزَّوْجِ مِنَ الزَّوْجَةِ إِنْ لَمْ تَتْرُكْ وَلَدًا وَلَا وَلَدَ ابْنٍ النِّصْفُ، فَإِنْ تَرَكَتْ وَلَدًا أَوْ وَلَدَ ابْنٍ مِنْهُ أَوْ مِنْ غَيْرِهِ فَلَهُ الرُّبُعُ."]]},{"id":"ri40_4","label":"بَابٌ فِي الْفَرَائِضِ · ٤","segs":[["matn","وَتَرِثُ هِيَ مِنْهُ الرُّبُعَ إِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَلَا وَلَدُ ابْنٍ، فَإِنْ كَانَ لَهُ وَلَدٌ أَوْ وَلَدُ ابْنٍ مِنْهَا أَوْ مِنْ غَيْرِهَا فَلَهَا الثُّمُنُ."]]},{"id":"ri40_5","label":"بَابٌ فِي الْفَرَائِضِ · ٥","segs":[["matn","وَمِيرَاثُ الْأُمِّ مِنِ ابْنِهَا الثُّلُثُ إِنْ لَمْ يَتْرُكْ وَلَدًا أَوْ وَلَدَ ابْنٍ أَوِ اثْنَيْنِ مِنَ الْإِخْوَةِ مَا كَانُوا فَصَاعِدًا، إِلَّا فِي فَرِيضَتَيْنِ: فِي زَوْجَةٍ وَأَبَوَيْنِ؛ فَلِلزَّوْجَةِ الرُّبُعُ، وَلِلْأُمِّ ثُلُثُ مَا بَقِيَ، وَمَا بَقِيَ لِلْأَبِ."]]},{"id":"ri40_6","label":"بَابٌ فِي الْفَرَائِضِ · ٦","segs":[["matn","وَفِي زَوْجٍ وَأَبَوَيْنِ؛ فَلِلزَّوْجِ النِّصْفُ، وَلِلْأُمِّ ثُلُثُ مَا بَقِيَ، وَمَا بَقِيَ لِلْأَبِ، وَلَهَا فِي غَيْرِ ذَلِكَ الثُّلُثُ إِلَّا مَا نَقَصَهَا الْعَوْلُ، إِلَّا أَنْ يَكُونَ لِلْمَيِّتِ وَلَدٌ أَوْ وَلَدُ ابْنٍ أَوِ اثْنَانِ مِنَ الْإِخْوَةِ مَا كَانَا فَلَهَا السُّدُسُ حِينَئِذٍ."]]},{"id":"ri40_7","label":"بَابٌ فِي الْفَرَائِضِ · ٧","segs":[["matn","وَمِيرَاثُ الْأَبِ مِنْ وَلَدِهِ إِذَا انْفَرَدَ وَرِثَ الْمَالَ كُلَّهُ، وَيُفْرَضُ لَهُ مَعَ الْوَلَدِ الذَّكَرِ أَوْ وَلَدِ الِابْنِ السُّدُسُ،"]]},{"id":"ri40_8","label":"بَابٌ فِي الْفَرَائِضِ · ٨","segs":[["matn","فَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَلَا وَلَدُ ابْنٍ فُرِضَ لِلْأَبِ السُّدُسُ، وَأُعْطِيَ مَنْ شَرِكَهُ مِنْ أَهْلِ السِّهَامِ سِهَامَهُمْ، ثُمَّ كَانَ لَهُ مَا بَقِيَ."]]},{"id":"ri40_9","label":"بَابٌ فِي الْفَرَائِضِ · ٩","segs":[["matn","وَمِيرَاثُ الْوَلَدِ الذَّكَرِ جَمِيعُ الْمَالِ إِنْ كَانَ وَحْدَهُ، أَوْ يَأْخُذُ مَا بَقِيَ بَعْدَ سِهَامِ مَنْ مَعَهُ مِنْ زَوْجَةٍ وَأَبَوَيْنِ أَوْ جَدٍّ أَوْ جَدَّةٍ، وَابْنُ الِابْنِ بِمَنْزِلَةِ الِابْنِ إِذَا لَمْ يَكُنِ ابْنٌ،"]]},{"id":"ri40_10","label":"بَابٌ فِي الْفَرَائِضِ · ١٠","segs":[["matn","فَإِنْ كَانَ ابْنٌ وَابْنَةٌ فَلِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ، وَكَذَلِكَ فِي كَثْرَةِ الْبَنِينَ وَالْبَنَاتِ وَقِلَّتِهِمْ يَرِثُونَ كَذَلِكَ جَمِيعَ الْمَالِ، أَوْ مَا فَضَلَ مِنْهُ بَعْدَ مَنْ شَرِكَهُمْ مِنْ أَهْلِ السِّهَامِ، وَابْنُ الِابْنِ كَالِابْنِ فِي عَدَمِهِ فِيمَا يَرِثُ وَيَحْجُبُ."]]},{"id":"ri40_11","label":"بَابٌ فِي الْفَرَائِضِ · ١١","segs":[["matn","وَمِيرَاثُ الْبِنْتِ الْوَاحِدَةِ النِّصْفُ، وَالِاثْنَتَيْنِ الثُّلُثَانِ، فَإِنْ كَثُرْنَ لَمْ يَزِدْنَ عَلَى الثُّلُثَيْنِ شَيْئًا."]]},{"id":"ri40_12","label":"بَابٌ فِي الْفَرَائِضِ · ١٢","segs":[["matn","وَابْنَةُ الِابْنِ كَالْبِنْتِ إِذَا لَمْ تَكُنْ بِنْتٌ، وَكَذَلِكَ بَنَاتُهُ كَالْبَنَاتِ فِي عَدَمِ الْبَنَاتِ، فَإِنْ كَانَتِ ابْنَةُ وَابْنَةُ ابْنٍ فَلِلِابْنَةِ النِّصْفُ، وَلِابْنَةِ الِابْنِ السُّدُسُ تَمَامُ الثُّلُثَيْنِ،"]]},{"id":"ri40_13","label":"بَابٌ فِي الْفَرَائِضِ · ١٣","segs":[["matn","وَإِنْ كَثُرَتْ بَنَاتُ الِابْنِ لَمْ يَزِدْنَ عَلَى ذَلِكَ السُّدُسِ، شَيْئًا إِنْ لَمْ يَكُنْ مَعَهُنَّ ذَكَرٌ وَمَا بَقِيَ لِلْعَصَبَةِ وَإِنْ كَانَتِ الْبَنَاتُ اثْنَتَيْنِ لَمْ يَكُنْ لِبَنَاتِ الِابْنِ شَيْءٌ،"]]},{"id":"ri40_14","label":"بَابٌ فِي الْفَرَائِضِ · ١٤","segs":[["matn","إِلَّا أَنْ يَكُونَ مَعَهُنَّ أَخٌ فَيَكُونُ مَا بَقِيَ بَيْنَهُنَّ وَبَيْنَهُ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ، وَكَذَلِكَ إِذَا كَانَ ذَلِكَ الذَّكَرُ تَحْتَهُنَّ كَانَ ذَلِكَ بَيْنَهُ وَبَيْنَهُنَّ كَذَلِكَ، وَكَذَلِكَ لَوْ وَرِثَ بَنَاتُ الِابْنِ مَعَ الِابْنَةِ السُّدُسَ،"]]},{"id":"ri40_15","label":"بَابٌ فِي الْفَرَائِضِ · ١٥","segs":[["matn","وَتَحْتَهُنَّ بَنَاتُ ابْنٍ مَعَهُنَّ أَوْ تَحْتَهُنَّ ذَكَرٌ كَانَ ذَلِكَ بَيْنَهُ وَبَيْنَ أَخَوَاتِهِ أَوْ مَنْ فَوْقَهُ مِنْ عَمَّاتِهِ، وَلَا يَدْخُلُ فِي ذَلِكَ مَنْ دَخَلَ فِي الثُّلُثَيْنِ مِنْ بَنَاتِ الِابْنِ."]]},{"id":"ri40_16","label":"بَابٌ فِي الْفَرَائِضِ · ١٦","segs":[["matn","وَمِيرَاثُ الْأُخْتِ الشَّقِيقَةِ النِّصْفُ، وَالِاثْنَتَيْنِ فَصَاعِدًا الثُّلُثَانِ، فَإِنْ كَانُوا إِخْوَةً وَأَخَوَاتٍ شَقَائِقَ أَوْ لِأَبٍ فَالْمَالُ بَيْنَهُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ قَلُّوا أَوْ كَثُرُوا، وَالْأَخَوَاتُ مَعَ الْبَنَاتِ كَالْعَصَبَةِ لَهُنَّ يَرِثْنَ مَا فَضَلَ عَنْهُنَّ، وَلَا يُرْبَى لَهُنَّ مَعَهُنَّ."]]},{"id":"ri40_17","label":"بَابٌ فِي الْفَرَائِضِ · ١٧","segs":[["matn","وَلَا مِيرَاثَ لِلْإِخْوَةِ وَالْأَخَوَاتِ مَعَ الْأَبِ وَلَا مَعَ الْوَلَدِ الذَّكَرِ أَوْ مَعَ وَلَدِ الْوَلَدِ. وَالْإِخْوَةُ لِلْأَبِ فِي عَدَمِ الشَّقَائِقِ كَالشَّقَائِقِ ذُكُورِهِمْ وَإِنَاثِهِمْ، فَإِنْ كَانَتْ أُخْتٌ شَقِيقَةٌ وَأُخْتٌ أَوْ أَخَوَاتٌ لِأَبٍ؛"]]},{"id":"ri40_18","label":"بَابٌ فِي الْفَرَائِضِ · ١٨","segs":[["matn","فَالنِّصْفُ لِلشَّقِيقَةِ، وَلِمَنْ بَقِيَ مِنَ الْأَخَوَاتِ لِلْأَبِ السُّدُسُ، وَلَوْ كَانَتَا شَقِيقَتَيْنِ لَمْ يَكُنْ لِلْأَخَوَاتِ لِلْأَبِ شَيْءٌ، إِلَّا أَنْ يَكُونَ مَعَهُنَّ ذَكَرٌ فَيَأْخُذُونَ مَا بَقِيَ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ."]]},{"id":"ri40_19","label":"بَابٌ فِي الْفَرَائِضِ · ١٩","segs":[["matn","وَمِيرَاثُ الْأُخْتِ لِلْأُمِّ وَالْأَخِ لِلْأُمِّ سَوَاءٌ؛ السُّدُسُ لِكُلِّ وَاحِدٍ، وَإِنْ كَثُرُوا فَالثُّلُثُ بَيْنَهُمُ الذَّكَرُ وَالْأُنْثَى فِيهِ سَوَاءٌ، وَيَحْجُبُهُمْ عَنِ الْمِيرَاثِ الْوَلَدُ وَبَنُوهُ وَالْأَبُ وَالْجَدُّ لِلْأَبِ."]]},{"id":"ri40_20","label":"بَابٌ فِي الْفَرَائِضِ · ٢٠","segs":[["matn","وَالْأَخُ يَرِثُ الْمَالَ إِذَا انْفَرَدَ كَانَ شَقِيقًا أَوْ لِأَبٍ، وَالشَّقِيقُ يَحْجُبُ الْأَخَ لِلْأَبِ، وَإِنْ كَانَ أَخٌ وَأُخْتٌ فَأَكْثَرُ شَقَائِقَ أَوْ لِأَبٍ فَالْمَالُ بَيْنَهُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ،"]]},{"id":"ri40_21","label":"بَابٌ فِي الْفَرَائِضِ · ٢١","segs":[["matn","وَإِنْ كَانَ مَعَ الْأَخِ ذُو سَهْمٍ بُدِئَ بِأَهْلِ السِّهَامِ، وَكَانَ لَهُ مَا بَقِيَ، وَكَذَلِكَ يَكُونُ مَا بَقِيَ لِلْإِخْوَةِ وَالْأَخَوَاتِ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ، فَإِنْ لَمْ يَبْقَ شَيْءٌ فَلَا شَيْءَ لَهُمْ."]]},{"id":"ri40_22","label":"بَابٌ فِي الْفَرَائِضِ · ٢٢","segs":[["matn","إِلَّا أَنْ يَكُونَ فِي أَهْلِ السِّهَامِ إِخْوَةٌ لِأُمٍّ قَدْ وَرِثُوا الثُّلُثَ، وَقَدْ بَقِيَ أَخٌ شَقِيقٌ أَوْ إِخْوَةٌ ذُكُورٌ أَوْ ذُكُورٌ وَإِنَاثٌ شَقَائِقُ مَعَهُمْ فَيُشَارِكُونَ كُلُّهُمُ الْإِخْوَةَ لِلْأُمِّ فِي ثُلُثِهِمْ فَيَكُونُ بَيْنَهُمْ بِالسَّوَاءِ،"]]},{"id":"ri40_23","label":"بَابٌ فِي الْفَرَائِضِ · ٢٣","segs":[["matn","وَهِيَ الْفَرِيضَةُ الَّتِي تُسَمَّى الْمُشْتَرَكَةَ، وَلَوْ كَانَ مَنْ بَقِيَ إِخْوَةٌ لِأَبٍ لَمْ يُشَارِكُوا الْإِخْوَةَ لِلْأُمِّ لِخُرُوجِهِمْ عَنْ وِلَادَةِ الْأُمِّ،"]]},{"id":"ri40_24","label":"بَابٌ فِي الْفَرَائِضِ · ٢٤","segs":[["matn","وَإِنْ كَانَ مَنْ بَقِيَ أُخْتًا أَوْ أَخَوَاتٍ لِأَبَوَيْنِ أَوْ لِأَبٍ أُعِيلَ لَهُنَّ وَإِنْ كَانَ مِنْ قِبَلِ الْأُمِّ أَخٌ"]]},{"id":"ri40_25","label":"بَابٌ فِي الْفَرَائِضِ · ٢٥","segs":[["matn","وَاحِدٌ أَوْ أُخْتٌ لَمْ تَكُنْ مُشْتَرِكَةً وَكَانَ مَا بَقِيَ لِلْإِخْوَةِ إِنْ كَانُوا ذُكُورًا أَوْ ذُكُورًا وَإِنَاثًا وَإِنْ كُنَّ إِنَاثًا لِأَبَوَيْنِ أَوْ لِأَبٍ أُعِيلَ لَهُنَّ،"]]},{"id":"ri40_26","label":"بَابٌ فِي الْفَرَائِضِ · ٢٦","segs":[["matn","وَالْأَخُ لِلْأَبِ كَالشَّقِيقِ فِي عَدَمِ الشَّقِيقِ إِلَّا فِي الْمُشْتَرَكَةِ."]]},{"id":"ri40_27","label":"بَابٌ فِي الْفَرَائِضِ · ٢٧","segs":[["matn","وَابْنُ الْأَخِ كَالْأَخِ فِي عَدَمِ الْأَخِ؛ كَانَ شَقِيقًا أَوْ لِأَبٍ، وَلَا يَرِثُ ابْنُ الْأَخِ لِلْأُمِّ، وَالْأَخُ لِلْأَبَوَيْنِ يَحْجُبُ الْأَخَ لِلْأَبِ، وَالْأَخُ لِلْأَبِ أَوْلَى مِنِ ابْنِ أَخٍ شَقِيقٍ، وَابْنُ أَخٍ شَقِيقٍ أَوْلَى مِنِ ابْنِ أَخٍ لِأَبٍ،"]]},{"id":"ri40_28","label":"بَابٌ فِي الْفَرَائِضِ · ٢٨","segs":[["matn","وَابْنُ أَخٍ لِأَبٍ يَحْجُبُ عَمًّا لِأَبَوَيْنِ، وَعَمٌّ لِأَبَوَيْنِ يَحْجُبُ عَمًّا لِأَبٍ، وَعَمٌّ لِأَبٍ يَحْجُبُ ابْنَ عَمٍّ لِأَبَوَيْنِ، وَابْنُ عَمٍّ لِأَبَوَيْنِ يَحْجُبُ ابْنَ عَمٍّ لِأَبٍ؛ وَهَكَذَا يَكُونُ الْأَقْرَبُ أَوْلَى."]]},{"id":"ri40_29","label":"بَابٌ فِي الْفَرَائِضِ · ٢٩","segs":[["matn","وَلَا يَرِثُ بَنُو الْأَخَوَاتِ مَا كُنَّ، وَلَا بَنُو الْبَنَاتِ وَلَا بَنَاتُ الْأَخِ مَا كَانَ، وَلَا بَنَاتُ الْعَمِّ، وَلَا جَدٌّ لِأُمٍّ، وَلَا عَمٌّ: أَخُو أَبِيكَ لِأُمِّهِ."]]},{"id":"ri40_30","label":"بَابٌ فِي الْفَرَائِضِ · ٣٠","segs":[["matn","وَلَا يَرِثُ عَبْدٌ وَلَا مَنْ فِيهِ بَقِيَّةُ رِقٍّ، وَلَا يَرِثُ الْمُسْلِمُ الْكَافِرَ وَلَا الْكَافِرُ الْمُسْلِمَ، وَلَا ابْنُ أَخٍ لِأُمٍّ، وَلَا جَدٌّ لِأُمٍّ، وَلَا أُمُّ أَبِي الْأُمِّ، وَلَا تَرِثُ أُمُّ أَبِي الْأَبِ مَعَ وَلَدِهَا أَبِي الْمَيِّتِ،"]]},{"id":"ri40_31","label":"بَابٌ فِي الْفَرَائِضِ · ٣١","segs":[["matn","وَلَا تَرِثُ إِخْوَةٌ لِأُمٍّ مَعَ الْجَدِّ لِلْأَبِ وَلَا مَعَ الْوَلَدِ وَوَلَدِ الْوَلَدِ ذَكَرًا كَانَ الْوَلَدُ أَوْ أُنْثَى، وَلَا مِيرَاثَ لِلْإِخْوَةِ مَعَ الْأَبِ مَا كَانُوا، وَلَا يَرِثُ عَمٌّ مَعَ الْجَدِّ، وَلَا ابْنُ أَخٍ مَعَ الْجَدِّ."]]},{"id":"ri40_32","label":"بَابٌ فِي الْفَرَائِضِ · ٣٢","segs":[["matn","وَلَا يَرِثُ قَاتِلُ الْعَمْدِ مِنْ مَالٍ وَلَا دِيَةٍ، وَلَا يَرِثُ قَاتِلُ الْخَطَإِ مِنَ الدِّيَةِ، وَيَرِثُ مِنَ الْمَالِ، وَكُلُّ مَنْ لَا يَرِثُ بِحَالٍ فَلَا يَحْجُبُ وَارِثًا."]]},{"id":"ri40_33","label":"بَابٌ فِي الْفَرَائِضِ · ٣٣","segs":[["matn","وَالْمُطَلَّقَةُ ثَلَاثًا فِي الْمَرَضِ تَرِثُ زَوْجَهَا إِنْ مَاتَ مِنْ مَرَضِهِ ذَلِكَ، وَلَا يَرِثُهَا، وَكَذَلِكَ إِنْ كَانَ الطَّلَاقُ وَاحِدَةً وَقَدْ مَاتَ مِنْ مَرَضِهِ ذَلِكَ بَعْدَ الْعِدَّةِ،"]]},{"id":"ri40_34","label":"بَابٌ فِي الْفَرَائِضِ · ٣٤","segs":[["matn","وَإِنْ طَلَّقَ الصَّحِيحُ امْرَأَتَهُ طَلْقَةً وَاحِدَةً فَإِنَّهُمَا يَتَوَارَثَانِ مَا كَانَتْ فِي الْعِدَّةِ، فَإِنِ انْقَضَتْ فَلَا مِيرَاثَ بَيْنَهُمَا بَعْدَهَا، وَمَنْ تَزَوَّجَ امْرَأَةً فِي مَرَضِهِ لَمْ تَرِثْهُ، وَلَا يَرِثُهَا."]]},{"id":"ri40_35","label":"بَابٌ فِي الْفَرَائِضِ · ٣٥","segs":[["matn","وَتَرِثُ الْجَدَّةُ لِلْأُمِّ السُّدُسَ، وَكَذَلِكَ الَّتِي لِلْأَبِ، فَإِنِ اجْتَمَعَتَا فَالسُّدُسُ بَيْنَهُمَا إِلَّا أَنْ تَكُونَ الَّتِي لِلْأُمِّ أَقْرَبَ بِدَرَجَةٍ فَتَكُونَ أَوْلَى بِهِ؛"]]},{"id":"ri40_36","label":"بَابٌ فِي الْفَرَائِضِ · ٣٦","segs":[["matn","لِأَنَّهَا الَّتِي فِيهَا النَّصُّ، وَإِنْ كَانَتِ الَّتِي لِلْأَبِ أَقْرَبَهُمَا فَالسُّدُسُ بَيْنَهُمَا، نِصْفَيْنِ وَلَا يَرِثُ عِنْدَ مَالِكٍ أَكْثَرُ مِنْ جَدَّتَيْنِ: أُمُّ الْأَبِ وَأُمُّ الْأُمِّ وَأُمَّهَاتُهُمَا،"]]},{"id":"ri40_37","label":"بَابٌ فِي الْفَرَائِضِ · ٣٧","segs":[["matn","وَيُذْكَرُ عَنْ زَيْدِ بْنِ ثَابِتٍ أَنَّهُ وَرَّثَ ثَلَاثَ جَدَّاتٍ: وَاحِدَةً مِنْ قِبَلِ الْأُمِّ، وَاثْنَتَيْنِ مِنْ قِبَلِ الْأَبِ: أُمُّ الْأَبِ وَأُمُّ أَبِي الْأَبِ، وَلَمْ يُحْفَظْ عَنِ الْخُلَفَاءِ تَوْرِيثُ أَكْثَرَ مِنْ جَدَّتَيْنِ."]]},{"id":"ri40_38","label":"بَابٌ فِي الْفَرَائِضِ · ٣٨","segs":[["matn","وَمِيرَاثُ الْجَدِّ إِذَا انْفَرَدَ فَلَهُ الْمَالُ، وَلَهُ مَعَ الْوَلَدِ الذَّكَرِ أَوْ مَعَ وَلَدِ الْوَلَدِ الذَّكَرِ السُّدُسُ، فَإِنْ شَرِكَهُ أَحَدٌ مِنْ أَهْلِ السِّهَامِ غَيْرَ الْإِخْوَةِ وَالْأَخَوَاتِ فَلْيُقْضَ لَهُ بِالسُّدُسِ، فَإِنْ بَقِيَ شَيْءٌ مِنَ الْمَالِ كَانَ لَهُ،"]]},{"id":"ri40_39","label":"بَابٌ فِي الْفَرَائِضِ · ٣٩","segs":[["matn","فَإِنْ كَانَ مَعَ أَهْلِ السِّهَامِ إِخْوَةٌ فَالْجَدُّ مُخَيَّرٌ فِي ثَلَاثَةِ أَوْجُهٍ يَأْخُذُ أَيَّ ذَلِكَ أَفْضَلُ لَهُ: إِمَّا مُقَاسَمَةُ الْإِخْوَةِ، أَوِ السُّدُسَ مِنْ رَأْسِ الْمَالِ، أَوْ ثُلُثَ مَا بَقِيَ فَإِنْ لَمْ يَكُنْ مَعَهُ غَيْرُ الْإِخْوَةِ؛"]]},{"id":"ri40_40","label":"بَابٌ فِي الْفَرَائِضِ · ٤٠","segs":[["matn","فَهُوَ يُقَاسِمُ أَخًا أَوْ أَخَوَيْنِ أَوْ عَدْلَهُمَا أَرْبَعَ أَخَوَاتٍ، فَإِنْ زَادُوا فَلَهُ الثُّلُثُ فَهُوَ يَرِثُ الثُّلُثَ مَعَ الْإِخْوَةِ، إِلَّا أَنْ تَكُونَ الْمُقَاسَمَةُ أَفْضَلَ لَهُ، وَالْإِخْوَةُ لِلْأَبِ مَعَهُ فِي عَدَمِ الشَّقَائِقِ كَالشَّقَائِقِ، فَإِنِ اجْتَمَعُوا عَادَّهُ الشَّقَائِقُ بِالَّذِينَ لِلْأَبِ؛"]]},{"id":"ri40_41","label":"بَابٌ فِي الْفَرَائِضِ · ٤١","segs":[["matn","فَمَنَعُوهُ بِهِمْ كَثْرَةَ الْمِيرَاثِ، ثُمَّ كَانُوا أَحَقَّ مِنْهُمْ بِذَلِكَ، إِلَّا أَنْ يَكُونَ مَعَ الْجَدِّ أُخْتٌ شَقِيقَةٌ وَلَهَا أَخٌ لِأَبٍ أَوْ أُخْتٌ لِأَبٍ أَوْ أَخٌ وَأُخْتٌ لِأَبٍ؛"]]},{"id":"ri40_42","label":"بَابٌ فِي الْفَرَائِضِ · ٤٢","segs":[["matn","فَتَأْخُذُ نِصْفَهَا مِمَّا حَصَلَ، وَتُسَلِّمُ مَا بَقِيَ إِلَيْهِمْ، وَلَا يُرْبَى لِلْأَخَوَاتِ مَعَ الْجَدِّ إِلَّا فِي الْغَرَّاءِ وَحْدَهَا، وَسَنَذْكُرُهَا بَعْدَ هَذَا."]]},{"id":"ri40_43","label":"بَابٌ فِي الْفَرَائِضِ · ٤٣","segs":[["matn","وَيَرِثُ الْمَوْلَى الْأَعْلَى إِذَا انْفَرَدَ جَمِيعَ الْمَالِ كَانَ رَجُلًا أَوِ امْرَأَةً، فَإِنْ كَانَ مَعَهُ أَهْلُ سَهْمٍ كَانَ لِلْمَوْلَى مَا بَقِيَ بَعْدَ أَهْلِ السِّهَامِ،"]]},{"id":"ri40_44","label":"بَابٌ فِي الْفَرَائِضِ · ٤٤","segs":[["matn","وَلَا يَرِثُ الْمَوْلَى مَعَ الْعَصَبَةِ، وَهُوَ أَحَقُّ مِنْ ذَوِي الْأَرْحَامِ الَّذِينَ لَا سَهْمَ لَهُمْ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ."]]},{"id":"ri40_45","label":"بَابٌ فِي الْفَرَائِضِ · ٤٥","segs":[["matn","وَلَا يَرِثُ مِنْ ذَوِي الْأَرْحَامِ إِلَّا مَنْ لَهُ سَهْمٌ فِي كِتَابِ اللَّهِ وَلَا يَرِثُ النِّسَاءُ مِنَ الْوَلَاءِ إِلَّا مَا أَعْتَقْنَ أَوْ جَرَّهُ مَنْ أَعْتَقْنَ إِلَيْهِنَّ بِوِلَادَةٍ أَوْ عِتْقٍ."]]},{"id":"ri40_46","label":"بَابٌ فِي الْفَرَائِضِ · ٤٦","segs":[["matn","وَإِذَا اجْتَمَعَ مَنْ لَهُ سَهْمٌ مَعْلُومٌ فِي كِتَابِ اللَّهِ وَكَانَ ذَلِكَ أَكْثَرَ مِنَ الْمَالِ أُدْخِلَ عَلَيْهِمْ كُلِّهِمُ الضَّرَرُ، وَقُسِمَتِ الْفَرِيضَةُ عَلَى مَبْلَغِ سِهَامِهِمْ."]]},{"id":"ri40_47","label":"بَابٌ فِي الْفَرَائِضِ · ٤٧","segs":[["matn","وَلَا يُعَالُ لِلْأُخْتِ مَعَ الْجَدِّ إِلَّا فِي الْغَرَّاءِ وَحْدَهَا، وَهِيَ امْرَأَةٌ تَرَكَتْ زَوْجَهَا وَأُمَّهَا وَأُخْتَهَا لِأَبَوَيْنِ أَوْ لِأَبٍ وَجَدَّهَا؛"]]},{"id":"ri40_48","label":"بَابٌ فِي الْفَرَائِضِ · ٤٨","segs":[["matn","فَلِلزَّوْجِ النِّصْفُ، وَلِلْأُمِّ الثُّلُثُ، وَلِلْجَدِّ السُّدُسُ، فَلَمَّا فَرَغَ الْمَالُ أُعِيلَ لِلْأُخْتِ بِالنِّصْفِ: ثَلَاثَةٌ، ثُمَّ جُمِعَ إِلَيْهَا سَهْمُ الْجَدِّ، فَيُقْسَمُ جَمِيعُ ذَلِكَ بَيْنَهُمَا عَلَى الثُّلُثِ لَهَا وَالثُّلُثَيْنِ لَهُ؛ فَتَبْلُغُ سَبْعَةً وَعِشْرِينَ سَهْمًا."]]}]},{"id":"ri41","title":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ","units":[{"id":"ri41_1","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١","segs":[["matn","الْوُضُوءُ لِلصَّلَاةِ فَرِيضَةٌ وَهُوَ مُشْتَقٌّ مِنَ الْوَضَاءَةِ إِلَّا الْمَضْمَضَةَ وَالِاسْتِنْشَاقَ وَمَسْحَ الْأُذُنَيْنِ؛ مِنْهُ فَإِنَّ ذَلِكَ سُنَّةٌ، وَالسِّوَاكُ مُسْتَحَبٌّ مُرَغَّبٌ فِيهِ، وَالْمَسْحُ عَلَى الْخُفَّيْنِ رُخْصَةٌ وَتَخْفِيفٌ."]]},{"id":"ri41_2","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢","segs":[["matn","وَالْغُسْلُ مِنَ الْجَنَابَةِ وَدَمِ الْحَيْضِ وَالنِّفَاسِ فَرِيضَةٌ، وَغُسْلُ الْجُمُعَةِ سُنَّةٌ، وَغُسْلُ الْعِيدَيْنِ مُسْتَحَبٌّ، وَالْغُسْلُ عَلَى مَنْ أَسْلَمَ فَرِيضَةٌ؛ لِأَنَّهُ جُنُبٌ، وَغَسْلُ الْمَيِّتِ سُنَّةٌ."]]},{"id":"ri41_3","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣","segs":[["matn","وَالصَّلَوَاتُ الْخَمْسُ فَرِيضَةٌ، وَتَكْبِيرَةُ الْإِحْرَامِ فَرِيضَةٌ، وَبَاقِي التَّكْبِيرِ سُنَّةٌ، وَالدُّخُولُ فِي الصَّلَاةِ بِنِيَّةِ الْفَرْضِ فَرِيضَةٌ، وَرَفْعُ الْيَدَيْنِ سُنَّةٌ، وَالْقِرَاءَةُ بِأُمِّ الْقُرْآنِ فِي الصَّلَاةِ فَرِيضَةٌ، وَمَا زَادَ عَلَيْهَا سُنَّةٌ وَاجِبَةٌ،"]]},{"id":"ri41_4","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤","segs":[["matn","وَالْقِيَامُ وَالرُّكُوعُ وَالسُّجُودُ فَرِيضَةٌ، وَالْجَلْسَةُ الْأُولَى سُنَّةٌ، وَالثَّانِيَةُ فَرِيضَةٌ، وَالسَّلَامُ فَرِيضَةٌ، وَالتَّيَامُنُ بِهِ قَلِيلًا سُنَّةٌ، وَتَرْكُ الْكَلَامِ فِي الصَّلَاةِ فَرِيضَةٌ، وَالتَّشَهُّدَانِ سُنَّةٌ، وَالْقُنُوتُ فِي الصُّبْحِ حَسَنٌ، وَلَيْسَ بِسُنَّةٍ، وَاسْتِقْبَالُ الْقِبْلَةِ فَرِيضَةٌ."]]},{"id":"ri41_5","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٥","segs":[["matn","وَصَلَاةُ الْجُمُعَةِ وَالسَّعْيُ إِلَيْهَا فَرِيضَةٌ، وَالْوِتْرُ سُنَّةٌ وَاجِبَةٌ، وَكَذَلِكَ صَلَاةُ الْعِيدَيْنِ وَالْخُسُوفِ وَالِاسْتِسْقَاءِ، وَصَلَاةُ الْخَوْفِ وَاجِبَةٌ أَمَرَ اللَّهُ سُبْحَانَهُ وَتَعَالَى بِهَا، وَهُوَ فِعْلٌ يَسْتَدْرِكُونَ بِهِ فَضْلَ الْجَمَاعَةِ، وَالْغُسْلُ لِدُخُولِ مَكَّةَ مُسْتَحَبٌّ."]]},{"id":"ri41_6","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٦","segs":[["matn","وَالْجَمْعُ لَيْلَةَ الْمَطَرِ تَخْفِيفٌ، وَقَدْ فَعَلَهُ الْخُلَفَاءُ، الرَّاشِدُونَ، وَالْجَمْعُ بِعَرَفَةَ وَالْمُزْدَلِفَةِ سُنَّةٌ وَاجِبَةٌ، وَجَمْعُ الْمُسَافِرِ فِي جِدِّ السَّيْرِ رُخْصَةٌ، وَجَمْعُ الْمَرِيضِ يَخَافُ أَنْ يُغْلَبَ عَلَى عَقْلِهِ تَخْفِيفٌ، وَكَذَلِكَ جَمْعُهُ لِعِلَّةٍ بِهِ؛"]]},{"id":"ri41_7","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٧","segs":[["matn","فَيَكُونُ ذَلِكَ أَرْفَقَ بِهِ، وَالْفِطْرُ فِي السَّفَرِ رُخْصَةٌ، وَالْإِقْصَارُ فِيهِ وَاجِبٌ."]]},{"id":"ri41_8","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٨","segs":[["matn","وَرَكْعَتَا الْفَجْرِ مِنَ الرَّغَائِبِ، وَقِيلَ: مِنَ السُّنَنِ، وَصَلَاةُ الضُّحَى نَافِلَةٌ، وَكَذَلِكَ قِيَامُ رَمَضَانَ نَافِلَةٌ، وَفِيهِ فَضْلٌ كَبِيرٌ؛ وَمَنْ قَامَهُ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ، وَالْقِيَامُ مِنَ اللَّيْلِ فِي رَمَضَانَ وَغَيْرِهِ مِنَ النَّوَافِلِ الْمُرَغَّبِ فِيهَا."]]},{"id":"ri41_9","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٩","segs":[["matn","وَالصَّلَاةُ عَلَى مَوْتَى الْمُسْلِمِينَ فَرِيضَةٌ يَحْمِلُهَا مَنْ قَامَ بِهَا، وَكَذَلِكَ مُوَارَاتُهُمْ بِالدَّفْنِ وَغَسْلُهُمْ سُنَّةٌ وَاجِبَةٌ، وَكَذَلِكَ طَلَبُ الْعِلْمِ فَرِيضَةٌ عَامَّةٌ يَحْمِلُهَا مَنْ قَامَ بِهَا، إِلَّا مَا يَلْزَمُ الرَّجُلَ فِي خَاصَّةِ نَفْسِهِ،"]]},{"id":"ri41_10","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٠","segs":[["matn","وَفَرِيضَةُ الْجِهَادِ عَامَّةٌ يَحْمِلُهَا مَنْ قَامَ بِهَا، إِلَّا أَنْ يَغْشَى الْعَدُوُّ مَحَلَّةَ قَوْمٍ فَيَجِبُ فَرْضًا عَلَيْهِمْ قِتَالُهُمْ إِذَا كَانُوا مِثْلَيْ عَدَدِهِمْ، وَالرِّبَاطُ فِي ثُغُورِ الْمُسْلِمِينَ وَسَدُّهَا وَحِيَاطَتُهَا وَاجِبٌ يَحْمِلُهُ مَنْ قَامَ بِهِ."]]},{"id":"ri41_11","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١١","segs":[["matn","وَصَوْمُ شَهْرِ رَمَضَانَ فَرِيضَةٌ، وَالِاعْتِكَافُ نَافِلَةٌ، وَالتَّنَفُّلُ بِالصَّوْمِ مُرَغَّبٌ فِيهِ، وَكَذَلِكَ صَوْمُ يَوْمِ عَاشُورَاءَ وَرَجَبٍ وَشَعْبَانَ وَيَوْمِ عَرَفَةَ وَالتَّرْوِيَةِ وَصَوْمُ يَوْمِ عَرَفَةَ لِغَيْرِ الْحَاجِّ أَفْضَلُ مِنْهُ لِلْحَاجِّ."]]},{"id":"ri41_12","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٢","segs":[["matn","وَزَكَاةُ الْعَيْنِ وَالْحَرْثِ وَالْمَاشِيَةِ فَرِيضَةٌ، وَزَكَاةُ الْفِطْرِ سُنَّةٌ فَرَضَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"ri41_13","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٣","segs":[["matn","وَحَجُّ الْبَيْتِ فَرِيضَةٌ، وَالْعُمْرَةُ سُنَّةٌ وَاجِبَةٌ، وَالتَّلْبِيَةُ سُنَّةٌ وَاجِبَةٌ، وَالنِّيَّةُ بِالْحَجِّ فَرِيضَةٌ، وَالطَّوَافُ لِلْإِفَاضَةِ فَرِيضَةٌ، وَالسَّعْيُ بَيْنَ الصَّفَا وَالْمَرْوَةِ فَرِيضَةٌ، وَالطَّوَافُ الْمُتَّصِلُ بِهِ وَاجِبٌ، وَطَوَافُ الْإِفَاضَةِ آكَدُ مِنْهُ،"]]},{"id":"ri41_14","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٤","segs":[["matn","وَالطَّوَافُ لِلْوَدَاعِ سُنَّةٌ، وَالْمَبِيتُ بِمِنًى لَيْلَةَ يَوْمِ عَرَفَةَ سُنَّةٌ، وَالْجَمْعُ بِعَرَفَةَ وَاجِبٌ، وَالْوُقُوفُ بِعَرَفَةَ فَرِيضَةٌ، وَمَبِيتُ الْمُزْدَلِفَةِ سُنَّةٌ وَاجِبَةٌ، وَوُقُوفُ الْمَشْعَرِ الْحَرَامِ مَأْمُورٌ بِهِ، وَرَمْيُ الْجِمَارِ سُنَّةٌ وَاجِبَةٌ، وَكَذَلِكَ الْحِلَاقُ."]]},{"id":"ri41_15","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٥","segs":[["matn","وَتَقْبِيلُ الرُّكْنِ سُنَّةٌ، وَاجِبَةٌ، وَالْغُسْلُ لِلْإِحْرَامِ سُنَّةٌ، وَالرُّكُوعُ عِنْدَ الْإِحْرَامِ سُنَّةٌ، وَغُسْلُ عَرَفَةَ سُنَّةٌ، وَالْغُسْلُ لِدُخُولِ مَكَّةَ مُسْتَحَبٌّ."]]},{"id":"ri41_16","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٦","segs":[["matn","وَالصَّلَاةُ فِي الْجَمَاعَةِ أَفْضَلُ مِنْ صَلَاةِ الْفَذِّ بِسَبْعٍ وَعِشْرِينَ دَرَجَةً، وَالصَّلَاةُ فِي الْمَسْجِدِ الْحَرَامِ وَمَسْجِدِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذًّا أَفْضَلُ مِنَ الصَّلَاةِ فِي سَائِرِ الْمَسَاجِدِ، وَاخْتُلِفَ فِي مِقْدَارِ التَّضْعِيفِ بِذَلِكَ بَيْنَ الْمَسْجِدِ الْحَرَامِ وَمَسْجِدِ الرَّسُولِ،"]]},{"id":"ri41_17","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٧","segs":[["matn","عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ وَلَمْ يُخْتَلَفْ أَنَّ الصَّلَاةَ فِي مَسْجِدِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَفْضَلُ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ وَسِوَى الْمَسْجِدِ الْحَرَامِ مِنَ الْمَسَاجِدِ،"]]},{"id":"ri41_18","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٨","segs":[["matn","وَأَهْلُ الْمَدِينَةِ يَقُولُونَ: إِنَّ الصَّلَاةَ فِيهِ أَفْضَلُ مِنَ الصَّلَاةِ فِي الْمَسْجِدِ الْحَرَامِ بِدُونِ الْأَلْفِ، وَهَذَا كُلُّهُ فِي الْفَرَائِضِ، وَأَمَّا النَّوَافِلُ فَفِي الْبُيُوتِ أَفْضَلُ."]]},{"id":"ri41_19","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ١٩","segs":[["matn","وَالتَّنَفُّلُ بِالرُّكُوعِ لِأَهْلِ مَكَّةَ أَحَبُّ إِلَيْنَا مِنَ الطَّوَافِ، وَالطَّوَافُ لِلْغُرَبَاءِ أَحَبُّ إِلَيْنَا مِنَ الرُّكُوعِ لِقِلَّةِ وُجُودِ ذَلِكَ لَهُمْ."]]},{"id":"ri41_20","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٠","segs":[["matn","وَمِنَ الْفَرَائِضِ غَضُّ الْبَصَرِ عَنِ الْمَحَارِمِ، وَلَيْسَ فِي النَّظْرَةِ الْأُولَى بِغَيْرِ تَعَمُّدٍ حَرَجٌ، وَلَا فِي النَّظَرِ إِلَى الْمُتَجَالَّةِ، وَلَا فِي النَّظَرِ إِلَى الشَّابَّةِ لِعُذْرٍ مِنْ شَهَادَةٍ عَلَيْهَا وَشِبْهِهِ، وَقَدْ أُرْخِصَ فِي ذَلِكَ لِلْخَاطِبِ."]]},{"id":"ri41_21","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢١","segs":[["matn","وَمِنَ الْفَرَائِضِ صَوْنُ اللِّسَانِ عَنِ الْكَذِبِ وَالزُّورِ وَالْفَحْشَاءِ وَالْغِيبَةِ وَالنَّمِيمَةِ وَالْبَاطِلِ كُلِّهِ؛ قَالَ الرَّسُولُ: عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ»، وَقَالَ: عَلَيْهِ السَّلَامُ «مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ»."]]},{"id":"ri41_22","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٢","segs":[["matn","وَحَرَّمَ اللَّهُ سُبْحَانَهُ دِمَاءَ الْمُسْلِمِينَ وَأَمْوَالَهُمْ وَأَعْرَاضَهُمْ إِلَّا بِحَقِّهَا، وَلَا يَحِلُّ دَمُ امْرِئٍ مُسْلِمٍ إِلَّا أَنْ يَكْفُرَ بَعْدَ إِيمَانِهِ، أَوْ يَزْنِيَ بَعْدَ إِحْصَانِهِ، أَوْ يَقْتُلَ نَفْسًا بِغَيْرِ نَفْسٍ، أَوْ فَسَادٍ فِي الْأَرْضِ، أَوْ يَمْرُقَ مِنَ الدِّينِ."]]},{"id":"ri41_23","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٣","segs":[["matn","وَلْتَكُفَّ يَدَكَ عَمَّا لَا يَحِلُّ لَكَ مِنْ مَالٍ أَوْ جَسَدٍ أَوْ دَمٍ، وَلَا تَسْعَ بِقَدَمَيْكَ فِيمَا لَا يَحِلُّ لَكَ. وَلَا تُبَاشِرْ بِفَرْجِكَ أَوْ بِشَيْءٍ مِنْ جَسَدِكَ مَا لَا يَحِلُّ لَكَ؛"]]},{"id":"ri41_24","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٤","segs":[["matn","قَالَ اللَّهُ سُبْحَانَهُ ﴿وَالَّذِينَ هُمْ لِفُرُوجِهِمْ حَافِظُونَ﴾ إِلَى قَوْلِهِ: ﴿فَأُولَئِكَ هُمُ الْعَادُونَ﴾، وَحَرَّمَ اللَّهُ سُبْحَانَهُ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ، وَأَنْ يُقْرَبَ النِّسَاءُ فِي دَمِ حَيْضِهِنَّ أَوْ نِفَاسِهِنَّ، وَحَرَّمَ مِنَ النِّسَاءِ مَا تَقَدَّمَ ذِكْرُنَا إِيَّاهُ."]]},{"id":"ri41_25","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٥","segs":[["matn","وَأَمَرَ بِأَكْلِ الطَّيِّبِ، وَهُوَ الْحَلَالُ؛ فَلَا يَحِلُّ لَكَ أَنْ تَأْكُلَ إِلَّا طَيِّبًا، وَلَا تَلْبَسَ إِلَّا طَيِّبًا، وَلَا تَرْكَبَ إِلَّا طَيِّبًا، وَلَا تَسْكُنَ إِلَّا طَيِّبًا، وَتَسْتَعْمِلُ سَائِرَ مَا تَنْتَفِعُ بِهِ طَيِّبًا،"]]},{"id":"ri41_26","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٦","segs":[["matn","وَمِنْ وَرَاءِ ذَلِكَ مُشْتَبِهَاتٌ مَنْ تَرَكَهَا سَلِمَ، وَمَنْ أَخَذَهَا كَانَ كَالرَّاتِعِ حَوْلَ الْحِمَى يُوشِكُ أَنْ يَقَعَ فِيهِ، وَحَرَّمَ اللَّهُ سُبْحَانَهُ أَكْلَ الْمَالِ بِالْبَاطِلِ، وَمِنَ الْبَاطِلِ الْغَصْبُ وَالتَّعَدِّي وَالْخِيَانَةُ وَالرِّبَا وَالسُّحْتُ وَالْقِمَارُ وَالْغَرَرُ وَالْغِشُّ وَالْخَدِيعَةُ وَالْخِلَابَةُ."]]},{"id":"ri41_27","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٧","segs":[["matn","وَحَرَّمَ اللَّهُ سُبْحَانَهُ أَكْلَ الْمَيْتَةِ وَالدَّمِ وَلَحْمِ الْخِنْزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ وَمَا ذُبِحَ لِغَيْرِ اللَّهِ، وَمَا أَعَانَ عَلَى مَوْتِهِ تَرَدٍّ مِنْ جَبَلٍ أَوْ وَقْذَةٌ بِعَصًا أَوْ غَيْرِهَا،"]]},{"id":"ri41_28","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٨","segs":[["matn","وَالْمُنْخَنِقَةُ بِحَبْلٍ أَوْ غَيْرِهِ، إِلَّا أَنْ يَضْطَرَّ إِلَى ذَلِكَ كَالْمَيْتَةِ، وَذَلِكَ إِذَا صَارَتْ بِذَلِكَ إِلَى حَالٍ لَا حَيَاةَ بَعْدَهُ، فَلَا ذَكَاةَ فِيهَا."]]},{"id":"ri41_29","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٢٩","segs":[["matn","وَلَا بَأْسَ لِلْمُضْطَرِّ أَنْ يَأْكُلَ الْمَيْتَةَ وَيَشْبَعَ وَيَتَزَوَّدَ، فَإِنِ اسْتَغْنَى عَنْهَا طَرَحَهَا، وَلَا بَأْسَ بِالِانْتِفَاعِ بِجِلْدِهَا إِذَا دُبِغَ، وَلَا يُصَلَّى عَلَيْهِ، وَلَا يُبَاعُ، وَلَا بَأْسَ بِالصَّلَاةِ عَلَى جُلُودِ السِّبَاعِ إِذَا ذُكِّيَتْ وَبَيْعِهَا،"]]},{"id":"ri41_30","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٠","segs":[["matn","وَيُنْتَفَعُ بِصُوفِ الْمَيْتَةِ وَشَعْرِهَا وَمَا يُنْزَعُ مِنْهَا فِي الْحَيَاةِ، وَأَحَبُّ إِلَيْنَا أَنْ يُغْسَلَ، وَلَا يُنْتَفَعُ بِرِيشِهَا وَلَا بِقَرْنِهَا وَأَظْلَافِهَا وَأَنْيَابِهَا، وَكُرِهَ الِانْتِفَاعُ بِأَنْيَابِ الْفِيلِ، وَكُلُّ شَيْءٍ مِنَ الْخِنْزِيرِ حَرَامٌ، وَقَدْ أُرْخِصَ فِي الِانْتِفَاعِ بِشَعْرِهِ."]]},{"id":"ri41_31","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣١","segs":[["matn","وَحَرَّمَ اللَّهُ سُبْحَانَهُ شُرْبَ الْخَمْرِ قَلِيلِهَا وَكَثِيرِهَا، وَشَرَابُ الْعَرَبِ يَوْمَئِذٍ فَضِيخُ التَّمْرِ، وَبَيَّنَ الرَّسُولُ عَلَيْهِ السَّلَامُ أَنَّ كُلَّ مَا أَسْكَرَ كَثِيرُهُ مِنَ الْأَشْرِبَةِ فَقَلِيلُهُ حَرَامٌ، وَكُلُّ مَا خَامَرَ الْعَقْلَ فَأَسْكَرَهُ مِنْ كُلِّ شَرَابٍ فَهُوَ خَمْرٌ،"]]},{"id":"ri41_32","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٢","segs":[["matn","وَقَالَ الرَّسُولُ: عَلَيْهِ السَّلَامُ «إِنَّ الَّذِي حَرَّمَ شُرْبَهَا حَرَّمَ بَيْعَهَا»، وَنَهَى عَنِ الْخَلِيطَيْنِ مِنَ الْأَشْرِبَةِ، وَذَلِكَ أَنْ يُخْلَطَا عِنْدَ الِانْتِبَاذِ وَعِنْدَ الشُّرْبِ، وَنَهَى عَنِ الِانْتِبَاذِ فِي الدُّبَّاءِ وَالْمُزَفَّتِ."]]},{"id":"ri41_33","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٣","segs":[["matn","وَنَهَى عَلَيْهِ السَّلَامُ عَنْ أَكْلِ كُلِّ ذِي نَابٍ مِنَ السِّبَاعِ، وَعَنْ أَكْلِ لُحُومِ الْحُمُرِ الْأَهْلِيَّةِ، وَدَخَلَ مَدْخَلَهَا لُحُومُ الْخَيْلِ وَالْبِغَالِ لِقَوْلِ اللَّهِ تَبَارَكَ وَتَعَالَى ﴿لِتَرْكَبُوهَا وَزِينَةً﴾،"]]},{"id":"ri41_34","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٤","segs":[["matn","وَلَا ذَكَاةَ فِي شَيْءٍ مِنْهَا إِلَّا فِي الْحُمُرِ الْوَحْشِيَّةِ، وَلَا بَأْسَ بِأَكْلِ سِبَاعِ الطَّيْرِ وَكُلِّ ذِي مِخْلَبٍ مِنْهَا."]]},{"id":"ri41_35","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٥","segs":[["matn","وَمِنَ الْفَرَائِضِ بِرُّ الْوَالِدَيْنِ وَإِنْ كَانَا فَاسِقَيْنِ، وَإِنْ كَانَا مُشْرِكَيْنِ فَلْيَقُلْ لَهُمَا قَوْلًا لَيِّنًا، وَلْيُعَاشِرْهُمَا بِالْمَعْرُوفِ، وَلَا يُطِعْهُمَا فِي مَعْصِيَةٍ كَمَا قَالَ اللَّهُ سُبْحَانَهُ وَتَعَالَى."]]},{"id":"ri41_36","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٦","segs":[["matn","وَعَلَى الْمُؤْمِنِ أَنْ يَسْتَغْفِرَ لِأَبَوَيْهِ الْمُؤْمِنَيْنِ. وَعَلَيْهِ مُوَالَاةُ الْمُؤْمِنِينَ وَالنَّصِيحَةُ لَهُمْ، وَلَا يَبْلُغُ أَحَدٌ حَقِيقَةَ الْإِيمَانِ حَتَّى يُحِبَّ لِأَخِيهِ الْمُؤْمِنِ مَا يُحِبُّ لِنَفْسِهِ، كَذَلِكَ رُوِيَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."]]},{"id":"ri41_37","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٧","segs":[["matn","وَعَلَيْهِ أَنْ يَصِلَ رَحِمَهُ، وَمِنْ حَقِّ الْمُؤْمِنِ عَلَى الْمُؤْمِنِ أَنْ يُسَلِّمَ عَلَيْهِ إِذَا لَقِيَهُ، وَيَعُودَهُ إِذَا مَرِضَ، وَيُشَمِّتَهُ إِذَا عَطَسَ، وَيَشْهَدَ جِنَازَتَهُ إِذَا مَاتَ، وَيَحْفَظَهُ إِذَا غَابَ فِي السِّرِّ وَالْعَلَانِيَةِ."]]},{"id":"ri41_38","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٨","segs":[["matn","وَلَا يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثِ لَيَالٍ، وَالسَّلَامُ يُخْرِجُهُ مِنَ الْهِجْرَانِ، وَلَا يَنْبَغِي لَهُ أَنْ يَتْرُكَ كَلَامَهُ بَعْدَ السَّلَامِ، وَالْهِجْرَانُ الْجَائِزُ هِجْرَانُ ذِي الْبِدْعَةِ أَوْ مُتَجَاهَرٍ بِالْكَبَائِرِ لَا يَصِلُ إِلَى عُقُوبَتِهِ،"]]},{"id":"ri41_39","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٣٩","segs":[["matn","وَلَا يَقْدِرُ عَلَى مَوْعِظَتِهِ أَوْ لَا يَقْبَلُهَا، وَلَا غِيبَةَ فِي هَذَيْنِ فِي ذِكْرِ حَالِهِمَا، وَلَا فِيمَا يُشَاوَرُ فِيهِ لِنِكَاحٍ أَوْ مُخَالَطَةٍ وَنَحْوِهِ، وَلَا فِي تَجْرِيحِ شَاهِدٍ وَنَحْوِهِ."]]},{"id":"ri41_40","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٠","segs":[["matn","وَمِنْ مَكَارِمِ الْأَخْلَاقِ أَنْ تَعْفُوَ عَمَّنْ ظَلَمَكَ، وَتُعْطِيَ مَنْ حَرَمَكَ، وَتَصِلَ مَنْ قَطَعَكَ، وَجِمَاعُ آدَابِ الْخَيْرِ وَأَزِمَّتِهِ تَتَفَرَّعُ عَنْ أَرْبَعَةِ أَحَادِيثَ: قَوْلُ النَّبِيِّ: عَلَيْهِ السَّلَامُ «مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ»،"]]},{"id":"ri41_41","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤١","segs":[["matn","وَقَوْلُهُ: عَلَيْهِ السَّلَامُ «مِنْ حُسْنِ إِسْلَامِ الْمَرْءِ تَرْكُهُ مَا لَا يَعْنِيهِ»، وَقَوْلُهُ عَلَيْهِ السَّلَامُ لِلَّذِي اخْتَصَرَ لَهُ فِي الْوَصِيَّةِ: «لَا تَغْضَبْ»، وَقَوْلُهُ: عَلَيْهِ السَّلَامُ «الْمُؤْمِنُ يُحِبُّ لِأَخِيهِ الْمُؤْمِنِ مَا يُحِبُّ لِنَفْسِهِ»."]]},{"id":"ri41_42","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٢","segs":[["matn","وَلَا يَحِلُّ لَكَ أَنْ تَتَعَمَّدَ سَمَاعَ الْبَاطِلِ كُلِّهِ، وَلَا أَنْ تَتَلَذَّذَ بِسَمَاعِ كَلَامِ امْرَأَةٍ لَا تَحِلُّ لَكَ، وَلَا سَمَاعِ شَيْءٍ مِنَ الْمَلَاهِي وَالْغِنَاءِ،"]]},{"id":"ri41_43","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٣","segs":[["matn","وَلَا قِرَاءَةُ الْقُرْآنِ بِاللُّحُونِ الْمُرَجَّعَةِ كَتَرْجِيعِ الْغِنَاءِ، وَلْيُجَلَّ كِتَابُ اللَّهِ الْعَزِيزُ أَنْ يُتْلَى إِلَّا بِسَكِينَةٍ وَوَقَارٍ وَمَا يُوقَنُ أَنَّ اللَّهَ يَرْضَى بِهِ، وَيُقَرِّبُ مِنْهُ مَعَ إِحْضَارِ الْفَهْمِ لِذَلِكَ."]]},{"id":"ri41_44","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٤","segs":[["matn","وَمِنَ الْفَرَائِضِ الْأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنِ الْمُنْكَرِ عَلَى كُلِّ مَنْ بُسِطَتْ يَدُهُ فِي الْأَرْضِ وَعَلَى كُلِّ مَنْ تَصِلُ يَدُهُ إِلَى ذَلِكَ، فَإِنْ لَمْ يَقْدِرْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَقْدِرْ فَبِقَلْبِهِ."]]},{"id":"ri41_45","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٥","segs":[["matn","وَفَرْضٌ عَلَى كُلِّ مُؤْمِنٍ أَنْ يُرِيدَ بِكُلِّ قَوْلٍ وَعَمَلٍ مِنَ الْبِرِّ وَجْهَ اللَّهِ الْكَرِيمِ، وَمَنْ أَرَادَ بِذَلِكَ غَيْرَ اللَّهِ لَمْ يُقْبَلْ عَمَلُهُ، وَالرِّيَاءُ الشِّرْكُ الْأَصْغَرُ."]]},{"id":"ri41_46","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٦","segs":[["matn","وَالتَّوْبَةُ فَرِيضَةٌ مِنْ كُلِّ ذَنْبٍ مِنْ غَيْرِ إِصْرَارٍ، وَالْإِصْرَارُ: الْمُقَامُ عَلَى الذَّنْبِ وَاعْتِقَادُ الْعَوْدِ إِلَيْهِ، وَمِنَ التَّوْبَةِ رَدُّ الْمَظَالِمِ وَاجْتِنَابُ الْمَحَارِمِ وَالنِّيَّةُ أَنْ لَا يَعُودَ،"]]},{"id":"ri41_47","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٧","segs":[["matn","وَلْيَسْتَغْفِرْ رَبَّهُ، وَيَرْجُو رَحْمَتَهُ، وَيَخَافُ عَذَابَهُ، وَيَتَذَكَّرُ نِعْمَتَهُ لَدَيْهِ، وَيَشْكُرُ فَضْلَهُ عَلَيْهِ بِالْأَعْمَالِ بِفَرَائِضِهِ وَتَرْكِ مَا يُكْرَهُ فِعْلُهُ، وَيَتَقَرَّبُ إِلَيْهِ بِمَا تَيَسَّرَ لَهُ مِنْ نَوَافِلِ الْخَيْرِ،"]]},{"id":"ri41_48","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٨","segs":[["matn","وَكُلُّ مَا ضَيَّعَ مِنْ فَرَائِضِهِ فَلْيَفْعَلْهُ الْآنَ، وَلْيَرْغَبْ إِلَى اللَّهِ فِي تَقَبُّلِهِ، وَيَتُوبُ إِلَيْهِ مِنْ تَضْيِيعِهِ،"]]},{"id":"ri41_49","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٤٩","segs":[["matn","وَلْيَلْجَأْ إِلَى اللَّهِ فِيمَا عَسُرَ عَلَيْهِ مِنْ قِيَادِ نَفْسِهِ وَمُحَاوَلَةِ أَمْرِهِ مُوقِنًا أَنَّهُ الْمَالِكُ لِصَلَاحِ شَأْنِهِ وَتَوْفِيقِهِ وَتَسْدِيدِهِ، لَا يُفَارِقُ ذَلِكَ عَلَى مَا فِيهِ مِنْ حَسَنٍ أَوْ قَبِيحٍ، وَلَا يَيْأَسُ مِنْ رَحْمَةِ اللَّهِ."]]},{"id":"ri41_50","label":"بَابُ جُمَلٍ مِنَ الْفَرَائِضِ وَالسُّنَنِ الْوَاجِبَةِ وَالرَّغَائِبِ · ٥٠","segs":[["matn","وَالْفِكْرَةُ فِي أَمْرِ اللَّهِ مِفْتَاحُ الْعِبَادَةِ، فَاسْتَعِنْ بِذِكْرِ الْمَوْتِ وَالْفِكْرَةِ فِيمَا بَعْدَهُ، وَفِي نِعْمَةِ رَبِّكَ عَلَيْكَ وَإِمْهَالِهِ لَكَ وَأَخْذِهِ لِغَيْرِكَ بِذَنْبِهِ، وَفِي سَالِفِ ذَنْبِكَ وَعَاقِبَةِ أَمْرِكَ؛ وَمُبَادَرَةِ مَا عَسَى أَنْ يَكُونَ قَدِ اقْتَرَبَ مِنْ أَجَلِكَ."]]}]},{"id":"ri42","title":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ","units":[{"id":"ri42_1","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ١","segs":[["matn","وَمِنَ الْفِطْرَةِ خَمْسٌ: قَصُّ الشَّارِبِ، وَهُوَ الْإِطَارُ وَهُوَ طَرَفُ الشَّعْرِ الْمُسْتَدِيرِ عَلَى الشَّفَةِ، لَا إِحْفَاؤُهُ، وَاللَّهُ أَعْلَمُ. وَقَصُّ الْأَظْفَارِ. وَنَتْفُ الْجَنَاحَيْنِ. وَحَلْقُ الْعَانَةِ، وَلَا بَأْسَ بِحِلَاقِ غَيْرِهَا مِنْ شَعْرِ الْجَسَدِ."]]},{"id":"ri42_2","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ٢","segs":[["matn","وَالْخِتَانُ لِلرِّجَالِ سُنَّةٌ، وَالْخِفَاضُ لِلنِّسَاءِ مَكْرُمَةٌ. وَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُعْفَى اللِّحْيَةُ وَتُوَفَّرَ وَلَا تُقَصَّ قَالَ مَالِكٌ: وَلَا بَأْسَ بِالْأَخْذِ مِنْ طُولِهَا إِذَا طَالَتْ كَثِيرًا، وَقَالَهُ غَيْرُ وَاحِدٍ مِنَ الصَّحَابَةِ وَالتَّابِعِينَ."]]},{"id":"ri42_3","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ٣","segs":[["matn","وَيُكْرَهُ صِبَاغُ الشَّعْرِ بِالسَّوَادِ مِنْ غَيْرِ تَحْرِيمٍ، وَلَا بَأْسَ بِهِ بِالْحِنَّاءِ وَالْكَتَمِ، وَنَهَى الرَّسُولُ عَلَيْهِ السَّلَامُ الذُّكُورَ عَنْ لِبَاسِ الْحَرِيرِ وَتَخَتُّمِ الذَّهَبِ وَعَنِ التَّخَتُّمِ بِالْحَدِيدِ، وَلَا بَأْسَ بِالْفِضَّةِ فِي حِلْيَةِ الْخَاتَمِ وَالسَّيْفِ وَالْمُصْحَفِ،"]]},{"id":"ri42_4","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ٤","segs":[["matn","وَلَا يُجْعَلُ ذَلِكَ فِي لِجَامٍ وَلَا سَرْجٍ وَلَا سِكِّينٍ وَلَا فِي غَيْرِ ذَلِكَ، وَيَتَخَتَّمُ النِّسَاءُ بِالذَّهَبِ، وَنُهِيَ عَنِ التَّخَتُّمِ بِالْحَدِيدِ، وَالِاخْتِيَارُ مِمَّا رُوِيَ فِي التَّخَتُّمِ التَّخَتُّمُ فِي الْيَسَارِ؛"]]},{"id":"ri42_5","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ٥","segs":[["matn","لِأَنَّ تَنَاوُلَ الشَّيْءِ بِالْيَمِينِ؛ فَهُوَ يَأْخُذُهُ بِيَمِينِهِ، وَيَجْعَلُهُ فِي يَسَارِهِ، وَاخْتُلِفَ فِي لِبَاسِ الْخَزِّ: فَأُجِيزَ، وَكُرِهَ."]]},{"id":"ri42_6","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ٦","segs":[["matn","وَكَذَلِكَ الْعَلَمُ فِي الثَّوْبِ مِنَ الْحَرِيرِ إِلَّا الْخَطَّ الرَّقِيقَ، وَلَا يَلْبَسُ النِّسَاءُ مِنَ الرَّقِيقِ مَا يَصِفُهُنَّ إِذَا خَرَجْنَ."]]},{"id":"ri42_7","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ٧","segs":[["matn","وَلَا يَجُرُّ الرَّجُلُ إِزَارَهُ بَطَرًا وَلَا ثَوْبَهُ مِنَ الْخُيَلَاءِ، وَلْيَكُنْ إِلَى الْكَعْبَيْنِ؛ فَهُوَ أَنْظَفُ لِثَوْبِهِ وَأَتْقَى لِرَبِّهِ، وَيُنْهَى عَنِ اشْتِمَالِ الصَّمَّاءِ، وَهِيَ عَلَى غَيْرِ ثَوْبٍ؛"]]},{"id":"ri42_8","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ٨","segs":[["matn","يَرْفَعُ ذَلِكَ مِنْ جِهَةٍ وَاحِدَةٍ، وَيَسْدُلُ الْأُخْرَى، وَذَلِكَ إِذَا لَمْ يَكُنْ تَحْتَ اشْتِمَالِكَ ثَوْبٌ، وَاخْتُلِفَ فِيهِ عَلَى ثَوْبٍ."]]},{"id":"ri42_9","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ٩","segs":[["matn","وَيُؤْمَرُ بِسَتْرِ الْعَوْرَةِ، وَآزِرَةُ الْمُؤْمِنِ إِلَى أَنْصَافِ سَاقَيْهِ، وَالْفَخِذُ عَوْرَةٌ، وَلَيْسَ كَالْعَوْرَةِ نَفْسِهَا، وَلَا يَدْخُلُ الرَّجُلُ الْحَمَّامَ إِلَّا بِمِئْزَرٍ، وَلَا تَدْخُلُهُ الْمَرْأَةُ إِلَّا مِنْ عِلَّةٍ، وَلَا يَتَلَاصَقُ رَجُلَانِ وَلَا امْرَأَتَانِ فِي لِحَافٍ وَاحِدٍ."]]},{"id":"ri42_10","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ١٠","segs":[["matn","وَلَا تَخْرُجُ امْرَأَةٌ إِلَّا مُسْتَتِرَةً فِيمَا لَا بُدَّ لَهَا مِنْهُ مِنْ شُهُودِ مَوْتِ أَبَوَيْهَا أَوْ ذِي قَرَابَتِهَا أَوْ نَحْوِ ذَلِكَ مِمَّا يُبَاحُ لَهَا،"]]},{"id":"ri42_11","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ١١","segs":[["matn","وَلَا تَحْضُرُ مِنْ ذَلِكَ مَا فِيهِ نَوْحُ نَائِحَةٍ أَوْ لَهْوٌ مِنْ مِزْمَارٍ أَوْ عُودٍ أَوْ شِبْهِهِ مِنَ الْمَلَاهِي الْمُلْهِيَةِ إِلَّا الدُّفَّ فِي النِّكَاحِ،"]]},{"id":"ri42_12","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ١٢","segs":[["matn","وَقَدِ اخْتُلِفَ فِي الْكَبَرِ، وَلَا يَخْلُو رَجُلٌ بِامْرَأَةٍ لَيْسَتْ مِنْهُ بِمَحْرَمٍ، وَلَا بَأْسَ أَنْ يَرَاهَا لِعُذْرٍ مِنْ شَهَادَةٍ عَلَيْهَا أَوْ نَحْوِ ذَلِكَ أَوْ إِذَا خَطَبَهَا، وَأَمَّا الْمُتَجَالَّةُ فَلَهُ أَنْ يَرَى وَجْهَهَا عَلَى كُلِّ حَالٍ."]]},{"id":"ri42_13","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ١٣","segs":[["matn","وَيُنْهَى النِّسَاءُ عَنْ وَصْلِ الشَّعْرِ وَعَنِ الْوَشْمِ. وَمَنْ لَبِسَ خُفًّا أَوْ نَعْلًا بَدَأَ بِيَمِينِهِ، وَإِذَا نَزَعَ بَدَأَ بِشِمَالِهِ، وَلَا بَأْسَ بِالِانْتِعَالِ قَائِمًا، وَيُكْرَهُ الْمَشْيُ فِي نَعْلٍ وَاحِدَةٍ."]]},{"id":"ri42_14","label":"بَابٌ فِي الْفِطْرَةِ وَالْخِتَانِ وَحَلْقِ الشَّعْرِ وَاللِّبَاسِ وَسَتْرِ الْعَوْرَةِ وَمَا يَتَّصِلُ بِذَلِكَ · ١٤","segs":[["matn","وَتُكْرَهُ التَّمَاثِيلُ فِي الْأَسِرَّةِ وَالْقِبَابِ وَالْجُدَرَانِ وَالْخَاتَمِ، وَلَيْسَ الرَّقْمُ فِي الثَّوْبِ مِنْ ذَلِكَ، وَتَرْكُهُ أَحْسَنُ."]]}]},{"id":"ri43","title":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ","units":[{"id":"ri43_1","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ١","segs":[["matn","وَإِذَا أَكَلْتَ أَوْ شَرِبْتَ فَوَاجِبٌ عَلَيْكَ أَنْ تَقُولَ: بِسْمِ اللَّهِ، وَتَتَنَاوَلَ بِيَمِينِكَ، فَإِذَا فَرَغْتَ فَلْتَقُلِ الْحَمْدُ لِلَّهِ، وَحَسَنٌ أَنْ تَلْعَقَ يَدَكَ قَبْلَ مَسْحِهَا،"]]},{"id":"ri43_2","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ٢","segs":[["matn","وَمِنْ آدَابِ الْأَكْلِ أَنْ تَجْعَلَ بَطْنَكَ: ثُلُثًا لِلطَّعَامِ وَثُلُثًا لِلشَّرَابِ وَثُلُثًا لِلنَّفَسِ، وَإِذَا أَكَلْتَ مَعَ غَيْرِكَ أَكَلْتَ مِمَّا يَلِيكَ، وَلَا تَأْخُذْ لُقْمَةً حَتَّى تَفْرُغَ الْأُخْرَى."]]},{"id":"ri43_3","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ٣","segs":[["matn","وَلَا تَتَنَفَّسْ فِي الْإِنَاءِ عِنْدَ شُرْبِكَ، وَلْتُبِنِ الْقَدَحَ عَنْ فِيكَ، ثُمَّ تُعَاوِدْهُ إِنْ شِئْتَ، وَلَا تَعُبَّ الْمَاءَ عَبًّا، وَلْتَمُصَّهُ مَصًّا."]]},{"id":"ri43_4","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ٤","segs":[["matn","وَتَلُوكُ طَعَامَكَ، وَتُنَعِّمُهُ مَضْغًا قَبْلَ بَلْعِهِ؛ وَتُنَظِّفُ فَاكَ بَعْدَ طَعَامِكَ، وَإِنْ غَسَلْتَ يَدَكَ مِنَ الْغَمَرِ وَاللَّبَنِ فَحَسَنٌ، وَتُخَلِّلُ مَا تَعَلَّقَ بِأَسْنَانِكَ مِنَ الطَّعَامِ،"]]},{"id":"ri43_5","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ٥","segs":[["matn","وَنَهَى الرَّسُولُ عَلَيْهِ السَّلَامُ عَنِ الْأَكْلِ وَالشُّرْبِ بِالشِّمَالِ، وَتُنَاوِلُ إِذَا شَرِبْتَ مَنْ عَلَى يَمِينِكَ، وَيُنْهَى عَنِ النَّفْخِ فِي الطَّعَامِ وَالشَّرَابِ وَالْكِتَابِ وَعَنِ الشُّرْبِ فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ."]]},{"id":"ri43_6","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ٦","segs":[["matn","وَلَا بَأْسَ بِالشُّرْبِ قَائِمًا، وَلَا يَنْبَغِي لِمَنْ أَكَلَ الْكُرَّاثَ أَوِ الثُّومَ أَوِ الْبَصَلَ نِيئًا أَنْ يَدْخُلَ الْمَسْجِدَ، وَيُكْرَهُ أَنْ يَأْكُلَ مُتَّكِئًا، وَيُكْرَهُ الْأَكْلُ مِنْ رَأْسِ الثَّرِيدِ."]]},{"id":"ri43_7","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ٧","segs":[["matn","وَنُهِيَ عَنِ الْقِرَانِ فِي التَّمْرِ، وَقِيلَ: إِنَّ ذَلِكَ مَعَ الْأَصْحَابِ الشُّرَكَاءِ فِيهِ، وَلَا بَأْسَ بِذَلِكَ مَعَ أَهْلِكَ أَوْ مَعَ قَوْمٍ تَكُونُ أَنْتَ أَطْعَمْتَهُمْ، وَلَا بَأْسَ فِي التَّمْرِ وَشِبْهِهِ أَنْ تَجُولَ يَدُكَ فِي الْإِنَاءِ، لِتَأْكُلَ مَا تُرِيدُ مِنْهُ."]]},{"id":"ri43_8","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ٨","segs":[["matn","وَلَيْسَ غَسْلُ الْيَدِ قَبْلَ الطَّعَامِ مِنَ السُّنَّةِ إِلَّا أَنْ يَكُونَ بِهَا أَذًى، وَلْيَغْسِلْ يَدَهُ وَفَاهُ بَعْدَ الطَّعَامِ مِنَ الْغَمَرِ، وَلْيُمَضْمِضْ فَاهُ مِنَ اللَّبَنِ، وَكُرِهَ غَسْلُ الْيَدِ بِالطَّعَامِ أَوْ بِشَيْءٍ مِنَ الْقَطَانِيِّ، وَكَذَلِكَ بِالنُّخَالَةِ، وَقَدِ اخْتُلِفَ فِي ذَلِكَ."]]},{"id":"ri43_9","label":"بَابٌ فِي الطَّعَامِ وَالشَّرَابِ · ٩","segs":[["matn","وَلْتُجِبْ إِذَا دُعِيتَ إِلَى وَلِيمَةِ الْمُعْرِسِ إِنْ لَمْ يَكُنْ هُنَاكَ لَهْوٌ مَشْهُورٌ وَلَا مُنْكَرٌ بَيِّنٌ، وَأَنْتَ فِي الْأَكْلِ بِالْخِيَارِ، وَقَدْ أَرْخَصَ مَالِكٌ فِي التَّخَلُّفِ لِكَثْرَةِ زِحَامِ النَّاسِ فِيهَا."]]}]},{"id":"ri44","title":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ","units":[{"id":"ri44_1","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١","segs":[["matn","وَرَدُّ السَّلَامِ وَاجِبٌ، وَالِابْتِدَاءُ بِهِ سُنَّةٌ مُرَغَّبٌ فِيهَا، وَالسَّلَامُ أَنْ يَقُولَ الرَّجُلُ: السَّلَامُ عَلَيْكُمْ، وَيَقُولُ الرَّادُّ: وَعَلَيْكُمُ السَّلَامُ، أَوْ يَقُولُ: سَلَامٌ عَلَيْكُمْ كَمَا قِيلَ لَهُ، وَأَكْثَرُ مَا يَنْتَهِي السَّلَامُ إِلَى الْبَرَكَةِ أَنْ تَقُولَ فِي رَدِّكَ:"]]},{"id":"ri44_2","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢","segs":[["matn","وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، وَلَا تَقُلْ فِي رَدِّكَ سَلَامُ اللَّهِ عَلَيْكَ، وَإِذَا سَلَّمَ وَاحِدٌ مِنَ الْجَمَاعَةِ أَجْزَأَ عَنْهُمْ، وَكَذَلِكَ إِنْ رَدَّ وَاحِدٌ مِنْهُمْ، وَلْيُسَلِّمِ الرَّاكِبُ عَلَى الْمَاشِي، وَالْمَاشِي عَلَى الْجَالِسِ."]]},{"id":"ri44_3","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٣","segs":[["matn","وَالْمُصَافَحَةُ حَسَنَةٌ، وَكَرِهَ مَالِكٌ الْمُعَانَقَةَ، وَأَجَازَهَا ابْنُ عُيَيْنَةَ، وَكَرِهَ مَالِكٌ تَقْبِيلَ الْيَدِ، وَأَنْكَرَ مَا رُوِيَ فِيهِ، وَلَا تُبْتَدَأُ الْيَهُودَ وَالنَّصَارَى بِالسَّلَامِ،"]]},{"id":"ri44_4","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٤","segs":[["matn","فَمَنْ سَلَّمَ عَلَى ذِمِّيٍّ فَلَا يَسْتَقِيلُهُ، وَإِنْ سَلَّمَ عَلَيْهِ الْيَهُودِيُّ أَوِ النَّصْرَانِيُّ فَلْيَقُلْ: عَلَيْكَ، وَمَنْ قَالَ: عَلَيْكَ السِّلَامُ بِكَسْرِ السِّينِ، وَهِيَ الْحِجَارَةُ فَقَدْ قِيلَ ذَلِكَ."]]},{"id":"ri44_5","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٥","segs":[["matn","وَالِاسْتِئْذَانُ وَاجِبٌ؛ فَلَا تَدْخُلْ بَيْتًا فِيهِ أَحَدٌ حَتَّى تَسْتَأْذِنَ ثَلَاثًا، فَإِنْ أُذِنَ لَكَ وَإِلَّا رَجَعْتَ، وَيُرَغَّبُ فِي عِيَادَةِ الْمَرْضَى، وَلَا يَتَنَاجَى اثْنَانِ دُونَ وَاحِدٍ،"]]},{"id":"ri44_6","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٦","segs":[["matn","وَكَذَلِكَ الْجَمَاعَةُ إِذَا أَبْقَوْا وَاحِدًا مِنْهُمْ، وَقَدْ قِيلَ: لَا يَنْبَغِي ذَلِكَ إِلَّا بِإِذْنِهِ، وَذِكْرُ الْهِجْرَةِ قَدْ تَقَدَّمَ فِي بَابٍ قَبْلَ هَذَا."]]},{"id":"ri44_7","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٧","segs":[["matn","قَالَ مُعَاذُ بْنُ جَبَلٍ: مَا عَمِلَ آدَمِيٌّ عَمَلًا أَنْجَى لَهُ مِنْ عَذَابِ اللَّهِ مِنْ ذِكْرِ اللَّهِ، وَقَالَ عُمَرُ: أَفْضَلُ مِنْ ذِكْرِ اللَّهِ بِاللِّسَانِ ذِكْرُ اللَّهِ عِنْدَ أَمْرِهِ وَنَهْيِهِ."]]},{"id":"ri44_8","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٨","segs":[["matn","وَمِنْ دُعَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلَّمَا أَصْبَحَ وَأَمْسَى: اللَّهُمَّ بِكَ نُصْبِحُ، وَبِكَ نُمْسِي، وَبِكَ نَحْيَا وَبِكَ نَمُوتُ، وَيَقُولُ فِي الصَّبَاحِ: وَإِلَيْكَ النُّشُورُ، وَفِي الْمَسَاءِ: وَإِلَيْكَ الْمَصِيرُ."]]},{"id":"ri44_9","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٩","segs":[["matn","وَرُوِيَ مَعَ ذَلِكَ، اللَّهُمَّ اجْعَلْنِي مِنْ أَعْظَمِ عِبَادِكَ عِنْدَكَ حَظًّا وَنَصِيبًا فِي كُلِّ خَيْرٍ تَقْسِمُهُ فِي هَذَا الْيَوْمِ، وَفِيمَا بَعْدَهُ: مِنْ نُورٍ تَهْدِي بِهِ، أَوْ رَحْمَةٍ تَنْشُرُهَا،"]]},{"id":"ri44_10","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٠","segs":[["matn","أَوْ رِزْقٍ تَبْسُطُهُ، أَوْ ضُرٍّ تَكْشِفُهُ، أَوْ ذَنْبٍ تَغْفِرُهُ، أَوْ شِدَّةٍ تَدْفَعُهَا، أَوْ فِتْنَةٍ تَصْرِفُهَا، أَوْ مُعَافَاةٍ تَمُنُّ بِهَا بِرَحْمَتِكَ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ."]]},{"id":"ri44_11","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١١","segs":[["matn","وَمِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ عِنْدَ النَّوْمِ أَنَّهُ كَانَ يَضَعُ يَدَهُ الْيُمْنَى تَحْتَ خَدِّهِ الْأَيْمَنِ وَالْيُسْرَى عَلَى فَخِذِهِ الْأَيْسَرِ ثُمَّ يَقُولُ:"]]},{"id":"ri44_12","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٢","segs":[["matn","اللَّهُمَّ بِاسْمِكَ وَضَعْتُ جَنْبِي، وَبِاسْمِكَ أَرْفَعُهُ، اللَّهُمَّ إِنْ أَمْسَكْتَ نَفْسِي فَاغْفِرْ لَهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ الصَّالِحِينَ مِنْ عِبَادِكَ،"]]},{"id":"ri44_13","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٣","segs":[["matn","اللَّهُمَّ إِنِّي أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، رَهْبَةً مِنْكَ وَرَغْبَةً إِلَيْكَ، لَا مَنْجَا وَلَا مَلْجَأَ مِنْكَ إِلَّا إِلَيْكَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ."]]},{"id":"ri44_14","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٤","segs":[["matn","فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ إِلَهِي لَا إِلَهَ إِلَّا أَنْتَ، رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ."]]},{"id":"ri44_15","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٥","segs":[["matn","وَمِمَّا رُوِيَ فِي الدُّعَاءِ عِنْدَ الْخُرُوجِ مِنَ الْمَنْزِلِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ."]]},{"id":"ri44_16","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٦","segs":[["matn","وَرُوِيَ فِي دُبُرِ كُلِّ صَلَاةٍ أَنْ يُسَبِّحَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَيُكَبِّرَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَيَحْمَدَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَيَخْتِمَ الْمِائَةَ بِلَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ."]]},{"id":"ri44_17","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٧","segs":[["matn","وَعِنْدَ الْخَلَاءِ تَقُولُ: الْحَمْدُ لِلَّهِ الَّذِي رَزَقَنِي لَذَّتَهُ، وَأَخْرَجَ عَنِّي مَشَقَّتَهُ، وَأَبْقَى فِي جِسْمِي قُوَّتَهُ."]]},{"id":"ri44_18","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٨","segs":[["matn","وَتَتَعَوَّذُ مِنْ كُلِّ شَيْءٍ تَخَافُهُ، وَعِنْدَمَا تَحِلُّ بِمَوْضِعٍ أَوْ تَجْلِسُ بِمَكَانٍ أَوْ تَنَامُ فِيهِ تَقُولُ: أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ."]]},{"id":"ri44_19","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ١٩","segs":[["matn","وَمِنَ التَّعَوُّذِ أَنْ تَقُولَ: أَعُوذُ بِوَجْهِ اللَّهِ الْكَرِيمِ وَبِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ،"]]},{"id":"ri44_20","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٠","segs":[["matn","وَبِأَسْمَاءِ اللَّهِ الْحُسْنَى كُلِّهَا مَا عَلِمْتُ مِنْهَا وَمَا لَمْ أَعْلَمْ مِنْ شَرِّ مَا خَلَقَ وَذَرَأَ وَبَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا،"]]},{"id":"ri44_21","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢١","segs":[["matn","وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ فِتْنَةِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ طَوَارِقِ اللَّيْلِ وَالنَّهَارِ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ،"]]},{"id":"ri44_22","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٢","segs":[["matn","وَيُقَالُ فِي ذَلِكَ أَيْضًا: وَمِنْ شَرِّ كُلِّ دَابَّةٍ رَبِّي آخِذٌ بِنَاصِيَتِهَا، إِنَّ رَبِّي عَلَى صِرَاطٍ مُسْتَقِيمٍ. وَيُسْتَحَبُّ لِمَنْ دَخَلَ مَنْزِلَهُ أَنْ يَقُولَ: مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ."]]},{"id":"ri44_23","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٣","segs":[["matn","وَيُكْرَهُ الْعَمَلُ فِي الْمَسَاجِدِ مِنْ خِيَاطَةٍ وَنَحْوِهَا، وَلَا يَغْسِلُ يَدَيْهِ فِيهِ، وَلَا يَأْكُلُ فِيهِ إِلَّا مِثْلَ الشَّيْءِ الْخَفِيفِ كَالسَّوِيقِ وَنَحْوِهِ، وَلَا يَقُصُّ فِيهِ شَارِبَهُ،"]]},{"id":"ri44_24","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٤","segs":[["matn","وَلَا يُقَلِّمُ فِيهِ أَظْفَارَهُ وَإِنْ أَخَذَهُ فِي ثَوْبِهِ، وَلَا يَقْتُلُ فِيهِ قَمْلَةً وَلَا بُرْغُوثًا، وَأُرَخِّصُ فِي مَبِيتِ الْغُرَبَاءِ فِي مَسَاجِدِ الْبَادِيَةِ."]]},{"id":"ri44_25","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٥","segs":[["matn","وَلَا يَنْبَغِي أَنْ يَقْرَأَ فِي الْحَمَّامِ إِلَّا الْآيَاتِ الْيَسِيرَةَ وَلَا يُكْثِرُ، وَيَقْرَأُ الرَّاكِبُ وَالْمُضْطَجِعُ وَالْمَاشِي مِنْ قَرْيَةٍ إِلَى قَرْيَةٍ، وَيُكْرَهُ ذَلِكَ لِلْمَاشِي إِلَى السُّوقِ، وَقَدْ قِيلَ:"]]},{"id":"ri44_26","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٦","segs":[["matn","إِنَّ ذَلِكَ لِلْمُتَعَلِّمِ وَاسِعٌ، وَمَنْ قَرَأَ الْقُرْآنَ فِي سَبْعٍ فَذَلِكَ حَسَنٌ، وَالتَّفَهُّمُ مَعَ قِلَّةِ الْقِرَاءَةِ أَفْضَلُ، وَرُوِيَ أَنَّ النَّبِيَّ عَلَيْهِ السَّلَامُ لَمْ يَقْرَأْهُ فِي أَقَلَّ مِنْ ثَلَاثٍ."]]},{"id":"ri44_27","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٧","segs":[["matn","وَيُسْتَحَبُّ لِلْمُسَافِرِ أَنْ يَقُولَ عِنْدَ رُكُوبِهِ: بِسْمِ اللَّهِ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمُنْقَلَبِ وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ."]]},{"id":"ri44_28","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٨","segs":[["matn","وَيَقُولُ الرَّاكِبُ إِذَا اسْتَوَى عَلَى الدَّابَّةِ: سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا، وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ."]]},{"id":"ri44_29","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٢٩","segs":[["matn","وَتُكْرَهُ التِّجَارَةُ إِلَى أَرْضِ الْعَدُوِّ وَبَلَدِ السُّودَانِ، وَقَالَ النَّبِيُّ عَلَيْهِ السَّلَامُ «السَّفَرُ قِطْعَةٌ مِنَ الْعَذَابِ»."]]},{"id":"ri44_30","label":"بَابٌ فِي السَّلَامِ وَالِاسْتِئْذَانِ وَالتَّنَاجِي وَالْقِرَاءَةِ وَالدُّعَاءِ وَذِكْرِ اللَّهِ وَالْقَوْلِ فِي السَّفَرِ · ٣٠","segs":[["matn","وَلَا يَنْبَغِي أَنْ تُسَافِرَ الْمَرْأَةُ مَعَ غَيْرِ ذِي مَحْرَمٍ مِنْهَا سَفَرَ يَوْمٍ وَلَيْلَةٍ فَأَكْثَرَ، إِلَّا فِي حَجِّ الْفَرِيضَةِ خَاصَّةً فِي قَوْلِ مَالِكٍ فِي رُفْقَةٍ مَأْمُونَةٍ وَإِنْ لَمْ يَكُنْ مَعَهَا ذُو مَحْرَمٍ فَذَلِكَ لَهَا."]]}]},{"id":"ri45","title":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ","units":[{"id":"ri45_1","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ١","segs":[["matn","وَلَا بَأْسَ بِالِاسْتِرْقَاءِ مِنَ الْعَيْنِ وَغَيْرِهَا وَالتَّعَوُّذِ وَالتَّعَالُجِ وَشُرْبِ الدَّوَاءِ وَالْفَصْدِ وَالْكَيِّ، وَالْحِجَامَةُ حَسَنَةٌ، وَالْكُحْلُ لِلتَّدَاوِي لِلرِّجَالِ، جَائِزٌ وَهُوَ مِنْ زِينَةِ النِّسَاءِ،"]]},{"id":"ri45_2","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ٢","segs":[["matn","وَلَا يُتَعَالَجُ بِالْخَمْرِ وَلَا بِالنَّجَاسَةِ وَلَا بِمَا فِيهِ مَيْتَةٌ وَلَا بِشَيْءٍ مِمَّا حَرَّمَ اللَّهُ، سُبْحَانَهُ وَتَعَالَى وَلَا بَأْسَ بِالِاكْتِوَاءِ، وَالرُّقَى بِكِتَابِ اللَّهِ وَبِالْكَلَامِ الطَّيِّبِ، وَلَا بَأْسَ بِالْمَعَاذَةِ تُعَلَّقُ وَفِيهَا الْقُرْآنُ."]]},{"id":"ri45_3","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ٣","segs":[["matn","وَإِذَا وَقَعَ الْوَبَاءُ بِأَرْضِ قَوْمٍ فَلَا يُقْدَمُ عَلَيْهِ، وَمَنْ كَانَ بِهَا فَلَا يَخْرُجُ فِرَارًا مِنْهُ."]]},{"id":"ri45_4","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ٤","segs":[["matn","وَقَالَ الرَّسُولُ عَلَيْهِ السَّلَامُ فِي الشُّؤْمِ: «إِنْ كَانَ فَفِي الْمَسْكَنِ وَالْمَرْأَةِ وَالْفَرَسِ»، وَكَانَ عَلَيْهِ السَّلَامُ يَكْرَهُ سَيِّئَ الْأَسْمَاءِ، وَيُحِبُّ الْفَأْلَ الْحَسَنَ."]]},{"id":"ri45_5","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ٥","segs":[["matn","وَالْغَسْلُ لِلْعَيْنِ أَنْ يَغْسِلَ الْعَائِنُ وَجْهَهُ وَيَدَيْهِ وَمِرْفَقَيْهِ وَرُكْبَتَيْهِ وَأَطْرَافَ رِجْلَيْهِ وَدَاخِلَةَ إِزَارِهِ فِي قَدَحٍ ثُمَّ يُصَبَّ عَلَى الْمَعِينِ."]]},{"id":"ri45_6","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ٦","segs":[["matn","وَلَا يَنْظُرُ فِي النُّجُومِ إِلَّا مَا يُسْتَدَلُّ بِهِ عَلَى الْقِبْلَةِ وَأَجْزَاءِ اللَّيْلِ، وَيَتْرُكُ مَا سِوَى ذَلِكَ."]]},{"id":"ri45_7","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ٧","segs":[["matn","وَلَا يُتَّخَذُ كَلْبٌ فِي الدُّورِ فِي الْحَضَرِ وَلَا فِي دُورِ الْبَادِيَةِ إِلَّا لِزَرْعٍ أَوْ مَاشِيَةٍ يَصْحَبُهَا فِي الصَّحْرَاءِ، ثُمَّ يَرُوحُ مَعَهَا، أَوْ لِصَيْدٍ يَصْطَادُهُ لِعَيْشِهِ لَا لِلَّهْوِ."]]},{"id":"ri45_8","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ٨","segs":[["matn","وَلَا بَأْسَ بِخِصَاءِ الْغَنَمِ لِمَا فِيهِ مِنْ صَلَاحِ لُحُومِهَا، وَنُهِيَ عَنْ خِصَاءِ الْخَيْلِ، وَيُكْرَهُ الْوَسْمُ فِي الْوَجْهِ، وَلَا بَأْسَ بِهِ فِي غَيْرِ ذَلِكَ."]]},{"id":"ri45_9","label":"بَابٌ فِي التَّعَالُجِ وَذِكْرِ الرُّقَى وَالطِّيَرَةِ وَالنُّجُومِ وَالْخِصَاءِ وَالْوَسْمِ وَالْكِلَابِ وَالرِّفْقِ بِالْمَمْلُوكِ · ٩","segs":[["matn","وَيُتَرَفَّقُ بِالْمَمْلُوكِ، وَلَا يُكَلَّفُ مِنَ الْعَمَلِ مَا لَا يُطِيقُ."]]}]},{"id":"ri46","title":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ","units":[{"id":"ri46_1","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١","segs":[["matn","قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «الرُّؤْيَا الْحَسَنَةُ مِنَ الرَّجُلِ الصَّالِحِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ»،"]]},{"id":"ri46_2","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٢","segs":[["matn","وَمَنْ رَأَى مِنْكُمْ مَا يَكْرَهُ فِي مَنَامِهِ فَإِذَا اسْتَيْقَظَ فَلْيَتْفُلْ عَنْ يَسَارِهِ ثَلَاثًا، وَلْيَقُلْ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا رَأَيْتُ فِي مَنَامِي أَنْ يَضُرَّنِي فِي دِينِي وَدُنْيَايَ."]]},{"id":"ri46_3","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٣","segs":[["matn","وَمَنْ تَثَاءَبَ فَلْيَضَعْ يَدَهُ عَلَى فِيهِ، وَمَنْ عَطَسَ فَلْيَقُلِ: الْحَمْدُ لِلَّهِ، وَعَلَى مَنْ سَمِعَهُ يَحْمَدُ اللَّهَ أَنْ يَقُولَ لَهُ: يَرْحَمُكَ اللَّهُ، وَيَرُدُّ الْعَاطِسُ عَلَيْهِ: يَغْفِرُ اللَّهُ لَنَا وَلَكُمْ، أَوْ يَقُولُ: يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ."]]},{"id":"ri46_4","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٤","segs":[["matn","وَلَا يَجُوزُ اللَّعِبُ بِالنَّرْدِ وَلَا بِالشِّطْرَنْجِ، وَلَا بَأْسَ أَنْ يُسَلِّمَ عَلَى مَنْ يَلْعَبُ بِهَا، وَيُكْرَهُ الْجُلُوسُ إِلَى مَنْ يَلْعَبُ بِهَا وَالنَّظَرُ إِلَيْهِمْ،"]]},{"id":"ri46_5","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٥","segs":[["matn","وَلَا بَأْسَ بِالسَّبْقِ بِالْخَيْلِ وَالْإِبِلِ وَبِالسِّهَامِ بِالرَّمْيِ وَإِنْ أَخْرَجَا شَيْئًا جَعَلَا بَيْنَهُمَا مُحَلِّلًا يَأْخُذُ ذَلِكَ الْمُحَلِّلُ إِنْ سَبَقَ هُوَ، وَإِنْ سَبَقَ غَيْرُهُ لَمْ يَكُنْ عَلَيْهِ شَيْءٌ، هَذَا قَوْلُ ابْنِ الْمُسَيِّبِ، وَقَالَ مَالِكٌ: إِنَّمَا يَجُوزُ أَنْ يُخْرِجَ الرَّجُلُ سَبَقًا؛"]]},{"id":"ri46_6","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٦","segs":[["matn","فَإِنْ سَبَقَ غَيْرُهُ أَخَذَهُ، وَإِنْ سَبَقَ هُوَ كَانَ لِلَّذِي يَلِيهِ مِنَ الْمُتَسَابِقَيْنِ وَإِنْ لَمْ يَكُنْ غَيْرُ جَاعِلِ السَّبَقِ وَآخَرُ؛ فَسَبَقَ جَاعِلُ السَّبْقِ أَكَلَهُ مَنْ حَضَرَ ذَلِكَ."]]},{"id":"ri46_7","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٧","segs":[["matn","وَجَاءَ فِيمَا ظَهَرَ مِنَ الْحَيَّاتِ بِالْمَدِينَةِ أَنْ تُؤْذَنَ ثَلَاثًا، وَإِنْ فَعَلَ ذَلِكَ فِي غَيْرِهَا فَهُوَ حَسَنٌ، وَلَا تُؤْذَنُ فِي الصَّحْرَاءِ، وَيُقْتَلُ مَا ظَهَرَ مِنْهَا."]]},{"id":"ri46_8","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٨","segs":[["matn","وَيُكْرَهُ قَتْلُ الْقَمْلِ وَالْبَرَاغِيثِ بِالنَّارِ، وَلَا بَأْسَ إِنْ شَاءَ اللَّهُ بِقَتْلِ النَّمْلِ إِذَا آذَتْ وَلَمْ يَقْدِرْ عَلَى تَرْكِهَا، وَلَوْ لَمْ تُقْتَلْ كَانَ أَحَبَّ إِلَيْنَا وَيُقْتَلُ الْوَزَغُ. وَيُكْرَهُ قَتْلُ الضَّفَادِعِ."]]},{"id":"ri46_9","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٩","segs":[["matn","وَقَالَ: النَّبِيُّ عَلَيْهِ السَّلَامُ إِنَّ اللَّهَ أَذْهَبَ عَنْكُمْ عُبِّيَّةَ الْجَاهِلِيَّةِ وَفَخْرَهَا بِالْآبَاءِ، مُؤْمِنٌ تَقِيٌّ أَوْ فَاجِرٌ شَقِيٌّ، أَنْتُمْ بَنُو آدَمَ، وَآدَمُ مِنْ تُرَابٍ، وَقَالَ النَّبِيُّ عَلَيْهِ السَّلَامُ فِي رَجُلٍ تَعَلَّمَ أَنْسَابَ النَّاسِ:"]]},{"id":"ri46_10","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٠","segs":[["matn","«عِلْمٌ لَا يَنْفَعُ وَجَهَالَةٌ لَا تَضُرُّ»، وَقَالَ عُمَرُ: تَعَلَّمُوا مِنْ أَنْسَابِكُمْ مَا تَصِلُونَ بِهِ أَرْحَامَكُمْ، وَقَالَ مَالِكٌ: وَأَكْرَهُ أَنْ يَرْفَعَ فِي النِّسْبَةِ فِيمَا قَبْلَ الْإِسْلَامِ مِنَ الْآبَاءِ."]]},{"id":"ri46_11","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١١","segs":[["matn","وَالرُّؤْيَا الصَّالِحَةُ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ، وَمَنْ رَأَى فِي مَنَامِهِ مَا يَكْرَهُ فَلْيَتْفُلْ عَنْ يَسَارِهِ ثَلَاثًا،"]]},{"id":"ri46_12","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٢","segs":[["matn","وَلْيَتَعَوَّذْ مِنْ شَرِّ مَا رَأَى، وَلَا يَنْبَغِي أَنْ يُفَسِّرَ الرُّؤْيَا مَنْ لَا عِلْمَ لَهُ بِهَا، وَلَا يُعَبِّرُهَا عَلَى الْخَيْرِ وَهِيَ عِنْدَهُ عَلَى الْمَكْرُوهِ."]]},{"id":"ri46_13","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٣","segs":[["matn","وَلَا بَأْسَ بِإِنْشَادِ الشِّعْرِ، وَمَا خَفَّ مِنَ الشِّعْرِ أَحْسَنُ، وَلَا يَنْبَغِي أَنْ يُكْثِرَ مِنْهُ وَمِنَ الشُّغْلِ بِهِ."]]},{"id":"ri46_14","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٤","segs":[["matn","وَأَوْلَى الْعُلُومِ وَأَفْضَلُهَا وَأَقْرَبُهَا إِلَى اللَّهِ عِلْمُ دِينِهِ وَشَرَائِعِهِ مِمَّا أَمَرَ بِهِ وَنَهَى عَنْهُ، وَدَعَا إِلَيْهِ وَحَضَّ عَلَيْهِ، فِي كِتَابِهِ وَعَلَى لِسَانِ نَبِيِّهِ، وَالْفِقْهُ فِي ذَلِكَ وَالْفَهْمُ فِيهِ وَالتَّهَمُّمُ بِرِعَايَتِهِ،"]]},{"id":"ri46_15","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٥","segs":[["matn","وَالْعَمَلُ بِهِ وَالْعِلْمُ أَفْضَلُ الْأَعْمَالِ، وَأَقْرَبُ الْعُلَمَاءِ إِلَى اللَّهِ تَعَالَى وَأَوْلَاهُمْ بِهِ أَكْثَرُهُمْ لَهُ خَشْيَةً وَفِيمَا عِنْدَهُ رَغْبَةً، وَالْعِلْمُ دَلِيلٌ إِلَى الْخَيْرَاتِ وَقَائِدٌ إِلَيْهَا."]]},{"id":"ri46_16","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٦","segs":[["matn","وَاللَّجَأُ إِلَى كِتَابِ اللَّهِ عَزَّ وَجَلَّ وَسُنَّةِ نَبِيِّهِ وَاتِّبَاعِ سَبِيلِ الْمُؤْمِنِينَ وَخَيْرِ الْقُرُونِ مِنْ خَيْرِ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ نَجَاةٌ؛ فَفِي الْمَفْزَعِ إِلَى ذَلِكَ الْعِصْمَةُ؛"]]},{"id":"ri46_17","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٧","segs":[["matn","وَفِي اتِّبَاعِ السَّلَفِ الصَّالِحِ النَّجَاةُ، وَهُمُ الْقُدْوَةُ فِي تَأْوِيلِ مَا تَأَوَّلُوهُ وَاسْتِخْرَاجِ مَا اسْتَنْبَطُوهُ، وَإِذَا اخْتَلَفُوا فِي الْفُرُوعِ وَالْحَوَادِثِ لَمْ يَخْرُجْ عَنْ جَمَاعَتِهِمْ."]]},{"id":"ri46_18","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٨","segs":[["matn","وَالْحَمْدُ لِلَّهِ الَّذِي هَدَانَا لِهَذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللَّهُ."]]},{"id":"ri46_19","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ١٩","segs":[["matn","قَالَ أَبُو مُحَمَّدٍ عَبْدُ اللَّهِ بْنُ أَبِي زَيْدٍ: قَدْ أَتَيْنَا عَلَى مَا شَرَطْنَا أَنْ نَأْتِيَ بِهِ فِي كِتَابِنَا هَذَا مِمَّا يَنْتَفِعُ بِهِ إِنْ شَاءَ اللَّهُ مَنْ رَغِبَ فِي تَعْلِيمِ ذَلِكَ مِنَ الصِّغَارِ،"]]},{"id":"ri46_20","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٢٠","segs":[["matn","وَمَنِ احْتَاجَ إِلَيْهِ مِنَ الْكِبَارِ، وَفِيهِ مَا يُؤَدِّي الْجَاهِلَ إِلَى عِلْمِ مَا يَعْتَقِدُهُ مِنْ دِينِهِ، وَيَعْمَلُ بِهِ مِنْ فَرَائِضِهِ، وَيُفْهِمُ كَثِيرًا مِنْ أُصُولِ الْفِقْهِ وَفُنُونِهِ، وَمِنَ السُّنَنِ وَالرَّغَائِبِ وَالْآدَابِ."]]},{"id":"ri46_21","label":"بَابٌ فِي الرُّؤْيَا وَالتَّثَاؤُبِ وَالْعُطَاسِ وَاللَّعِبِ بِالنَّرْدِ وَغَيْرِهَا وَالسَّبَقِ بِالْخَيْلِ وَالرَّمْيِ وَغَيْرِ ذَلِكَ · ٢١","segs":[["matn","وَأَنَا أَسْأَلُ اللَّهَ عَزَّ وَجَلَّ أَنْ يَنْفَعَنَا وَإِيَّاكَ بِمَا عَلَّمَنَا، وَيُعِينَنَا وَإِيَّاكَ عَلَى الْقِيَامِ بِحَقِّهِ فِيمَا كَلَّفَنَا، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، وَصَلَّى اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ نَبِيِّهِ وَعَلَى آلِهِ وَصَحْبِهِ وَسَلَّمَ تَسْلِيمًا كَثِيرًا."]]}]}],"basmala":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","sharh":false};
